  document.getElementById('edit-cl-debut').value=c.debut||TODAY;
  document.getElementById('edit-cl-adhesion').value=c.adhesion||0;
  document.getElementById('edit-cl-adhesion-statut').value=c.adhesionStatut||'non_paye';
