// Synchronise le select durée avec une valeur numérique (pour ouvrirEditionClient)
function syncDureeSelect(selId, inpId, val){
  const sel = document.getElementById(selId);
  const inp = document.getElementById(inpId);
  if(!sel||!inp) return;
  const known = ['93','186','372'];
  if(known.includes(String(val))){sel.value=String(val);inp.style.display='none';inp.value=val;}
  else{sel.value='custom';inp.style.display='';inp.value=val;}
}


window.calcJourEdit = function(){
  const p=parseFloat(document.getElementById('edit-cl-montant').value)||0;
  const d=parseInt(document.getElementById('edit-cl-duree').value)||372;
  const el=document.getElementById('edit-cl-calc-info');
  if(p>0){el.style.display='block';const jmv=Math.ceil(p/d);const debut=document.getElementById('edit-cl-debut').value||TODAY;const fin=new Date(debut+'T12:00:00');fin.setDate(fin.getDate()+d);el.innerHTML=`💰 Cotisation : <strong>${fmt(jmv)}/jour</strong> sur ${d} jours → Fin : <strong>${fin.toLocaleDateString('fr-FR')}</strong>`;}
  else el.style.display='none';
};

window.sauvegarderEditionClient = _withActionLock('sauvegarderEditionClient', async function(){
  const cid=document.getElementById('edit-cl-id').value;
  const nom=document.getElementById('edit-cl-nom').value.trim();
  const tel=document.getElementById('edit-cl-tel').value.trim();
  const ct=document.getElementById('edit-cl-contrat').value.trim();
  const mt=parseFloat(document.getElementById('edit-cl-montant').value)||0;
  const debut=document.getElementById('edit-cl-debut').value;
  if(!nom||!tel||!ct||mt<=0||!debut){notify('Champs obligatoires manquants','err');return;}
  const newCode=document.getElementById('edit-cl-code').value.trim().toUpperCase();
  // Vérifier doublon de code si changé
  if(newCode){
    const doublon=DB.clients.find(c=>c._id!==cid&&c.codeClient&&c.codeClient.toUpperCase()===newCode);
    if(doublon){notify(`Code "${newCode}" déjà utilisé par ${esc(doublon.nom)}`,'err');return;}
  }
  const newCommercialId = document.getElementById('edit-cl-com').value;
  // ── Contrôle avant départ : si le commercial du client change ici (mutation
  // manuelle via ce formulaire, pas seulement via l'outil de transfert en
  // masse), on note la date de ce changement. C'est cette date qui sert de
  // référence dans la section "Contrôle avant départ" pour ne compter que
  // les paiements reçus par le NOUVEAU commercial après sa prise de poste.
  const clAvant = DB.clients.find(c=>c._id===cid);
  const commercialAChange = clAvant && clAvant.commercialId !== newCommercialId;
  // ✅ FIX : les clients importés peuvent porter un champ caché
  // 'cotisationJourFixe' (fixé une fois à l'import) que jm() priorise
  // toujours sur montantTotal/duree. Ce formulaire modifie justement
  // montantTotal/duree — sans effacer cotisationJourFixe, la nouvelle
  // cotisation calculée ici (affichée dans l'aperçu ci-dessus) ne
  // s'appliquerait jamais réellement. On l'efface donc à chaque
  // modification du contrat pour que le nouveau montant/durée fasse foi.
  const patch = {
    codeClient:newCode, nom, tel,
    ville:document.getElementById('edit-cl-ville').value,
    quartier:document.getElementById('edit-cl-qrt').value,
    contrat:ct, montantTotal:mt,
    duree:parseInt(document.getElementById('edit-cl-duree').value)||372,
    debut, note:document.getElementById('edit-cl-note').value,
    commercialId:newCommercialId,
    adhesion:parseFloat(document.getElementById('edit-cl-adhesion').value)||0,
    adhesionStatut:document.getElementById('edit-cl-adhesion-statut').value,
    cotisationJourFixe: null
  };
  if(commercialAChange) patch.dateAffectation = TODAY;
  await fbUpdate('clients',cid,patch);
  // ── CORRECTIF DERIVE joursCouv ──────────────────────────────────────
  // Ce formulaire modifie montantTotal / duree et efface cotisationJourFixe
  // (voir le patch ci-dessus) : la cotisation journaliere jm(cl) change donc,
  // et avec elle joursCouv = totalPaye / jm(cl). Or joursCouv est un champ
  // STOCKE sur le client, lu tel quel par statsLite() pour afficher le retard
  // dans les listes. Sans ce recalcul, le retard affiche restait calcule sur
  // l'ANCIEN contrat jusqu'au paiement suivant du client — parfois des jours.
  // _recalcClientPaiementRollup() relit les paiements de CE client et
  // reecrit totalPaye / joursCouv / dernierPaiement* avec la nouvelle
  // formule. Requete ciblee, peu couteuse.
  // Volontairement NON bloquant pour l'utilisateur : la modification du
  // contrat est deja enregistree ci-dessus. Si le recalcul echoue (reseau),
  // on le signale sans annuler la modification — le prochain paiement du
  // client, ou le script recalc-totalpaye.mjs, rattrapera l'ecart.
  try {
    await _recalcClientPaiementRollup(cid);
  } catch(e) {
    console.warn('[rollup] recalcul apres edition client echoue pour', cid, e);
  }
  closeM('m-edit-client');
  notify(`Client ${nom} mis à jour ✓`);
});


// ========= MODIFICATION DU CONTRAT AVEC ARTICLES =========
// State temporaire des articles du contrat en cours d'édition
let _mcArticles = []; // [{artId, nom, qty, pv}]

let _mcArticlesInitial = []; // snapshot avant modification pour diff

window.ouvrirModifContrat = async function(cid){
  if(!cid){ notify("Client introuvable","err"); return; }
  const c = getCl(cid);
  // ── OPTION C ── modification de contrat : les jours de couverture deja
  // acquis dependent du cumul reel des paiements.
  await _ensureClientPaysLoaded(cid);
  const s = stats(c);
  document.getElementById("mc-cl-id").value = cid;
  document.getElementById("mc-cl-info").innerHTML =
    "<strong>"+esc(c.nom)+"</strong> · "+esc(c.contrat||"—")+"<br>"
    +"Déjà payé : <strong style=\"color:var(--accent2)\">"+fmt(s.totalPaye)+"</strong> / "+fmt(c.montantTotal||0)+" "
    +"— Restant : <strong style=\"color:"+(s.totalRestant>0?"var(--accent)":"var(--accent2)")+"\">"+fmt(s.totalRestant)+"</strong>";
  const mcContratEl = document.getElementById("mc-contrat");
  mcContratEl.value = c.contrat||"";
  // Marquer la désignation initiale comme "auto" si elle correspond au pattern articles
  // (sera écrasée librement par mcAutoNom si l'admin ne l'a pas modifiée manuellement)
  mcContratEl.dataset.auto = c.contrat||"";
  document.getElementById("mc-montant").value = c.montantTotal||"";
  syncDureeSelect("mc-duree-sel","mc-duree",c.duree||372);

  // Réinitialiser les nouveaux champs
  const codeEl = document.getElementById("mc-art-code"); if(codeEl) codeEl.value='';
  const qtyCodeEl = document.getElementById("mc-art-qty-code"); if(qtyCodeEl) qtyCodeEl.value=1;
  const msgEl = document.getElementById("mc-art-code-msg"); if(msgEl) msgEl.style.display='none';
  const noteEl = document.getElementById("mc-note-modif"); if(noteEl) noteEl.value='';

  // Charger les articles actuels du contrat + snapshot initial pour diff
  _mcArticles = (c.contratArticles||[]).map(a=>({...a}));
  _mcArticlesInitial = (c.contratArticles||[]).map(a=>({...a}));

  // Remplir le select de produits
  const sel = document.getElementById("mc-art-sel");
  // ── VOLET 23 ── les produits indisponibles ne sont plus proposes ici :
  // ajouter un produit a un contrat existant reste une vente. Les produits
  // DEJA au contrat ne sont pas touches — ils vivent dans _mcArticles, pas
  // dans cette liste.
  sel.innerHTML = '<option value="">— Sélectionner un produit —</option>'
    + DB.produits.filter(p=>p.nom && !_prodIndispo(p)).sort((a,b)=>a.nom.localeCompare(b.nom))
        .map(p=>'<option value="'+p._id+'" data-pv="'+(p.prix||0)+'" data-nom="'+esc(p.nom)+'">'+esc(p.nom)+' — '+fmt(p.prix)+'</option>').join('');
  sel.onchange = function(){
    const opt = sel.options[sel.selectedIndex];
    const pv = opt ? opt.getAttribute('data-pv') : '';
    document.getElementById("mc-art-pv").value = pv||'';
  };

  _mcRenderArticles();
  calcMC();
  closeM("m-pay");
  openM("m-modif-contrat");
};

// Rend la liste des articles du contrat
function _mcRenderArticles(){
  const liste = document.getElementById("mc-art-liste");
  const vide  = document.getElementById("mc-art-vide");
  if(!_mcArticles.length){
    vide.style.display='';
    [...liste.querySelectorAll('.mc-art-row')].forEach(r=>r.remove());
    return;
  }
  vide.style.display='none';
  [...liste.querySelectorAll('.mc-art-row')].forEach(r=>r.remove());
  _mcArticles.forEach((a,i)=>{
    // Détecter si cet article était dans le contrat initial (pack d'origine) ou ajouté
    const estOriginal = _mcArticlesInitial.some(o=>o.artId===a.artId);
    const row = document.createElement('div');
    row.className = 'mc-art-row';
    row.style.cssText = 'display:flex;align-items:center;gap:8px;padding:9px 12px;border-bottom:1px solid var(--border);'+(i%2?'background:rgba(26,32,53,0.35)':'')+(estOriginal?'':'background:rgba(56,201,160,0.05);border-left:2px solid rgba(56,201,160,0.4);');
    const badgeNouv = !estOriginal ? '<span style="font-size:9px;background:rgba(56,201,160,0.15);color:var(--accent2);border:1px solid rgba(56,201,160,0.3);border-radius:4px;padding:1px 5px;margin-left:4px;font-weight:700;">NOUVEAU</span>' : '';
    row.innerHTML =
      '<span style="flex:2;font-size:12px;font-weight:600;color:var(--text);">'+esc(a.nom)+badgeNouv+'</span>'
      +'<span style="flex:0 0 34px;text-align:center;">'
        +'<input type="number" min="1" value="'+a.qty+'" style="width:100%;background:var(--surface);border:1px solid var(--border);border-radius:5px;padding:4px 6px;color:var(--accent);font-weight:700;font-size:12px;text-align:center;outline:none;" onchange="mcChangerQty('+i+',this.value)">'
      +'</span>'
      +'<span style="flex:0 0 110px;">'
        +'<input type="number" min="0" value="'+a.pv+'" style="width:100%;background:var(--surface);border:1px solid var(--border);border-radius:5px;padding:4px 6px;color:var(--accent2);font-weight:600;font-size:11px;text-align:right;outline:none;" onchange="mcChangerPv('+i+',this.value)">'
      +'</span>'
      +'<span style="flex:0 0 90px;text-align:right;font-size:11px;font-weight:700;color:var(--accent);">'+fmt(a.qty*a.pv)+'</span>'
      +'<button onclick="mcSupprimerArticle('+i+')" title="Retirer du contrat (−'+fmt(a.qty*a.pv)+')" style="flex:0 0 auto;background:rgba(224,92,82,0.12);border:1px solid rgba(224,92,82,0.3);border-radius:6px;padding:4px 9px;color:var(--danger);font-size:11px;font-weight:700;cursor:pointer;font-family:\'Outfit\',sans-serif;">➖</button>';
    liste.appendChild(row);
  });
  // Ligne total
  const totalNouv = _mcArticles.reduce((s,a)=>s+(Number(a.qty)||0)*(Number(a.pv)||0),0);
  const totalAnc  = _mcArticlesInitial.reduce((s,a)=>s+(Number(a.qty)||0)*(Number(a.pv)||0),0);
  const delta = totalNouv - totalAnc;
  const deltaHtml = (totalAnc>0 && delta!==0)
    ? ' <span style="font-size:11px;font-weight:600;color:'+(delta>0?'var(--accent2)':'var(--danger)')+';">'+(delta>0?'▲ +':'▼ ')+fmt(Math.abs(delta))+'</span>'
    : '';
  const totRow = document.createElement('div');
  totRow.className = 'mc-art-row';
  totRow.style.cssText = 'display:flex;justify-content:flex-end;align-items:center;gap:8px;padding:8px 12px;background:rgba(201,168,76,0.06);border-top:2px solid rgba(201,168,76,0.2);';
  totRow.innerHTML = '<span style="font-size:11px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.8px;">Total produits</span>'
    +'<span style="font-family:\'Space Grotesk\',sans-serif;font-size:15px;font-weight:800;color:var(--accent);">'+fmt(totalNouv)+'</span>'
    +deltaHtml;
  liste.appendChild(totRow);
}

window.mcAjouterParCode = function(){
  const codeEl = document.getElementById('mc-art-code');
  const msgEl  = document.getElementById('mc-art-code-msg');
  const qtyEl  = document.getElementById('mc-art-qty-code');
  if(!codeEl||!msgEl) return;
  const code = codeEl.value.trim().toUpperCase();
  if(!code){ _mcShowMsg(msgEl,'Veuillez saisir un code ou une référence produit.','err'); return; }
  const prod = DB.produits.find(p=>
    (p.ref||'').toUpperCase()===code ||
    (p.nom||'').toUpperCase()===code
  );
  if(!prod){ _mcShowMsg(msgEl,`Aucun produit trouvé pour « ${code} ».`,'err'); return; }
  // ── VOLET 23 ── le champ « par code » contourne la liste deroulante :
  // sans ce controle, il resterait un chemin de vente ouvert.
  if(_prodIndispo(prod)){ _mcShowMsg(msgEl, _msgProdIndispo(prod), 'err'); return; }
  const qty = Math.max(1, parseInt(qtyEl?qtyEl.value:1)||1);
  // ✅ Un même produit peut désormais être ajouté plusieurs fois comme
  // lignes séparées du contrat (au lieu d'être automatiquement fusionné en
  // augmentant la quantité de la ligne existante).
  _mcArticles.push({artId:prod._id, nom:prod.nom, qty, pv:prod.prix||0});
  _mcShowMsg(msgEl,`✓ « ${esc(prod.nom)} » ajouté au contrat.`,'ok');
  codeEl.value='';
  if(qtyEl) qtyEl.value=1;
  _mcRenderArticles();
  mcRecalcTotal();
  mcAutoNom();
};

function _mcShowMsg(el, txt, type){
  const colors={ok:'rgba(34,212,160,0.15)',err:'rgba(224,92,82,0.14)',warn:'rgba(247,201,79,0.15)'};
  const tcol={ok:'var(--accent2)',err:'var(--danger)',warn:'var(--accent3)'};
  el.style.cssText=`display:block;background:${colors[type]||colors.ok};color:${tcol[type]||tcol.ok};border:1px solid ${tcol[type]||tcol.ok};border-radius:5px;padding:4px 9px;font-size:11px;`;
  el.textContent=txt;
  setTimeout(()=>{ if(type==='ok') el.style.display='none'; },DELAY_NOTIFY_HIDE_MS);
}

window.mcAjouterArticle = function(){
  const sel = document.getElementById("mc-art-sel");
  const qtyVal = parseInt(document.getElementById("mc-art-qty").value)||1;
  const pvVal  = parseFloat(document.getElementById("mc-art-pv").value)||0;
  if(!sel.value){ notify("Sélectionnez un produit","err"); return; }
  if(pvVal<=0){ notify("Prix unitaire invalide","err"); return; }
  // ── VOLET 23 ── garde de ceinture : la liste deroulante ne propose deja
  // plus les produits indisponibles, mais sa valeur peut etre forcee depuis
  // la console. Le refus doit vivre ici, au point d'ajout, pas seulement
  // dans l'affichage.
  {
    const _pSel = (DB.produits||[]).find(x=>x._id===sel.value);
    if(_prodIndispo(_pSel)){ notify(_msgProdIndispo(_pSel),'err'); return; }
  }
  const opt = sel.options[sel.selectedIndex];
  const nom = opt ? opt.getAttribute('data-nom') : sel.value;
  // ✅ Un même produit peut désormais être ajouté plusieurs fois comme
  // lignes séparées du contrat (au lieu d'être automatiquement fusionné en
  // augmentant la quantité de la ligne existante) — permet par exemple deux
  // lignes du même produit à des prix différents.
  _mcArticles.push({artId:sel.value, nom, qty:qtyVal, pv:pvVal});
  sel.value='';
  document.getElementById("mc-art-qty").value=1;
  document.getElementById("mc-art-pv").value='';
  _mcRenderArticles();
  mcRecalcTotal();
  mcAutoNom();
};

window.mcSupprimerArticle = function(i){
  _mcArticles.splice(i,1);
  _mcRenderArticles();
  mcRecalcTotal();
  mcAutoNom();
};

window.mcChangerQty = function(i, val){
  const q = Math.max(1, parseInt(val)||1);
  _mcArticles[i].qty = q;
  _mcRenderArticles();
  mcRecalcTotal();
};

window.mcChangerPv = function(i, val){
  const p = Math.max(0, parseFloat(val)||0);
  _mcArticles[i].pv = p;
  _mcRenderArticles();
  mcRecalcTotal();
};

// Recalcule le montant total depuis la liste d'articles — toujours écrasé
window.mcRecalcTotal = function(){
  const total = _mcArticles.reduce((s,a)=>s+(Number(a.qty)||0)*(Number(a.pv)||0),0);
  document.getElementById("mc-montant").value = total > 0 ? total : '';
  calcMC();
};

// Auto-génère la désignation du contrat depuis les articles
window.mcAutoNom = function(){
  const inp = document.getElementById("mc-contrat");
  if(!_mcArticles.length){
    // Si la désignation était auto, la vider aussi
    if(!inp.dataset.auto || inp.value.trim() === inp.dataset.auto){
      inp.value = ''; inp.dataset.auto = '';
    }
    return;
  }
  // Ne pas écraser une désignation saisie manuellement
  const current = inp.value.trim();
  const autoLabel = _mcArticles.map(a=>a.qty>1?a.qty+'× '+a.nom:a.nom).join(' + ');
  if(!current || current === inp.dataset.auto) {
    inp.value = autoLabel;
    inp.dataset.auto = autoLabel;
  }
};

window.mcDureeChange = function(sel){
  const inp = document.getElementById("mc-duree");
  if(sel.value==="custom"){inp.style.display="";inp.value="";inp.focus();}
  else{inp.style.display="none";inp.value=sel.value;calcMC();}
};

window.calcMC = function(){
  const p = parseFloat(document.getElementById("mc-montant").value)||0;
  const d = parseInt(document.getElementById("mc-duree").value)||372;
  const el = document.getElementById("mc-calc-info");
  if(p>0){ el.style.display="block"; el.innerHTML="💰 Cotisation résultante : <strong>"+fmt(Math.ceil(p/d))+"/jour</strong> sur "+d+" jours"; }
  else el.style.display="none";
};

window.sauvegarderModifContrat = _withActionLock('sauvegarderModifContrat', async function(){
  if(!session || !['admin','chef_agence'].includes(session.role)){ notify("Accès réservé à l'administrateur ou au chef d'agence","err"); return; }
  const cid = document.getElementById("mc-cl-id").value;
  const ct  = document.getElementById("mc-contrat").value.trim();
  const mt  = parseFloat(document.getElementById("mc-montant").value)||0;
  const dur = parseInt(document.getElementById("mc-duree").value)||372;
  if(!ct || mt<=0 || dur<=0){ notify("Contrat, montant et durée obligatoires","err"); return; }

  const c = getCl(cid);
  const noteMotif = (document.getElementById("mc-note-modif").value||"").trim();

  // ── Calculer le diff articles (ajoutés / retirés) ──
  const ancienIds  = new Set(_mcArticlesInitial.map(a=>a.artId));
  const nouveauIds = new Set(_mcArticles.map(a=>a.artId));

  const articlesAjoutes   = _mcArticles.filter(a=>!ancienIds.has(a.artId));
  const articlesSupprimés = _mcArticlesInitial.filter(a=>!nouveauIds.has(a.artId));
  const articlesQteChange = _mcArticles.filter(a=>{
    const old = _mcArticlesInitial.find(o=>o.artId===a.artId);
    return old && old.qty !== a.qty;
  });

  // ── Construire la note historique ──
  const ancienContratLabel = c.contrat || "—";
  const ancienMontant = c.montantTotal || 0;
  const ancienDuree   = c.duree || 372;
  const dateModif = TODAY;
  const now = new Date();
  const heureModif = String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');

  let noteHistorique = `[Modif ${dateModif} ${heureModif} par ${esc(session.nom)}]`;
  noteHistorique += ` Ancien contrat : « ${ancienContratLabel} » — ${fmt(ancienMontant)} — ${ancienDuree}j.`;
  if(articlesAjoutes.length)   noteHistorique += ` +Ajout : ${articlesAjoutes.map(a=>a.nom+(a.qty>1?' ×'+a.qty:'')).join(', ')}.`;
  if(articlesSupprimés.length) noteHistorique += ` −Retrait : ${articlesSupprimés.map(a=>a.nom).join(', ')}.`;
  if(articlesQteChange.length) noteHistorique += ` Qté modifiée : ${articlesQteChange.map(a=>{const o=_mcArticlesInitial.find(x=>x.artId===a.artId); return a.nom+' ('+o.qty+'→'+a.qty+')';}).join(', ')}.`;
  if(noteMotif) noteHistorique += ` Motif : ${noteMotif}.`;

  // Conserver les notes précédentes si existantes
  const noteExistante = (c.note||"").trim();
  const nouvelleNote = noteExistante ? noteExistante + "\n" + noteHistorique : noteHistorique;

  // ── Enregistrer ──
  // ✅ FIX : un client importé porte parfois un champ caché 'cotisationJourFixe'
  // (fixé une fois à l'import) que jm() priorise toujours sur montantTotal/duree.
  // On l'efface donc ici aussi (comme dans sauvegarderEditionClient) pour que la
  // cotisation journalière suive bien le nouveau montant/durée du contrat modifié.
  await fbUpdate("clients", cid, {
    contrat: ct,
    montantTotal: mt,
    duree: dur,
    contratArticles: _mcArticles.map(a=>({artId:a.artId,nom:a.nom,qty:a.qty,pv:a.pv})),
    note: nouvelleNote,
    cotisationJourFixe: null
  });

  // ── CORRECTIF DERIVE joursCouv ──────────────────────────────────────
  // Meme raison qu'a sauvegarderEditionClient : montantTotal / duree
  // changent et cotisationJourFixe est efface, donc jm(cl) change et
  // joursCouv stocke devient perime. On le recalcule immediatement.
  // Non bloquant : le contrat est deja enregistre ci-dessus.
  try {
    await _recalcClientPaiementRollup(cid);
  } catch(e) {
    console.warn('[rollup] recalcul apres modification de contrat echoue pour', cid, e);
  }

  closeM("m-modif-contrat");

  // ── Notification résumée ──
  let notifMsg = `✅ Contrat mis à jour — ${ct} — ${fmt(mt)}`;
  if(articlesAjoutes.length)   notifMsg += ` | ➕ ${articlesAjoutes.map(a=>a.nom+(a.qty>1?' ×'+a.qty:'')).join(', ')}`;
  if(articlesSupprimés.length) notifMsg += ` | ➖ ${articlesSupprimés.map(a=>a.nom).join(', ')}`;
  notify(notifMsg, "ok");

  // Si des articles ont été ajoutés, afficher une alerte récap visible
  if(articlesAjoutes.length || articlesSupprimés.length || articlesQteChange.length){
    setTimeout(()=>{
      let lignes = `<strong style="color:var(--accent)">📋 Résumé modification contrat — ${esc(c.nom)}</strong><br><span style="font-size:11px;color:var(--muted);">${dateModif} ${heureModif}</span><br><br>`;
      if(articlesAjoutes.length)   lignes += `<span style="color:var(--accent2)">➕ Ajoutés :</span> ${articlesAjoutes.map(a=>'<strong>'+esc(a.nom)+'</strong>'+(a.qty>1?' ×'+a.qty:'')+' — '+fmt(a.pv*a.qty)).join(', ')}<br>`;
      if(articlesSupprimés.length) lignes += `<span style="color:var(--danger)">➖ Retirés :</span> ${articlesSupprimés.map(a=>'<strong>'+esc(a.nom)+'</strong>').join(', ')}<br>`;
      if(articlesQteChange.length) lignes += `<span style="color:var(--accent)">🔄 Qté modifiée :</span> ${articlesQteChange.map(a=>{const o=_mcArticlesInitial.find(x=>x.artId===a.artId);return'<strong>'+esc(a.nom)+'</strong> : '+o.qty+' → '+a.qty;}).join(', ')}<br>`;
      lignes += `<br><span style="color:var(--muted);font-size:11px;">Ancien : ${esc(ancienContratLabel)} — ${fmt(ancienMontant)}<br>Nouveau : ${esc(ct)} — ${fmt(mt)}</span>`;
      if(noteMotif) lignes += `<br><span style="color:var(--subtle);font-size:11px;">Motif : ${esc(noteMotif)}</span>`;
      // Afficher dans un modal d'info rapide ou dans une notification enrichie
      const overlay = document.createElement('div');
      overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:12000;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(3px);';
      overlay.innerHTML=`<div style="background:var(--surface);border:1px solid rgba(201,168,76,0.4);border-radius:16px;padding:28px 30px;max-width:420px;width:94vw;box-shadow:0 20px 60px rgba(0,0,0,0.5);">
        <div style="margin-bottom:14px;line-height:1.8;">${lignes}</div>
        <button onclick="this.closest('div[style*=fixed]').remove()" style="width:100%;padding:9px;background:rgba(201,168,76,0.14);border:1px solid rgba(201,168,76,0.35);border-radius:8px;color:var(--accent);font-weight:700;font-size:13px;cursor:pointer;font-family:'Outfit',sans-serif;">✓ Compris</button>
      </div>`;
      document.body.appendChild(overlay);
    }, 400);
  }
});

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 46 — RÉSILIATION DIRECTE D'UN CLIENT (sans transfert)   ║
// ╚══════════════════════════════════════════════════════════════╝
// Jusqu'ici, un contrat ne pouvait être résilié QUE par un transfert de
// solde (page Transfert & Résiliation). Ajout d'une résiliation simple
// depuis la liste Clients : mêmes rôles que cette page (admin, chef
// d'agence, secrétaire), motif obligatoire, MÊMES champs que la
// résiliation par transfert (statutContrat 'resilie', dateResiliation,
// motifResiliation, resiliePar) — tout le reste de l'application la traite
// donc à l'identique : blocage des encaissements (volet 40), badge, totaux.
// Champ en plus : resiliationType 'simple', qui distingue cette résiliation
// d'une résiliation par transfert.
// RÉACTIVATION : admin seulement, et SEULEMENT pour une résiliation simple.
// Une résiliation par transfert se défait par « Annuler » dans Transfert &
// Résiliation, qui retire aussi le paiement transféré — la réactiver ici
// laisserait ce paiement en double.
// Le solde déjà versé n'est NI remboursé NI déplacé : c'est une décision de
// gestion, hors application (ou transfert, si l'argent passe à un autre contrat).
function _clPeutResilier(){
  return !!session && [ROLES.ADMIN, ROLES.CHEF_AGENCE, ROLES.SECRETAIRE].includes(session.role);
}
function _clRafraichirListe(){
  if(typeof curPg !== 'undefined' && curPg === 'tous-clients') renderTousCls();
}

window.resilierClient = _withActionLock((...a)=>'resilierClient:'+a.join(':'), async function(cid){
  if(!_clPeutResilier()){ notify("Accès refusé — réservé à l'admin, au chef d'agence et à la secrétaire",'err'); return; }
  const c = (DB.clients||[]).find(x => x._id === cid);
  if(!c){ notify('Client introuvable','err'); return; }
  if(c.statutContrat === 'resilie'){ notify('Ce contrat est déjà résilié','err'); return; }
  const s = statsLite(c);
  const ok = await confirmDialog(
    `Client : ${esc(c.nom)}${c.codeClient?' ('+esc(c.codeClient)+')':''}\n`+
    `Commercial : ${esc(getCom(c.commercialId).nom||'—')}\n`+
    `Déjà versé : ${fmt(s.totalPaye)} sur ${fmt(c.montantTotal||0)} (${s.pct} %)\n\n`+
    `Le contrat sera marqué RÉSILIÉ : plus aucun encaissement ne sera possible.\n`+
    `Le montant déjà versé n'est ni remboursé ni transféré par cette action`+
    ` (pour le reporter sur un autre contrat, utilisez plutôt « Transfert & Résiliation »).`,
    { title: '🚫 Résilier ce contrat ?', okLabel: 'Continuer', danger: true });
  if(!ok) return;
  const motif = (prompt(`Motif de la résiliation de ${c.nom} (obligatoire) :`) || '').trim();
  if(!motif){ notify('Résiliation abandonnée — un motif est obligatoire','err'); return; }
  try{
    await fbUpdate('clients', cid, {
      statutContrat: 'resilie',
      dateResiliation: TODAY,
      motifResiliation: motif.slice(0, 300),
      resiliePar: session.nom || session.userId,
      resilieParId: session.userId,
      resiliationType: 'simple'
    });
    notify(`✅ Contrat de ${esc(c.nom)} résilié`);
  }catch(e){
    notify('Échec de la résiliation : ' + (e.message || e), 'err');
  }
  _clRafraichirListe();
});

window.reactiverClient = _withActionLock((...a)=>'reactiverClient:'+a.join(':'), async function(cid){
  if(!session || session.role !== ROLES.ADMIN){ notify("Réactivation réservée à l'administrateur",'err'); return; }
  const c = (DB.clients||[]).find(x => x._id === cid);
  if(!c){ notify('Client introuvable','err'); return; }
  if(c.statutContrat !== 'resilie'){ notify("Ce contrat n'est pas résilié",'err'); return; }
  if(c.resiliationType !== 'simple'){
    notify("Ce contrat a été résilié par un transfert : annulez le transfert dans « Transfert & Résiliation » (cela retire aussi le paiement transféré).",'err');
    return;
  }
  const ok = await confirmDialog(
    `Réactiver le contrat de ${esc(c.nom)} ?\n\nRésilié le ${c.dateResiliation||'—'} par ${c.resiliePar||'—'}\nMotif : ${c.motifResiliation||'—'}`,
    { title: '↩ Réactiver le contrat', okLabel: 'Réactiver' });
  if(!ok) return;
  const motif = (prompt('Motif de la réactivation (obligatoire) :') || '').trim();
  if(!motif){ notify('Réactivation abandonnée — un motif est obligatoire','err'); return; }
  try{
    await fbUpdate('clients', cid, {
      statutContrat: 'actif',
      dateResiliation: null, motifResiliation: null, resiliePar: null, resilieParId: null, resiliationType: null,
      reactiveLe: TODAY, reactiveParNom: session.nom || session.userId, reactiveMotif: motif.slice(0, 300)
    });
    notify(`✅ Contrat de ${esc(c.nom)} réactivé`);
  }catch(e){
    notify('Échec de la réactivation : ' + (e.message || e), 'err');
  }
  _clRafraichirListe();
});

window.supprimerClient = _withActionLock((...a)=>'supprimerClient:'+a.join(':'), async function(cid){
  const c=getCl(cid);
  if(!(await confirmDialog(`Supprimer définitivement le client "${esc(c.nom)}" ?\n\nTous ses paiements et historique seront conservés mais le client sera retiré de la liste.`,{title:'🗑 Suppression client',okLabel:'Supprimer',danger:true}))) return;
  // ── VOLET 38 ──
  if(!(await _auditAvantSuppression('clients', cid, {
    clientId: cid, clientNom: c.nom||'', clientCode: c.codeClient||'',
    commercialId: c.commercialId||'', agenceId: c.agenceId||'',
    montant: c.totalPaye||0, date: c.debut||'',
    libelleCourt: `${c.nom||'—'}${c.codeClient?' ('+c.codeClient+')':''}`,
    extra: { contrat: c.contrat||'', montantTotal: c.montantTotal||0 }
  }))) return;
  await fbDelete('clients',cid);
  notify(`Client ${esc(c.nom)} supprimé`);
});

// ── Suppression d'un frais d'adhésion (réservé admin — règles Firestore) ──
window.supprimerAdhesionPay = _withActionLock((...a)=>'supprimerAdhesionPay:'+a.join(':'), async function(id, clientId){
  if(!session || session.role!=='admin'){ notify("Action réservée à l'administrateur", 'err'); return; }
  const a = DB.adhesionPays.find(x=>x._id===id);
  if(!a){ notify('Paiement introuvable', 'err'); return; }
  if(!(await confirmDialog(`Supprimer définitivement ce frais d'adhésion de ${fmt(a.montant)} du ${a.date} ?`,{title:"🗑 Suppression frais d'adhésion",okLabel:'Supprimer',danger:true}))) return;
  // ── VOLET 38 ──
  const _ac = clientId ? getCl(clientId) : {};
  if(!(await _auditAvantSuppression('adhesionPays', id, {
    clientId: clientId||'', clientNom: _ac.nom||'', clientCode: _ac.codeClient||'',
    commercialId: a.commercialId||'', montant: a.montant,
    date: a.date||'', heure: a.heure||'', note: a.note||'',
    libelleCourt: `${fmt(a.montant)} — ${_ac.nom||'—'}`
  }))) return;
  try{
    await fbDelete('adhesionPays', id);
    // Si le client n'a plus aucun paiement d'adhésion, on remet son statut à "non payé"
    const resteAdh = DB.adhesionPays.filter(x=>x.clientId===clientId);
    if(resteAdh.length===0){
      const c = DB.clients.find(x=>x._id===clientId);
      if(c) await fbUpdate('clients', clientId, {adhesionStatut:'non_paye'});
    }
    notify("Frais d'adhésion supprimé");
    const ficheOpen = document.getElementById('m-fiche-client')?.classList.contains('open');
    const detailOpen = document.getElementById('m-detail')?.classList.contains('open');
    if(ficheOpen && typeof ouvrirFicheClient==='function' && clientId) ouvrirFicheClient(clientId);
    if(detailOpen && typeof openDet==='function' && clientId) openDet(clientId);
    if(typeof renderControle==='function') renderControle();
  }catch(e){
    console.error('Échec suppression adhésion:', e);
    notify("Échec de la suppression — vérifiez votre connexion.", 'err');
  }
});

// ========= HELPERS =========
function fmt(n){ return Number(n||0).toLocaleString('fr-FR')+' FCFA'; }

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 27 — UN TOTAL FAUX NE DOIT PAS S'AFFICHER « 0 »        ║
// ╚══════════════════════════════════════════════════════════════╝
// LE DEFAUT. Deux fonctions voisines ne sommaient pas de la meme facon :
//     cumulLivraisons : .reduce((a,l)=>a+(Number(l.montant)||0),0)   ← protege
//     soldeClient     : .reduce((a,p)=>a+p.montant,0)                ← NON protege
// Or fmt(NaN) affiche « 0 FCFA » (Number(NaN||0) vaut 0). Il suffit donc d'UN
// SEUL paiement dont le champ `montant` est une chaine — ou absent — pour que
// toute la somme devienne NaN, ou une concatenation de chaines, et s'affiche
// comme un zero parfaitement credible. C'est exactement le symptome observe
// le 28/09/2026 : « ca dit total actualise mais affiche zero alors que le
// client n'est plus a zero ».
//
// Le meme defaut touchait _recalcClientPaiementRollup(), qui ECRIT totalPaye
// sur la fiche client : un montant en chaine y produisait un totalPaye faux,
// propage ensuite partout.
//
// CETTE FONCTION somme toujours en numerique, et DENONCE en console le
// document fautif — avec sa collection, son identifiant et la valeur en
// cause. Un chiffre faux devient ainsi tracable au lieu d'etre silencieux.
function _sommeMontants(liste, etiquette, champ){
  champ = champ || 'montant';
  let total = 0, suspects = 0, premier = null;
  for (const d of (liste || [])) {
    const brut = d ? d[champ] : undefined;
    const n = Number(brut);
    if (!Number.isFinite(n)) {
      suspects++;
      if (!premier) premier = { _id: d && d._id, valeur: brut, type: typeof brut };
      continue;                       // on ignore le document fautif, on ne casse pas le total
    }
    total += n;
  }
  if (suspects) {
    console.error(`[montant] ${suspects} document(s) de « ${etiquette||'?'} » ont un champ `
      + `« ${champ} » inutilisable et ont ete IGNORES dans le total. Premier cas :`, premier);
  }
  return total;
}

// ── Badge "correction admin" — jamais caché, toujours visible partout où
// le paiement/l'adhésion apparaît (fiche du jour, registre, historique).
// Affiche la date réelle de saisie, l'auteur et le motif au survol.
// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 30 — UNE SAISIE NE PEUT PLUS ETRE DATEE DANS LE FUTUR  ║
// ╚══════════════════════════════════════════════════════════════╝
// LE DEFAUT, constate le 29/09/2026. Une mise de 500 FCFA apparaissait sur la
// fiche du jour d'un commercial avec le badge « Correction », dont l'infobulle
// disait : « Correction saisie le 2026-07-15 par Amyrath. Motif : fiche
// 29/06/2026 ».
//
// Ce n'etait pas un defaut d'affichage. La fiche du jour lit les paiements par
// requete serveur « date == <date affichee> » : pour apparaitre le 29/09, le
// document PORTAIT REELLEMENT date = '2026-09-29'. En recoupant :
//
//   dateSaisieReelle = 2026-07-15  → la saisie a bien eu lieu le 15 juillet
//   motifCorrection  = « fiche 29/06/2026 » → l'intention etait le 29 JUIN
//   date             = 2026-09-29  → ce qui a ete enregistre
//
// L'operateur a saisi 29/09 au lieu de 29/06 — un mois errone dans le
// selecteur de date. Le paiement a alors ete POST-DATE de deux mois et demi.
// Il est reste invisible tout ce temps (aucune fiche ne portait cette date),
// puis a surgi le jour ou le calendrier l'a rattrape.
//
// Rien ne s'y opposait : ni le champ date (aucun attribut `max`), ni le
// controle a l'enregistrement, qui verifiait seulement « date != aujourd'hui »
// pour exiger un motif — sans jamais se demander de quel cote.
//
// CONSEQUENCES d'une saisie post-datee, toutes silencieuses :
//   · la recette du jour de la saisie est sous-evaluee ;
//   · le versement du commercial ne correspond plus a sa fiche ;
//   · le solde du client est credite immediatement (soldeClient somme TOUS
//     les paiements, sans filtre de date) alors que la fiche ne le montre pas ;
//   · le jour venu, une recette apparait sans que personne n'ait encaisse.
//
// CE QUI EST FAIT ICI : un refus net, au meme endroit pour les deux ecrans de
// saisie, plus l'attribut `max` sur les champs de date — la ceinture et les
// bretelles. Le message nomme la confusion la plus probable.
//
// ⚠️ LIMITE ASSUMEE : ce controle est cote navigateur. Il arrete l'erreur de
// frappe, qui est le risque reel ici ; il n'arreterait pas quelqu'un qui
// contournerait deliberement l'interface. Un controle equivalent dans les
// regles Firestore supposerait de comparer une chaine 'AAAA-MM-JJ' a l'horloge
// serveur, ce que le langage des regles ne fait pas de facon fiable — je
// prefere le dire que livrer un garde-fou approximatif.
function _dateSaisieValide(dateStr, libelle){
  if(!dateStr) return true;                       // champ vide = date du jour
  if(dateStr <= TODAY) return true;               // format AAAA-MM-JJ : comparaison lexicale = chronologique
  const [a,m,jr] = String(dateStr).split('-');
  notify(`⛔ Date impossible : ${jr}/${m}/${a} est dans le futur. `
    + `${libelle} ne peut pas être daté après aujourd'hui (${TODAY}). `
    + `Vérifiez le MOIS — une confusion entre deux mois est l'erreur la plus fréquente.`, 'err');
  return false;
}

function badgeCorrection(p){
  if(!p || !p.estCorrection) return '';
  const auteur = p.saisiParNom || 'admin';
  const dateReelle = p.dateSaisieReelle || '';
  const motif = (p.motifCorrection || '').replace(/"/g,'&quot;');
  const titre = `Correction saisie le ${dateReelle} par ${auteur}. Motif : ${motif}`;
  return `<span title="${titre}" style="display:inline-flex;align-items:center;gap:3px;margin-left:5px;background:rgba(224,92,82,0.12);border:1px solid rgba(247,97,79,0.4);border-radius:10px;padding:1px 7px;font-size:9px;font-weight:700;color:var(--danger);white-space:nowrap;">🔧 Correction</span>`;
}

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 38 — JOURNAL D'AUDIT : TRACER TOUTES LES SUPPRESSIONS  ║
// ╚══════════════════════════════════════════════════════════════╝
// CONSTAT DE DEPART. La collection 'auditLog' existait, mais SEULES DEUX
// actions y etaient ecrites : la suppression d'un paiement verrouille et
// celle d'un rachat de carnet. Les DOUZE autres suppressions de
// l'application — paiement ordinaire, mise, adhesion, livraison, mouvement
// de stock, depense, client, produit, article, utilisateur, agence, demande
// de livraison — ne laissaient AUCUNE trace.
//
// Un journal incomplet qu'on prend pour complet est plus dangereux que pas
// de journal du tout : on y cherche une suppression, on ne la trouve pas, et
// on en conclut qu'elle n'a pas eu lieu.
//
// PRINCIPE RETENU, identique a celui deja en place pour les deux actions
// existantes : LE JOURNAL EST ECRIT AVANT LA SUPPRESSION, et si le journal
// ne peut pas etre ecrit, ON NE SUPPRIME RIEN. Une suppression non tracee
// serait pire qu'une suppression refusee.

// Libelle lisible + obligation de motif, par collection.
// Le motif est EXIGE la ou l'effacement touche a l'argent ou a un client :
// ce sont les seuls cas ou, six mois plus tard, « pourquoi ? » est une
// question a laquelle personne ne saura repondre de memoire.
const _AUDIT_TYPES = {
  paiements:         { libelle: 'Paiement',              motif: true  },
  mises:             { libelle: 'Mise',                  motif: true  },
  adhesionPays:      { libelle: "Frais d'adhésion",      motif: true  },
  rachatCarnetPays:  { libelle: 'Rachat de carnet',      motif: true  },
  depenses:          { libelle: 'Dépense commerciale',   motif: true  },
  clients:           { libelle: 'Client',                motif: true  },
  livraisons:        { libelle: 'Livraison',             motif: false },
  stockMvts:         { libelle: 'Mouvement de stock',    motif: false },
  produits:          { libelle: 'Produit',               motif: false },
  articles:          { libelle: 'Article',               motif: false },
  commerciaux:       { libelle: 'Utilisateur',           motif: false },
  agences:           { libelle: 'Agence',                motif: false },
  demandesLivraison: { libelle: 'Demande de livraison',  motif: false },
  // ── Trouvees par le controle 16 de verifier.js, pas par relecture
  // manuelle : je les avais manquees toutes les trois en inventoriant les
  // suppressions. C'est exactement ce pour quoi ce garde-fou a ete ecrit.
  // `versements` porte un motif OBLIGATOIRE : annuler un versement rend a un
  // commercial le droit de saisir sur une journee deja cloturee. C'est une
  // decision de gestion, pas un reglage.
  versements:        { libelle: 'Versement (annulation)', motif: true  },
  primesPaliers:     { libelle: 'Palier de prime',        motif: false },
  paliersDuree:      { libelle: 'Palier de durée',        motif: false },
  // ── VOLET 40 ── suppression d'une ligne de l'historique des transferts.
  transferts:        { libelle: 'Transfert de contrat',    motif: true  },
  // ── VOLET 52 ──
  rouleauxMvts:      { libelle: 'Attribution de rouleaux', motif: true  }
};

function _auditLibelle(col){ return (_AUDIT_TYPES[col] || {}).libelle || col; }

// Retrouve l'agence a inscrire au journal. On la fige AU MOMENT de la
// suppression : la deduire plus tard depuis le commercial donnerait son
// agence du jour, pas celle de l'epoque — faux des le premier transfert.
function _auditAgence(infos){
  if(infos && infos.agenceId) return infos.agenceId;
  if(infos && infos.commercialId){
    const com = (DB.commerciaux||[]).find(c=>c._id===infos.commercialId);
    if(com && com.agenceId) return com.agenceId;
  }
  return null;
}

// Demande le motif quand il est exige, ecrit le journal, et renvoie true
// SEULEMENT si tout a abouti. L'appelant doit donc faire :
//     if(!(await _auditAvantSuppression('mises', id, {...}))) return;
//     await fbDelete('mises', id);
//
// `infos` accepte, toutes facultatives : clientId, clientNom, clientCode,
// commercialId, commercialNom, agenceId, montant, date, heure, note,
// libelleCourt (ce que l'admin verra dans la liste), extra (objet libre).
async function _auditAvantSuppression(col, docId, infos){
  infos = infos || {};
  const cfg = _AUDIT_TYPES[col] || { libelle: col, motif: false };

  let motif = '';
  // ── VOLET 40 ── motif déjà saisi par l'appelant (annulation d'un
  // transfert : un seul motif pour toutes les suppressions qu'elle entraîne).
  if(typeof infos.motifImpose === 'string' && infos.motifImpose.trim()){
    motif = infos.motifImpose.trim();
  } else if(cfg.motif){
    motif = (prompt(`Motif de la suppression — ${cfg.libelle} `
      + `(obligatoire, sera enregistré dans le journal d'audit) :`) || '').trim();
    if(!motif){ notify('Suppression annulée — un motif est obligatoire', 'err'); return false; }
  } else {
    // Facultatif : on le propose quand meme. Annuler la boite ne doit PAS
    // annuler la suppression — d'ou le test sur null plutot que sur ''.
    const saisi = prompt(`Motif de la suppression — ${cfg.libelle} (facultatif) :`);
    motif = (saisi === null ? '' : String(saisi)).trim();
  }

  const com = infos.commercialId
    ? ((DB.commerciaux||[]).find(c=>c._id===infos.commercialId) || {})
    : {};
  const agenceId = _auditAgence(infos);
  const ag = agenceId ? ((DB.agences||[]).find(a=>a._id===agenceId) || {}) : {};

  try {
    await fbAdd('auditLog', {
      action: 'suppression_' + col,
      collection: col,
      typeLibelle: cfg.libelle,
      documentId: docId || '',
      clientId: infos.clientId || '', clientNom: infos.clientNom || '',
      clientCode: infos.clientCode || '',
      commercialId: infos.commercialId || '',
      commercialNom: infos.commercialNom || com.nom || '',
      // ⚠️ FIGEE a l'instant de la suppression. Voir _auditAgence().
      agenceId: agenceId || '', agenceNom: ag.nom || '',
      montant: Number(infos.montant) || 0,
      date: infos.date || '', heure: infos.heure || '',
      note: infos.note || '',
      libelleCourt: infos.libelleCourt || '',
      extra: infos.extra || null,
      motif,
      effectuePar: session.userId, effectueParNom: session.nom || session.userId,
      effectueParRole: session.role,
      horodatage: new Date().toISOString(),
      horodatageJour: TODAY,
      appVersion: APP_VERSION          // ── VOLET 39 ──
    });
    return true;
  } catch(e) {
    console.error("[audit] journal non ecrit — suppression abandonnee :", col, docId, e);
    notify("⚠️ Le journal d'audit n'a pas pu être écrit — suppression annulée par prudence. "
      + ((e && e.code) ? `(${e.code})` : ''), 'err');
    return false;
  }
}

// ─── Debounce générique pour les champs de recherche/filtre ───
// Évite de re-render toute la liste à CHAQUE frappe clavier : on attend
// que l'utilisateur arrête de taper (120ms) avant de lancer le rendu.
// ✅ FIX RÉACTIVITÉ : délai réduit (250ms → 120ms, quasi instantané) et
// exécution protégée par try/catch — avant, une erreur en cours de rendu
// s'arrêtait silencieusement (aucun message, aucun plantage visible) et
// le tableau restait figé jusqu'au rechargement ou au reclic sur le menu.
// Désormais toute erreur est signalée immédiatement via notify().
const _debounceTimers = {};
function dRender(fnName, delay){
  delay = (delay === undefined || delay === null) ? 120 : delay;
  clearTimeout(_debounceTimers[fnName]);
  _debounceTimers[fnName] = setTimeout(function(){
    safeRender(fnName);
  }, delay);
}

// ✅ Exécute une fonction de rendu (par nom ou référence) en capturant
// toute exception, pour que le filtrage/la recherche ne reste JAMAIS
// bloqué(e) silencieusement — l'erreur est reportée et loggée.
function safeRender(fnOrName){
  try {
    const fn = typeof fnOrName === 'string' ? window[fnOrName] : fnOrName;
    if (typeof fn === 'function') fn();
  } catch(e) {
    console.error('[safeRender] Erreur de rendu :', fnOrName, e);
    notify('Erreur d\'affichage — réessayez ou changez de page puis revenez : '+(e.message||String(e)), 'err');
  }
}
// ✅ PERF : getCl() est appelée 44 fois dans l'app et fait un .find() linéaire
// sur DB.clients — la plus grosse collection potentielle (jusqu'à 30 000
// clients selon les commentaires du code). Indexée en Map, invalidée via
// _dbVer.clients (ajoutée ci-dessous, déjà mise à jour par _touchVer()).
let _clIdxCache = null, _clIdxVer = -1;
function _clIndex(){
  if(_clIdxCache && _clIdxVer === _dbVer.clients) return _clIdxCache;
  const m = new Map();
  for(const c of (DB.clients||[])) m.set(c._id, c);
  _clIdxCache = m; _clIdxVer = _dbVer.clients;
  return m;
}
function getCl(id){ return _clIndex().get(id)||{nom:'—',contrat:'—'}; }
// ✅ PERF : getCom() est appelée ~30 fois dans l'app, dont une fois PAR LIGNE
// de chaque tableau client affiché. Avec un .find() linéaire sur
// DB.commerciaux à chaque appel, le coût grandit avec le nombre de
// commerciaux × le nombre de lignes affichées. On indexe une seule fois
// dans une Map, invalidée automatiquement via _dbVer.commerciaux (déjà mis
// à jour par _touchVer() sur tout ajout/modif/suppression/snapshot de la
// collection 'commerciaux').
let _comIdxCache = null, _comIdxVer = -1;
function _comIndex(){
  if(_comIdxCache && _comIdxVer === _dbVer.commerciaux) return _comIdxCache;
  const m = new Map();
  for(const c of (DB.commerciaux||[])) m.set(c._id, c);
  _comIdxCache = m; _comIdxVer = _dbVer.commerciaux;
  return m;
}
function getCom(id){ return _comIndex().get(id)||{nom:'—'}; }

// ✅ PERF : index combiné produits+articles, pour remplacer le motif
// `DB.produits.find(x=>x._id===id)||DB.articles.find(x=>x._id===id)` répété
// dans les boucles de rendu des contrats clients (une recherche linéaire
// double PAR ARTICLE de contrat PAR CLIENT affiché). Invalidé via
// _dbVer.produits/_dbVer.articles (déjà mis à jour par _touchVer()).
// (clés déjà déclarées dans _dbVer ci-dessus)
let _prodArtIdxCache = null, _prodArtIdxVerP = -1, _prodArtIdxVerA = -1;
function _prodArtIndex(){
  if(_prodArtIdxCache && _prodArtIdxVerP===_dbVer.produits && _prodArtIdxVerA===_dbVer.articles) return _prodArtIdxCache;
  const m = new Map();
  for(const x of (DB.produits||[])) if(!m.has(x._id)) m.set(x._id, x);
  for(const x of (DB.articles||[])) if(!m.has(x._id)) m.set(x._id, x);
  _prodArtIdxCache = m; _prodArtIdxVerP = _dbVer.produits; _prodArtIdxVerA = _dbVer.articles;
  return m;
}
function getProdOuArticle(id){ return _prodArtIndex().get(id); }
function getArt(id){ return DB.articles.find(a=>a._id===id)||{nom:'—',unite:'pcs'}; }
function getProd(id){ return (DB.produits||[]).find(p=>p._id===id)||{nom:'—',prix:0,composition:[]}; }

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 23 — PRODUIT INDISPONIBLE A LA VENTE                   ║
// ╚══════════════════════════════════════════════════════════════╝
// LA REGLE. Un produit marque indisponible :
//   ✖ ne peut plus etre ajoute au contrat d'un client — ni a la creation
//     d'un nouveau client, ni en modification d'un contrat existant
//     (ajouter un produit a un contrat, c'est une vente, meme si le client
//      est ancien : il ne s'etait pas engage sur CE produit) ;
//   ✔ reste LIVRABLE par le staff, sans restriction de blocage ;
//   ✔ reste DEMANDABLE au gestionnaire de stock par un chef d'agence —
//     sinon l'agence ne pourrait plus faire venir la marchandise pour
//     honorer les contrats en cours, c'est-a-dire exactement ce qu'on
//     cherche a preserver.
//
// CE N'EST PAS UNE SUPPRESSION. Le produit reste en base, garde son
// historique, et revient en vente d'un clic. Les livraisons passees ne sont
// pas touchees (elles portent de toute facon leur propre copie du produit —
// voir le volet 17).
//
// L'ABSENCE DU CHAMP VAUT « DISPONIBLE » : les produits crees avant ce volet
// n'ont pas `indisponible`, et continuent donc de se comporter comme avant.
function _prodIndispo(p){ return !!(p && p.indisponible); }

// Message unique, pour que le refus soit formule pareil partout.
function _msgProdIndispo(p){
  return `🚫 « ${esc((p&&p.nom)||'Ce produit')} » est indisponible à la vente — il ne peut plus être ajouté à un contrat. Il reste livrable aux clients qui l'avaient déjà.`;
}

// Rappelle, au moment de rendre un produit indisponible, combien de clients
// l'ont deja a leur contrat : ce sont eux qui devront encore etre livres,
// et c'est l'information qui manque pour decider sereinement.
// Lecture en memoire uniquement, aucune requete Firestore.
window.prodMajBandeauDispo = function(prodOpt){
  const box = document.getElementById('prod-dispo-info');
  if(!box) return;
  const coche = !!document.getElementById('prod-indisponible')?.checked;
  const id = (prodOpt && prodOpt._id) || document.getElementById('prod-edit-id')?.value || '';
  if(!coche || !id){ box.style.display = 'none'; return; }
  // DB.clients peut n'etre chargee que partiellement selon le role et la
  // page : on annonce donc « au moins N », jamais un total ferme.
  const n = (DB.clients||[]).filter(c =>
    (c.produitsPrixFiges||[]).some(x => x.produitId === id)
    && (c.statutContrat||'actif') !== 'resilie').length;
  box.style.display = 'block';
  box.innerHTML = n > 0
    ? `⚠️ Au moins <strong>${n}</strong> client(s) actif(s) ont ce produit à leur contrat. Ils resteront livrables.`
    : `Aucun client actif n'a ce produit à son contrat, d'après les fiches chargées.`;
};

// ── AGENCES ──
function getAgence(id){ return DB.agences.find(a=>a._id===id)||{nom:'—'}; }
// Retourne l'agenceId de la session courante (null pour admin)
function sessionAgenceId(){
  if(!session || session.role===ROLES.ADMIN) return null;
  const u = DB.commerciaux.find(c=>c._id===session.userId);
  return u ? u.agenceId : null;
}
// Filtre un tableau de commerciaux par agence de session
function comsDansAgence(){
  const aid = sessionAgenceId();
  if(!aid) return DB.commerciaux; // admin voit tout
  return DB.commerciaux.filter(c=>c.agenceId===aid);
}
// Filtre les clients visibles par la session
function clientsDansAgence(){
  const aid = sessionAgenceId();
  if(!aid) return DB.clients; // admin voit tout
  const comIds = new Set(comsDansAgence().map(c=>c._id));
  return DB.clients.filter(c=>comIds.has(c.commercialId));
}
// Filtre les paiements visibles par la session
function paiementsDansAgence(){
  const aid = sessionAgenceId();
  if(!aid) return DB.paiements;
  const comIds = new Set(comsDansAgence().map(c=>c._id));
  return DB.paiements.filter(p=>comIds.has(p.commercialId));
}
// Filtre les livraisons visibles par la session
function livraisonsDansAgence(){
  const aid = sessionAgenceId();
  if(!aid) return DB.livraisons;
  const clIds = new Set(clientsDansAgence().map(c=>c._id));
  return DB.livraisons.filter(l=>clIds.has(l.clientId));
}
function jm(cl){ if(cl.cotisationJourFixe>0) return cl.cotisationJourFixe; return cl.montantTotal?Math.ceil(cl.montantTotal/cl.duree):0; }

// Calcule le cumul des livraisons (articles livrés) à déduire du solde client
// ── PERF : index mémorisés clientId → [enregistrements] ──
// Évite de refaire un .filter() sur TOUTE la collection paiements/livraisons
// pour CHAQUE client (coût O(clients × paiements) sur la page "Tous les clients").
// L'index est reconstruit uniquement quand _dbVer change (cf. _touchVer ci-dessus).
let _payIdxCache = null, _payIdxVer = -1;
function _payIndex(){
  if(_payIdxCache && _payIdxVer === _dbVer.paiements) return _payIdxCache;
  const m = new Map();
  for(const p of DB.paiements){
    if(!m.has(p.clientId)) m.set(p.clientId, []);
    m.get(p.clientId).push(p);
  }
  _payIdxCache = m; _payIdxVer = _dbVer.paiements;
  return m;
}
let _livIdxCache = null, _livIdxVer = -1;
function _livIndex(){
  if(_livIdxCache && _livIdxVer === _dbVer.livraisons) return _livIdxCache;
  const m = new Map();
  for(const l of DB.livraisons){
    if(!m.has(l.clientId)) m.set(l.clientId, []);
    m.get(l.clientId).push(l);
  }
  _livIdxCache = m; _livIdxVer = _dbVer.livraisons;
  return m;
}

function cumulLivraisons(clientId){
  const arr = _livIndex().get(clientId) || [];
  return arr.filter(l=>l.statut!=='annule').reduce((a,l)=>a+(Number(l.montant)||0),0);
}

// Solde disponible du client = total payé - cumul livraisons reçues
function soldeClient(cl){
  // ── CORRECTIF ── cette fonction sommait _payIndex() sur DB.paiements, tout
  // comme stats() le faisait avant l'option C. DB.paiements ne contenant plus
  // que la journee en cours pour un commercial / une secretaire / un chef
  // d'agence, le solde etait SOUS-EVALUE pour tout client non precharge — d'ou
  // des livraisons bloquees a tort et un "Solde dispo." faux dans le
  // formulaire. On applique donc la meme regle que stats() : on ne somme la
  // memoire que si l'historique de ce client y est reellement complet
  // (_paysComplet), sinon on lit le champ denormalise cl.totalPaye, tenu a
  // jour par _recalcClientPaiementRollup().
  // ── VOLET 27 ── la somme passe par _sommeMontants : un paiement au
  // montant inutilisable est ignore et signale, au lieu de faire basculer
  // tout le total a NaN — donc a « 0 FCFA » a l'ecran.
  const totalPaye = _paysComplet(cl._id)
    ? _sommeMontants(_payIndex().get(cl._id) || [], 'paiements du client ' + cl._id)
    : (Number(cl.totalPaye) || 0);
  const totalLiv   = cumulLivraisons(cl._id);
  return totalPaye - totalLiv;
}

// ✅ AUDIT SYNCHRO (point #1) : variante "fraîche" de soldeClient(), relue
// directement sur Firestore plutôt que sur DB.paiements/DB.livraisons en
// mémoire — mêmes principes que la vérification fraîche de adhesionStatut
// dans saveLivraison(). Sur un poste dont le listener temps réel a un léger
// retard (coupure réseau, onglet resté ouvert longtemps), le solde local
// peut être inexact au moment précis où on décide de bloquer/autoriser une
// livraison. Portée volontairement limitée à CE SEUL client
// (where('clientId','==',...), pas de pagination) : l'historique d'un
// client reste petit (quelques dizaines à quelques centaines de documents),
// donc peu coûteux — contrairement à charger paiements/livraisons en entier.
// Retourne null si la vérification est impossible (hors-ligne, erreur,
// délai dépassé) : l'appelant doit alors se replier sur soldeClient() local
// plutôt que de bloquer l'utilisateur à tort.
async function _soldeClientFrais(clientId){
  if (!db_fs || !isOnline) return null;
  try {
    const timeoutPromise = new Promise((_, reject) =>
      setTimeout(() => reject(new Error('Délai dépassé (15s)')), 15000)
    );
    const fetchPromise = Promise.all([
      getDocs(query(collection(db_fs, 'paiements'), where('clientId', '==', clientId))),
      getDocs(query(collection(db_fs, 'livraisons'), where('clientId', '==', clientId)))
    ]);
    const [snapPay, snapLiv] = await Promise.race([fetchPromise, timeoutPromise]);
    const totalPaye = snapPay.docs.reduce((a, d) => a + (Number(d.data().montant) || 0), 0);
    const totalLiv = snapLiv.docs.reduce((a, d) => {
      const l = d.data();
      return l.statut !== 'annule' ? a + (Number(l.montant) || 0) : a;
    }, 0);
    return totalPaye - totalLiv;
  } catch(e) {
    console.warn('[_soldeClientFrais] Vérification solde à jour impossible, repli sur cache local :', e);
    return null;
  }
}

// ── PERF : cache mémoïsé de stats() par client ──────────────────────────
// stats(cl) est appelée plusieurs fois pour le MÊME client dans une seule
// passe (une fois pour le tri retard-desc/cotis-desc, une ou plusieurs fois
// pour l'affichage de la ligne), sur des listes pouvant compter des
// milliers de clients. Le calcul lui-même est déjà bon marché (grâce aux
// index _payIndex()/_livIndex()), mais le refaire 2-3x par client par
// rendu reste un gaspillage évitable. On mémoïse le résultat par client,
// invalidé automatiquement si : la référence de l'objet client change
// (mise à jour de ses champs), les paiements/livraisons ont changé
// (_dbVer), ou si TODAY a changé (changement de jour).
const _statsCache = new Map(); // clientId -> {obj, verP, verL, today, result}
// ── OPTION C : registre des clients dont l'historique de paiements est
// integralement charge en memoire ───────────────────────────────────────
// DB.paiements n'etant plus exhaustive pour un commercial (voir
// _ON_DEMAND_COLS_FOR_COMMERCIAL), stats() ne peut plus supposer que
// _payIndex() contient tout. Ce Set memorise les clients pour lesquels on a
// fait une requete ciblee where('clientId','==',cid) : pour EUX, et pour eux
// seuls, _payIndex() redevient une source fiable du detail ligne par ligne.
const _paysLoadedForClient = new Set();

// Vrai si le detail des paiements de ce client est fiable en memoire.
function _paysComplet(cid) {
  return _loadedCols.has('paiements') || _paysLoadedForClient.has(cid);
}

// Charge (une seule fois) TOUS les paiements d'un client et les fusionne
// dans DB.paiements. Idempotent : un second appel ne repaye aucune lecture.
// A appeler AVANT tout ecran qui affiche ou imprime le detail des paiements
// d'un client (fiche, detail, recu, ecran de saisie).
// ⚠️ Necessite l'index paiements(clientId ASC).
async function _ensureClientPaysLoaded(cid) {
  if (!cid || _paysComplet(cid)) return;
  if (!db_fs) return;
  // ── CORRECTIF ── hors reseau, getDocs() est servi par le cache persistant
  // de Firestore, qui ne contient plus l'historique complet du client depuis
  // l'option C. Il repondrait donc SANS ERREUR avec une vue partielle, et on
  // marquerait le client "complet" a tort — ce qui autoriserait ensuite
  // _recalcClientPaiementRollup() a ecrire un totalPaye faux (voir le
  // correctif ci-dessous) et stats() a afficher un total sous-evalue.
  // Hors reseau, on ne marque donc rien : stats() et soldeClient() se
  // replient sur les champs denormalises, exacts a la derniere synchro.
  if (!isOnline) return;
  try {
    // ── CORRECTIF ── on charge AUSSI les livraisons de ce client. Le solde
    // disponible vaut (total paye - cumul livraisons) : corriger le seul
    // total paye ne suffit pas. Le listener 'livraisons' d'un commercial ne
    // couvre que ses 30 PREMIERS clients (voir _queryForCol), donc
    // cumulLivraisons() sous-comptait pour tous les autres — le solde etait
    // alors SUR-evalue et une livraison pouvait passer alors qu'elle aurait
    // du etre bloquee. Defaut anterieur a l'option C, corrige ici.
    // ── VOLET 6 ── 'adhesionPays' et 'rachatCarnetPays' ajoutees : elles
    // relevent maintenant du regime "jour courant", donc les ecrans par
    // client (fiche, detail, recu) doivent aussi les recuperer de facon
    // ciblee. Quatre requetes en parallele, toutes sur un seul client.
    const [snapPay, snapLiv, snapAdh, snapRac] = await Promise.all([
      getDocs(query(collection(db_fs,'paiements'),        where('clientId','==', cid))),
      getDocs(query(collection(db_fs,'livraisons'),       where('clientId','==', cid))),
      getDocs(query(collection(db_fs,'adhesionPays'),     where('clientId','==', cid))),
      getDocs(query(collection(db_fs,'rachatCarnetPays'), where('clientId','==', cid)))
    ]);
    const fusion = (col, snap) => {
      if (!DB[col]) DB[col] = [];
      const existing = new Map(DB[col].map(d => [d._id, d]));
      snap.docs.forEach(d => existing.set(d.id, {...d.data(), _id: d.id}));
      DB[col] = [...existing.values()];
      _touchVer(col);
    };
    fusion('paiements',        snapPay);
    fusion('livraisons',       snapLiv);
    fusion('adhesionPays',     snapAdh);
    fusion('rachatCarnetPays', snapRac);
    _paysLoadedForClient.add(cid);
  } catch(e) {
    console.error('[option C] chargement des paiements du client', cid, e);
    notify("L'historique de ce client n'a pas pu etre charge — verifiez votre connexion.", 'err');
  }
}

function stats(cl){
  const cached = _statsCache.get(cl._id);
  // ── OPTION C ── 'full' ajoute a la cle : un resultat calcule sur les
  // champs denormalises ne doit pas etre reservi apres le chargement complet
  // de l'historique du client (et inversement).
  if (cached && cached.obj === cl && cached.verP === _dbVer.paiements &&
      cached.verL === _dbVer.livraisons && cached.today === TODAY &&
      cached.full === _paysComplet(cl._id)) {
    return cached.result;
  }
  const m = jm(cl);
  const start = new Date(cl.debut), end = new Date(TODAY);
  const joursEcoules = Math.max(0, Math.floor((end-start)/86400000)+1);
  const pays = _payIndex().get(cl._id) || [];
  // ── OPTION C ── DB.paiements n'est plus forcement exhaustive (commercial :
  // journee en cours uniquement). Sommer _payIndex() sous-evaluerait alors
  // totalPaye pour tout client ayant paye avant aujourd'hui — et cette valeur
  // fausse partirait sur les recus imprimes.
  // Regle : on ne somme les paiements en memoire QUE si l'historique de ce
  // client est reellement complet (_paysComplet). Sinon on utilise le champ
  // denormalise cl.totalPaye, tenu a jour par _recalcClientPaiementRollup()
  // a chaque paiement — c'est deja la source utilisee par statsLite().
  // ⚠️ Le tableau .pays reste, lui, potentiellement partiel : tout ecran qui
  // affiche ou imprime le detail ligne par ligne DOIT appeler
  // _ensureClientPaysLoaded(cid) avant (voir les appelants patches).
  const _complet = _paysComplet(cl._id);
  const totalPaye = _complet
    // ── VOLET 27 ── voir _sommeMontants.
    ? _sommeMontants(pays, 'paiements du client ' + cl._id)
    : ((Number(cl.totalPaye)||0));
  const totalLivraisons = cumulLivraisons(cl._id);
  const soldeNet = totalPaye - totalLivraisons;
  const joursCouv = m>0?Math.floor(totalPaye/m):0;
  const pct = cl.montantTotal?Math.min(100,Math.round((totalPaye/cl.montantTotal)*100)):0;
  const joursRetard = Math.max(0,joursEcoules-joursCouv);
  const totalRestant = Math.max(0,cl.montantTotal-totalPaye);
  const paidToday = pays.some(p=>p.date===TODAY);
  const result = {m,joursEcoules,joursCouv,joursRestants:Math.max(0,cl.duree-joursCouv),joursRetard,totalPaye,totalLivraisons,soldeNet,totalRestant,pct,paidToday,pays};
  _statsCache.set(cl._id, {obj:cl, verP:_dbVer.paiements, verL:_dbVer.livraisons, today:TODAY, full:_complet, result});
  return result;
}

// ── ÉTAPE 2 DU CHANTIER (dénormalisation) : version "légère" de stats() ──
// N'utilise QUE les champs déjà dénormalisés sur le client lui-même
// (totalPaye/joursCouv/dernierPaiementDate/Heure, tenus à jour à chaque
// paiement par _recalcClientPaiementRollup, voir plus haut) — ne lit JAMAIS
// DB.paiements/_payIndex(), donc ne dépend jamais de la collection
// 'paiements' chargée en mémoire, contrairement à stats().
// À utiliser pour les écrans qui listent BEAUCOUP de clients à la fois
// (Tous les clients, Contrôle, dashboard) et n'ont besoin que du niveau/
// retard/%/dernier paiement — PAS de l'historique détaillé ligne par ligne
// (fiche complète, reçu, historique des mises) : ces écrans-là continuent
// d'utiliser stats() et son tableau .pays complet, inchangé.
// ⚠️ Ne renvoie pas .pays ni .soldeNet/.totalLivraisons (livraisons non
// dénormalisées) — à ne pas utiliser si l'écran a besoin de ces valeurs.
function statsLite(cl){
  const m = jm(cl);
  const start = new Date(cl.debut), end = new Date(TODAY);
  const joursEcoules = Math.max(0, Math.floor((end-start)/86400000)+1);
  const totalPaye = (Number(cl.totalPaye)||0);
  const joursCouv = cl.joursCouv||0;
  const pct = cl.montantTotal?Math.min(100,Math.round((totalPaye/cl.montantTotal)*100)):0;
  const joursRetard = Math.max(0,joursEcoules-joursCouv);
  const totalRestant = Math.max(0,cl.montantTotal-totalPaye);
  return {
    m, joursEcoules, joursCouv, joursRestants:Math.max(0,cl.duree-joursCouv), joursRetard,
    totalPaye, totalRestant, pct,
    dernierPaiementDate: cl.dernierPaiementDate||'', dernierPaiementHeure: cl.dernierPaiementHeure||''
  };
}

function sb(t,c){ return `<span class="sb ${c}">${t}</span>`; }
function ratio(montant,cotis){ const r=cotis>0?(montant/cotis):1; const col=r>=2?'var(--accent3)':r>=1?'var(--accent2)':'var(--muted)'; return`<span style="font-size:11px;color:${col}">${Math.round(r*10)/10}x</span>`; }
function joursEnJM(jours){ if(!jours||jours<=0) return "0/1"; const mois=Math.floor((jours-1)/31)+1; const jour=((jours-1)%31)+1; return jour+"/"+mois; }
function stockStatut(a){ if(a.stock<=0)return sb('Rupture','sr'); if(a.stock<=a.stockMin)return sb('Stock bas','sy'); return sb('OK','sg'); }
function livStatut(s){ if(s==='livre')return sb('Livré','sg'); if(s==='annule')return sb('Annulé','sr'); return sb('En attente','sy'); }
// ✅ FIX VISIBILITÉ : badge dédié "Connexion instable" — distinct de
// synchronisé/hors-ligne. Si le réseau bascule plusieurs fois en peu de
// temps (flapping Wi-Fi/4G), on l'affiche pour rassurer l'utilisateur
// (les données restent en cache local, rien n'est perdu) plutôt que de le
// laisser voir l'app clignoter sans explication.
const UNSTABLE_WINDOW_MS = 15000;   // fenêtre d'observation
const UNSTABLE_THRESHOLD = 3;       // nb de bascules dans la fenêtre pour déclarer "instable"
const UNSTABLE_CLEAR_MS  = 10000;   // durée sans nouvelle bascule avant de considérer que c'est redevenu stable
let _networkTransitions = [];
let _unstableClearTimer = null;

function _showUnstableBadge(show) {
  const el = document.getElementById('unstable-badge');
  if (el) el.style.display = show ? 'flex' : 'none';
  // ✅ Ce badge est lui aussi dans la sidebar, donc invisible sous 900px :
  // on répercute l'information sur la pastille flottante (voir
  // _syncFloatingIndicator), seul repère visible sur téléphone.
  _syncReseauInstable = !!show;
  try { _syncPanelRefresh(); } catch(e) {}
}

function _noteNetworkTransition() {
  const now = Date.now();
  _networkTransitions.push(now);
  _networkTransitions = _networkTransitions.filter(t => now - t <= UNSTABLE_WINDOW_MS);
  if (_networkTransitions.length >= UNSTABLE_THRESHOLD) {
    _showUnstableBadge(true);
    if (_unstableClearTimer) clearTimeout(_unstableClearTimer);
    _unstableClearTimer = setTimeout(() => {
      _networkTransitions = [];
      _showUnstableBadge(false);
    }, UNSTABLE_CLEAR_MS);
  }
}

let _lastSyncStatusOk = null;
let _lastSyncOkRaw = true; // dernier état réseau connu, pour re-rendre la barre quand seul le compteur change
function setSyncStatus(ok){
  _lastSyncOkRaw = ok;
  // ✅ DÉTAIL SYNCHRO : la clé de déduplication inclut désormais le nombre
  // d'opérations en attente, sinon le compteur affiché resterait figé quand
  // seul ce nombre change (l'état `ok`, lui, ne bouge pas). Le garde-fou
  // anti-saccades reste entier : on ne réécrit le DOM que si l'affichage
  // change réellement.
  const _nbAttente = (typeof _offlineQueue !== 'undefined' && _offlineQueue) ? _offlineQueue.length : 0;
  const _cle = String(ok) + '|' + _nbAttente;
  if (_lastSyncStatusOk === _cle) return; // ✅ FIX SACCADES : évite de réécrire le DOM si l'état est inchangé (appelé à chaque onSnapshot, potentiellement très fréquent en connexion instable)
  _lastSyncStatusOk = _cle;
  const el = document.getElementById('sync-status');
  if (!el) return;
  const _couleur = _nbAttente ? 'var(--accent3, var(--accent))' : (ok ? 'var(--accent2)' : 'var(--accent3)');
  // Avant : « Synchronisé » s'affichait même avec des saisies encore en file
  // d'attente sur l'appareil — message rassurant mais faux. On indique
  // maintenant explicitement le nombre de saisies non transmises.
  const _libelle = _nbAttente
    ? (_nbAttente + ' saisie(s) non transmise(s)')
    : (ok ? 'Synchronisé' : 'Synchronisation...');
  el.innerHTML = `<div class="sync-dot" style="background:${_couleur}"></div><span style="color:${_couleur}">${_libelle}</span>`;
  el.style.cursor = 'pointer';
  el.title = 'Cliquer pour voir le détail de la synchronisation';
}

// ========= SÉCURITÉ : échappement HTML anti-XSS =========
// ✅ PERF : une seule passe sur la chaîne (regex combinée + table de
// correspondance) au lieu de 5 .replace() séquentiels qui reparcourent
// la chaîne à chaque fois. esc() est appelée un très grand nombre de fois
// par rendu (chaque champ texte de chaque ligne client/produit/paiement),
// donc réduire son coût unitaire compte sur les grandes listes.
const _ESC_MAP = { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' };
const _ESC_RE = /[&<>"']/g;
function esc(s){
  if(s == null) return '';
  return String(s).replace(_ESC_RE, c => _ESC_MAP[c]);
}
window.esc = esc;

// ✅ Échappement sûr pour une cellule d'export CSV (RFC 4180 : encadrée de
// guillemets, guillemets internes doublés) — ET neutralisation de
// l'injection de formule Excel/LibreOffice (recommandation OWASP) : si la
// valeur commence par =, +, -, @ ou une tabulation, un tableur peut
// l'interpréter comme le début d'une formule au lieu d'un texte. On
// préfixe alors d'une apostrophe, invisible à l'ouverture, qui force
// l'interprétation en texte brut.
// ⚠️ Ne PAS utiliser esc() (échappement HTML, pour innerHTML) dans un
// export CSV : il transformerait par exemple "&" en "&amp;" dans le
// fichier ouvert par l'utilisateur, ce qui est incorrect pour du texte brut.
function _csvCell(v){
  let s = (v==null) ? '' : String(v);
  if(/^[=+\-@\t\r]/.test(s)) s = "'" + s;
  return '"' + s.replace(/"/g,'""') + '"';
}

// ╔══════════════════════════════════════════════════════════════╗
// ║  MODULE: AUTH                                                 ║
// ║  Extraction: node extract-modules.js → js/auth.js            ║
// ╚══════════════════════════════════════════════════════════════╝
// ========= LOGIN =========
function showLogin(){
  fillLogin();
  document.getElementById('login-screen').classList.remove('hidden');
}

function fillLogin(){
  // Réinitialise les champs de connexion
  const u = document.getElementById('login-user');
  if(u) u.value = '';
}

// ── POINT 4 CORRIGÉ : verrou anti-brute-force DOUBLE couche ──
// Couche 1 : localStorage (client) — rapide, bloque immédiatement
// Couche 2 : Firestore 'loginAttempts' (serveur) — résiste au changement
//            de navigateur, d'appareil, ou au vidage du cache
const _LGA_PALIERS = [60000, 300000, 1800000, 7200000]; // 1min,5min,30min,2h
function _lgaKey(key){ return '_lga_' + key.replace(/[^a-z0-9._-]/gi,'_'); }
function _getLoginAttempt(key){
  try{ return JSON.parse(localStorage.getItem(_lgaKey(key)) || '{"count":0,"until":0,"cycles":0}'); }
  catch(e){ return {count:0,until:0,cycles:0}; }
}
function _setLoginAttempt(key,val){ try{ localStorage.setItem(_lgaKey(key), JSON.stringify(val)); }catch(e){} }

// Verrou serveur Firestore — clé = email normalisé (minuscules), doit correspondre
// EXACTEMENT à request.auth.token.email.lower() côté règles pour permettre le reset sécurisé.
function _lgsKey(email){ return String(email).trim().toLowerCase().slice(0,150); }

async function _checkServerLock(email) {
  if (!db_fs) return null; // mode local : pas de verrou serveur
  try {
    const snap = await getDoc(doc(db_fs, 'loginAttempts', _lgsKey(email)));
    if (!snap.exists()) return null;
    return snap.data();
  } catch(e) { return null; }
}

async function _incServerLock(email) {
  if (!db_fs) return;
  try {
    const key = _lgsKey(email);
    const ref = doc(db_fs, 'loginAttempts', key);
    const snap = await getDoc(ref);
    if (!snap.exists()) {
      await setDoc(ref, { count: 1, windowStart: serverTimestamp() });
    } else {
      const d = snap.data();
      const windowMs = 60 * 1000;
      const windowStart = d.windowStart?.toDate ? d.windowStart.toDate() : new Date(d.windowStart);
      if (Date.now() - windowStart.getTime() > windowMs) {
        await setDoc(ref, { count: 1, windowStart: serverTimestamp() });
      } else {
        await updateDoc(ref, { count: (d.count||0) + 1 });
      }
    }
  } catch(e) { /* non bloquant */ }
}

async function _resetServerLock(email) {
  if (!db_fs) return;
  try {
    await setDoc(doc(db_fs, 'loginAttempts', _lgsKey(email)), { count: 0, windowStart: serverTimestamp() });
  } catch(e) {}
}
window.doLogin = _withActionLock('doLogin', async function(){
  const raw = (document.getElementById('login-user').value || '').trim().toLowerCase();
  const pinRaw = document.getElementById('login-pin').value;
  const errEl = document.getElementById('login-err');

  if (!raw || !pinRaw) {
    errEl.textContent = 'Veuillez saisir votre email et mot de passe.';
    errEl.style.display = 'block';
    return;
  }

  // ── Couche 1 : verrou localStorage (immédiat) ──
  const now = Date.now();
  const att = _getLoginAttempt(raw);
  if(att.until > now){
    const resteS = Math.ceil((att.until - now) / 1000);
    const msg = resteS > 90 ? `réessayez dans ${Math.ceil(resteS/60)} min` : `réessayez dans ${resteS} s`;
    errEl.textContent = `Trop de tentatives — ${msg}`;
    errEl.style.display = 'block';
    return;
  }

  // ── Couche 2 : verrou serveur Firestore (résiste au changement d'appareil) ──
  const serverLock = await _checkServerLock(raw);
  if (serverLock && serverLock.count >= 5) {
    const windowStart = serverLock.windowStart?.toDate ? serverLock.windowStart.toDate() : new Date(serverLock.windowStart);
    const elapsed = Date.now() - windowStart.getTime();
    if (elapsed < 60000) {
      const resteS = Math.ceil((60000 - elapsed) / 1000);
      errEl.textContent = `Trop de tentatives (serveur) — réessayez dans ${resteS} s`;
      errEl.style.display = 'block';
      return;
    }
  }

  try {
    let emailToUse = raw;
    if (!raw.includes('@')) {
      // ✅ Les commerciaux ne sont chargés qu'après auth.
      // On tente d'abord via la liste en mémoire (si déjà chargée),
      // sinon on demande à l'utilisateur d'utiliser son email.
      const u = DB.commerciaux.find(c => c.nom.toLowerCase() === raw);
      if (u && u.email) {
        emailToUse = u.email.toLowerCase();
      } else {
        throw new Error('Veuillez utiliser votre adresse email pour vous connecter.');
      }
    }

    const userCred = await signInWithEmailAndPassword(auth, emailToUse, pinRaw);
    const firebaseUid = userCred.user.uid;

    await ensureCollectionsLoaded(['commerciaux', 'commerciauxPrive', 'agences']);
    _mergeCommerciaux();
    // ✅ FIX BASCULE DE RÔLE : on cherche UNIQUEMENT par UID Firebase (source de vérité).
    // Chercher aussi par email causait des collisions si deux documents ont le même email.
    let u = DB.commerciaux.find(c => c._id === firebaseUid);
    // Fallback email uniquement si l'UID ne correspond à aucun document (migration)
    if (!u) u = DB.commerciaux.find(c => c.email && c.email.toLowerCase() === emailToUse);
    // 🔄 FIX CACHE PÉRIMÉ : si rien ne correspond, le cache IndexedDB local de
    // cet appareil (sans expiration, voir _cacheWrite) peut simplement être
    // plus vieux que la fiche Firestore (compte créé/corrigé après la dernière
    // synchronisation de ce navigateur). Avant de conclure à un profil manquant,
    // on force UNE relecture réseau fraîche de commerciaux/commerciauxPrive
    // (uniquement ces 2 collections, pas les autres — ne ralentit pas le login
    // normal) et on retente la comparaison une seule fois.
    if (!u) {
      await idbDelete(_SS_PREFIX + 'commerciaux');
      await idbDelete(_SS_PREFIX + 'commerciauxPrive');
      DB.commerciaux = []; DB.commerciauxPrive = [];
      _loadedCols.delete('commerciaux'); _loadedCols.delete('commerciauxPrive');
      await ensureCollectionsLoaded(['commerciaux', 'commerciauxPrive']);
      _mergeCommerciaux();
      u = DB.commerciaux.find(c => c._id === firebaseUid);
      if (!u) u = DB.commerciaux.find(c => c.email && c.email.toLowerCase() === emailToUse);
    }
    if (!u) {
      await signOut(auth);
      // 🔎 DIAGNOSTIC : on n'affiche plus seulement le message générique, on ajoute
      // de quoi identifier la cause exacte sans avoir à fouiller la console Firebase.
      const _diagN = DB.commerciaux.length;
      const _diagProche = DB.commerciaux.find(c => c.email && c.email.toLowerCase().trim() === emailToUse.trim());
      let _diag = `[Diag] UID=${firebaseUid} | email=${emailToUse} | ${_diagN} fiche(s) commerciaux chargée(s)`;
      if (_diagN === 0) {
        _diag += ' — AUCUNE fiche chargée (vérifiez les règles de sécurité Firestore sur la collection commerciaux)';
      } else if (_diagProche) {
        _diag += ` — une fiche a cet email mais un ID document différent (ID=${_diagProche._id}) : mettez à jour l'ID du document pour qu'il soit égal à l'UID ci-dessus`;
      } else {
        _diag += ' — aucune fiche commerciaux avec cet email : vérifiez le champ email de la fiche';
      }
      throw new Error(`Profil utilisateur introuvable dans la base. Contactez l'administrateur. ${_diag}`);
    }
    // ✅ FIX RÔLE MANQUANT : si le champ role est absent ou vide, bloquer la connexion.
    // Sans cette garde, session.role vaut undefined et l'app traite l'utilisateur
    // comme un commercial par défaut (comportement des conditions if/else).
    const _VALID_ROLES = ['admin','commercial','secretaire','gestionnaire_stock','controleur','chef_agence'];
    if (!u.role || !_VALID_ROLES.includes(u.role)) {
      await signOut(auth);
      throw new Error(`Rôle utilisateur invalide ou manquant ("${u.role || 'vide'}"). Contactez l'administrateur.`);
    }

    // Succès — réinitialiser les deux verrous
    _setLoginAttempt(raw, {count:0, until:0, cycles:0});
    await _resetServerLock(raw);
    errEl.style.display = 'none';
    session = {userId: u._id, role: u.role, nom: u.nom};
    _sessionInvalidHandled = false; // ✅ FIX : réarme le garde-fou pour la nouvelle session
    _resetSessionTimer();
    _startTokenRefresh(); // Point 5 : démarrer le rafraîchissement proactif
    _startAlertesLivraison(); // 🔔 Alertes carnet terminé / produit prêt à livrer

  } catch(e) {
    // Incrémenter les deux verrous
    att.count = (att.count || 0) + 1;
    if(att.count >= 5){
      const cycle = Math.min(att.cycles || 0, _LGA_PALIERS.length - 1);
      att.until = now + _LGA_PALIERS[cycle];
      att.cycles = (att.cycles || 0) + 1;
      att.count = 0;
    }
    _setLoginAttempt(raw, att);
    await _incServerLock(raw); // verrou serveur

    const resteMin = att.until > now ? Math.ceil((att.until - now) / 60000) : 0;
    let msg = e.message || 'Identifiant ou mot de passe incorrect.';
    if (e.code === 'auth/wrong-password' || e.code === 'auth/invalid-credential' || e.code === 'auth/user-not-found') {
      msg = att.until > now
        ? (resteMin <= 1 ? 'Trop de tentatives — compte bloqué 1 minute' : `Trop de tentatives — compte bloqué ${resteMin} minutes`)
        : `Email ou mot de passe incorrect (${att.count}/5)`;
    } else if (e.code === 'auth/invalid-email') {
      msg = 'Adresse email invalide.';
    } else if (e.code === 'auth/too-many-requests') {
      msg = 'Trop de tentatives — Firebase a temporairement bloqué ce compte.';
    }
    errEl.textContent = msg;
    errEl.style.display = 'block';
    return;
  }
  // ── VOLET 12 ── toute la sequence de demarrage a ete extraite dans
  // _demarrerSessionApp() ci-dessous, pour etre reutilisee TELLE QUELLE par
  // la restauration de session apres mise a jour. Dupliquer ces ~40 lignes
  // aurait garanti une derive : une correction faite ici et oubliee la-bas.
  await _demarrerSessionApp();
});

// ╔══════════════════════════════════════════════════════════════╗
// ║  DEMARRAGE DE L'APPLICATION APRES AUTHENTIFICATION            ║
// ╚══════════════════════════════════════════════════════════════╝
// Appelee a deux endroits, avec exactement le meme effet :
//   1. apres une connexion par mot de passe (gestionnaire ci-dessus) ;
//   2. apres une restauration de session suite a une mise a jour
//      (_tenterRestaurationSession, plus bas).
// Prerequis dans les deux cas : `session` est deja renseignee.
async function _demarrerSessionApp() {
  // ── VOLET 19 ── purge des caches de schema anterieur. Volontairement NON
  // attendue : c'est un nettoyage d'espace disque, il ne doit pas retarder
  // l'affichage d'une seule milliseconde. Place ici, et non a l'evaluation du
  // module, parce que _idbOpen et _IDB_STORE sont declares plus bas dans le
  // fichier — a l'evaluation, ils ne seraient pas encore initialises.
  // ── VOLET 25 ── remplace _cachePurgerAnciennesVersions() du volet 19 :
  // meme role, mais etendu a l'instantane hors ligne et aux etats
  // d'interface, et pilote par _STOCKAGE_VERSION.
  _stockageVerifierVersion().catch(e => console.warn('[stockage] :', e));

  document.getElementById('login-screen').classList.add('hidden');
  // ── VOLET 74 (#1) ── nouvelle session → re-verrouiller et recharger la config
  // de visibilité (le déverrouillage ne survit pas à une reconnexion).
  _visUnlocked = false; _VIS.loaded = false; try{ _visCharger(); }catch(e){}
  // ── VOLET 60 ── information unique sur la géolocalisation des encaissements.
  // Non attendue : purement informatif, ne doit pas retarder l'affichage.
  _geoInfoUnique();
  // FIX 2 : clé AES dérivée de l'UID Firebase + secret appareil (plus du mot de passe)
  if (session.role ===ROLES.COMMERCIAL) {
    await _initLocalKey(session.userId); // UID Firebase, jamais le mot de passe
    await loadLocalDataEncrypted();
    // ⚠️ FIX PERTE SILENCIEUSE : si _loadOfflineQueue() a été appelée plus
    // tôt (ex: au boot, avant que la clé locale existe) et avait dû
    // reporter la lecture faute de clé, on la relit maintenant que
    // _localKey est prête — sans ça, une file chiffrée déjà présente sur
    // l'appareil pouvait rester invisible pour tout le reste de la session.
    if (_offlineQueueLoadPending) await _loadOfflineQueue();
  }
  // ── VOLET 10 : RENDU OPTIMISTE ────────────────────────────────────────
  // loadLocalDataEncrypted() vient de restaurer le snapshot chiffre de
  // l'appareil : DB.clients, DB.commerciaux, etc. sont DEJA en memoire.
  // Jusqu'ici l'application attendait pourtant la fin du chargement reseau
  // (ensureCollectionsLoaded) ET du re-chiffrement avant d'afficher quoi que
  // ce soit — l'agent regardait un ecran vide alors que ses donnees etaient
  // deja la, sur son propre telephone.
  //
  // Desormais : si le snapshot contient de quoi afficher, on affiche TOUT DE
  // SUITE, puis le reseau rafraichit en arriere-plan (les listeners temps
  // reel declenchent leur propre re-rendu, voir setupPageListeners).
  //
  // Condition stricte : il faut au minimum retrouver l'utilisateur connecte
  // dans DB.commerciaux. Sinon (toute premiere connexion sur cet appareil,
  // snapshot absent ou illisible), on garde l'ancien comportement : on
  // attend les donnees. Mieux vaut un ecran d'attente qu'une interface vide
  // et fausse.
  const _snapshotUtilisable =
    Array.isArray(DB.commerciaux) && DB.commerciaux.some(c => c._id === session.userId);

  let _appAffichee = false;
  function _afficherApp() {
    if (_appAffichee) return;
    _appAffichee = true;
    setupUI();
    go(getRoleHome(session.role));
    buildBottomNav(session.role);
    bnGo(getRoleHome(session.role));
  }
  if (_snapshotUtilisable) _afficherApp();

  // Pré-charger les collections terrain pour le mode offline (commercial uniquement)
  if (session.role ===ROLES.COMMERCIAL && isOnline) {
    // ── OPTION C ── 'paiements' retiree du snapshot hors-ligne. C'est elle
    // qui faisait exploser _encryptLocal(DB) a la connexion. Les soldes
    // restent exacts hors reseau grace aux champs denormalises du client
    // (totalPaye / joursCouv / dernierPaiementDate). Contrepartie assumee :
    // le detail ligne par ligne d'un client n'est plus consultable sans
    // reseau ; la saisie et l'impression de recu continuent de fonctionner
    // via la file d'attente chiffree.
    const terrainCols = ['clients','mises','adhesionPays','commerciaux','agences','primesPaliers'];
    await ensureCollectionsLoaded(terrainCols);
    // ── VOLET 10 ── PLUS DE `await` ICI.
    // _doSaveLocalEncrypted() serialise et chiffre tout le perimetre
    // hors-ligne (voir _OFFLINE_SNAPSHOT_COLS). A la connexion, l'app venait
    // de DECHIFFRER ce meme snapshot (loadLocalDataEncrypted) pour le
    // RE-CHIFFRER aussitot — souvent a l'identique — et l'affichage attendait
    // la fin de cette operation. Sur un telephone d'entree de gamme avec
    // ~2000 clients, cela represente des secondes d'ecran vide.
    // Le snapshot est un confort hors-ligne, jamais une donnee metier : rien
    // ne justifie qu'il retarde l'affichage. On passe donc par la version
    // DEBOUNCEE (600 ms), qui s'execute apres le premier rendu et regroupe
    // les appels rapproches.
    //
    // NB : je n'ai volontairement PAS ajoute de "sauter si rien n'a change".
    // Le compteur _dbVer ne couvre que 6 collections sur les 11 du snapshot
    // (voir sa declaration) : un tel raccourci pourrait laisser le snapshot
    // hors-ligne perime sans qu'on s'en apercoive. Le rendre non bloquant
    // suffit a regler le probleme d'affichage, sans ce risque.
    saveLocalEncrypted();
  }
  setupRealtimeListeners();
  chatInit();
  _notifBellInit();
  await _loadOfflineQueue();
  _updateOfflineBadge();
  // ✅ FIX SYNCHRO (audit temps réel, point #1) : jusqu'ici, une file
  // d'attente rechargée ici (opérations saisies hors-ligne lors d'une
  // session précédente, jamais rejouées) ne se synchronisait QUE si une
  // vraie transition réseau hors-ligne→en ligne se produisait pendant que
  // l'app restait ouverte (voir _applyOnlineState). Au démarrage, `isOnline`
  // est positionné directement à `true` (voir initFB) sans jamais passer par
  // cette transition — donc une mise/paiement resté(e) en attente pouvait ne
  // JAMAIS se synchroniser tant qu'aucune coupure réseau n'avait lieu,
  // malgré un reçu déjà délivré au client. On tente donc aussi la
  // resynchronisation ici, dès la connexion, si on est en ligne. Volontairement
  // pas attendu (pas de `await`) : ne doit pas retarder l'affichage de
  // l'application — _replayOfflineQueue() gère elle-même son propre statut
  // de synchro et se termine sans rien casser si la file est vide.
  if (isOnline) _replayOfflineQueue();
  // ── VOLET 10 ── si le rendu optimiste a deja eu lieu, cet appel ne fait
  // rien ; sinon (premiere connexion sur l'appareil) il affiche l'app
  // maintenant que les donnees sont la — comportement d'avant, inchange.
  _afficherApp();
  // Rafraichissement apres le rendu optimiste : les donnees reseau sont
  // arrivees APRES le premier affichage, on redessine la page courante pour
  // qu'elle les reflete. Les listeners temps reel font de meme de leur cote,
  // mais ce rendu explicite evite d'attendre leur premier snapshot.
  if (_snapshotUtilisable && session && curPg) {
    try { renderPg(curPg); } catch(e) { console.warn('[demarrage] re-rendu apres chargement :', e); }
  }
}


// ═══════════ MOT DE PASSE OUBLIÉ (écran de connexion) ═══════════
// ✅ Ajouté en complément du bouton admin existant (resetPasswordCom) : un
// utilisateur qui connaît son adresse email peut désormais déclencher lui-
// même l'envoi d'un lien de réinitialisation, sans dépendre de l'admin.
// Fonctionne AVANT authentification (sendPasswordResetEmail ne nécessite
// pas d'être connecté) — mais nécessite de connaître son EMAIL : avant
// connexion, DB.commerciaux n'est pas chargée (voir doLogin : "les
// commerciaux ne sont chargés qu'après auth"), donc impossible de résoudre
// un simple nom d'utilisateur en email ici. D'où la note invitant à
// contacter l'admin si l'email n'est pas connu.
window.ouvrirMotDePasseOublie = function(){
  document.getElementById('login-form-normal').style.display = 'none';
  document.getElementById('login-forgot-link-wrap').style.display = 'none';
  document.getElementById('login-btn-confirm').style.display = 'none';
  document.getElementById('login-err').style.display = 'none';
  document.getElementById('login-form-forgot').style.display = '';
  document.getElementById('login-forgot-actions').style.display = 'flex';
  document.getElementById('forgot-err').style.display = 'none';
  document.getElementById('forgot-ok').style.display = 'none';
  // Pré-remplir avec l'identifiant déjà saisi s'il ressemble à un email
  const raw = (document.getElementById('login-user').value || '').trim();
  document.getElementById('forgot-email').value = raw.includes('@') ? raw : '';
  document.getElementById('forgot-email').focus();
};

window.fermerMotDePasseOublie = function(){
  document.getElementById('login-form-forgot').style.display = 'none';
  document.getElementById('login-forgot-actions').style.display = 'none';
  document.getElementById('forgot-err').style.display = 'none';
  document.getElementById('forgot-ok').style.display = 'none';
  document.getElementById('login-form-normal').style.display = '';
  document.getElementById('login-forgot-link-wrap').style.display = '';
  document.getElementById('login-btn-confirm').style.display = '';
};

window.envoyerResetMotDePasse = _withActionLock('envoyerResetMotDePasse', async function(){
  const email = (document.getElementById('forgot-email').value || '').trim().toLowerCase();
  const errEl = document.getElementById('forgot-err');
  const okEl = document.getElementById('forgot-ok');
  errEl.style.display = 'none';
  okEl.style.display = 'none';
  if(!email || !email.includes('@')){
    errEl.textContent = 'Veuillez saisir une adresse email valide.';
    errEl.style.display = 'block';
    return;
  }
  const btn = document.getElementById('forgot-btn-confirm');
  if(btn){ btn.disabled = true; btn.textContent = '⏳ Envoi…'; }
  try{
    await sendPasswordResetEmail(auth, email);
  }catch(e){
    // ✅ Volontairement pas de distinction "compte inexistant" ici (contrairement
    // à resetPasswordCom côté admin) : révéler qu'un email n'est associé à
    // aucun compte serait une fuite d'information sur l'écran de connexion,
    // public par nature. Seule une vraie erreur technique (réseau, email mal
    // formé détecté côté serveur, quota Firebase) affiche un message distinct.
    if(e?.code === 'auth/invalid-email'){
      errEl.textContent = 'Adresse email invalide.';
      errEl.style.display = 'block';
      if(btn){ btn.disabled = false; btn.textContent = 'Envoyer le lien'; }
      return;
    }
    if(e?.code === 'auth/too-many-requests'){
      errEl.textContent = 'Trop de tentatives — réessayez plus tard.';
      errEl.style.display = 'block';
      if(btn){ btn.disabled = false; btn.textContent = 'Envoyer le lien'; }
      return;
    }
    if(e?.code !== 'auth/user-not-found'){
      console.warn('[envoyerResetMotDePasse] Erreur inattendue :', e);
    }
    // user-not-found (et tout autre cas non géré ci-dessus) → même message
    // générique que le succès, volontairement.
  }
  if(btn){ btn.disabled = false; btn.textContent = 'Envoyer le lien'; }
  document.getElementById('login-form-forgot').style.display = 'none';
  document.getElementById('login-forgot-actions').style.display = 'none';
  okEl.style.display = 'block';
});

window.doLogout = async function(){
  // ── VOLET 59 ── AVANT tout le reste (et donc avant signOut) : la règle
  // pushTokens exige d'être encore connecté pour supprimer son jeton.
  try{ await _pushDesinscrire(); }catch(_){}
  // ✅ Indispensable maintenant que les listeners sont persistants entre
  // navigations : sans ça, les listeners (filtrés sur l'ancien utilisateur)
  // resteraient actifs et seraient réutilisés à tort pour le prochain login.
  _unsubscribeAll();
  chatTeardown();
  clearInterval(_alertesLivraisonInterval); // ✅ stopper les rappels de livraison
  session = null;
  _localKey = null; // C2 — effacer la clé AES de la mémoire
  _clearCryptoWorkerKey(); // idem côté worker de chiffrement
  _offlineQueue = [];
  // ✅ RAPPORT DE SYNCHRO : le journal local contient des noms de clients et
  // des montants. Sur un appareil partagé, l'utilisateur suivant ne doit pas
  // pouvoir consulter l'historique du précédent. On l'efface donc de la
  // mémoire ET du disque à la déconnexion, comme la file d'attente.
  _syncJournalLocal = [];
  _syncJournalLocalCharge = false;
  _syncJournalServeur = [];
  _syncServeurMessage = '';
  try { window.fermerDetailSynchro && window.fermerDetailSynchro(); } catch(e) {}
  try { document.getElementById('sync-float-pill')?.remove(); } catch(e) {}
  idbDelete(_SYNC_JOURNAL_KEY + '_enc').catch(()=>{});
  idbDelete(_SYNC_JOURNAL_KEY).catch(()=>{});
  _stopSessionTimer();
  _loadedCols.clear();
  // Déconnexion Firebase Auth
  if (auth) { try { signOut(auth); } catch(e){} }
  document.getElementById('login-screen').classList.remove('hidden');
  document.getElementById('login-pin').value = '';
  fillLogin();
  // ✅ FIX LATENCE + FIX QUOTA : vider le cache (désormais IndexedDB, voir
  // plus haut) à la déconnexion pour qu'un autre utilisateur ne voie pas les
  // données du précédent. Fait en dernier et attendu (await) : l'UI de
  // login s'affiche immédiatement sans attendre, mais on est sûr que le
  // cache est bien vidé avant qu'un prochain _loadCol() ne puisse le relire.
  await _cacheClear();
};

// ========= TIMEOUT DE SESSION (inactivité 8h) =========
// ✅ Allongé de 3h à 8h (durée d'une journée de travail) pour tout le monde.
const SESSION_TIMEOUT_MS = 8 * 60 * 60 * 1000; // 8 heures
let _sessionTimer = null;
let _sessionWarningTimer = null;
// ── VOLET 32 ── instant de la derniere interaction reelle de l'utilisateur.
// Pose a la connexion, mis a jour a chaque clic/frappe/toucher.
let _derniereActivite = 0;
let _tokenRefreshInterval = null; // Point 5 : rafraîchissement proactif du token

function _resetSessionTimer() {
  if (!session) return;
  if (!_derniereActivite) _derniereActivite = Date.now();   // ── VOLET 32 ──
  clearTimeout(_sessionTimer);
  clearTimeout(_sessionWarningTimer);
  _sessionWarningTimer = setTimeout(() => {
    if (session) notify('⚠️ Session inactive — déconnexion dans 2 minutes', 'warn');
  }, SESSION_TIMEOUT_MS - 2 * 60 * 1000);
  _sessionTimer = setTimeout(() => {
    if (session) {
      notify('🔒 Session expirée — veuillez vous reconnecter', 'err');
      window.doLogout();
    }
  }, SESSION_TIMEOUT_MS);
}

function _stopSessionTimer() {
  // ── VOLET 32 ── une session arretee n'a plus d'activite : sans cette
  // remise a zero, un marqueur pose juste apres une deconnexion paraitrait
  // provenir d'une session vivante.
  _derniereActivite = 0;
  clearTimeout(_sessionTimer);
  clearTimeout(_sessionWarningTimer);
  clearInterval(_tokenRefreshInterval);
  _sessionTimer = null;
  _sessionWarningTimer = null;
  _tokenRefreshInterval = null;
}

// ── POINT 5 CORRIGÉ : révocation serveur détectée en temps réel ──
// onAuthStateChanged est déclenché par Firebase dès que le token est
// révoqué (suppression du compte, désactivation, déconnexion forcée).
// Plus besoin d'attendre l'expiration du token (1 heure).
// FIX BLOCAGE UI : cet appel était fait directement au niveau racine du
// script, donc exécuté immédiatement au chargement de la page — avant
// même que 'auth' soit initialisé par initFB(). Cela provoquait un crash
// synchrone qui interrompait tout le reste du script (ADMIN_NAV, COM_NAV,
// getRoleNav, etc. n'étaient alors jamais définis → menu invisible après
// connexion). On encapsule donc l'inscription dans une fonction, appelée
// uniquement quand 'auth' existe réellement.
let _authStateListenerRegistered = false;
// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 12 — MISE A JOUR SANS REDEMANDER LE MOT DE PASSE       ║
// ╚══════════════════════════════════════════════════════════════╝
// CONSTAT : Firebase Auth reste connecte apres un rechargement (aucun
// setPersistence() n'est appele, donc la persistance par defaut
// browserLocalPersistence s'applique, en IndexedDB). En revanche l'objet
// `session` de l'application, lui, est perdu : il n'est affecte QU'A UN SEUL
// endroit, dans le gestionnaire du formulaire de connexion. Et
// onAuthStateChanged ne traitait que le cas inverse (`!firebaseUser &&
// session`). D'ou l'ecran de connexion apres chaque mise a jour.
//
// CHOIX RETENU (option A) : la session n'est restauree QUE juste apres une
// mise a jour, jamais lors d'une ouverture normale. Le confort est apporte
// la ou il compte, sans relacher la securite ailleurs : au demarrage du
// lendemain, ou sur un telephone rallume, le mot de passe reste exige.
//
// Le minuteur d'inactivite (8 h), le rafraichissement de jeton (50 min) et
// la revocation serveur continuent de fonctionner a l'identique.
const _MAJ_MARQUEUR = 'gestcom_maj_reload';
const _MAJ_FENETRE_MS = 60 * 1000; // le marqueur n'est valable qu'une minute

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 32 — « SESSION ACTIVE » DEVIENT UNE VRAIE CONDITION    ║
// ╚══════════════════════════════════════════════════════════════╝
// AVANT : le marqueur etait pose des lors qu'un compte Firebase etait
// connecte (auth.currentUser). Or `auth.currentUser` survit tres largement a
// la session applicative : le jeton Firebase reste valide, et il est
// rafraichi automatiquement toutes les 50 minutes, meme quand l'agent n'a
// plus touche l'appareil depuis des heures.
//
// Autrement dit, une mise a jour survenant APRES l'expiration de la session
// (8 h d'inactivite) reconnectait quand meme l'agent — silencieusement.
// C'est precisement ce qui a ete signale : « ca reconnecte de suite sans
// savoir si la personne etait en session active ou pas ».
//
// DESORMAIS, trois conditions cumulatives, verifiees a la POSE du marqueur :
//   1. une session applicative existe (l'objet `session`) ;
//   2. le compte Firebase connecte est BIEN celui de cette session ;
//   3. la derniere interaction reelle date de moins que le delai
//      d'inactivite (8 h).
// La condition 3 est REVERIFIEE a la consommation, pour que le temps passe
// hors ligne pendant le rechargement compte lui aussi.
//
// Si l'une manque : aucun marqueur, donc ecran de connexion apres le
// rechargement. C'est le comportement demande — retrouver son ecran si la
// session etait active, redemander les identifiants sinon.
function _majPoserMarqueur() {
  try {
    if (!session || !session.userId) return;                    // 1
    const uid = auth && auth.currentUser ? auth.currentUser.uid : null;
    if (!uid || uid !== session.userId) return;                 // 2
    const inactif = Date.now() - (_derniereActivite || 0);
    if (!_derniereActivite || inactif >= SESSION_TIMEOUT_MS) {   // 3
      console.info('[maj] session inactive depuis trop longtemps — reconnexion exigée après la mise à jour.');
      return;
    }
    sessionStorage.setItem(_MAJ_MARQUEUR, JSON.stringify({
      t: Date.now(), uid, act: _derniereActivite
    }));
  } catch (e) { /* stockage indisponible : on retombe sur l'ecran de connexion */ }
}

// Consomme le marqueur : il est EFFACE des la premiere lecture, qu'il soit
// valide ou non. Un marqueur ne peut donc jamais servir deux fois.
function _majConsommerMarqueur(uid) {
  try {
    const brut = sessionStorage.getItem(_MAJ_MARQUEUR);
    sessionStorage.removeItem(_MAJ_MARQUEUR);
    if (!brut) return false;
    const m = JSON.parse(brut);
    if (!m || typeof m.t !== 'number') return false;
    if (Date.now() - m.t > _MAJ_FENETRE_MS) return false; // trop ancien
    if (m.uid && uid && m.uid !== uid) return false;      // pas le meme compte
    // ── VOLET 32 ── on reverifie l'inactivite ICI. Le rechargement peut avoir
    // dure (reseau lent, telephone qui rame) ; c'est l'ecart avec la derniere
    // ACTIVITE REELLE qui compte, pas celui avec la pose du marqueur.
    if (typeof m.act !== 'number' || (Date.now() - m.act) >= SESSION_TIMEOUT_MS) {
      console.info('[maj] session expirée pendant le rechargement — reconnexion exigée.');
      return false;
    }
    return true;
  } catch (e) { return false; }
}

let _restaurationEnCours = false;

async function _tenterRestaurationSession(firebaseUser) {
  if (_restaurationEnCours || session || !firebaseUser) return;
  if (!_majConsommerMarqueur(firebaseUser.uid)) return; // pas une mise a jour
  _restaurationEnCours = true;
  try {
    // Meme resolution du profil qu'a la connexion : on retrouve la fiche
    // 'commerciaux' dont l'id est l'UID Firebase.
    await ensureCollectionsLoaded(['commerciaux', 'commerciauxPrive']);
    if (typeof _mergeCommerciaux === 'function') _mergeCommerciaux();
    const u = DB.commerciaux.find(c => c._id === firebaseUser.uid);
    const _ROLES_VALIDES = ['admin','commercial','secretaire','gestionnaire_stock','controleur','chef_agence'];
    if (!u || !u.role || !_ROLES_VALIDES.includes(u.role)) {
      // Profil introuvable ou role invalide : on ne restaure rien, l'ecran de
      // connexion reste affiche. Meme prudence qu'a la connexion normale.
      console.warn('[maj] restauration abandonnee : profil introuvable ou role invalide');
      return;
    }
    session = { userId: u._id, role: u.role, nom: u.nom };
    _sessionInvalidHandled = false;
    _resetSessionTimer();
    _startTokenRefresh();
    _startAlertesLivraison();
    // _demarrerSessionApp() redérive la cle locale (_initLocalKey) et
    // recharge la file hors-ligne chiffree : sans cela l'agent retrouverait
    // son ecran mais perdrait l'acces a ses saisies en attente.
    await _demarrerSessionApp();
    notify('✅ Mise à jour installée — vous êtes resté connecté', 'ok');
  } catch (e) {
    console.error('[maj] echec de la restauration de session :', e);
    session = null;
    _stopSessionTimer();
    // Repli explicite : l'ecran de connexion doit rester utilisable.
    const ls = document.getElementById('login-screen');
    if (ls) ls.classList.remove('hidden');
    notify("La session n'a pas pu être restaurée — veuillez vous reconnecter.", 'err');
  } finally {
    _restaurationEnCours = false;
  }
}

function _registerAuthStateListener() {
  if (_authStateListenerRegistered || !auth) return;
  _authStateListenerRegistered = true;
  onAuthStateChanged(auth, async (firebaseUser) => {
    // ── VOLET 12 ── cas qui n'etait traite NULLE PART : authentifie cote
    // Firebase mais sans session applicative — exactement l'etat au
    // redemarrage qui suit une mise a jour.
    if (firebaseUser && !session) {
      await _tenterRestaurationSession(firebaseUser);
      return;
    }
    if (!firebaseUser && session) {
      // Firebase a révoqué la session côté serveur
      notify('🔒 Session révoquée — veuillez vous reconnecter', 'err');
      session = null;
      _localKey = null;
      _clearCryptoWorkerKey(); // idem côté worker de chiffrement
      _offlineQueue = [];
      _stopSessionTimer();
      document.getElementById('login-screen').classList.remove('hidden');
      document.getElementById('login-pin').value = '';
      fillLogin();
    }
  });
}
// Si 'auth' est déjà disponible à ce stade (cas rare), on s'enregistre tout
// de suite ; sinon initFB() se chargera de l'appeler après getAuth(app).
_registerAuthStateListener();

// Rafraîchissement proactif du token toutes les 50 min (token Firebase = 1h)
// Détecte aussi une révocation lors du rafraîchissement
function _startTokenRefresh() {
  clearInterval(_tokenRefreshInterval);
  _tokenRefreshInterval = setInterval(async () => {
    if (!auth?.currentUser || !session) { clearInterval(_tokenRefreshInterval); return; }
    try {
      await auth.currentUser.getIdToken(true); // force=true = appel réseau
    } catch(e) {
      // getIdToken échoue si le compte a été désactivé ou supprimé
      notify('🔒 Session expirée ou révoquée — veuillez vous reconnecter', 'err');
      window.doLogout();
    }
  }, 50 * 60 * 1000); // 50 minutes
}

// ═══════════════ 🔔 ALERTES : carnet terminé / produit prêt à livrer ═══════
// Objectif : réduire les oublis d'enregistrement de livraison.
// - Alerte A : le client a atteint la durée de son carnet (ex: 372 jours
//   couverts par ses paiements) — le carnet est terminé.
// - Alerte B : le client a déjà payé assez pour couvrir le prix d'un
//   article de son contrat, mais cet article ne lui a pas encore été
//   livré (soldeNet = payé - déjà livré >= prix de l'article).
// Tant que la livraison correspondante n'est pas enregistrée, l'alerte
// revient périodiquement (elle ne se déclenche pas qu'une seule fois) —
// c'est justement pour éviter l'oubli.
const _ALERTES_LIV_INTERVAL_MS = 20 * 60 * 1000;   // vérifie toutes les 20 min
const _ALERTES_LIV_RENOTIF_MS  = 3 * 60 * 60 * 1000; // ne re-notifie le MÊME client/produit qu'après 3h
let _alertesLivraisonInterval = null;

function _alertesLivLastNotifKey(){
  return 'gestcom_alertes_liv_' + (session ? session.userId : 'anon');
}
function _alertesLivLireCache(){
  try { return JSON.parse(localStorage.getItem(_alertesLivLastNotifKey())||'{}'); }
  catch(e){ return {}; }
}
function _alertesLivEcrireCache(cache){
  try { localStorage.setItem(_alertesLivLastNotifKey(), JSON.stringify(cache)); } catch(e){}
}

// Quantité déjà livrée d'un article donné pour un client (livraisons au
// statut réellement "livré", pas en attente/annulée — même logique que le
// filtre corrigé dans dessinerTopProduits()).
function _qtyLivreeArticle(clientId, artId){
  return (DB.livraisons||[])
    .filter(l => l.clientId===clientId && l.produitId===artId &&
      (l.statut==='livre'||l.statut==='livré'||l.statut==='livre_partiel'))
    .reduce((s,l)=>s+(Number(l.qty)||0), 0);
}

function verifierAlertesLivraison(){
  if(!session) return;
  // ✅ Les commerciaux ne doivent plus recevoir AUCUNE notification concernant
  // des clients (y compris leurs propres clients) — ces alertes de livraison
  // portent justement sur des clients, donc on coupe entièrement pour ce rôle.
  if(session.role === ROLES.COMMERCIAL) return;
  const clients = clientsDansAgence();

  const cache = _alertesLivLireCache();
  const maintenant = Date.now();
  const alertes = []; // {client, type, titre, corps}

  for(const cl of clients){
    const s = stats(cl);

    // ── Alerte A : carnet terminé (durée atteinte, ex: 372 jours) ──
    const duree = cl.duree || 372;
    if(s.joursCouv >= duree && s.totalRestant <= 0){
      alertes.push({
        cl, type:'carnet_termine',
        titre: `📘 Carnet terminé — ${cl.nom}`,
        corps: `${cl.nom} a atteint les ${duree} jours de son carnet (entièrement payé). Vérifiez que tout a bien été livré/clôturé.`
      });
    }

    // ── Alerte B : produit déjà payé mais pas encore livré ──
    if(cl.contratArticles && cl.contratArticles.length){
      for(const a of cl.contratArticles){
        const qtyLivree = _qtyLivreeArticle(cl._id, a.artId);
        if(qtyLivree >= (a.qty||1)) continue; // déjà entièrement livré
        const prixUnitaire = Number(a.pv)||0;
        if(prixUnitaire > 0 && s.soldeNet >= prixUnitaire){
          alertes.push({
            cl, type:'produit_pret_'+a.artId,
            titre: `📦 Livraison à faire — ${cl.nom}`,
            corps: `${cl.nom} a déjà payé de quoi couvrir "${a.nom||'un produit'}" (solde dispo: ${fmt(s.soldeNet)}) — livraison pas encore enregistrée.`
          });
        }
      }
    }
  }

  // Filtrer selon le délai de re-notification (pour "revenir de temps en
  // temps" sans spammer à chaque vérification).
  const aNotifier = alertes.filter(al=>{
    const key = al.cl._id+'|'+al.type;
    const dernier = cache[key] || 0;
    return (maintenant - dernier) >= _ALERTES_LIV_RENOTIF_MS;
  });

  // Nettoyer le cache des entrées dont la condition n'est plus vraie
  // (livraison entre-temps enregistrée) pour ne pas le laisser grossir indéfiniment.
  const clesActives = new Set(alertes.map(al=>al.cl._id+'|'+al.type));
  Object.keys(cache).forEach(k=>{ if(!clesActives.has(k)) delete cache[k]; });

  if(!aNotifier.length){ _alertesLivEcrireCache(cache); return; }

  aNotifier.forEach(al=>{
    const key = al.cl._id+'|'+al.type;
    cache[key] = maintenant;
    // Onglet visible et actif → notification interne (toast) discrète.
    // Onglet caché/en arrière-plan → notification navigateur, pour ne pas
    // manquer le rappel même sans regarder l'app (même logique que le chat).
    if(document.hidden || !document.hasFocus()){
      _alerteLivNotifNavigateur(al.titre, al.corps, al.cl._id);
    } else {
      notify(`${al.titre} — ${al.corps}`, al.type==='carnet_termine' ? 'success' : '', al.cl._id);
    }
  });
  _alertesLivEcrireCache(cache);
}

// ⛔ RÉVOQUÉ (pour le moment, à la demande) : notification NAVIGATEUR pour les
// alertes livraison (carnet terminé / produit prêt à livrer, côté clients).
// L'alerte interne à l'app (toast, voir verifierAlertesLivraison() →
// notify()) reste active quand l'onglet est visible/actif — seule la
// notification système du navigateur (et la demande de permission associée,
// voir _startAlertesLivraison() ci-dessous) est désactivée. Pour réactiver :
// restaurer le corps de fonction précédent (garder ce commentaire comme repère).
function _alerteLivNotifNavigateur(titre, corps, clientId){
  return;
}

function _startAlertesLivraison(){
  clearInterval(_alertesLivraisonInterval);
  // ⛔ RÉVOQUÉ : ne plus demander la permission de notification navigateur au
  // titre des alertes livraison (voir _alerteLivNotifNavigateur ci-dessus).
  // Le chat, lui, continue de la demander de son côté (chatInit() →
  // chatDemanderPermissionNotif()) — non concerné par cette révocation.
  // Premier passage peu après la connexion (laisse le temps aux données de charger),
  // puis vérification périodique tant que la session est active.
  setTimeout(()=>{ try{ verifierAlertesLivraison(); }catch(e){ console.error('[alertes livraison]', e); } }, 15000);
  _alertesLivraisonInterval = setInterval(()=>{
    if(!session){ clearInterval(_alertesLivraisonInterval); return; }
    try{ verifierAlertesLivraison(); }catch(e){ console.error('[alertes livraison]', e); }
  }, _ALERTES_LIV_INTERVAL_MS);
}

// Réinitialiser le timer à chaque interaction utilisateur
// ── VOLET 32 ── on retient AUSSI l'instant de la derniere activite. Le
// minuteur d'inactivite vit en memoire : il disparait au rechargement. Sans
// cet horodatage, impossible de savoir APRES une mise a jour si la session
// etait encore active ou deja expiree — c'est exactement ce qui permettait
// une reconnexion silencieuse alors que l'agent n'etait plus vraiment en
// session.
['click','keydown','mousemove','touchstart'].forEach(evt => {
  document.addEventListener(evt, () => {
    if (session) { _derniereActivite = Date.now(); _resetSessionTimer(); }
  }, { passive: true });
});

// ╔══════════════════════════════════════════════════════════════╗
// ║  MODULE: CHAT D'ASSISTANCE (tous rôles)                       ║
// ║  Collections Firestore : chatConversations / chatMessages /   ║
// ║  chatTyping — indépendantes du moteur DB[col] générique       ║
// ║  (flux temps réel léger, non chargé en pagination complète).  ║
// ╚══════════════════════════════════════════════════════════════╝
const CHAT_ROLE_LABELS = {admin:'Administrateur',commercial:'Commercial',secretaire:'Secrétaire',
  gestionnaire_stock:'Gest. de stock',controleur:'Contrôleur',chef_agence:"Chef d'Agence",comptable:'Comptable'};

// ── Modèle : messagerie many-to-many. Un id de conversation = paire d'UID
// triée alphabétiquement : "uidA__uidB". N'importe quel rôle peut écrire à
// n'importe quel autre rôle (plus de distinction staff/non-staff).
function _chatPairId(a,b){ return [a,b].sort().join('__'); }
function _chatOtherUid(convId){
  const conv = _chatConversations.get(convId);
  if(conv?.participants) return conv.participants.find(u=>u!==session.userId) || conv.participants[0];
  const parts = String(convId).split('__');
  return parts.find(u=>u!==session.userId) || parts[0];
}

let _chatConvId = null;            // conversation actuellement ouverte dans le fil
let _chatConversations = new Map();// toutes mes conversations, convId -> data
let _chatMessages = [];            // messages de la conversation actuellement ouverte
let _chatConvListReady = false;    // évite les notifications sur le snapshot initial
let _chatDernierNotifTs = new Map();// ── VOLET 75 ── convId -> updatedAt du dernier message déjà signalé. Survit aux ré-abonnements (retour au premier plan) ; vidé seulement à la connexion (chatInit). Empêche d'avaler OU de rejouer une notification.
let _chatMsgsReady = false;
let _chatTypingSentAt = 0;
let _chatTypingResetTimer = null;
let _chatPanelOpen = false;
// ✅ RÉPONSE OBLIGATOIRE (commercial) : non-null = id de la conversation dont
// le dernier message vient du staff et reste sans réponse. Tant que non-null,
// le panneau de chat est forcé ouvert en plein écran et ne peut pas être
// fermé (voir _chatEvaluateForcedBlock / chatToggle). Redevient null dès que
// le commercial répond (ou si un admin/staff prend la main sur son compte).
let _chatForcedBlockConvId = null;

function _chatHeureNow(){
  const n = new Date();
  return String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0');
}
function _chatInitiales(nom){
  if(!nom) return '?';
  const parts = String(nom).trim().split(/\s+/);
  return ((parts[0]?.[0]||'')+(parts[1]?.[0]||'')).toUpperCase() || nom[0].toUpperCase();
}

// ── Bulle déplaçable (glisser-déposer, position mémorisée) ──
let _chatDragInitDone = false;
function _chatInitDrag(){
  if(_chatDragInitDone) return;
  const bubble = document.getElementById('chat-bubble');
  if(!bubble) return;
  _chatDragInitDone = true;

  // Restaure la position sauvegardée
  try{
    const saved = JSON.parse(localStorage.getItem('chatBubblePos')||'null');
    if(saved && typeof saved.left==='number' && typeof saved.top==='number'){
      _chatApplyPos(saved.left, saved.top);
    }
  }catch(_){}

  let dragging = false, moved = false, startX=0, startY=0, startLeft=0, startTop=0;

  function onDown(ev){
    const p = ev.touches ? ev.touches[0] : ev;
    dragging = true; moved = false;
    const rect = bubble.getBoundingClientRect();
    startX = p.clientX; startY = p.clientY;
    startLeft = rect.left; startTop = rect.top;
    bubble.classList.add('dragging');
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
    document.addEventListener('touchmove', onMove, {passive:false});
    document.addEventListener('touchend', onUp);
  }
  function onMove(ev){
    if(!dragging) return;
    const p = ev.touches ? ev.touches[0] : ev;
    const dx = p.clientX - startX, dy = p.clientY - startY;
    if(Math.abs(dx)>4 || Math.abs(dy)>4) moved = true;
    if(moved && ev.cancelable) ev.preventDefault();
    let left = startLeft + dx, top = startTop + dy;
    const w = bubble.offsetWidth, h = bubble.offsetHeight;
    left = Math.max(4, Math.min(window.innerWidth - w - 4, left));
    top = Math.max(4, Math.min(window.innerHeight - h - 4, top));
    _chatApplyPos(left, top);
  }
  function onUp(){
    if(!dragging) return;
    dragging = false;
    bubble.classList.remove('dragging');
    document.removeEventListener('mousemove', onMove);
    document.removeEventListener('mouseup', onUp);
    document.removeEventListener('touchmove', onMove);
    document.removeEventListener('touchend', onUp);
    if(moved){
      const rect = bubble.getBoundingClientRect();
      try{ localStorage.setItem('chatBubblePos', JSON.stringify({left:rect.left, top:rect.top})); }catch(_){}
      // Empêche le clic (ouverture du chat) juste après un glisser
      bubble.dataset.justDragged = '1';
      setTimeout(()=>{ delete bubble.dataset.justDragged; }, 50);
    }
  }
  bubble.addEventListener('mousedown', onDown);
  bubble.addEventListener('touchstart', onDown, {passive:true});
  // Bloque l'ouverture du panneau si ce clic suit immédiatement un glisser
  bubble.addEventListener('click', (ev)=>{
    if(bubble.dataset.justDragged){ ev.stopImmediatePropagation(); ev.preventDefault(); }
  }, true);

  // Repositionne si la fenêtre est redimensionnée (évite que la bulle sorte de l'écran)
  window.addEventListener('resize', ()=>{
    const rect = bubble.getBoundingClientRect();
    const w = bubble.offsetWidth, h = bubble.offsetHeight;
    const left = Math.max(4, Math.min(window.innerWidth - w - 4, rect.left));
    const top = Math.max(4, Math.min(window.innerHeight - h - 4, rect.top));
    if(bubble.style.left) _chatApplyPos(left, top);
  });
}
function _chatApplyPos(left, top){
  const bubble = document.getElementById('chat-bubble');
  if(!bubble) return;
  bubble.style.left = left+'px';
  bubble.style.top = top+'px';
  bubble.style.right = 'auto';
  bubble.style.bottom = 'auto';
}
// Démarré une seule fois à la connexion (comme setupRealtimeListeners()).
function chatInit(){
  if(!session || !db_fs) return;
  _chatConversations.clear();
  _chatMessages = [];
  _chatConvId = null;
  _chatConvListReady = false;
  _chatDernierNotifTs.clear();   // ── VOLET 75 ── repart de zéro à chaque connexion
  _chatMsgsReady = false;

  const bubble = document.getElementById('chat-bubble');
  if(bubble) bubble.style.display = 'flex';
  _chatInitDrag();
  chatDemanderPermissionNotif();
  _pushInscrire();   // ── VOLET 59 ── ne fait rien si la permission n'est pas accordée
  ensureCollectionsLoaded(['commerciaux']).catch(()=>{});

  document.getElementById('chat-hdr-title').textContent = '💬 Messagerie';
  document.getElementById('chat-hdr-sub').textContent = 'Sélectionnez une conversation';
  const newBtn = document.getElementById('chat-hdr-new');
  if(newBtn) newBtn.style.display = 'inline-block';
  _chatSubscribeConvList();
  _chatStartPeriodicServerCheck();
}

async function _chatEnsureConversation(convId, otherUid){
  const other = DB.commerciaux.find(c=>c._id===otherUid) || {};
  await setDoc(doc(db_fs,'chatConversations',convId), {
    participants: [session.userId, otherUid].sort(),
    names: {[session.userId]: session.nom, [otherUid]: other.nom||'—'},
    roles: {[session.userId]: session.role, [otherUid]: other.role||''},
    updatedAt: Date.now()
  }, {merge:true});
}

// ✅ FIX COÛT FIREBASE : l'admin écoutait auparavant TOUTE la collection
// 'chatConversations' sans aucun filtre, en permanence dès la connexion (pas
// seulement à l'ouverture du panneau chat) — une conversation qui n'a plus
// bougé depuis des mois restait quand même écoutée en temps réel. Chaque
// message envoyé par n'importe quel membre du personnel, n'importe où,
// déclenchait un événement facturé pour chaque admin connecté, et le coût
// grossissait avec (nb total de conversations créées depuis le début) ×
// (fréquence des messages) × (admins connectés) — sans jamais redescendre.
// On restreint désormais la vue admin aux conversations actives dans les
// _CHAT_ADMIN_ACTIVE_WINDOW_MS derniers jours (30 j par défaut, réglable
// ci-dessous). Une conversation dormante plus ancienne ne coûte plus rien
// tant qu'elle ne reçoit pas un nouveau message (qui met à jour 'updatedAt'
// et la fera réapparaître dans la fenêtre au prochain (re)chargement).
const _CHAT_ADMIN_ACTIVE_WINDOW_MS = 30 * 24 * 60 * 60 * 1000; // 30 jours

// ── Liste de MES conversations (commercial/staff) OU des conversations
// ACTIVES récemment (admin — supervision de la messagerie) ──
function _chatSubscribeConvList(){
  const isAdminView = session.role === ROLES.ADMIN;
  const colRef = collection(db_fs,'chatConversations');
  const q = isAdminView
    ? query(colRef, where('updatedAt','>', Date.now()-_CHAT_ADMIN_ACTIVE_WINDOW_MS), orderBy('updatedAt','desc'))
    : query(colRef, where('participants','array-contains',session.userId));
  const unsub = onSnapshot(q, snap => {
    let totalUnread = 0;
    snap.forEach(d => {
      const data = {...d.data(), _id:d.id};
      _chatConversations.set(d.id, data);
      if(isAdminView){
        // ✅ L'admin n'étant pas participant, il n'a pas de compteur
        // unread[uid] alimenté par les autres utilisateurs. On se base donc
        // sur un horodatage "vu par l'admin" (adminSeenAt), comparé à la
        // date du dernier message — 1 conversation avec activité non vue
        // par l'admin = +1 sur le badge.
        const dernierMsg = data.updatedAt || 0;
        const vuLe = data.adminSeenAt?.[session.userId] || 0;
        if(data.lastAuthorId && data.lastAuthorId !== session.userId && dernierMsg > vuLe){
          totalUnread++;
        }
      } else {
        // ✅ Comportement généralisé à tous les utilisateurs (aligné sur celui
        // de l'admin) : 1 point par CONVERSATION ayant des messages non lus,
        // et non plus le nombre réel de messages cumulés dans unread[uid].
        if((data.unread?.[session.userId] || 0) > 0) totalUnread++;
      }
    });
    // Suppression des conversations disparues côté serveur (rare)
    const liveIds = new Set(); snap.forEach(d=>liveIds.add(d.id));
    for(const id of [..._chatConversations.keys()]) if(!liveIds.has(id)) _chatConversations.delete(id);

    // ── VOLET 75 ── Notification FIABLE en premier plan.
    // AVANT : tout ce bloc n'était exécuté que si _chatConvListReady était
    // vrai ; or _chatForceResumeSync (retour au premier plan sur mobile) le
    // remettait à false, si bien que le message arrivé juste avant le
    // ré-abonnement n'était NI sonné NI signalé à la cloche.
    // MAINTENANT : on mémorise, PAR conversation, le updatedAt du dernier
    // message déjà signalé (_chatDernierNotifTs). Ce suivi survit aux
    // ré-abonnements et n'est vidé qu'à la connexion. On signale donc tout
    // message dont le updatedAt a RÉELLEMENT augmenté depuis la dernière fois :
    // jamais deux fois le même, et jamais toutes les conversations au
    // démarrage (1er snapshot = amorçage silencieux de la mémoire).
    snap.docChanges().forEach(ch=>{
      if(ch.type!=='modified' && ch.type!=='added') return;
      const d = {...ch.doc.data(), _id:ch.doc.id};
      const ts = d.updatedAt || 0;
      const vuTs = _chatDernierNotifTs.get(d._id) || 0;
      // ── VOLET 42 ── « conversation affichée » = panneau OUVERT sur elle.
      const _convAffichee = _chatPanelOpen && d._id === _chatConvId;
      const estNouveau = d.lastAuthorId && d.lastAuthorId !== session.userId && ts > vuTs;
      // _chatConvListReady=false UNIQUEMENT au tout premier snapshot après la
      // connexion : on amorce alors la mémoire sans sonner (sinon toutes les
      // conversations existantes sonneraient au démarrage).
      if(_chatConvListReady && estNouveau && !_convAffichee){
        const nomExp = d.names?.[d.lastAuthorId] || 'un utilisateur';
        // Pour l'admin, préciser aussi le destinataire (conversation entre 2 tiers)
        const autreNom = isAdminView
          ? (d.participants||[]).map(p=>d.names?.[p]).find(n=>n && n!==nomExp)
          : null;
        const libelle = autreNom ? `${nomExp} → ${autreNom}` : nomExp;
        playChatNotifSound();
        notify(`💬 Nouveau message de ${libelle}`);
        if(document.hidden || !document.hasFocus()){
          chatNotifNavigateur(`💬 ${libelle}`, d.lastMsg||'Nouveau message');
        }
      }
      // Mémorise le dernier updatedAt vu (signalé, amorcé, ou conversation
      // ouverte) pour ne JAMAIS re-signaler le même message, y compris après
      // un ré-abonnement au retour au premier plan.
      if(ts > vuTs) _chatDernierNotifTs.set(d._id, ts);
    });
    _chatConvListReady = true;
    _chatUpdateBadge(totalUnread);
    // ✅ RÉOUVERTURE FORCÉE (à la demande, remplace l'ancien déclenchement par
    // évènement révoqué ci-dessus) : côté COMMERCIAL uniquement, si un message
    // du staff reste sans réponse, le panneau de chat est forcé en plein écran
    // et ne peut plus être fermé tant que le commercial n'a pas répondu (voir
    // _chatEvaluateForcedBlock ci-dessous). Contrairement à l'ancien
    // déclenchement "sur évènement" (qui pouvait se rejouer à chaque
    // redémarrage de l'écouteur — voir _chatForceResumeSync — tant que le
    // message restait sans réponse), celui-ci est "à l'état" : il se
    // recalcule à chaque snapshot à partir de l'état réel (y a-t-il UN
    // message non répondu, oui/non), donc aucun risque de boucle — et il ne
    // ferme/ne perturbe jamais l'écran en dessous (simple overlay CSS, pas de
    // navigation ni de perte de saisie en cours).
    _chatEvaluateForcedBlock();
    if(_chatPanelOpen && !_chatConvId) renderChatConvList();
    if(_chatPanelOpen && _chatConvId) renderChatConvList(); // maj discrète du badge liste en arrière-plan
  }, err => console.error('[chat] listener conversations', err));
  _activeListeners.set('chat_conv_list', unsub);
}

// ── Filet de sécurité (mobile) : vérification périodique côté serveur ──
// L'écouteur temps réel (_chatSubscribeConvList, ci-dessus) est censé capter
// toute nouvelle conversation instantanément. En pratique, sur mobile, le
// cache local Firestore met parfois du temps à "découvrir" un document qu'il
// n'a JAMAIS vu auparavant (typiquement : le tout premier message d'une
// personne avec qui on n'a jamais discuté), surtout sur connexion instable —
// contrairement à la mise à jour d'une conversation déjà connue, qui elle
// arrive normalement sans problème. On rattrape donc ce cas précis toutes les
// 20s (app au premier plan uniquement) avec une lecture qui CONTOURNE le
// cache local (getDocsFromServer) pour être sûr de refléter l'état réel.
let _chatPeriodicTimer = null;
function _chatStartPeriodicServerCheck(){
  if(_chatPeriodicTimer) return;
  // FIX COÛT FIREBASE : 20s → 3 minutes. C'est un simple filet de sécurité
  // de secours (le onSnapshot temps réel gère déjà la synchro normale) —
  // pas besoin d'une fréquence aussi élevée pour un rôle de rattrapage.
  _chatPeriodicTimer = setInterval(_chatServerCheckOnce, 180000);
}
async function _chatServerCheckOnce(){
  if(!db_fs || !session || document.hidden) return;
  try{
    const isAdminView = session.role === ROLES.ADMIN;
    const colRef = collection(db_fs,'chatConversations');
    // Même filtre par activité récente que _chatSubscribeConvList (voir plus
    // haut) — ce filet de sécurité ne doit pas re-parcourir les conversations
    // dormantes que le listener temps réel a volontairement exclues.
    const q = isAdminView
      ? query(colRef, where('updatedAt','>', Date.now()-_CHAT_ADMIN_ACTIVE_WINDOW_MS), orderBy('updatedAt','desc'))
      : query(colRef, where('participants','array-contains',session.userId));
    // ⚠️ FIX COÛT FIREBASE : getDocsFromServer() forçait une lecture facturée
    // en base à CHAQUE appel (toutes les 20s, par utilisateur connecté),
    // en ignorant volontairement le cache local — alors que le onSnapshot
    // temps réel actif en parallèle maintient déjà ce cache à jour sans
    // frais supplémentaire. Résultat mesuré : ~2,25M lectures/jour pour
    // seulement 15-50 utilisateurs (x300 par rapport à l'attendu), la
    // majorité venant très probablement de cette fonction.
    // getDocsFromCache() est GRATUITE (aucune lecture facturée) : elle lit
    // uniquement les données déjà synchronisées localement par le listener
    // temps réel, qui reste la véritable source de vérité comme le
    // rappelle le commentaire ci-dessous. En cas d'échec (cache vide,
    // listener pas encore initialisé), on retombe sur une vraie lecture
    // serveur classique (getDocs, qui respecte le cache Firestore standard,
    // contrairement à getDocsFromServer qui le contourne systématiquement).
    // ✅ FIX BADGE MUET SUR MOBILE : sur certains navigateurs mobiles, le
    // cache persistant IndexedDB de Firestore peut ne jamais se peupler
    // correctement (quota de stockage restreint, navigation privée, profil
    // Chrome particulier...) SANS lever d'erreur — getDocsFromCache() renvoie
    // alors un résultat VIDE en silence au lieu d'échouer, et ce filet de
    // sécurité croit à tort qu'il n'y a aucune conversation. Comme le
    // listener temps réel principal (onSnapshot) s'appuie sur ce même cache,
    // il reste alors bloqué à 0 en permanence — même après un rechargement
    // complet de la page, puisque le cache local reste vide d'une session à
    // l'autre sur cet appareil. On ne fait donc confiance à un résultat de
    // cache VIDE que si on a la preuve qu'il n'y a vraiment rien à voir
    // (aucune conversation déjà connue en mémoire) ; sinon on force une
    // vraie lecture serveur pour se rattraper — rare, donc sans impact sur
    // le coût Firebase (l'essentiel du trafic passe encore par le cache).
    let snap;
    try {
      snap = await getDocsFromCache(q);
      // Résultat vide ET rien de connu en mémoire non plus : on ne peut pas
      // distinguer "vraiment aucune conversation" de "cache local jamais
      // peuplé sur cet appareil" — on vérifie donc auprès du serveur pour
      // lever le doute (peu fréquent : ce check ne tourne que toutes les 3
      // minutes, et se re-fera confiance au cache dès qu'il aura une donnée).
      if (snap.empty) {
        snap = await getDocs(q);
      }
    } catch(cacheErr) {
      snap = await getDocs(q);
    }
    let totalUnread = 0;
    snap.forEach(d=>{
      const data = {...d.data(), _id:d.id};
      const isNewConv = !_chatConversations.has(d.id);
      _chatConversations.set(d.id, data);
      let hasUnread;
      if(isAdminView){
        const dernierMsg = data.updatedAt || 0;
        const vuLe = data.adminSeenAt?.[session.userId] || 0;
        hasUnread = !!(data.lastAuthorId && data.lastAuthorId !== session.userId && dernierMsg > vuLe);
      } else {
        hasUnread = (data.unread?.[session.userId] || 0) > 0;
      }
      if(hasUnread) totalUnread++;
      // Notifie seulement pour une conversation VRAIMENT nouvelle (jamais vue
      // avant sur cet appareil) que l'écouteur temps réel aurait manquée —
      // évite tout doublon avec la notification déjà gérée normalement par
      // onSnapshot pour les conversations déjà connues.
      if(isNewConv && hasUnread && data.lastAuthorId && data.lastAuthorId !== session.userId && !(_chatPanelOpen && d.id === _chatConvId)){
        const nomExp = data.names?.[data.lastAuthorId] || 'un utilisateur';
        playChatNotifSound();
        notify(`💬 Nouveau message de ${nomExp}`);
      }
    });
    _chatUpdateBadge(totalUnread);
    if(_chatPanelOpen && !_chatConvId) renderChatConvList();
  }catch(e){ /* silencieux : simple filet de sécurité, la souscription temps réel reste la source principale */ }
}

// ── Notifications navigateur (hors page / onglet en arrière-plan) ──
function chatDemanderPermissionNotif(){
  if(!('Notification' in window)) return;
  if(Notification.permission === 'default'){
    // ── VOLET 59 ── permission tout juste accordée → inscription push.
    Notification.requestPermission()
      .then(p=>{ if(p === 'granted') _pushInscrire(); })
      .catch(()=>{});
  }
}
// ── VOLET 41 ── Notification système, compatible Android.
// AVANT : `new Notification(...)` uniquement. Chrome sur Android REFUSE ce
// constructeur (TypeError « Illegal constructor ») : il exige qu'une page
// passe par son service worker. L'erreur était avalée par le catch — sur
// Android, la notification ne s'affichait donc JAMAIS, en silence.
// Et `icon: '🔔'` n'est pas une adresse d'image : icône cassée partout.
// DÉSORMAIS : registration.showNotification() (Android, ordinateur, iPhone
// installé sur l'écran d'accueil), avec repli sur new Notification() là où
// le service worker n'est pas disponible. Le clic est traité par sw.js
// (notificationclick), qui ramène l'app au premier plan et ouvre le chat.
// ⚠️ Limite inchangée : l'app doit être OUVERTE (premier plan ou arrière-
// plan). Application fermée → rien, faute de push serveur (option B).
const _CHAT_NOTIF_ICON = 'icons/icon-192x192.png';
async function chatNotifNavigateur(titre, corps){
  if(!('Notification' in window) || Notification.permission !== 'granted') return;
  const options = {
    body: corps,
    icon: _CHAT_NOTIF_ICON,
    badge: _CHAT_NOTIF_ICON,
    tag: 'chat-assistance', // regroupe les notifs successives au lieu d'en empiler 10
    renotify: true,
    data: { type: 'chat' }
  };
  try{
    if('serviceWorker' in navigator){
      const reg = await navigator.serviceWorker.getRegistration();
      if(reg && typeof reg.showNotification === 'function'){
        await reg.showNotification(titre, options);
        return;
      }
    }
  }catch(e){
    console.warn('[chat] notification via service worker impossible, repli :', e);
  }
  try{
    const n = new Notification(titre, options);
    n.onclick = ()=>{ window.focus(); chatToggle(true); n.close(); };
    setTimeout(()=>n.close(), 8000);
  }catch(e){ console.warn('[chat] notification système indisponible sur cet appareil :', e); }
}

// ── VOLET 41 ── Clic sur une notification affichée par le service worker :
// sw.js ramène la fenêtre au premier plan puis envoie ce message.
if('serviceWorker' in navigator){
  navigator.serviceWorker.addEventListener('message', (ev)=>{
    if(ev.data && ev.data.type === 'CHAT_OPEN' && session){
      try{ chatToggle(true); }catch(_){}
    }
  });
}

// ╔══════════════════════════════════════════════════════════════╗
// ║  ── VOLET 59 ── NOTIFICATIONS PUSH (application FERMÉE)        ║
// ╚══════════════════════════════════════════════════════════════╝
// Chaque appareil connecté, dont la permission de notification est
// accordée, obtient un jeton Firebase Cloud Messaging et l'enregistre dans
// pushTokens/{jeton} = { uid, ua, appVersion, updatedAt }.
// La Cloud Function notifierNouveauMessage (functions/index.js) lit ces
// jetons à chaque nouveau message et envoie le push ; sw.js l'affiche,
// même application fermée.
// Le module Messaging est chargé À LA DEMANDE (import dynamique) : aucun
// impact sur le temps de démarrage.
// ⚠️ À RENSEIGNER : clé publique « Web Push » du projet Firebase
// (Console Firebase → ⚙ Paramètres du projet → Cloud Messaging →
// Certificats Web Push → « Paire de clés »). Clé PUBLIQUE : elle peut
// figurer dans le code. Tant qu'elle est vide, le push reste désactivé et
// la messagerie fonctionne exactement comme en v58.
const _PUSH_VAPID_KEY = 'BIGpA9UdMa4VunPwwvYuQU0Lb5WgTsGsdCKoKSpoM5NCW2njHKMwWNjMLNY7Y5ltctWf9A_0YLtsOLcgv63S7qE';
const _PUSH_SDK_URL = 'https://www.gstatic.com/firebasejs/10.12.2/firebase-messaging.js';
let _pushMessaging = null;
let _pushToken = null;
let _pushEnCours = false;

function _pushDelai(ms){ return new Promise(r=>setTimeout(()=>r(null), ms)); }

// Le service worker actif sait-il afficher un push ? Un ancien sw.js (v58 ou
// avant, tant que l'utilisateur n'a pas cliqué « Mettre à jour ») ne le sait
// pas : Chrome afficherait alors « Ce site a été mis à jour en arrière-plan ».
// On ne s'inscrit donc qu'auprès d'un sw.js qui répond au PUSH_PING.
function _pushSwCompatible(reg){
  return new Promise(resolve=>{
    const sw = reg && reg.active;
    if(!sw){ resolve(false); return; }
    const canal = new MessageChannel();
    const t = setTimeout(()=>resolve(false), 2000);
    canal.port1.onmessage = (ev)=>{ clearTimeout(t); resolve(!!(ev.data && ev.data.push)); };
    try{ sw.postMessage({ type: 'PUSH_PING' }, [canal.port2]); }
    catch(_){ clearTimeout(t); resolve(false); }
  });
}

async function _pushInscrire(){
  if(_pushEnCours || !session || !db_fs) return;
  if(!_PUSH_VAPID_KEY){ console.info('[push] clé VAPID non renseignée — notifications push désactivées'); return; }
  if(!('Notification' in window) || Notification.permission !== 'granted') return;
  if(!('serviceWorker' in navigator) || !('PushManager' in window)) return;
  _pushEnCours = true;
  try{
    const m = await import(_PUSH_SDK_URL);
    if(!(await m.isSupported())){ console.info('[push] non pris en charge par ce navigateur'); return; }
    // navigator.serviceWorker.ready ne se résout jamais si l'enregistrement
    // a échoué : on borne l'attente.
    const reg = await Promise.race([navigator.serviceWorker.ready, _pushDelai(10000)]);
    if(!reg){ console.warn('[push] service worker indisponible'); return; }
    if(!(await _pushSwCompatible(reg))){
      console.info('[push] service worker pas encore à jour — inscription au prochain lancement');
      return;
    }
    if(!_pushMessaging) _pushMessaging = m.getMessaging(getApp());
    const token = await m.getToken(_pushMessaging, { vapidKey: _PUSH_VAPID_KEY, serviceWorkerRegistration: reg });
    if(!token || !session) return;
    _pushToken = token;
    await setDoc(doc(db_fs,'pushTokens',token), {
      uid: session.userId,
      ua: String(navigator.userAgent||'').slice(0,200),
      appVersion: APP_VERSION,
      updatedAt: serverTimestamp()
    });
  }catch(e){
    console.warn('[push] inscription impossible :', e && (e.code || e.message));
  }finally{
    _pushEnCours = false;
  }
}

// À la déconnexion : l'appareil ne doit plus recevoir les messages de
// l'utilisateur sortant (téléphone partagé). Borné à 2,5 s pour ne jamais
// bloquer la déconnexion hors réseau ; un jeton resté en base sera de toute
// façon réattribué au prochain utilisateur qui se connecte sur cet appareil,
// ou supprimé par la Cloud Function dès que FCM le déclare invalide.
async function _pushDesinscrire(){
  const token = _pushToken;
  _pushToken = null;
  // Session déjà invalide (expirée, révoquée) : la suppression serait refusée
  // par les règles — on ne fait pas attendre la déconnexion pour rien.
  if(!token || !db_fs || !auth || !auth.currentUser) return;
  await Promise.race([
    (async()=>{
      try{ await deleteDoc(doc(db_fs,'pushTokens',token)); }catch(_){}
      try{
        if(_pushMessaging){ const m = await import(_PUSH_SDK_URL); await m.deleteToken(_pushMessaging); }
      }catch(_){}
    })(),
    _pushDelai(2500)
  ]);
}

// ── Son de notification pour nouveau message de chat ──
let _chatAudioCtx = null;
function playChatNotifSound(){
  try{
    if(!_chatAudioCtx) _chatAudioCtx = new (window.AudioContext||window.webkitAudioContext)();
    const ctx = _chatAudioCtx;
    if(ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;
    // Petit "ding" à deux notes, doux et discret
    [[880,now,0.11],[1175,now+0.09,0.13]].forEach(([freq,t,dur])=>{
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(0, t);
      gain.gain.linearRampToValueAtTime(0.18, t+0.015);
      gain.gain.exponentialRampToValueAtTime(0.0001, t+dur);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(t); osc.stop(t+dur+0.02);
    });
  }catch(e){ /* audio non disponible (autoplay bloqué avant 1ère interaction) */ }
}
// Débloque l'audio dès la première interaction de l'utilisateur avec la page
// (obligatoire dans les navigateurs modernes avant de pouvoir jouer un son)
// ✅ FIX : ne pas s'arrêter au tout premier tap ({once:true}) — si ce
// premier tap arrive avant la connexion (session encore null, ex: tap sur
// le champ de connexion), la demande de permission de notification était
// perdue pour toujours (le listener était déjà consommé). On continue
// maintenant d'écouter les interactions tant que la permission n'a pas été
// explicitement accordée/refusée par le navigateur.
function _armerDemandeNotifSurGeste(){
  const onGeste = ()=>{
    if(!_chatAudioCtx){ try{ _chatAudioCtx = new (window.AudioContext||window.webkitAudioContext)(); }catch(_){} }
    // ✅ FIX SON MUET SUR MOBILE : créer l'AudioContext ne suffit pas — sur
    // iOS Safari notamment, un contexte créé pendant un geste utilisateur
    // démarre quand même parfois en 'suspended', et seul un resume() appelé
    // de façon SYNCHRONE dans ce même geste peut le débloquer. L'ancien code
    // ne créait le contexte qu'ici et ne le "resume"-ait que plus tard, dans
    // playChatNotifSound() — déclenché de façon asynchrone par un événement
    // Firestore (pas un geste utilisateur), ce que les navigateurs mobiles
    // ignorent silencieusement. Résultat : le son ne se débloquait jamais,
    // même après avoir déjà discuté une fois. On appelle donc resume() ici,
    // directement dans le gestionnaire de clic/tap.
    if(_chatAudioCtx && _chatAudioCtx.state === 'suspended'){
      _chatAudioCtx.resume().catch(()=>{});
    }
    if(session) chatDemanderPermissionNotif();
    // On continue d'écouter tant que l'audio n'est pas confirmé débloqué OU
    // que la permission de notification n'est pas encore tranchée — utile
    // si le 1er tap a eu lieu avant la connexion, ou si ce premier resume()
    // a échoué pour une raison quelconque (on retentera au prochain geste).
    const audioOk = _chatAudioCtx && _chatAudioCtx.state === 'running';
    const notifDecidee = !('Notification' in window) || Notification.permission !== 'default';
    if(audioOk && notifDecidee){
      ['click','keydown','touchstart'].forEach(evt=>document.removeEventListener(evt, onGeste));
    }
  };
  ['click','keydown','touchstart'].forEach(evt=>{
    document.addEventListener(evt, onGeste, {passive:true});
  });
}
_armerDemandeNotifSurGeste();

// ── Messages d'une conversation ──
function _chatSubscribeMessages(convId){
  const old = _activeListeners.get('chat_messages'); if(old){ try{old();}catch(_){} }
  _chatMsgsReady = false;
  _chatMessages = [];
  const colRef = collection(db_fs,'chatMessages');
  const q = query(colRef, where('conversationId','==',convId));
  const unsub = onSnapshot(q, snap => {
    const msgs = [];
    snap.forEach(d=>msgs.push({...d.data(), _id:d.id}));
    msgs.sort((a,b)=>(a.tsMs||0)-(b.tsMs||0));
    _chatMessages = msgs;
    if(_chatMsgsReady){
      snap.docChanges().forEach(ch=>{
        if(ch.type==='added'){
          const m = ch.doc.data();
          if(m.authorId !== session.userId){
            playChatNotifSound();
            if(!_chatPanelOpen || _chatConvId!==convId){
              notify(`💬 Nouveau message de ${m.authorNom||'assistance'}`);
            }
            if(document.hidden || !document.hasFocus()){
              chatNotifNavigateur(`💬 ${m.authorNom||'Assistance'}`, m.texte||'Nouveau message');
            }
          }
        }
      });
    }
    _chatMsgsReady = true;
    if(_chatConvId===convId) renderChatMessages();
  }, err => console.error('[chat] listener messages', err));
  _activeListeners.set('chat_messages', unsub);
}

// ── Indicateur « en train d'écrire » ──
function _chatSubscribeTyping(convId){
  const old = _activeListeners.get('chat_typing'); if(old){ try{old();}catch(_){} }
  const otherUid = _chatOtherUid(convId);
  const ref = doc(db_fs,'chatTyping',convId);
  const unsub = onSnapshot(ref, snap => {
    if(!snap.exists()) { _chatRenderTyping(false); return; }
    const d = snap.data();
    const now = Date.now();
    const actif = d[`typing_${otherUid}`] && (now - (d[`typingAt_${otherUid}`]||0) < 6000);
    _chatRenderTyping(actif, d[`nom_${otherUid}`]);
  }, err => console.error('[chat] listener typing', err));
  _activeListeners.set('chat_typing', unsub);
}
function _chatRenderTyping(actif, nom){
  const row = document.getElementById('chat-typing-row');
  const txt = document.getElementById('chat-typing-txt');
  if(!row) return;
  if(actif){
    if(txt) txt.textContent = `${nom||'…'} en train d'écrire…`;
    row.classList.add('visible');
  } else {
    row.classList.remove('visible');
  }
}

// ── Badge (bulle flottante) ──
function _chatUpdateBadge(n){
  const badge = document.getElementById('chat-bubble-badge');
  if(badge){
    if(n>0){ badge.textContent = n>99?'99+':n; badge.classList.add('visible'); }
    else badge.classList.remove('visible');
  }
  // Cumul dans le badge de la cloche 🔔 (notifications + messages chat)
  _chatUnreadCount = n;
  if(typeof _notifBellUpdateBadge==='function') _notifBellUpdateBadge();
}

// ── Reconnexion forcée au retour au premier plan (mobile) ──
// Sur mobile, le navigateur suspend le JS et coupe la connexion Firestore
// (WebSocket) dès que l'app passe en arrière-plan (écran verrouillé, onglet
// caché, app minimisée). Contrairement au desktop où l'onglet reste actif
// en continu, le badge de chat ne se met alors PAS à jour tant que l'app
// est en arrière-plan — c'est une limitation du système, pas un bug de
// l'app. En revanche, on peut garantir que dès que l'utilisateur revient
// sur l'app, le badge se rafraîchisse IMMÉDIATEMENT.
//
// ⚠️ Note technique : on NE PASSE PAS par enableNetwork(db_fs) ici. Cet
// appel peut entrer en collision avec la gestion interne du SDK Firestore
// lors des cycles arrière-plan/premier plan rapides sur mobile, et
// provoquer l'erreur "FIRESTORE INTERNAL ASSERTION FAILED: Unexpected
// state" (bug connu du SDK, cf. github.com/firebase/firebase-js-sdk).
// À la place, on désabonne puis ré-abonne proprement les listeners du
// chat : ça force un nouveau onSnapshot frais sans toucher à l'état
// réseau interne du SDK — beaucoup plus sûr.
let _chatForegroundResumeTimer = null;
function _chatForceResumeSync(){
  if (!db_fs || !session) return;
  if (_chatForegroundResumeTimer) clearTimeout(_chatForegroundResumeTimer);
  // Petit debounce pour éviter les appels multiples si plusieurs événements
  // (visibilitychange + focus + pageshow) se déclenchent presque en même temps.
  _chatForegroundResumeTimer = setTimeout(() => {
    // Re-souscrit la liste des conversations (alimente le badge).
    const oldConv = _activeListeners.get('chat_conv_list');
    if (oldConv) { try{ oldConv(); }catch(_){} _activeListeners.delete('chat_conv_list'); }
    // ── VOLET 75 ── On NE remet PLUS _chatConvListReady à false ici. La
    // dé-duplication par updatedAt (_chatDernierNotifTs) empêche désormais le
    // spam au ré-abonnement ; garder l'état « prêt » permet de signaler le
    // message arrivé pendant que l'app était en arrière-plan (sinon il était
    // avalé par l'amorçage silencieux du snapshot de ré-abonnement).
    _chatSubscribeConvList();
    // Si une conversation est ouverte, re-souscrit aussi ses messages/typing.
    // ── VOLET 42 ── seulement si le panneau est OUVERT (voir chatToggle).
    if (_chatConvId && _chatPanelOpen) {
      _chatSubscribeMessages(_chatConvId);
      _chatSubscribeTyping(_chatConvId);
    }
  }, 50);
}
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') _chatForceResumeSync();
});
window.addEventListener('focus', _chatForceResumeSync);
// pageshow avec persisted=true couvre le cas iOS Safari où la page est
// restaurée depuis le cache (bfcache) sans re-déclencher 'load'.
window.addEventListener('pageshow', (e) => { if (e.persisted) _chatForceResumeSync(); });

// ═══════════ RÉPONSE OBLIGATOIRE (commercial) — voir _chatForcedBlockConvId ═══
// Recalcule, à PARTIR DE L'ÉTAT ACTUEL (pas d'un évènement ponctuel), s'il
// existe une conversation où le dernier message vient du staff et reste sans
// réponse du commercial. Appelée à chaque snapshot de la liste des
// conversations (voir _chatSubscribeConvList) — donc aussi bien à la
// connexion que sur chaque nouveau message ou reconnexion. Étant "à l'état"
// et non "sur évènement", un redémarrage de l'écouteur (_chatForceResumeSync,
// retour au premier plan mobile) ne peut jamais la faire "rejouer" une action
// déjà faite : elle constate juste que le blocage est (ou n'est plus) requis.
// ── VOLET 44 ── PLEIN ÉCRAN À LA RÉCEPTION, FERMETURE AUTORISÉE ─────────
// Demande : quand un membre du staff écrit à un commercial, la conversation
// s'OUVRE d'elle-même en plein écran (on est sûr que le message a été vu),
// mais le commercial peut la FERMER. Remplace le « blocage tant qu'il n'a
// pas répondu » (volets précédents), retiré à la demande.
// Une seule ouverture automatique par message : on mémorise, par
// conversation, l'horodatage du dernier message déjà ouvert d'office
// (localStorage, avec repli en mémoire). Fermer ne la fait donc PAS se
// rouvrir au prochain rafraîchissement ; un NOUVEAU message, si.
// Conditions : rôle commercial ; dernier message d'un AUTRE utilisateur qui
// n'est pas commercial ; non lu ; plus récent que la dernière ouverture.
// Les messages arrivés pendant que l'application était fermée s'ouvrent
// donc à la prochaine ouverture de l'application.
const _chatAutoMem = {};
function _chatAutoCle(){ return 'mmb_chat_auto_' + (session && session.userId); }
function _chatAutoLire(){
  try { return JSON.parse(localStorage.getItem(_chatAutoCle()) || '{}') || {}; } catch(e) { return {}; }
}
function _chatAutoNoter(convId, ts){
  _chatAutoMem[convId] = ts;
  try { const m = _chatAutoLire(); m[convId] = ts; localStorage.setItem(_chatAutoCle(), JSON.stringify(m)); } catch(e) {}
}
function _chatEvaluateForcedBlock(){
  if(!session || session.role !== ROLES.COMMERCIAL) return;
  const deja = _chatAutoLire();
  let cible = null;
  for(const [id, conv] of _chatConversations){
    const auteur = conv.lastAuthorId;
    if(!auteur || auteur === session.userId) continue;
    const roleAuteur = conv.lastAuthorRole || (conv.roles && conv.roles[auteur]) || '';
    if(roleAuteur === ROLES.COMMERCIAL) continue;          // message d'un autre agent
    if(((conv.unread && conv.unread[session.userId]) || 0) <= 0) continue;
    const ts = conv.updatedAt || 0;
    if(ts <= Math.max(deja[id] || 0, _chatAutoMem[id] || 0)) continue;
    if(!cible || ts > cible.ts) cible = { id, ts };
  }
  if(!cible) return;
  _chatAutoNoter(cible.id, cible.ts);
  _chatForcedBlockConvId = cible.id;   // = conversation affichée en plein écran
  chatToggle(true);
  chatSelectConv(cible.id);
  _chatApplyForcedBlockUI();
}

// Applique/retire l'habillage "plein écran, pas de fermeture possible" — en
// style inline pour ne dépendre d'aucune règle CSS externe non fournie ici.
function _chatApplyForcedBlockUI(){
  const panel = document.getElementById('chat-panel');
  const closeBtn = document.querySelector('.chat-hdr-close');
  const backBtn = document.getElementById('chat-hdr-back');
  const newBtn = document.getElementById('chat-hdr-new');
  const blocked = !!_chatForcedBlockConvId;
  // ── VOLET 44 ── plein écran, mais fermeture et retour TOUJOURS visibles.
  if(closeBtn) closeBtn.style.display = '';
  if(backBtn) backBtn.style.display = '';
  if(panel){
    if(blocked){
      panel.style.position = 'fixed';
      panel.style.inset = '0';
      panel.style.top = '0'; panel.style.left = '0'; panel.style.right = '0'; panel.style.bottom = '0';
      panel.style.width = '100vw';
      panel.style.height = '100vh';
      panel.style.maxWidth = '100vw';
      panel.style.maxHeight = '100vh';
      panel.style.borderRadius = '0';
      panel.style.zIndex = '99999';
    } else {
      panel.style.position = '';
      panel.style.inset = '';
      panel.style.top = ''; panel.style.left = ''; panel.style.right = ''; panel.style.bottom = '';
      panel.style.width = '';
      panel.style.height = '';
      panel.style.maxWidth = '';
      panel.style.maxHeight = '';
      panel.style.borderRadius = '';
      panel.style.zIndex = '';
    }
  }
}

// ── Ouverture / fermeture du panneau ──
window.chatToggle = function(force){
  const panel = document.getElementById('chat-panel');
  if(!panel) return;
  const nextState = (typeof force==='boolean') ? force : !_chatPanelOpen;
  // ⛔ Réponse exigée : on refuse toute tentative de fermeture (bulle, croix,
  // ou tout autre appel) tant qu'un message du staff reste sans réponse.
  // ── VOLET 44 ── la fermeture n'est plus refusée : elle quitte le plein écran.
  if(!nextState && _chatForcedBlockConvId){
    _chatForcedBlockConvId = null;
    _chatApplyForcedBlockUI();
  }
  _chatPanelOpen = nextState;
  panel.classList.toggle('open', _chatPanelOpen);
  // ── VOLET 42 ── Discussion FERMÉE = plus aucune conversation « affichée ».
  // AVANT : fermer le panneau laissait _chatConvId sur la dernière
  // conversation ouverte, et la liste des conversations ne notifiait JAMAIS
  // cette conversation-là (elle la croyait sous les yeux de l'utilisateur).
  // Seul l'écouteur de messages prenait le relais ; or il était relancé au
  // retour au premier plan avec un premier lot silencieux : les messages
  // reçus pendant que le téléphone était en veille ne sonnaient pas.
  // DÉSORMAIS : à la fermeture on coupe l'écouteur de messages (_chatConvId
  // est gardé pour rouvrir au même endroit) ; la liste des conversations,
  // qui tourne en permanence, notifie alors toutes les conversations.
  if(!_chatPanelOpen){
    ['chat_messages','chat_typing'].forEach(k=>{
      const u = _activeListeners.get(k); if(u){ try{u();}catch(_){} _activeListeners.delete(k); }
    });
  }
  if(_chatPanelOpen){
    if(_chatConvId) chatSelectConv(_chatConvId); else { renderChatConvList(); _chatShowView('list'); }
  }
  _chatApplyForcedBlockUI();
};
function _chatShowView(view){
  const list = document.getElementById('chat-conv-list');
  const thread = document.getElementById('chat-thread');
  const picker = document.getElementById('chat-new-picker');
  const back = document.getElementById('chat-hdr-back');
  const newBtn = document.getElementById('chat-hdr-new');
  if(picker) picker.style.display = 'none';
  if(view==='list'){
    list.classList.add('visible'); thread.classList.remove('visible');
    back?.classList.remove('visible');
    if(newBtn) newBtn.style.display = 'inline-block';
    document.getElementById('chat-hdr-title').textContent = '💬 Messagerie';
    document.getElementById('chat-hdr-sub').textContent = 'Sélectionnez une conversation';
  } else if(view==='picker'){
    list.classList.remove('visible'); thread.classList.remove('visible');
    if(picker) picker.style.display = 'flex';
    back?.classList.add('visible');
    if(newBtn) newBtn.style.display = 'none';
    document.getElementById('chat-hdr-title').textContent = '✎ Nouveau message';
    document.getElementById('chat-hdr-sub').textContent = 'Choisissez un destinataire';
  } else {
    list.classList.remove('visible'); thread.classList.add('visible');
    back?.classList.add('visible'); if(newBtn) newBtn.style.display='none';
  }
}
window.chatBackToList = function(){
  _chatConvId = null;
  const old = _activeListeners.get('chat_messages'); if(old){ try{old();}catch(_){} _activeListeners.delete('chat_messages'); }
  const oldT = _activeListeners.get('chat_typing'); if(oldT){ try{oldT();}catch(_){} _activeListeners.delete('chat_typing'); }
  _chatShowView('list');
  renderChatConvList();
};

// ── Nouveau message : TOUS les rôles peuvent écrire à TOUS les rôles ──
window.chatOpenNewConvPicker = function(){
  const search = document.getElementById('chat-new-search');
  if(search) search.value = '';
  _chatShowView('picker');
  renderChatNewPicker();
};
window.renderChatNewPicker = function(){
  const el = document.getElementById('chat-new-picker-list');
  if(!el) return;
  const q = (document.getElementById('chat-new-search')||{}).value?.trim().toLowerCase() || '';
  // Tous les utilisateurs de l'app, tous rôles et toutes agences confondus, sauf soi-même.
  let users = (DB.commerciaux||[]).filter(c=>c._id !== session.userId);
  if(q) users = users.filter(c=>(c.nom||'').toLowerCase().includes(q));
  users = users.slice().sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  if(!users.length){
    el.innerHTML = '<div class="chat-conv-empty">Aucun utilisateur trouvé</div>';
    return;
  }
  el.innerHTML = users.map(u=>`
    <div class="chat-conv-item" onclick="chatStartConvWith('${u._id}')">
      <div class="chat-conv-avatar">${esc(_chatInitiales(u.nom))}</div>
      <div class="chat-conv-info">
        <div class="chat-conv-name">${esc(u.nom||'—')} <span style="color:var(--muted);font-weight:400;">· ${esc(CHAT_ROLE_LABELS[u.role]||u.role||'')}</span></div>
      </div>
    </div>
  `).join('');
};
window.chatStartConvWith = async function(userId){
  const u = DB.commerciaux.find(c=>c._id===userId);
  if(!u){ notify('Utilisateur introuvable','err'); return; }
  const convId = _chatPairId(session.userId, userId);
  try{
    await _chatEnsureConversation(convId, userId);
    if(!_chatConversations.has(convId)){
      _chatConversations.set(convId, {
        participants:[session.userId, userId].sort(),
        names:{[session.userId]:session.nom, [userId]:u.nom},
        roles:{[session.userId]:session.role, [userId]:u.role},
        _id:convId
      });
    }
    chatSelectConv(convId);
  }catch(e){
    console.error('[chat] démarrage conversation', e);
    notify("Erreur lors de l'ouverture de la conversation","err");
  }
};

// ── Sélection d'une conversation ──
window.chatSelectConv = function(convId){
  _chatConvId = convId;
  const conv = _chatConversations.get(convId) || {};
  const isAdminObserving = session.role===ROLES.ADMIN && !(conv.participants||[]).includes(session.userId);
  if(isAdminObserving){
    // ✅ Admin en supervision : ni l'un ni l'autre des 2 participants,
    // donc afficher les 2 noms plutôt qu'un "autre" incorrect.
    const noms = (conv.participants||[]).map(p=>conv.names?.[p]||'—');
    document.getElementById('chat-hdr-title').textContent = '💬 ' + noms.join(' ↔ ');
    document.getElementById('chat-hdr-sub').textContent = 'Supervision — conversation entre 2 utilisateurs';
  } else {
    const otherUid = _chatOtherUid(convId);
    const otherNom = conv.names?.[otherUid] || 'Utilisateur';
    const otherRole = conv.roles?.[otherUid];
    document.getElementById('chat-hdr-title').textContent = '💬 ' + otherNom;
    document.getElementById('chat-hdr-sub').textContent = CHAT_ROLE_LABELS[otherRole] || otherRole || '';
  }
  _chatShowView('thread');
  const inputBar = document.querySelector('.chat-input-bar');
  if(inputBar) inputBar.style.display = isAdminObserving ? 'none' : '';
  _chatSubscribeMessages(convId);
  _chatSubscribeTyping(convId);
  _chatMarkRead();
};

async function _chatMarkRead(){
  if(!_chatConvId) return;
  try{
    if(session.role === ROLES.ADMIN){
      // ✅ L'admin n'est pas participant : on trace la date de dernière
      // consultation par l'admin séparément (adminSeenAt), pour calculer
      // le badge/notifications de supervision (voir _chatSubscribeConvList).
      await setDoc(doc(db_fs,'chatConversations',_chatConvId), {adminSeenAt:{[session.userId]:Date.now()}}, {merge:true});
    } else {
      await setDoc(doc(db_fs,'chatConversations',_chatConvId), {unread:{[session.userId]:0}}, {merge:true});
    }
  }catch(e){ console.error('[chat] marquage lu', e); }
}

// ── Rendu ──
function renderChatConvList(){
  const el = document.getElementById('chat-conv-list');
  if(!el) return;
  const isAdminView = session.role === ROLES.ADMIN;
  const convs = [..._chatConversations.values()].sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
  if(!convs.length){
    el.innerHTML = '<div class="chat-conv-empty">Aucune conversation pour le moment — cliquez sur ✎ pour écrire à quelqu\'un</div>';
    return;
  }
  el.innerHTML = convs.map(c=>{
    let nom, role, unread;
    if(isAdminView && !(c.participants||[]).includes(session.userId)){
      // ✅ Vue supervision admin : afficher les 2 interlocuteurs (l'admin
      // n'est ni l'un ni l'autre), et calculer le badge via adminSeenAt.
      const noms = (c.participants||[]).map(p=>c.names?.[p]||'—');
      nom = noms.join(' ↔ ');
      role = '';
      const dernierMsg = c.updatedAt || 0;
      const vuLe = c.adminSeenAt?.[session.userId] || 0;
      unread = (c.lastAuthorId && c.lastAuthorId!==session.userId && dernierMsg>vuLe) ? 1 : 0;
    } else {
      const otherUid = c.participants?.find(p=>p!==session.userId) || _chatOtherUid(c._id);
      nom = c.names?.[otherUid] || '—';
      role = c.roles?.[otherUid] || '';
      unread = c.unread?.[session.userId] || 0;
    }
    return `
    <div class="chat-conv-item" onclick="chatSelectConv('${c._id}')">
      <div class="chat-conv-avatar">${esc(_chatInitiales(nom))}</div>
      <div class="chat-conv-info">
        <div class="chat-conv-name">${esc(nom)}${role?` <span style="color:var(--muted);font-weight:400;">· ${esc(CHAT_ROLE_LABELS[role]||role)}</span>`:''}</div>
        <div class="chat-conv-last">${esc(c.lastMsg||'—')}</div>
      </div>
      ${unread?`<div class="chat-conv-badge">${unread>99?'99+':unread}</div>`:''}
    </div>`;
  }).join('');
}

function renderChatMessages(){
  const el = document.getElementById('chat-messages');
  if(!el) return;
  if(!_chatMessages.length){
    el.innerHTML = '<div class="chat-msg-empty">Aucun message pour l\'instant — envoyez votre question ci-dessous</div>';
    return;
  }
  el.innerHTML = _chatMessages.map(m=>{
    const mine = m.authorId === session.userId;
    const peutSupprimer = mine || session.role ===ROLES.ADMIN;
    const delBtn = peutSupprimer
      ? `<button class="chat-msg-del" title="Supprimer" onclick="chatSupprimerMessage('${m._id}', ${m.storagePath?`'${esc(m.storagePath)}'`:'null'})">✕</button>`
      : '';
    // ✅ Expiration des reçus envoyés par message : un reçu partagé avec un
    // commercial via la messagerie devient inconsultable après RECU_MSG_TTL_MS
    // (voir envoyerRecuAuCommercial). m.expireAt est fixé à l'envoi ; les
    // messages plus anciens (envoyés avant l'ajout de cette fonctionnalité)
    // n'ont pas ce champ et restent donc consultables sans limite.
    const recuExpire = m.type === 'recu' && m.expireAt && Date.now() > m.expireAt;
    const contenu = m.type === 'image'
      ? `<img src="${esc(m.imageUrl)}" class="chat-msg-img" onclick="window.open('${esc(m.imageUrl)}','_blank')" alt="Image envoyée">`
      : m.type === 'recu'
      ? `<div class="chat-msg-recu">
          <div style="font-size:13px;">${esc(m.texte||'📄 Reçu')}</div>
          ${recuExpire
            ? `<div style="margin-top:8px;font-size:11px;color:var(--muted);font-style:italic;">⏱️ Ce reçu a expiré et ne peut plus être ouvert.</div>`
            : `<button class="btn btn-xs" style="margin-top:8px;background:rgba(201,168,76,0.15);color:var(--accent);border:1px solid rgba(201,168,76,0.35);font-weight:700;" onclick="ouvrirRecuDepuisChat('${esc(m.recuId)}', ${m.expireAt||'null'})">🖨️ Ouvrir / Imprimer le reçu</button>`}
        </div>`
      : esc(m.texte||'');
    return `<div class="chat-msg ${mine?'chat-msg-mine':'chat-msg-theirs'}">
      ${delBtn}
      ${!mine?`<div class="chat-msg-author">${esc(m.authorNom||'—')}</div>`:''}
      ${contenu}
      <div class="chat-msg-meta">${esc(m.date||'')} ${esc(m.heure||'')}</div>
    </div>`;
  }).join('');
  el.scrollTop = el.scrollHeight + 200;
}

// ── Saisie / indicateur de frappe ──
window.chatOnInput = function(el){
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight, 80) + 'px';
  if(!_chatConvId) return;
  const now = Date.now();
  if(now - _chatTypingSentAt > 1500){
    _chatTypingSentAt = now;
    setDoc(doc(db_fs,'chatTyping',_chatConvId), {
      [`typing_${session.userId}`]: true,
      [`typingAt_${session.userId}`]: now,
      [`nom_${session.userId}`]: session.nom
    }, {merge:true}).catch(()=>{});
  }
  clearTimeout(_chatTypingResetTimer);
  _chatTypingResetTimer = setTimeout(()=>{
    if(!_chatConvId) return;
    setDoc(doc(db_fs,'chatTyping',_chatConvId), {[`typing_${session.userId}`]:false}, {merge:true}).catch(()=>{});
  }, 3000);
};
window.chatOnKeydown = function(ev){
  if(ev.key==='Enter' && !ev.shiftKey){ ev.preventDefault(); chatEnvoyer(); }
};

// ── Envoi d'un message ──
window.chatEnvoyer = _withActionLock('chatEnvoyer', async function(){
  const input = document.getElementById('chat-input');
  const texte = (input?.value||'').trim();
  if(texte.length > 4000){ notify('Message trop long (max 4000 caractères)','err'); return; }
  if(!texte) return;
  const convId = _chatConvId;
  if(!convId){ notify('Sélectionnez une conversation','err'); return; }
  const otherUid = _chatOtherUid(convId);
  const btn = document.getElementById('chat-send-btn');
  if(btn) btn.disabled = true;
  try{
    const now = Date.now();
    await _chatEnsureConversation(convId, otherUid);
    await addDoc(collection(db_fs,'chatMessages'), {
      conversationId: convId,
      type: 'texte',
      authorId: session.userId,
      authorNom: session.nom,
      authorRole: session.role,
      texte,
      tsMs: now,
      date: TODAY,
      heure: _chatHeureNow(),
      _ts: serverTimestamp()
    });
    const conv = _chatConversations.get(convId) || {};
    const otherUnread = (conv.unread?.[otherUid] || 0) + 1;
    await setDoc(doc(db_fs,'chatConversations',convId), {
      lastMsg: texte.slice(0,120),
      lastAuthorId: session.userId,
      lastAuthorRole: session.role,
      updatedAt: now,
      unread: {[otherUid]: otherUnread, [session.userId]: 0}
    }, {merge:true});

    // Fin immédiate de l'indicateur de frappe
    setDoc(doc(db_fs,'chatTyping',convId), {[`typing_${session.userId}`]:false}, {merge:true}).catch(()=>{});

    if(input){ input.value=''; input.style.height='auto'; }
  } catch(e){
    console.error('[chat] envoi message', e);
    notify("Erreur lors de l'envoi du message","err");
  } finally {
    if(btn) btn.disabled = false;
  }
});

// ── Envoi d'une image ──
window.chatEnvoyerImage = _withActionLock((...a)=>'chatEnvoyerImage:'+a.join(':'), async function(file){
  const imgInput = document.getElementById('chat-img-input');
  if(!file) return;
  if(!_chatConvId){ notify('Sélectionnez une conversation','err'); if(imgInput) imgInput.value=''; return; }
  if(!file.type?.startsWith('image/')){ notify('Seules les images sont acceptées','err'); if(imgInput) imgInput.value=''; return; }
  const MAX = 8 * 1024 * 1024; // 8 Mo, doit correspondre à la règle Storage
  if(file.size > MAX){ notify('Image trop lourde (8 Mo max)','err'); if(imgInput) imgInput.value=''; return; }
  if(!storage){ notify('Firebase Storage non initialisé','err'); return; }

  const convId = _chatConvId;
  const otherUid = _chatOtherUid(convId);
  const btn = document.getElementById('chat-attach-btn');
  if(btn) btn.disabled = true;
  try{
    const ext = (file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'') || 'jpg';
    const path = `chatImages/${convId}/${Date.now()}_${session.userId}.${ext}`;
    const fileRef = storageRef(storage, path);
    await uploadBytes(fileRef, file, { contentType: file.type });
    const url = await getDownloadURL(fileRef);

    const now = Date.now();
    await _chatEnsureConversation(convId, otherUid);
    await addDoc(collection(db_fs,'chatMessages'), {
      conversationId: convId,
      type: 'image',
      imageUrl: url,
      storagePath: path,
      authorId: session.userId,
      authorNom: session.nom,
      authorRole: session.role,
      texte: '',
      tsMs: now,
      date: TODAY,
      heure: _chatHeureNow(),
      _ts: serverTimestamp()
    });
    const conv = _chatConversations.get(convId) || {};
    const otherUnread = (conv.unread?.[otherUid] || 0) + 1;
    await setDoc(doc(db_fs,'chatConversations',convId), {
      lastMsg: '📷 Photo',
      lastAuthorId: session.userId,
      lastAuthorRole: session.role,
      updatedAt: now,
      unread: {[otherUid]: otherUnread, [session.userId]: 0}
    }, {merge:true});
  }catch(e){
    console.error('[chat] envoi image', e);
    notify("Erreur lors de l'envoi de l'image","err");
  }finally{
    if(btn) btn.disabled = false;
    if(imgInput) imgInput.value = '';
  }
});

// ── Suppression d'un message (par son auteur, ou par un admin) ──
window.chatSupprimerMessage = async function(msgId, storagePath){
  if(!confirm('Supprimer ce message ?')) return;
  try{
    await deleteDoc(doc(db_fs,'chatMessages',msgId));
    if(storagePath){
      try{ await deleteObject(storageRef(storage, storagePath)); }
      catch(e){ /* non bloquant : l'image peut déjà avoir été supprimée */ }
    }
  }catch(e){
    console.error('[chat] suppression message', e);
    notify("Impossible de supprimer ce message","err");
  }
};

function chatTeardown(){
  ['chat_conv_list','chat_messages','chat_typing','chat_own_conv'].forEach(k=>{
    const u = _activeListeners.get(k); if(u){ try{u();}catch(_){} _activeListeners.delete(k); }
  });
  _chatConversations.clear();
  _chatMessages = [];
  _chatConvId = null;
  _chatPanelOpen = false;
  _chatForcedBlockConvId = null; // ✅ évite qu'un habillage plein écran reste collé à la déconnexion
  const panel = document.getElementById('chat-panel'); if(panel) panel.classList.remove('open');
  _chatApplyForcedBlockUI();
  const bubble = document.getElementById('chat-bubble'); if(bubble) bubble.style.display = 'none';
  _chatUpdateBadge(0);
  const bell = document.getElementById('notif-bell'); if(bell) bell.style.display = 'none';
  const notifPanel = document.getElementById('notif-panel'); if(notifPanel) notifPanel.classList.remove('open');
  _notifBellPanelOpen = false;
}
