function getRoleLabel(role){
  const labels={admin:'Administrateur',commercial:'Commercial',secretaire:'Secrétaire',controleur:'Contrôleur',gestionnaire_stock:'Gest. de stock',chef_agence:"Chef d'Agence"};
  return labels[role]||role;
}

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 21 — MENU LATERAL : GROUPES REPLIABLES                 ║
// ╚══════════════════════════════════════════════════════════════╝
// LE PROBLEME. La section « Gestion » de l'admin comptait 21 entrees
// d'affilee, 11 pour le chef d'agence. Sur un ecran de portable, retrouver
// une page demandait de faire defiler tout le menu.
//
// COMMENT C'EST FAIT, ET POURQUOI AINSI. Les six constantes XXX_NAV ne sont
// PAS reecrites. Elles contiennent 25 icones SVG, des onclick et des
// identifiants : les recopier dans un nouvel ordre, c'etait 25 occasions de
// perdre une entree ou de casser un handler. A la place, ce module DEPLACE
// les noeuds .nav-item deja rendus dans des groupes qu'il cree. Un noeud
// deplace conserve tout : son icone, son onclick, son id, son etat actif.
//
// LE GARDE-FOU QUI COMPTE. Toute entree presente dans le menu mais ABSENTE
// de la table de regroupement ci-dessous est placee dans un groupe final
// « Autres ». Une faute de frappe dans un identifiant ne fait donc jamais
// disparaitre une page : elle la rend visible ailleurs. C'est volontaire —
// un menu incomplet en production serait invisible jusqu'a ce qu'un agent
// s'en plaigne.

// Table de regroupement : ordre des groupes, et ordre des entrees dans
// chacun. Les identifiants sont ceux des <div id="nav-…"> des constantes NAV.
// Un identifiant inconnu d'un role est simplement ignore pour ce role, ce qui
// permet de partager la meme table entre tous.
const _NAV_GROUPES = [
  { titre: 'Principal', ids: ['nav-admin-dashboard','nav-registre','nav-historique','nav-historique-recus'] },
  { titre: 'Mon espace', ids: ['nav-com-clients','nav-com-nouveau-client','nav-com-livraisons'] },
  // 'nav-controle' est rattache aux Clients : c'est un ecran de controle PAR
  // client. Il avait d'abord son propre groupe « Consultation », qui ne
  // contenait qu'une entree chez le controleur — un entete a cliquer pour
  // une seule ligne n'apporte rien.
  { titre: 'Clients', ids: ['nav-tous-clients','nav-analyse-clients','nav-controle','nav-transfert-resiliation'] },
  { titre: 'Saisies du jour', ids: ['nav-saisie-mises','nav-saisie-adhesions','nav-fiche'] },
  { titre: 'Livraisons & stock', ids: ['nav-livraisons','nav-demandes-agents','nav-demandes-livraison','nav-articles','nav-produits','nav-stock','nav-gstock-periode'] },
  { titre: 'Rapports', ids: ['nav-rapport-activite','nav-depenses-commerciaux','nav-controle-depart'] },
  { titre: 'Administration', ids: ['nav-commerciaux','nav-agences','nav-carnets','nav-rouleaux','nav-audit','nav-erreurs','nav-sante','nav-primes','nav-paliers-duree'] },
];

const _NAV_ETAT_CLE = 'gestcom_nav_groupe_ouvert';

function _navGroupeOuvertMemorise(){
  try { return localStorage.getItem(_NAV_ETAT_CLE) || ''; } catch(e) { return ''; }
}
function _navMemoriserGroupe(titre){
  try { localStorage.setItem(_NAV_ETAT_CLE, titre || ''); } catch(e) { /* mode prive */ }
}

// Titre du groupe contenant une page donnee — pour ouvrir le bon groupe au
// demarrage et apres chaque navigation.
function _navGroupeDeLaPage(pageId){
  const cible = 'nav-' + pageId;
  for (const g of _NAV_GROUPES) if (g.ids.includes(cible)) return g.titre;
  return '';
}

// Construit les groupes a partir du menu deja rendu dans #nav-menu.
// Idempotent : appelable apres chaque re-rendu du menu.
function navRegrouperMenu(){
  const menu = document.getElementById('nav-menu');
  if (!menu) return;
  if (menu.dataset.regroupe === '1') return;   // deja fait pour ce rendu

  // On collecte les .nav-item existants par identifiant, puis on vide le
  // menu de ses anciens entetes .nav-sec. Les noeuds .nav-item sont
  // CONSERVES et redeplaces — jamais recrees.
  const parId = new Map();
  const ordreOrigine = [];
  menu.querySelectorAll('.nav-item').forEach(el => {
    if (el.id) { parId.set(el.id, el); ordreOrigine.push(el.id); }
    else ordreOrigine.push(el);            // entree sans id : conservee telle quelle
  });
  if (!parId.size) return;                 // menu vide (utilisateur non charge)

  const fragment = document.createDocumentFragment();
  const utilises = new Set();

  const ajouterGroupe = (titre, elements) => {
    if (!elements.length) return;
    const sec = document.createElement('div');
    sec.className = 'nav-sec nav-sec-clic';
    sec.setAttribute('role', 'button');
    sec.setAttribute('tabindex', '0');
    sec.setAttribute('aria-expanded', 'false');
    sec.dataset.groupe = titre;
    // ── VOLET 22 ── ordre des elements : segment de rail, libelle, pastille,
    // compteur, chevron. Le chevron passe a DROITE : l'oeil suit le rail a
    // gauche, l'etat d'ouverture se lit en fin de ligne.
    sec.innerHTML = '<span class="nav-rail-t"></span>'
      + '<span class="nav-lbl">' + esc(titre) + '</span>'
      + '<span class="nav-dot"></span>'
      + '<span class="nav-cnt">' + elements.length + '</span>'
      + '<span class="nav-chev">\u25B6</span>';
    sec.onclick = () => navToggleGroupe(titre);
    sec.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); navToggleGroupe(titre); } };
    // ── VOLET 22 ── le groupe devient « rail + colonne d'entrees ». Les
    // .nav-item vont dans la colonne, jamais directement dans .nav-grp, sinon
    // ils se placeraient a cote du rail au lieu d'etre dessous.
    const grp = document.createElement('div');
    grp.className = 'nav-grp';
    grp.dataset.groupe = titre;
    const rail = document.createElement('div');
    rail.className = 'nav-rail';
    rail.setAttribute('aria-hidden', 'true');
    const colonne = document.createElement('div');
    colonne.className = 'nav-grp-items';
    elements.forEach(el => colonne.appendChild(el));
    grp.appendChild(rail);
    grp.appendChild(colonne);
    fragment.appendChild(sec);
    fragment.appendChild(grp);
  };

  for (const g of _NAV_GROUPES) {
    const els = [];
    for (const id of g.ids) {
      const el = parId.get(id);
      if (el) { els.push(el); utilises.add(id); }
    }
    ajouterGroupe(g.titre, els);
  }

  // ── GARDE-FOU ── tout ce que la table n'a pas place. Dans l'ordre
  // d'origine, pour rester lisible.
  const restants = ordreOrigine
    .filter(x => typeof x === 'string' && !utilises.has(x))
    .map(id => parId.get(id))
    .filter(Boolean);
  const sansId = ordreOrigine.filter(x => typeof x !== 'string');
  ajouterGroupe('Autres', restants.concat(sansId));
  if (restants.length) {
    console.warn('[menu] ' + restants.length + ' entree(s) hors table de regroupement, placee(s) dans « Autres » :',
                 restants.map(e => e.id).join(', '));
  }

  menu.innerHTML = '';
  menu.appendChild(fragment);
  menu.dataset.regroupe = '1';

  // Ouverture initiale : le groupe de la page courante, sinon celui retenu de
  // la derniere session, sinon le premier.
  const voulu = _navGroupeDeLaPage(curPg || '') || _navGroupeOuvertMemorise();
  const titres = [...menu.querySelectorAll('.nav-sec-clic')].map(s => s.dataset.groupe);
  navToggleGroupe(titres.includes(voulu) ? voulu : (titres[0] || ''), true);
}

// Ouvre un groupe et referme les autres (comportement retenu : un seul
// ouvert a la fois — le menu reste court, sans defilement).
// `forcerOuvert` empeche la bascule quand l'appel est programmatique.
// Declaree comme fonction de module PUIS exposee sur window (meme motif que
// renderDemandesLivraison plus haut). Un « window.x = function » seul n'est
// atteignable depuis ce module que par la resolution implicite du global :
// ca marche dans le navigateur, mais c'est fragile et intestable hors de lui.
function navToggleGroupe(titre, forcerOuvert){
  const menu = document.getElementById('nav-menu');
  if (!menu || !titre) return;
  const sec = menu.querySelector('.nav-sec-clic[data-groupe="' + titre.replace(/"/g,'') + '"]');
  const dejaOuvert = sec && sec.getAttribute('aria-expanded') === 'true';
  const ouvrir = forcerOuvert ? true : !dejaOuvert;

  menu.querySelectorAll('.nav-sec-clic').forEach(s => {
    const actif = ouvrir && s.dataset.groupe === titre;
    s.setAttribute('aria-expanded', actif ? 'true' : 'false');
  });
  menu.querySelectorAll('.nav-grp').forEach(g => {
    g.classList.toggle('ouvert', ouvrir && g.dataset.groupe === titre);
  });
  _navMemoriserGroupe(ouvrir ? titre : '');
  navMarquerGroupeActif();
}
window.navToggleGroupe = navToggleGroupe;

// Pastille sur l'entete du groupe qui contient la page courante, pour qu'on
// sache ou l'on se trouve meme quand ce groupe est replie.
function navMarquerGroupeActif(){
  const menu = document.getElementById('nav-menu');
  if (!menu) return;
  const g = _navGroupeDeLaPage(curPg || '');
  menu.querySelectorAll('.nav-sec-clic').forEach(s => {
    s.classList.toggle('contient-actif', !!g && s.dataset.groupe === g);
  });
}

// Appelee apres chaque navigation : regroupe si besoin, ouvre le groupe de la
// page atteinte, et met la pastille a jour.
function navSynchroniserMenu(){
  navRegrouperMenu();
  const g = _navGroupeDeLaPage(curPg || '');
  if (g) navToggleGroupe(g, true);
  else navMarquerGroupeActif();
}
window.navSynchroniserMenu = navSynchroniserMenu;
window.navRegrouperMenu = navRegrouperMenu;

function getRoleNav(role){
  if(role===ROLES.ADMIN) return ADMIN_NAV;
  if(role===ROLES.COMMERCIAL) return COM_NAV;
  if(role===ROLES.SECRETAIRE) return SECRETAIRE_NAV;
  if(role===ROLES.CONTROLEUR) return CONTROLEUR_NAV;
  if(role===ROLES.GESTIONNAIRE_STOCK) return GSTOCK_NAV;
  if(role===ROLES.CHEF_AGENCE) return CHEF_AGENCE_NAV;
  return COM_NAV;
}
function getRoleHome(role){
  if(role===ROLES.ADMIN) return 'admin-dashboard';
  if(role===ROLES.COMMERCIAL) return 'saisie-mises';
  if(role===ROLES.SECRETAIRE) return 'registre';
  if(role===ROLES.CONTROLEUR) return 'controle';
  if(role===ROLES.GESTIONNAIRE_STOCK) return 'stock';
  if(role===ROLES.CHEF_AGENCE) return 'registre';
  return 'com-clients';
}

function setupUI(){
  const u = (DB.commerciaux||[]).find(c=>c._id===session.userId);
  // ── VOLET 10 ── garde defensive. Sans elle, `u.nom[0]` leve une
  // TypeError et TOUT le demarrage s'arrete, ecran vide, sans message.
  // Cela pouvait deja arriver si le chargement de 'commerciaux' echouait
  // (reseau, regles Firestore) ; c'est desormais possible aussi pendant le
  // rendu optimiste, avant que le reseau ait repondu. On affiche alors des
  // valeurs neutres : l'interface se remplit au rendu suivant.
  if (!u) {
    document.getElementById('s-av').textContent = '?';
    document.getElementById('s-nm').textContent = (session && session.nom) || '…';
    document.getElementById('s-rl').textContent = '…';
    // ── VOLET 21 ── innerHTML remplace les noeuds : le marqueur doit etre
  // remis a zero, sinon navRegrouperMenu() croirait le travail deja fait et
  // laisserait le menu a plat.
  document.getElementById('nav-menu').innerHTML = getRoleNav(session.role);
  document.getElementById('nav-menu').dataset.regroupe = '';
  navRegrouperMenu();
    document.getElementById('today-pill').textContent =
      new Date().toLocaleDateString('fr-FR',{weekday:'short',day:'numeric',month:'long'});
    return;
  }
  document.getElementById('s-av').textContent = u.nom[0];
  document.getElementById('s-nm').textContent = u.nom;
  const ag = u.agenceId ? getAgence(u.agenceId) : null;
  const agLabel = ag ? ' · 🏢 '+ag.nom : '';
  document.getElementById('s-rl').textContent = getRoleLabel(u.role)+(u.zone?' · '+u.zone:'')+agLabel;
  // ── VOLET 21 ── innerHTML remplace les noeuds : le marqueur doit etre
  // remis a zero, sinon navRegrouperMenu() croirait le travail deja fait et
  // laisserait le menu a plat.
  document.getElementById('nav-menu').innerHTML = getRoleNav(session.role);
  document.getElementById('nav-menu').dataset.regroupe = '';
  navRegrouperMenu();
  document.getElementById('today-pill').textContent = new Date().toLocaleDateString('fr-FR',{weekday:'short',day:'numeric',month:'long'});
}

