// ═══════════════════════════════════════════════════════════════
//  DEMANDES DE LIVRAISON (chef d'agence ↔ gestionnaire de stock)
// ═══════════════════════════════════════════════════════════════
// Cycle : en_attente → partielle (si une ligne indisponible) → cloturee.
// Une ligne indisponible porte un délai d'attente (en jours) ; une fois
// échu, une NOUVELLE demande "en_attente" est générée automatiquement pour
// cette ligne (voir _checkRecreationDemandes), afin que le chef d'agence
// n'ait pas à ressaisir sa demande manuellement.

let demandeLignesTmp = []; // lignes en cours de construction dans le modal de création

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 50 — DEMANDES DE LIVRAISON DES AGENCES PAR ARTICLE      ║
// ╚══════════════════════════════════════════════════════════════╝
// Les NOUVELLES demandes portent des ARTICLES (stock physique) au lieu de
// produits. Chaque nouvelle ligne est marquée nature:'article' :
//   { nature:'article', articleId, articleNom, articleRef, unite, qteDemandee, … }
// Les lignes SANS ce marqueur sont des lignes PRODUIT, créées avant ce volet :
//   { produitId, produitNom, produitRef, qteDemandee, … }
// Elles restent affichées, traitées, recréées et décomposées en articles
// (via la composition du produit) EXACTEMENT comme avant : rien n'est
// converti ni réécrit dans les demandes existantes.
function _dlEstArticle(l){ return !!l && l.nature === 'article'; }
function _dlLigneCle(l){ return _dlEstArticle(l) ? l.articleId : l.produitId; }
function _dlLigneLib(l){
  const ref = _dlEstArticle(l) ? l.articleRef : l.produitRef;
  const nom = _dlEstArticle(l) ? l.articleNom : l.produitNom;
  return `${ref?`<span style="color:var(--muted);">${esc(ref)}</span> — `:''}${esc(nom||'—')}`
    + (_dlEstArticle(l) ? (l.unite ? ` <span style="color:var(--muted);font-size:10px;">(${esc(l.unite)})</span>` : '')
                        : ` <span style="font-size:9px;padding:0 5px;border-radius:4px;border:1px solid var(--border);color:var(--muted);">produit</span>`);
}

function _demandeAgenceId(){
  const u = DB.commerciaux.find(c=>c._id===session.userId);
  return u?.agenceId || '';
}

window.openModalDemandeLivraison = function(){
  if(session?.role !== 'chef_agence'){ notify("Accès réservé au chef d'agence",'err'); return; }
  demandeLignesTmp = [];
  // ── VOLET 50 ── liste des ARTICLES (le stock physique), plus des produits.
  _dlRemplirArticles('');
  const refEl = document.getElementById('dl-ref'); if(refEl) refEl.value = '';
  const qtyEl = document.getElementById('dl-qty'); if(qtyEl) qtyEl.value = 1;
  const noteEl = document.getElementById('dl-note'); if(noteEl) noteEl.value = '';
  _renderDemandeLignesTmp();
  openM('m-demande-livraison');
};

// Recherche un produit par son code/référence (saisi dans la case dédiée)
// et sélectionne automatiquement l'option correspondante dans la liste.
// ── VOLET 51 ── RECHERCHE PAR NOM OU PAR CODE (formulaire de demande).
// À la frappe, la liste ne garde que les articles dont le CODE ou le NOM
// contient le texte saisi (majuscules et accents ignorés). Un code exact, ou
// un seul résultat, est sélectionné d'office. AVANT : code exact uniquement,
// à la validation du champ.
function _dlNormaliser(t){
  return String(t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
}
function _dlRemplirArticles(q){
  const sel = document.getElementById('dl-produit');
  if(!sel) return [];
  const n = _dlNormaliser(q);
  const liste = (DB.articles||[])
    .filter(a => !n || _dlNormaliser(a.ref).includes(n) || _dlNormaliser(a.nom).includes(n))
    .sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  sel.innerHTML = `<option value="">${n ? `— ${liste.length} article(s) trouvé(s) —` : '— Sélectionner un article —'}</option>` +
    liste.map(a=>`<option value="${a._id}" data-ref="${esc(a.ref||'')}">${esc(a.ref?a.ref+' — ':'')}${esc(a.nom||'')}${a.unite?' ('+esc(a.unite)+')':''}</option>`).join('');
  return liste;
}
window.dlChercherParRef = function(){
  const refEl = document.getElementById('dl-ref');
  const sel = document.getElementById('dl-produit');
  if(!refEl || !sel) return;
  const q = refEl.value;
  const liste = _dlRemplirArticles(q);
  if(!_dlNormaliser(q)) return;
  const exact = liste.find(a => _dlNormaliser(a.ref) === _dlNormaliser(q));
  if(exact) sel.value = exact._id;
  else if(liste.length === 1) sel.value = liste[0]._id;
};

// Quand on choisit un produit dans la liste, on affiche sa référence dans la case.
window.dlSyncRefDepuisSelect = function(){
  const sel = document.getElementById('dl-produit');
  const refEl = document.getElementById('dl-ref');
  if(!sel || !refEl) return;
  const opt = sel.options[sel.selectedIndex];
  // ── VOLET 51 ── on n'écrase la recherche que si l'article choisi a un code.
  const ref = opt ? (opt.getAttribute('data-ref')||'') : '';
  if(ref) refEl.value = ref;
};

window.dlAjouterLigne = function(){
  const sel = document.getElementById('dl-produit');
  const pid = sel?.value;
  const qty = parseInt(document.getElementById('dl-qty')?.value)||0;
  if(!pid){ notify('Choisissez un article (ou saisissez son code)','err'); return; }
  if(qty<=0){ notify('Quantité invalide','err'); return; }
  // ── VOLET 50 ── ligne ARTICLE.
  const art = (DB.articles||[]).find(a=>a._id===pid);
  if(!art) return;
  const existant = demandeLignesTmp.find(l=>_dlEstArticle(l) && l.articleId===pid);
  if(existant) existant.qteDemandee += qty;
  else demandeLignesTmp.push({nature:'article', articleId:pid, articleNom:art.nom||'', articleRef:art.ref||'', unite:art.unite||'', qteDemandee:qty});
  document.getElementById('dl-qty').value = 1;
  document.getElementById('dl-ref').value = '';
  _dlRemplirArticles('');   // ── VOLET 51 ── liste complète pour la ligne suivante
  _renderDemandeLignesTmp();
};

window.dlSupprimerLigne = function(pid){
  demandeLignesTmp = demandeLignesTmp.filter(l=>_dlLigneCle(l)!==pid);
  _renderDemandeLignesTmp();
};

function _renderDemandeLignesTmp(){
  const tb = document.getElementById('dl-lignes-body');
  if(!tb) return;
  if(!demandeLignesTmp.length){
    tb.innerHTML = '<tr><td colspan="3" style="text-align:center;color:var(--muted);padding:14px;">Aucun article ajouté</td></tr>';
    return;
  }
  tb.innerHTML = demandeLignesTmp.map(l=>`<tr>
    <td>${_dlLigneLib(l)}</td>
    <td>${l.qteDemandee}</td>
    <td><button class="btn btn-ghost btn-sm" onclick="dlSupprimerLigne('${_dlLigneCle(l)}')">✕</button></td>
  </tr>`).join('');
}

window.saveDemandeLivraison = _withActionLock('saveDemandeLivraison', async function(){
  if(!demandeLignesTmp.length){ notify('Ajoutez au moins un article à la demande','err'); return; }
  const agenceId = _demandeAgenceId();
  if(!agenceId){ notify('Aucune agence associée à votre compte','err'); return; }
  await fbAdd('demandesLivraison', {
    agenceId,
    agenceNom: getAgence(agenceId).nom,
    chefAgenceId: session.userId,
    chefAgenceNom: session.nom,
    statut: 'en_attente',
    lignes: demandeLignesTmp.map(l=>({...l, qteEnvoyee:0, statutLigne:'en_attente', delaiJours:0, delaiDate:'', recreee:false})),
    dateCreation: TODAY,
    note: document.getElementById('dl-note')?.value || ''
  });
  closeM('m-demande-livraison');
  notify('Demande de livraison envoyée ✓');
  demandeLignesTmp = [];
  renderDemandesLivraison();
});

// ── Traitement par le gestionnaire de stock (ou admin) : pour chaque ligne,
// il indique la quantité effectivement envoyée, ou la marque indisponible
// avec un délai d'attente (en jours) avant nouvelle tentative automatique.
// Calcule, pour un ensemble de lignes de produits (produitId + quantité),
// la liste agrégée des articles physiques à préparer (via la composition
// de chaque produit), pour que le gestionnaire sache exactement quoi sortir.
function _articlesAPreparerPourLignes(lignes){
  const totaux = {}; // articleId -> {nom, unite, qte}
  lignes.forEach(({produitId, articleId, qte})=>{
    // ── VOLET 50 ── ligne ARTICLE : l'article lui-même, sans décomposition.
    if(articleId){
      const a = (DB.articles||[]).find(x=>x._id===articleId) || {};
      if(!totaux[articleId]) totaux[articleId] = {nom:a.nom||'—', unite:a.unite||'', qte:0};
      totaux[articleId].qte += qte;
      return;
    }
    // Ligne PRODUIT (demandes antérieures) : décomposition comme avant.
    const prod = DB.produits.find(p=>p._id===produitId);
    const comp = prod?.composition || [];
    comp.forEach(c=>{
      const q = (c.qte||0) * qte;
      if(!totaux[c.articleId]) totaux[c.articleId] = {nom:c.nom, unite:c.unite||'', qte:0};
      totaux[c.articleId].qte += q;
    });
  });
  return Object.values(totaux).sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
}

// Lit l'état courant du formulaire de traitement (qté envoyée / indisponible)
// et affiche la liste des articles composants à préparer pour les lignes
// qui seront effectivement envoyées.
window.dlGenererListeArticles = function(demandeId){
  const d = DB.demandesLivraison.find(x=>x._id===demandeId);
  if(!d) return;
  const lignesEnvoi = [];
  d.lignes.forEach((l,i)=>{
    const indispo = document.getElementById('dl-tr-indispo-'+i)?.checked;
    if(indispo) return;
    const qty = Math.max(0, Math.min(l.qteDemandee, parseInt(document.getElementById('dl-tr-qty-'+i)?.value)||0));
    if(qty>0) lignesEnvoi.push(_dlEstArticle(l) ? {articleId:l.articleId, qte:qty} : {produitId:l.produitId, qte:qty});
  });
  const articles = _articlesAPreparerPourLignes(lignesEnvoi);
  const zone = document.getElementById('dl-tr-articles-zone');
  if(!zone) return;
  if(!articles.length){
    zone.innerHTML = '<div style="font-size:12px;color:var(--muted);">Aucun article à préparer (aucune quantité envoyée ou composition non renseignée).</div>';
    return;
  }
  zone.innerHTML = `<div style="font-size:11px;font-weight:700;color:var(--muted);margin-bottom:6px;">📋 Articles à préparer :</div>` +
    articles.map(a=>`<div style="font-size:12px;padding:3px 0;display:flex;justify-content:space-between;"><span>${esc(a.nom)}</span><strong>${a.qte} ${esc(a.unite)}</strong></div>`).join('');
};

window.ouvrirTraitementDemande = function(demandeId){
  if(!['admin','gestionnaire_stock'].includes(session?.role)){ notify('Accès non autorisé','err'); return; }
  const d = DB.demandesLivraison.find(x=>x._id===demandeId);
  if(!d){ notify('Demande introuvable','err'); return; }
  let overlay = document.getElementById('dl-traiter-overlay');
  if(overlay) overlay.remove();
  overlay = document.createElement('div');
  overlay.id = 'dl-traiter-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9998;display:flex;align-items:center;justify-content:center;padding:20px;';
  overlay.onclick = (e)=>{ if(e.target===overlay) overlay.remove(); };
  const lignesHtml = d.lignes.map((l,i)=>`
    <div style="border:1px solid var(--border);border-radius:10px;padding:12px;margin-bottom:10px;background:var(--surface2);">
      <div style="font-weight:700;font-size:13px;margin-bottom:8px;">${_dlLigneLib(l)} <span style="color:var(--muted);font-weight:400;">— demandé : ${l.qteDemandee}</span></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
        <label style="font-size:11px;color:var(--muted);">Qté envoyée</label>
        <input type="number" id="dl-tr-qty-${i}" value="${l.statutLigne==='envoye'?l.qteEnvoyee:l.qteDemandee}" min="0" max="${l.qteDemandee}" style="width:80px;background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);">
        <label style="font-size:11px;color:var(--muted);margin-left:10px;display:flex;align-items:center;gap:4px;">
          <input type="checkbox" id="dl-tr-indispo-${i}" ${l.statutLigne==='indisponible'?'checked':''} onchange="dlToggleIndispo(${i})"> Indisponible
        </label>
        <span id="dl-tr-delai-wrap-${i}" style="display:${l.statutLigne==='indisponible'?'inline-flex':'none'};align-items:center;gap:6px;">
          <label style="font-size:11px;color:var(--muted);">Délai (jours)</label>
          <input type="number" id="dl-tr-delai-${i}" value="${l.delaiJours||3}" min="1" style="width:60px;background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);">
        </span>
      </div>
    </div>`).join('');
  overlay.innerHTML = `
    <div style="background:var(--card);border:1px solid var(--border);border-radius:14px;max-width:560px;width:100%;max-height:85vh;display:flex;flex-direction:column;overflow:hidden;">
      <div style="display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid var(--border);">
        <strong style="font-size:15px;">🚚 Traiter la demande — ${esc(d.agenceNom||'')}</strong>
        <button onclick="document.getElementById('dl-traiter-overlay').remove()" style="background:none;border:none;color:var(--muted);font-size:20px;cursor:pointer;">✕</button>
      </div>
      <div style="overflow-y:auto;padding:16px 20px;">
        <div style="font-size:11px;color:var(--muted);margin-bottom:10px;">Demandé par ${esc(d.chefAgenceNom||'')} le ${d.dateCreation}</div>
        <div style="margin-bottom:14px;">
          <label style="font-size:11px;color:var(--muted);display:block;margin-bottom:4px;">📅 Date d'envoi effective (pour les articles disponibles)</label>
          <input type="date" id="dl-tr-date-envoi" value="${d.dateEnvoiPrevue||TODAY}" style="background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:6px 10px;color:var(--text);">
        </div>
        ${lignesHtml}
        <div style="margin-top:6px;">
          <button class="btn btn-ghost btn-sm" onclick="dlGenererListeArticles('${d._id}')">📋 Générer la liste des articles à préparer</button>
          <div id="dl-tr-articles-zone" style="margin-top:10px;border:1px dashed var(--border);border-radius:10px;padding:10px 12px;"></div>
        </div>
        <div style="margin-top:14px;">
          <label style="font-size:11px;color:var(--muted);display:block;margin-bottom:4px;">📝 Note pour le chef d'agence (optionnelle)</label>
          <textarea id="dl-tr-note" rows="2" placeholder="Ex. : article X en rupture générale, arrivage prévu semaine prochaine…" style="width:100%;background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:6px 10px;color:var(--text);resize:vertical;">${esc(d.noteTraitement||'')}</textarea>
        </div>
      </div>
      <div style="padding:14px 20px;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:8px;">
        <button class="btn btn-ghost" onclick="document.getElementById('dl-traiter-overlay').remove()">Annuler</button>
        <button class="btn btn-primary" onclick="confirmerTraitementDemande('${d._id}')">✅ Valider</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
};

window.dlToggleIndispo = function(i){
  const wrap = document.getElementById('dl-tr-delai-wrap-'+i);
  const cb = document.getElementById('dl-tr-indispo-'+i);
  if(wrap) wrap.style.display = cb.checked ? 'inline-flex' : 'none';
};

window.confirmerTraitementDemande = _withActionLock((...a)=>'confirmerTraitementDemande:'+a.join(':'), async function(demandeId){
  const d = DB.demandesLivraison.find(x=>x._id===demandeId);
  if(!d) return;
  const nouvellesLignes = d.lignes.map((l,i)=>{
    const indispo = document.getElementById('dl-tr-indispo-'+i)?.checked;
    if(indispo){
      const delaiJours = Math.max(1, parseInt(document.getElementById('dl-tr-delai-'+i)?.value)||3);
      const delaiDate = new Date(Date.now()+delaiJours*86400000).toISOString().split('T')[0];
      return {...l, statutLigne:'indisponible', qteEnvoyee:0, delaiJours, delaiDate, recreee:false};
    }
    const qty = Math.max(0, Math.min(l.qteDemandee, parseInt(document.getElementById('dl-tr-qty-'+i)?.value)||0));
    return {...l, statutLigne:'envoye', qteEnvoyee:qty, delaiJours:0, delaiDate:''};
  });
  const dateEnvoi = document.getElementById('dl-tr-date-envoi')?.value;
  const yaDesLignesEnvoyees = nouvellesLignes.some(l=>l.statutLigne==='envoye' && l.qteEnvoyee>0);
  if(yaDesLignesEnvoyees && !dateEnvoi){ notify("Indiquez la date d'envoi effective",'err'); return; }
  const toutesEnvoyees = nouvellesLignes.every(l=>l.statutLigne==='envoye');
  const statut = toutesEnvoyees ? 'cloturee' : 'partielle';
  const noteTraitement = (document.getElementById('dl-tr-note')?.value || '').trim();
  const recapNote = noteTraitement ? `\n\nNote pour le chef d'agence :\n« ${noteTraitement} »` : '';
  if(!(await confirmDialog(`Confirmer le traitement de cette demande pour « ${d.agenceNom||''} » ?${recapNote}`,{title:'✅ Confirmer le traitement',okLabel:'Confirmer'}))) return;
  await fbUpdate('demandesLivraison', demandeId, {
    lignes: nouvellesLignes,
    statut,
    dateEnvoiPrevue: dateEnvoi || '',
    dateTraitement: TODAY,
    traiteParId: session.userId,
    traiteParNom: session.nom,
    noteTraitement
  });
  document.getElementById('dl-traiter-overlay')?.remove();
  notify('Demande traitée ✓');
  renderDemandesLivraison();
});

// Suppression d'une demande de livraison — réservée à l'admin (une demande
// déjà envoyée aux agences/commerciaux ne doit pas pouvoir être effacée par
// n'importe qui, seulement corrigée en cas d'erreur de saisie par exemple).
window.supprimerDemandeLivraison = _withActionLock((...a)=>'supprimerDemandeLivraison:'+a.join(':'), async function(demandeId){
  if(session?.role !== 'admin'){ notify('Accès refusé — admin uniquement','err'); return; }
  const d = DB.demandesLivraison.find(x=>x._id===demandeId);
  if(!d){ notify('Demande introuvable','err'); return; }
  if(!(await confirmDialog(`Supprimer la demande de livraison de « ${esc(d.agenceNom||'')} » du ${d.dateCreation} ?`,{title:'🗑 Suppression demande de livraison',okLabel:'Supprimer',danger:true}))) return;
  // ── VOLET 38 ──
  if(!(await _auditAvantSuppression('demandesLivraison', demandeId, {
    agenceId: d.agenceId||'', date: d.dateCreation||'',
    libelleCourt: `${d.agenceNom||'—'} — ${d.statut||'—'}`
  }))) return;
  await fbDelete('demandesLivraison', demandeId);
  notify('Demande de livraison supprimée');
  renderDemandesLivraison();
});

// ── Recréation automatique : pour toute ligne indisponible dont le délai
// est échu et qui n'a pas encore été reprise, on génère une nouvelle
// demande "en_attente" reprenant uniquement cette ligne, et on marque
// l'ancienne ligne comme reprise (recreee) pour ne jamais la dupliquer.
async function _checkRecreationDemandes(){
  const today = TODAY;
  for(const d of DB.demandesLivraison.slice()){
    if(d.statut!=='partielle') continue;
    const lignesAReprendre = d.lignes.filter(l=>l.statutLigne==='indisponible' && !l.recreee && l.delaiDate && l.delaiDate<=today);
    if(!lignesAReprendre.length) continue;
    const majLignes = d.lignes.map(l=>lignesAReprendre.includes(l) ? {...l, recreee:true} : l);
    await fbUpdate('demandesLivraison', d._id, {lignes: majLignes});
    await fbAdd('demandesLivraison', {
      agenceId: d.agenceId,
      agenceNom: d.agenceNom,
      chefAgenceId: d.chefAgenceId,
      chefAgenceNom: d.chefAgenceNom,
      statut: 'en_attente',
      // ── VOLET 50 ── la ligne reprise garde sa nature (article OU produit).
      lignes: lignesAReprendre.map(l=>({...(_dlEstArticle(l)
          ? {nature:'article', articleId:l.articleId, articleNom:l.articleNom||'', articleRef:l.articleRef||'', unite:l.unite||''}
          : {produitId:l.produitId, produitNom:l.produitNom, produitRef:l.produitRef||''}),
        qteDemandee:l.qteDemandee, qteEnvoyee:0, statutLigne:'en_attente', delaiJours:0, delaiDate:'', recreee:false})),
      dateCreation: today,
      note: 'Générée automatiquement — articles indisponibles de la demande précédente (délai écoulé)',
      demandeParentId: d._id
    });
  }
}

// ✅ Filtre par statut (chips "Toutes / En attente / Partielle / Clôturée",
// voir filtrerDemandesStatut). Valeurs alignées sur d.statut telles qu'écrites
// par saveDemandeLivraison/ouvrirTraitementDemande : 'en_attente','partielle','cloturee'.
let dlFiltreStatut = '';
window.filtrerDemandesStatut = function(s, btn){
  dlFiltreStatut = s;
  document.querySelectorAll('#dl-filtre-statut-bar .prod-filter-chip').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  renderDemandesLivraison();
};

async function renderDemandesLivraison(){
  const role = session?.role;
  await _checkRecreationDemandes();

  let demandes = (DB.demandesLivraison||[]).slice();
  if(role==='chef_agence'){
    const agenceId = _demandeAgenceId();
    demandes = demandes.filter(d=>d.agenceId===agenceId);
  }

  // Total de reference : AVANT le filtre agence et le filtre de date, mais
  // APRES la restriction par role. C'est le nombre de demandes que ce role
  // peut voir en tout.
  const totalAvantFiltre = demandes.length;
  let _dlAgenceActive = false;

  // ── VOLET 15 ── filtre agence ────────────────────────────────────────
  // Le chef d'agence est deja restreint a la sienne ci-dessus : le
  // selecteur reste masque pour lui. Il sert a l'admin, au gestionnaire de
  // stock et au controleur, qui voient les demandes de TOUTES les agences.
  const _dlWrap = document.getElementById('dl-agence-wrap');
  const _dlSelAg = document.getElementById('dl-filter-agence');
  if(_dlWrap) _dlWrap.style.display = (role==='chef_agence') ? 'none' : 'inline-flex';
  if(_dlSelAg && role!=='chef_agence'){
    // Repeuplement uniquement si la liste des agences a change : sinon le
    // choix en cours serait perdu a chaque re-rendu (statut, date...).
    const _ags = (DB.agences||[]).slice().sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
    const _sig = _ags.map(a=>a._id).join(',');
    if(_dlSelAg.dataset.sig !== _sig){
      const _prev = _dlSelAg.value;
      _dlSelAg.innerHTML = '<option value="">Toutes les agences</option>'
        + _ags.map(a=>`<option value="${esc(a._id)}">${esc(a.nom||'(sans nom)')}</option>`).join('');
      _dlSelAg.dataset.sig = _sig;
      // On ne restaure le choix precedent que s'il existe encore.
      if(_prev && _ags.some(a=>a._id===_prev)) _dlSelAg.value = _prev;
    }
    const _agFiltre = _dlSelAg.value;
    if(_agFiltre){ _dlAgenceActive = true; demandes = demandes.filter(d=>d.agenceId===_agFiltre); }
  }
  // ── Filtre par date (sur la date de création de la demande) ──
  // Comparaison lexicographique valide car dateCreation est au format ISO 'AAAA-MM-JJ'.
  // ── VOLET 15 ── le total de reference est celui d'AVANT le filtre agence
  // (calcule plus haut), pour que « 3 / 12 » se lise « 3 affichees sur 12
  // demandes visibles par ce role ».
  const dateDebut = document.getElementById('dl-date-debut')?.value||'';
  const dateFin = document.getElementById('dl-date-fin')?.value||'';
  if(dateDebut) demandes = demandes.filter(d=>(d.dateCreation||'') >= dateDebut);
  if(dateFin) demandes = demandes.filter(d=>(d.dateCreation||'') <= dateFin);
  const countEl = document.getElementById('dl-date-count');
  if(countEl) countEl.textContent = (dateDebut||dateFin||_dlAgenceActive)
    ? `(${demandes.length} / ${totalAvantFiltre})` : '';

  // ── Filtre par statut ── Les compteurs des chips reflètent la plage de
  // dates déjà appliquée ci-dessus, mais pas le statut sélectionné lui-même
  // (sinon les autres chips retomberaient toujours à 0 une fois un statut
  // choisi) — même logique que les chips de catégorie de la page Produits.
  const cntEnAttente = demandes.filter(d=>d.statut==='en_attente').length;
  const cntPartielle = demandes.filter(d=>d.statut==='partielle').length;
  const cntCloturee  = demandes.filter(d=>d.statut==='cloturee').length;
  const elToutes = document.getElementById('dl-cnt-toutes');
  const elEnAttente = document.getElementById('dl-cnt-en_attente');
  const elPartielle = document.getElementById('dl-cnt-partielle');
  const elCloturee = document.getElementById('dl-cnt-cloturee');
  if(elToutes) elToutes.textContent = demandes.length;
  if(elEnAttente) elEnAttente.textContent = cntEnAttente;
  if(elPartielle) elPartielle.textContent = cntPartielle;
  if(elCloturee) elCloturee.textContent = cntCloturee;
  if(dlFiltreStatut) demandes = demandes.filter(d=>d.statut===dlFiltreStatut);

  demandes.sort((a,b)=> (b.dateCreation||'').localeCompare(a.dateCreation||'') || (b._id||'').localeCompare(a._id||''));

  const statutBadge = (s)=>({
    en_attente: '<span style="font-size:11px;font-weight:700;padding:3px 9px;border-radius:20px;background:rgba(201,168,76,0.15);color:var(--warn);">⏳ En attente</span>',
    partielle:  '<span style="font-size:11px;font-weight:700;padding:3px 9px;border-radius:20px;background:rgba(224,92,82,0.15);color:var(--danger);">⚠️ Partielle</span>',
    cloturee:   '<span style="font-size:11px;font-weight:700;padding:3px 9px;border-radius:20px;background:rgba(34,212,160,0.15);color:var(--accent2);">✅ Clôturée</span>'
  }[s] || s);

  const canTraiter = ['admin','gestionnaire_stock'].includes(role);
  const canSupprimer = role === 'admin';

  const cont = document.getElementById('dl-liste');
  if(!cont) return;
  if(!demandes.length){
    // ── VOLET 15 ── sans cette precision, une liste vide a cause du filtre
    // agence se lirait comme « il n'y a aucune demande ».
    cont.innerHTML = `<div style="text-align:center;color:var(--muted);padding:30px;">Aucune demande de livraison${dlFiltreStatut?' pour ce statut':''}${_dlAgenceActive?' dans cette agence':''}</div>`;
    return;
  }
  cont.innerHTML = demandes.map(d=>{
    const lignesHtml = d.lignes.map(l=>{
      const icon = l.statutLigne==='envoye' ? '✅' : l.statutLigne==='indisponible' ? '⛔' : '⏳';
      const detail = l.statutLigne==='envoye' ? `envoyé ${l.qteEnvoyee}/${l.qteDemandee}`
        : l.statutLigne==='indisponible' ? `indisponible — délai jusqu'au ${l.delaiDate}${l.recreee?' (nouvelle demande générée)':''}`
        : `demandé ${l.qteDemandee}`;
      return `<div style="font-size:12px;padding:3px 0;">${icon} ${_dlLigneLib(l)} — ${detail}</div>`;
    }).join('');
    return `<div style="border:1px solid var(--border);border-radius:12px;padding:14px 16px;margin-bottom:12px;background:var(--surface);">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:8px;">
        <div>
          <strong style="font-size:13px;">🏢 ${esc(d.agenceNom||'')}</strong>
          <span style="font-size:11px;color:var(--muted);margin-left:8px;">par ${esc(d.chefAgenceNom||'')} · ${d.dateCreation}</span>
        </div>
        ${statutBadge(d.statut)}
      </div>
      ${lignesHtml}
      ${d.dateEnvoiPrevue ? `<div style="font-size:11px;color:var(--accent2);margin-top:6px;">📅 Livraison prévue le <strong>${d.dateEnvoiPrevue}</strong></div>` : ''}
      ${d.note ? `<div style="font-size:11px;color:var(--muted);margin-top:6px;font-style:italic;">${esc(d.note)}</div>` : ''}
      ${d.noteTraitement ? `<div style="font-size:11px;color:var(--text);margin-top:6px;padding:6px 10px;background:var(--surface2);border-radius:8px;border-left:3px solid var(--accent2);"><strong>📝 Note du gestionnaire${d.traiteParNom?` (${esc(d.traiteParNom)})`:''} :</strong> ${esc(d.noteTraitement)}</div>` : ''}
      ${(canTraiter && d.statut!=='cloturee') || canSupprimer ? `<div style="margin-top:10px;display:flex;gap:8px;">
        ${canTraiter && d.statut!=='cloturee' ? `<button class="btn btn-primary btn-sm" onclick="ouvrirTraitementDemande('${d._id}')">Traiter</button>` : ''}
        ${canSupprimer ? `<button class="btn btn-warn btn-sm" onclick="supprimerDemandeLivraison('${d._id}')">🗑 Supprimer</button>` : ''}
      </div>` : ''}
    </div>`;
  }).join('');
}
// Exposée sur window : appelée directement par les attributs oninput des
// champs de filtre de date ajoutés ci-dessus (id="dl-date-debut"/"dl-date-fin").
window.renderDemandesLivraison = renderDemandesLivraison;

function renderArticles(){
  // ── Recherche ──
  const q = (document.getElementById('art-search')?.value||'').toLowerCase().trim();
  const qRef = (document.getElementById('art-filter-ref')?.value||'').toLowerCase().trim();
  // ── Tri ──
  const sort = document.getElementById('art-sort')?.value || 'nom';
  let arts = [...DB.articles];
  if(q) arts = arts.filter(a=>(a.nom||'').toLowerCase().includes(q)||(a.cat||'').toLowerCase().includes(q));
  if(qRef) arts = arts.filter(a=>(a.ref||'').toLowerCase().includes(qRef));
  arts.sort((a,b)=>{
    if(sort==='ref') return (a.ref||'').localeCompare(b.ref||'');
    if(sort==='pv_asc') return (a.pv||0)-(b.pv||0);
    if(sort==='pv_desc') return (b.pv||0)-(a.pv||0);
    if(sort==='stock_asc') return (a.stock||0)-(b.stock||0);
    if(sort==='stock_desc') return (b.stock||0)-(a.stock||0);
    return (a.nom||'').localeCompare(b.nom||'');
  });
  const isAdmin = ['admin','chef_agence'].includes(session?.role);

  // ── GALERIE ──
  document.getElementById('art-view-galerie').innerHTML = arts.length===0
    ? '<div class="emp" style="padding:40px;grid-column:1/-1;">Aucun article trouvé.</div>'
    : arts.map(a=>{
        const imgHtml = a.image
          ? `<img src="${a.image}" loading="lazy" decoding="async" alt="${esc(a.nom)}" style="width:100%;height:140px;object-fit:cover;display:block;">`
          : `<div style="width:100%;height:140px;background:var(--surface2);display:flex;align-items:center;justify-content:center;font-size:48px;">${catEmoji(a.cat)}</div>`;
        const stockColor = a.stock<=0?'var(--danger)':a.stock<=a.stockMin?'var(--accent3)':'var(--accent2)';
        const adminBtns = isAdmin ? `
          <div style="display:flex;gap:4px;padding:6px 10px 8px;border-top:1px solid var(--border);" onclick="event.stopPropagation()">
            <button class="btn btn-ghost btn-xs" style="flex:1;" onclick="editArt('${a._id}')">✏️ Modifier</button>
            <button class="btn btn-xs btn-warn" onclick="delArt('${a._id}')">🗑</button>
          </div>` : '';
        const refBadge = a.ref ? `<span class="art-card-ref-badge">🏷️ ${esc(a.ref)}</span>` : `<span style="font-size:9px;color:var(--muted);font-style:italic;">Sans réf.</span>`;
        return `<div class="art-card" onclick="ouvrirArtModal('${a._id}')">
          ${imgHtml}
          <div class="art-card-body">
            <div style="margin-bottom:3px;">${refBadge}</div>
            <div class="art-card-nom" title="${esc(a.nom)}">${esc(a.nom)}</div>
            <div style="font-size:9.5px;color:var(--muted);margin-bottom:4px;">${esc(a.cat||'—')}</div>
            <div class="art-card-stock" style="color:${stockColor}">Stock : ${a.stock} ${a.unite||'pcs'} ${stockStatut(a)}</div>
          </div>
          ${adminBtns}
        </div>`;
      }).join('');

  // ── LISTE ──
  document.getElementById('tb-articles').innerHTML = arts.map(a=>`<tr>
    <td style="width:46px;">
      ${a.image
        ? `<img src="${a.image}" loading="lazy" decoding="async" alt="" style="width:38px;height:38px;object-fit:cover;border-radius:6px;cursor:pointer;" onclick="ouvrirArtModal('${a._id}')">`
        : `<div style="width:38px;height:38px;border-radius:6px;background:var(--surface2);display:flex;align-items:center;justify-content:center;font-size:20px;cursor:pointer;" onclick="ouvrirArtModal('${a._id}')">${catEmoji(a.cat)}</div>`}
    </td>
    <td><span style="display:inline-block;background:rgba(201,168,76,0.13);border:1px solid rgba(201,168,76,0.3);border-radius:5px;padding:2px 8px;font-size:11px;color:var(--accent);font-weight:700;letter-spacing:0.3px;">${esc(a.ref)||'—'}</span></td><td class="fw6">${esc(a.nom)}</td><td class="tm">${esc(a.cat)}</td>
    <td class="tm">${fmt(a.pa)}</td>
    <td><div style="font-weight:700;color:${a.stock<=0?'var(--danger)':a.stock<=a.stockMin?'var(--accent3)':'var(--accent2)'}">${a.stock} ${a.unite}</div><div class="stock-bar"><div class="stock-fill" style="width:${Math.min(100,a.stock*100/((a.stockMin*3)||1))}%;background:${a.stock<=0?'var(--danger)':a.stock<=a.stockMin?'var(--accent3)':'var(--accent2)'}"></div></div></td>
    <td class="tm">${a.stockMin}</td><td>${stockStatut(a)}</td>
    <td style="white-space:nowrap;">
      <button class="btn btn-ghost btn-xs" onclick="openMvtFor('${a._id}')" style="margin-right:3px"${['controleur'].includes(session?.role)?' hidden':''}>± Stock</button>
      ${isAdmin?`<button class="btn btn-ghost btn-xs" onclick="editArt('${a._id}')" style="margin-right:3px;">✏️</button><button class="btn btn-xs btn-warn" onclick="delArt('${a._id}')">🗑</button>`:''}
    </td>
  </tr>`).join('')||'<tr><td colspan="9" class="emp">Aucun article.</td></tr>';
}

function catEmoji(cat){
  const c=(cat||'').toLowerCase();
  if(c.includes('mob')||c.includes('cana')||c.includes('chais')) return '🛋️';
  if(c.includes('elec')||c.includes('tv')||c.includes('télé')) return '📺';
  if(c.includes('frigo')||c.includes('réfri')||c.includes('cong')) return '🧊';
  if(c.includes('cuisi')||c.includes('four')||c.includes('gas')) return '🍳';
  if(c.includes('info')||c.includes('ordi')||c.includes('pc')) return '💻';
  if(c.includes('télé')||c.includes('phone')||c.includes('mob')) return '📱';
  if(c.includes('linge')||c.includes('mach')) return '🫧';
  if(c.includes('clim')||c.includes('air')) return '❄️';
  return '📦';
}

let artImageModalId = null; // compat legacy

// ── Ouvrir modal image article → redirige vers zoom catalogue multi-images ──
window.ouvrirArtModal = function(artId){
  ouvrirZoomCatalogue(artId);
};

window.changerImageArticle = async function(input){
  if(!input.files[0]||!artImageModalId) return;
  const b64 = await fileToBase64(input.files[0]);
  if(!b64){ notify('Image trop grande (max 2 Mo)','err'); return; }
  await fbUpdate('articles', artImageModalId, {image: b64});
  document.getElementById('art-img-modal-img').src = b64;
  document.getElementById('art-img-modal-img').style.display = '';
  notify('Image mise à jour ✓');
};

window.supprimerImageArticle = async function(){
  if(!artImageModalId) return;
  if(!(await confirmDialog("Supprimer l'image de cet article ?",{title:'🗑 Suppression',okLabel:'Supprimer',danger:true}))) return;
  await fbUpdate('articles', artImageModalId, {image:''});
  document.getElementById('art-img-modal-img').src='';
  document.getElementById('art-img-modal-img').style.display='none';
  notify('Image supprimée');
};


function fileToBase64(file){
  return new Promise(res=>{
    if(file.size>2.5*1024*1024){res(null);return;}
    const r=new FileReader();
    r.onload=e=>res(e.target.result);
    r.onerror=()=>res(null);
    r.readAsDataURL(file);
  });
}

// ── VOLET 6 ── la page Stock affiche des CUMULS d'entrees/sorties par
// article, calcules sur tout l'historique des mouvements (volontairement
// independants du stock courant, qui peut avoir ete corrige a la main). Elle
// a donc besoin de la collection entiere, contrairement aux autres ecrans.
// A noter : avant ce volet, cette page ne chargeait qu'UNE page de 500
// mouvements (stockMvts n'etait pas dans _AUTO_FULL_LOAD_COLS) — ces cumuls
// etaient donc DEJA faux au-dela de 500 mouvements. Ce chargement explicite
// corrige ce defaut latent en meme temps.
// Le cout est paye uniquement a l'ouverture de cette page, plus au demarrage
// ni sur les autres ecrans — c'est bien du "a la demande".
// ── VOLET 14 ── _stockAssurerHistoriqueComplet() a ete SUPPRIMEE : elle
// n'avait qu'un seul appelant, renderStock(), d'ou le volet 14 l'a retiree.
// Son role est desormais tenu par stockChargerToutHistorique(), declenchee
// par un bouton et non plus automatiquement. Aucune fonctionnalite perdue :
// le chargement integral reste possible, il est simplement devenu explicite.

function renderStock(){
  // ── VOLET 14 ── le chargement integral automatique de 'stockMvts' est
  // SUPPRIME. Au volet 6 il etait declenche a chaque ouverture de la page,
  // parce que les cumuls de l'inventaire en avaient besoin. Cette collection
  // grossit indefiniment : la page devenait de plus en plus lente a ouvrir.
  // Desormais : la journee en cours suffit a l'ouverture ; l'historique
  // complet n'est charge que sur demande explicite (bouton « Charger tout
  // l'historique »), ou par plage de dates via les filtres.
  const _histoComplet = _loadedCols.has('stockMvts');
  document.getElementById('stock-kpi').innerHTML=`
    <div class="kpi-card kc-blue"><div class="kpi-lbl">Articles</div><div class="kpi-val kv-blue">${DB.articles.length}</div></div>
    <div class="kpi-card kc-red"><div class="kpi-lbl">Ruptures</div><div class="kpi-val kv-red">${DB.articles.filter(a=>a.stock<=0).length}</div></div>
    <div class="kpi-card kc-yellow"><div class="kpi-lbl">Stock bas</div><div class="kpi-val kv-yellow">${DB.articles.filter(a=>a.stock>0&&a.stock<=a.stockMin).length}</div></div>
    <div class="kpi-card kc-green"><div class="kpi-lbl">Mouvements</div><div class="kpi-val kv-green">${DB.stockMvts.length}</div><div class="kpi-sub">${_histoComplet?'historique complet':'chargés (période affichée)'}</div></div>`;
  renderStockMvts();
  // Peupler le filtre agences (une seule fois)
  const selAg = document.getElementById('stock-agence-filter');
  if(selAg && selAg.options.length <= 1){
    DB.agences.forEach(ag=>{
      const o=document.createElement('option');
      o.value=ag._id; o.textContent='🏢 '+ag.nom;
      selAg.appendChild(o);
    });
    if(session.role===ROLES.GESTIONNAIRE_STOCK){
      const agId=sessionAgenceId();
      if(agId) selAg.value=agId;
    }
  }
  renderStockParAgence();
  renderInventaire();
  // ✅ Générateur "Valeur des entrées" réservé à l'admin.
  const veWrap = document.getElementById('valeur-entrees-wrap');
  if(veWrap){
    veWrap.style.display = session?.role==='admin' ? '' : 'none';
    const dateEl = document.getElementById('ve-date');
    if(dateEl && !dateEl.value) dateEl.value = TODAY;
  }
}

// ─── Filtres (date + agence) sur les mouvements de stock ───
// Ces champs ne font pas partie du gabarit HTML statique : on les injecte
// une seule fois au premier rendu, juste à côté du champ de recherche
// existant, pour ne pas dépendre d'une modification du HTML. Idempotent
// (ne réinjecte pas si déjà présent), donc sans risque à chaque appel de
// renderStockMvts().
function _ensureStockMvtDateFilterUI(){
  if(document.getElementById('stock-mvt-date-debut')) return;
  const searchEl = document.getElementById('stock-mvt-search');
  if(!searchEl) return; // le conteneur attendu n'existe pas sur cette page
  const wrap = document.createElement('div');
  wrap.style.cssText = 'display:inline-flex;align-items:center;gap:6px;margin-left:8px;flex-wrap:wrap;';
  const optionsAgences = (DB.agences||[]).slice().sort((a,b)=>(a.nom||'').localeCompare(b.nom||'','fr'))
    .map(ag=>`<option value="${ag._id}">${esc(ag.nom)}</option>`).join('');
  wrap.innerHTML = `
    <label style="font-size:11px;color:var(--muted);">Du</label>
    <input type="date" id="stock-mvt-date-debut" oninput="renderStockMvts()" style="background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);">
    <label style="font-size:11px;color:var(--muted);">au</label>
    <input type="date" id="stock-mvt-date-fin" oninput="renderStockMvts()" style="background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);">
    <button class="btn btn-ghost btn-xs" onclick="document.getElementById('stock-mvt-date-debut').value='';document.getElementById('stock-mvt-date-fin').value='';renderStockMvts();">✕ Dates</button>
    <!-- ── VOLET 14 ── un SEUL bouton pour tout l'historique : il sert a la
         fois la liste des mouvements et les cumuls de l'inventaire. -->
    <button class="btn btn-xs" id="stock-mvt-tout-btn" onclick="stockChargerToutHistorique()"
      style="background:rgba(201,168,76,0.15);color:var(--accent);border:1px solid rgba(201,168,76,0.4);font-weight:700;"
      title="Charge l'intégralité des mouvements de stock — nécessaire pour les cumuls entrés/sortis de l'inventaire">📚 Charger tout l'historique</button>
    <!-- ── VOLET 47 ── filtre par code (référence) d'article -->
    <input type="text" id="stock-mvt-code" placeholder="Code article…" oninput="dRender('renderStockMvts')"
      style="background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--accent);font-weight:700;text-transform:uppercase;width:120px;">
    <label style="font-size:11px;color:var(--muted);margin-left:6px;">🏢 Agence</label>
    <select id="stock-mvt-filter-agence" onchange="renderStockMvts()" style="background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);">
      <option value="">Toutes</option>
      ${optionsAgences}
    </select>`;
  searchEl.insertAdjacentElement('afterend', wrap);
  // ── VOLET 47 ── zone du bilan entrées / sorties, au-dessus du tableau.
  const panel = document.getElementById('stock-mvt-panel');
  if(panel && !document.getElementById('stock-mvt-bilan')){
    const z = document.createElement('div'); z.id = 'stock-mvt-bilan'; z.style.marginBottom = '10px';
    panel.insertBefore(z, panel.firstChild);
  }
}

// ─── Rendu filtrable du tableau de mouvements ───
// ── VOLET 14 ── chargement integral, sur demande explicite uniquement.
// Sert la liste des mouvements ET les cumuls de l'inventaire : un seul
// bouton, une seule lecture, les deux affichages se mettent a jour.
let _stockToutEnCours = false;
window.stockChargerToutHistorique = async function(){
  if (_stockToutEnCours) return;
  if (_loadedCols.has('stockMvts')) { notify('Historique déjà chargé'); return; }
  _stockToutEnCours = true;
  const btn = document.getElementById('stock-mvt-tout-btn');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Chargement…'; }
  try {
    await _forceFullLoad('stockMvts');
    if (curPg === 'stock') renderStock();
    notify('📚 Historique complet des mouvements chargé');
  } catch(e) {
    console.error('[stock] chargement integral', e);
    notify("L'historique n'a pas pu être chargé — vérifiez votre connexion.", 'err');
  } finally {
    _stockToutEnCours = false;
    const b = document.getElementById('stock-mvt-tout-btn');
    if (b) { b.disabled = false; b.textContent = '📚 Charger tout l\'historique'; }
  }
};

// ── VOLET 14 ── quand l'utilisateur choisit une plage de dates, on va la
// chercher sur Firestore : sans cela, une periode anterieure n'afficherait
// RIEN, puisque DB.stockMvts ne contient que la journee en cours.
// Meme mecanisme que l'historique des recus et les depenses (volet 6).
let _stockRangeEnCours = null;
function _stockAssurerPlage(){
  if (_loadedCols.has('stockMvts')) return; // tout est deja la
  const d = document.getElementById('stock-mvt-date-debut')?.value || '';
  const f = document.getElementById('stock-mvt-date-fin')?.value || '';
  if (!d || !f) return;
  const cle = d + ':' + f;
  if (_stockRangeEnCours === cle) return;
  _stockRangeEnCours = cle;
  _fetchColDateRange('stockMvts', d, f)
    .then(() => { if (curPg === 'stock') renderStockMvts(); })
    .catch(e => console.error('[stock] plage', e));
}

// ── VOLET 47 ── BILAN ENTRÉES (approvisionnements) / SORTIES PAR ARTICLE
// Sur les mouvements filtrés (période, type, code, agence, recherche).
// Fiable seulement si la période est entièrement chargée : sinon, marqué
// PARTIEL (même principe que le bilan des carnets, volet 45).
function _stockPeriodeComplete(d, f){
  if(_loadedCols.has('stockMvts')) return true;
  if(!d || !f) return false;
  for(const k of Object.keys(_dateFetchCache || {})){
    if(!k.startsWith('range:stockMvts:')) continue;
    const [, , a, b] = k.split(':');
    if(a <= d && f <= b) return true;
  }
  return false;
}
function _stockRenderBilan(mvts, d, f, actif){
  const zone = document.getElementById('stock-mvt-bilan');
  if(!zone) return;
  if(!actif){ zone.innerHTML = ''; return; }
  const isAdm = session?.role === ROLES.ADMIN;
  const parArt = new Map();
  let qE = 0, qS = 0, vE = 0;
  mvts.forEach(m => {
    const a = getArt(m.articleId);
    const r = parArt.get(m.articleId) || { ref: a.ref || '—', nom: a.nom || '—', unite: a.unite || '', e: 0, s: 0, pa: Number(a.pa) || 0 };
    const q = Number(m.qty) || 0;
    if(m.type === 'entree'){ r.e += q; qE += q; vE += q * r.pa; } else { r.s += q; qS += q; }
    parArt.set(m.articleId, r);
  });
  const lignes = [...parArt.values()].sort((x,y) => (y.e + y.s) - (x.e + x.s));
  const complet = _stockPeriodeComplete(d, f);
  const alerte = complet ? '' : `<div class="ib ib-yellow" style="font-size:12px;margin-bottom:6px;">⚠️ <strong>Totaux partiels</strong> : ${(!d||!f)
      ? "renseignez les deux dates (Du / Au) pour charger la période, ou chargez tout l'historique."
      : "la période est en cours de chargement — les totaux se mettent à jour d'eux-mêmes."}</div>`;
  zone.innerHTML = `${alerte}
    <div class="kpi-row" style="margin-bottom:8px;">
      <div class="kpi-card kc-green"><div class="kpi-lbl">Entrées (approvisionnements)</div><div class="kpi-val kv-green">${qE}</div>${isAdm?`<div class="kpi-sub">valeur d'achat : ${fmt(vE)}</div>`:''}</div>
      <div class="kpi-card kc-red"><div class="kpi-lbl">Sorties</div><div class="kpi-val kv-red">${qS}</div></div>
      <div class="kpi-card kc-blue"><div class="kpi-lbl">Articles concernés</div><div class="kpi-val kv-blue">${lignes.length}</div></div>
    </div>
    ${lignes.length ? `<details ${lignes.length <= 8 ? 'open' : ''}><summary style="cursor:pointer;font-size:12px;font-weight:700;">📋 Détail par article</summary>
      <div class="tw" style="margin-top:6px;"><table><thead><tr><th>Code</th><th>Article</th><th style="text-align:center;">Entrées</th><th style="text-align:center;">Sorties</th>${isAdm?'<th style="text-align:right;">Valeur entrées</th>':''}</tr></thead><tbody>
      ${lignes.map(r => `<tr><td style="color:var(--accent);font-weight:700;">${esc(r.ref)}</td><td>${esc(r.nom)}</td>
        <td style="text-align:center;color:var(--accent2);font-weight:700;">${r.e} ${esc(r.unite)}</td><td style="text-align:center;color:var(--danger);">${r.s} ${esc(r.unite)}</td>
        ${isAdm?`<td style="text-align:right;">${r.pa>0?fmt(r.e*r.pa):'<span style="color:var(--warn)">prix non défini</span>'}</td>`:''}</tr>`).join('')}
      </tbody></table></div></details>` : ''}`;
}

window.renderStockMvts = function(){
  _ensureStockMvtDateFilterUI();
  _stockAssurerPlage();
  const q = (document.getElementById('stock-mvt-search')?.value||'').toLowerCase().trim();
  const filtType = document.getElementById('stock-mvt-filter-type')?.value||'';
  const sortMode = document.getElementById('stock-mvt-sort')?.value||'date-desc';
  const dateDebut = document.getElementById('stock-mvt-date-debut')?.value||'';
  const dateFin = document.getElementById('stock-mvt-date-fin')?.value||'';
  const filtAgence = document.getElementById('stock-mvt-filter-agence')?.value||'';
  // ── Tri du tableau ──
  // ✅ CORRIGÉ : 'date-desc'/'date-asc' faisaient auparavant un simple
  // .reverse() de l'ordre d'insertion de DB.stockMvts — pas un vrai tri sur
  // le champ 'date'. Un mouvement saisi en retard avec une date passée
  // restait alors affiché à sa place d'insertion au lieu d'être classé avec
  // les mouvements de sa vraie date. On trie maintenant explicitement sur
  // 'date' (comparaison lexicographique valide, format ISO 'AAAA-MM-JJ') ;
  // le tri étant stable, les mouvements d'une même date gardent entre eux
  // leur ordre d'insertion d'origine.
  // 'nom-asc'/'nom-desc' trient par nom d'article (localeCompare : respecte
  // les accents français, ex. "Écran" après "Eau").
  let mvts = [...DB.stockMvts];
  if(sortMode === 'nom-asc' || sortMode === 'nom-desc'){
    mvts = mvts
      .map(m => ({ m, nom: getArt(m.articleId)?.nom || '' }))
      .sort((a,b) => sortMode === 'nom-asc' ? a.nom.localeCompare(b.nom,'fr') : b.nom.localeCompare(a.nom,'fr'))
      .map(x => x.m);
  } else {
    const asc = sortMode === 'date-asc';
    mvts = mvts.sort((a,b)=>{
      const cmp = (a.date||'').localeCompare(b.date||'');
      return asc ? cmp : -cmp;
    });
  }
  if(filtType) mvts = mvts.filter(m=>m.type===filtType);
  // Comparaison lexicographique valide car m.date est au format ISO 'AAAA-MM-JJ'.
  if(dateDebut) mvts = mvts.filter(m=>(m.date||'') >= dateDebut);
  if(dateFin) mvts = mvts.filter(m=>(m.date||'') <= dateFin);
  // Filtre agence : couvre à la fois une sortie manuelle envoyée à cette
  // agence (destinationId, voir saveMvt) et une déduction automatique de
  // livraison sur le solde de cette agence (agenceId, voir deduireStockLivraison).
  if(filtAgence) mvts = mvts.filter(m=>m.destinationId===filtAgence || m.agenceId===filtAgence);
  // ── VOLET 47 ── code (référence) de l'article.
  const filtCode = (document.getElementById('stock-mvt-code')?.value || '').trim().toLowerCase();
  if(filtCode) mvts = mvts.filter(m => (getArt(m.articleId).ref || '').toLowerCase().includes(filtCode));
  if(q) mvts = mvts.filter(m=>{
    const a=getArt(m.articleId);
    return (a.nom||'').toLowerCase().includes(q)||
      (m.note||'').toLowerCase().includes(q)||
      (m.destinationNom||'').toLowerCase().includes(q)||
      (m.destinationLibre||'').toLowerCase().includes(q);
  });
  try { _stockRenderBilan(mvts, dateDebut, dateFin, !!(filtCode || dateDebut || dateFin || filtType)); } catch(e){ console.error('[stock] bilan', e); }
  const countEl = document.getElementById('stock-mvt-count');
  // ── VOLET 14 ── le denominateur n'est plus « tous les mouvements » mais
  // « ceux charges ». On le dit, plutot que de laisser croire a un total.
  if(countEl) countEl.textContent = _loadedCols.has('stockMvts')
    ? `(${mvts.length} / ${DB.stockMvts.length})`
    : `(${mvts.length} / ${DB.stockMvts.length} chargés)`;
  document.getElementById('tb-stock-mvt').innerHTML=mvts.map(m=>{
    const a=getArt(m.articleId);
    const destLabel = m.type==='sortie'
      ? (m.destinationNom ? `<span style="background:rgba(224,92,82,0.15);border:1px solid rgba(224,92,82,0.3);border-radius:5px;padding:2px 7px;font-size:10px;color:var(--danger);">🏢 ${esc(m.destinationNom)}</span>`
        : m.destinationLibre ? `<span style="font-size:11px;color:var(--warn);">✏️ ${esc(m.destinationLibre)}</span>`
        : '<span style="color:var(--muted);font-size:10px;">—</span>')
      : '<span style="color:var(--muted);font-size:10px;">—</span>';
    return`<tr>
      <td>${m.date}</td>
      <td class="fw6">${esc(a.nom)}</td>
      <td>${m.type==='entree'?sb('📥 Entrée','sg'):sb('📤 Sortie','sr')}</td>
      <td style="font-weight:700;color:${m.type==='entree'?'var(--accent2)':'var(--danger)'}">${m.type==='entree'?'+':'-'}${m.qty} ${esc(a.unite)}</td>
      <td class="fw6">${m.stockApres} ${esc(a.unite)}</td>
      <td>${destLabel}</td>
      <td class="tm" style="font-size:11px">${esc(m.note||'—')}</td>
      <td>${session?.role==='admin'?`<button class="btn btn-xs btn-warn" onclick="deleteStockMvt('${m._id}')" title="Supprimer ce mouvement et corriger le stock en conséquence">🗑</button>`:''}</td>
    </tr>`;
  }).join('')||'<tr><td colspan="8" class="emp">Aucun mouvement</td></tr>';
};

// ─── Suppression d'un mouvement de stock (admin uniquement) ───
// Corrige le stock courant de l'article en sens inverse du mouvement
// supprimé (une entrée supprimée retire la quantité, une sortie supprimée
// la restitue), puis supprime l'enregistrement du mouvement lui-même.
// ⚠️ Ne recalcule PAS rétroactivement le "stockApres" des mouvements
// suivants pour cet article : ces valeurs restent des photos historiques
// de l'état au moment de chaque mouvement, seul le stock courant de
// l'article (source de vérité pour les opérations futures) est corrigé.
window.deleteStockMvt = _withActionLock((...a)=>'deleteStockMvt:'+a.join(':'), async function(mvtId){
  if(session?.role!=='admin'){ notify('Accès réservé à l\'administrateur','err'); return; }
  const m = DB.stockMvts.find(x=>x._id===mvtId);
  if(!m){ notify('Mouvement introuvable','err'); return; }
  const art = DB.articles.find(a=>a._id===m.articleId);
  const ok = await confirmDialog(
    `Supprimer ce mouvement (${m.type==='entree'?'Entrée':'Sortie'} de ${m.qty} ${art?esc(art.unite):''} — ${art?esc(art.nom):'article inconnu'}) ?<br><br>Le stock actuel de l'article sera automatiquement corrigé en conséquence.`,
    {title:'🗑 Supprimer le mouvement', okLabel:'Supprimer', danger:true}
  );
  if(!ok) return;
  // ── VOLET 38 ── journal AVANT toute correction de stock : si le journal
  // echoue, on n'a ni touche au stock ni supprime le mouvement.
  if(!(await _auditAvantSuppression('stockMvts', mvtId, {
    agenceId: m.agenceId || m.destinationId || '',
    date: m.date||'', heure: m.heure||'',
    libelleCourt: `${m.type==='entree'?'Entrée':'Sortie'} ${m.qty} — ${art?art.nom:'article inconnu'}`,
    extra: { articleId: m.articleId||'', qty: m.qty||0, type: m.type||'' }
  }))) return;
  // ✅ Depuis la bascule vers le stock par agence, un mouvement de sortie
  // peut avoir affecté soit le stock global (mouvement manuel vers une
  // agence, avec destinationId), soit uniquement le solde d'une agence
  // (déduction automatique d'une livraison client, avec agenceId — voir
  // deduireStockLivraison) — jamais les deux à la fois pour une livraison.
  if(m.agenceId){
    // Mouvement issu d'une livraison client : seul le solde de l'agence a
    // été débité, le stock global n'a pas bougé.
    await ajusterStockAgence(m.agenceId, m.articleId, m.qty);
  } else {
    if(art){
      // Sens inverse du mouvement : une entrée supprimée retire la quantité
      // du stock, une sortie supprimée la restitue.
      const nouveauStock = art.stock + (m.type==='entree' ? -m.qty : m.qty);
      await fbUpdate('articles', art._id, {stock: nouveauStock});
    }
    if(m.type==='sortie' && m.destinationId){
      // Sortie manuelle vers une agence : elle avait aussi crédité son
      // solde — on le débite en retour.
      await ajusterStockAgence(m.destinationId, m.articleId, -m.qty);
    }
  }
  await fbDelete('stockMvts', mvtId);
  notify('Mouvement supprimé et stock corrigé ✓');
  renderStockMvts();
  renderInventaire();
});

// ─── Générateur : valeur totale des entrées d'un jour (prix d'achat) ───
// Réservé à l'admin. Calcule, pour une date donnée, la somme des quantités
// entrées (mouvements de type 'entree') multipliées par le prix d'achat
// (a.pa) de chaque article — donne la valeur d'achat totale réceptionnée
// ce jour-là, article par article et en cumul.
// ── VOLET 47 ── période (Du / Au) et code article. AVANT : un seul jour.
// La période est d'abord chargée (une lecture, mise en cache) si l'historique
// complet ne l'est pas : le total porte donc sur TOUTES les entrées.
window.calculerValeurEntrees = _withActionLock('calculerValeurEntrees', async function(){
  if(session?.role!=='admin'){ notify('Accès réservé à l\'administrateur','err'); return; }
  const date = document.getElementById('ve-date')?.value;
  const dateFin = document.getElementById('ve-date-fin')?.value || date;
  if(!date){ notify('Sélectionnez une date (ou une période)','err'); return; }
  if(dateFin < date){ notify('La date de fin est antérieure à la date de début','err'); return; }
  const code = (document.getElementById('ve-code')?.value || '').trim().toLowerCase();
  const totalEl = document.getElementById('ve-total');
  if(!_loadedCols.has('stockMvts')){
    if(totalEl) totalEl.textContent = '⏳ Chargement de la période…';
    await _fetchColDateRange('stockMvts', date, dateFin);
  }
  const entrees = (DB.stockMvts||[]).filter(m => m.type==='entree' && (m.date||'') >= date && (m.date||'') <= dateFin)
    .filter(m => !code || (getArt(m.articleId).ref || '').toLowerCase().includes(code));
  // Cumul par article (plusieurs entrées du même article possibles)
  const parArticle = {};
  entrees.forEach(m=>{
    if(!parArticle[m.articleId]) parArticle[m.articleId] = 0;
    parArticle[m.articleId] += (Number(m.qty)||0);
  });
  const tbody = document.getElementById('tb-valeur-entrees');
  const artIds = Object.keys(parArticle);
  const periode = date === dateFin ? `le ${date}` : `du ${date} au ${dateFin}`;
  if(!artIds.length){
    if(tbody) tbody.innerHTML = `<tr><td colspan="4" class="emp">Aucune entrée de stock ${esc(periode)}${code?' pour ce code':''}.</td></tr>`;
    if(totalEl) totalEl.textContent = 'Total : ' + fmt(0);
    return;
  }
  let totalGeneral = 0;
  const rows = artIds.map(aid=>{
    const a = getArt(aid);
    const qty = parArticle[aid];
    const pa = Number(a.pa)||0;
    const valeur = qty * pa;
    totalGeneral += valeur;
    return `<tr>
      <td class="fw6">${a.ref?`<span style="color:var(--accent);font-size:10px;">${esc(a.ref)}</span> `:''}${esc(a.nom)}</td>
      <td>${qty} ${esc(a.unite||'pcs')}</td>
      <td>${pa>0?fmt(pa):'<span style="color:var(--warn)">Non défini</span>'}</td>
      <td style="font-weight:700;color:var(--accent2);">${fmt(valeur)}</td>
    </tr>`;
  }).join('');
  if(tbody) tbody.innerHTML = rows;
  if(totalEl) totalEl.textContent = `Total ${periode} : ` + fmt(totalGeneral);
});

// ─── Collapse/expand mouvements ───
