// ═══ RECHERCHE ARTICLE DANS LE MODAL MOUVEMENT ═══
window.mvtArtLiveSearch = function(){
  const q = (document.getElementById('mvt-art-search').value||'').trim().toLowerCase();
  const res = document.getElementById('mvt-art-results');
  if(!q){ res.style.display='none'; return; }
  const found = DB.articles.filter(a=>
    (a.nom||'').toLowerCase().includes(q) ||
    (a.ref||'').toLowerCase().includes(q) ||
    (a.cat||'').toLowerCase().includes(q)
  ).slice(0,8);
  if(!found.length){
    res.style.display='block';
    res.innerHTML='<div style="padding:10px;font-size:12px;color:var(--muted);">Aucun article trouvé.</div>';
    return;
  }
  res.style.display='block';
  res.innerHTML=found.map(a=>{
    const stockColor = a.stock<=0?'var(--danger)':a.stock<=(a.stockMin||0)?'var(--warn)':'var(--accent2)';
    return `<div onclick="mvtSelectArt(${JSON.stringify({_id:a._id,nom:a.nom,ref:a.ref||'',stock:a.stock,unite:a.unite||'pcs',stockMin:a.stockMin||0}).replace(/"/g,'&quot;')})"
      style="padding:10px 12px;cursor:pointer;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;transition:background 0.12s;"
      onmouseover="this.style.background='rgba(212,137,58,0.1)'" onmouseout="this.style.background=''">
      <div>
        <div style="font-weight:700;font-size:13px;">${esc(a.nom)}</div>
        <div style="font-size:10px;color:var(--muted);margin-top:2px;">${a.ref?`<span style="color:var(--accent);font-weight:600;">Réf: ${esc(a.ref)}</span> · `:''} ${esc(a.cat||'—')}</div>
      </div>
      <div style="text-align:right;">
        <div style="font-size:13px;font-weight:800;color:${stockColor};">${a.stock} ${esc(a.unite||'pcs')}</div>
        <div style="font-size:10px;color:var(--muted);">en stock</div>
      </div>
    </div>`;
  }).join('');
};

window.mvtSelectArt = function(art){
  // art peut être un objet ou une string JSON
  if(typeof art === 'string') art = JSON.parse(art);
  document.getElementById('mvt-art').value = art._id;
  document.getElementById('mvt-art-search').style.display='none';
  document.getElementById('mvt-art-results').style.display='none';
  const stockColor = art.stock<=0?'var(--danger)':art.stock<=(art.stockMin||0)?'var(--warn)':'var(--accent2)';
  document.getElementById('mvt-art-sel-nom').textContent = art.nom;
  document.getElementById('mvt-art-sel-info').innerHTML =
    `${art.ref?`Réf: <strong style="color:var(--accent)">${esc(art.ref)}</strong> &nbsp;·&nbsp; `:''}Stock actuel : <strong style="color:${stockColor}">${art.stock} ${esc(art.unite||'pcs')}</strong>${art.stockMin>0?` &nbsp;·&nbsp; Min: ${art.stockMin}`:''}`;
  document.getElementById('mvt-art-selected').style.display='flex';
};

window.mvtClearArt = function(){
  document.getElementById('mvt-art').value='';
  document.getElementById('mvt-art-search').value='';
  document.getElementById('mvt-art-search').style.display='';
  document.getElementById('mvt-art-results').style.display='none';
  document.getElementById('mvt-art-selected').style.display='none';
  document.getElementById('mvt-art-search').focus();
};

// ═══ STOCK PAR AGENCE ═══
// ✅ État persistant par agence (collapsed / filtres date & code) — conservé
// entre les re-rendus puisque innerHTML est reconstruit à chaque appel.
const _spaState = {};
function _spaGet(agId){
  if(!_spaState[agId]) _spaState[agId] = {collapsed:false, date:'', code:''};
  return _spaState[agId];
}
window._spaToggle = function(agId){
  _spaGet(agId).collapsed = !_spaGet(agId).collapsed;
  renderStockParAgence();
};
window._spaSetDate = function(agId, val){
  _spaGet(agId).date = val || '';
  // ── VOLET 14 ── DB.stockMvts ne contient plus que la periode chargee :
  // on va chercher la journee demandee avant de re-afficher, sinon elle
  // paraitrait vide. _fetchColDateRange a son propre cache (TTL), donc
  // re-choisir la meme date ne relit pas Firestore.
  if (val && !_loadedCols.has('stockMvts')) {
    _fetchColDateRange('stockMvts', val, val)
      .then(() => renderStockParAgence())
      .catch(e => console.error('[stock/agence] jour', e));
  }
  renderStockParAgence();
};
window._spaSetCode = function(agId, val){
  _spaGet(agId).code = val || '';
  renderStockParAgence();
};
window._spaResetFiltres = function(agId){
  const st = _spaGet(agId);
  st.date = ''; st.code = '';
  renderStockParAgence();
};

window.renderStockParAgence = function(){
  const wrap = document.getElementById('stock-par-agence-wrap');
  if(!wrap) return;
  const filtAgId = document.getElementById('stock-agence-filter')?.value || '';
  let agences = DB.agences.length ? [...DB.agences] : [];
  if(filtAgId) agences = agences.filter(ag=>ag._id===filtAgId);
  if(session.role===ROLES.GESTIONNAIRE_STOCK){
    const agId=sessionAgenceId();
    if(agId) agences = agences.filter(ag=>ag._id===agId);
  }
  if(!agences.length){
    wrap.innerHTML='<div style="padding:14px;color:var(--muted);font-size:13px;">Aucune agence disponible.</div>';
    return;
  }
  wrap.innerHTML = agences.map(ag=>{
    const st = _spaGet(ag._id);
    const comIds = DB.commerciaux.filter(c=>c.agenceId===ag._id).map(c=>c._id);
    const clIds  = DB.clients.filter(c=>comIds.includes(c.commercialId)).map(c=>c._id);
    const codeQ = st.code.trim().toLowerCase();

    // ── Sorties de stock vers cette agence (via mouvements manuels), filtrées par date ──
    let sortiesVersAgence = DB.stockMvts.filter(m=>m.type==='sortie' && m.destinationId===ag._id);
    if(st.date) sortiesVersAgence = sortiesVersAgence.filter(m=>m.date===st.date);
    const sortiesMap = {}; // articleId => qty envoyée
    sortiesVersAgence.forEach(m=>{ sortiesMap[m.articleId]=(sortiesMap[m.articleId]||0)+m.qty; });

    // ── Livraisons confirmées de cette agence (décomposées produit → articles), filtrées par date ──
    let livs = DB.livraisons.filter(l=>clIds.includes(l.clientId) && l.statut==='livre');
    if(st.date) livs = livs.filter(l=>l.date===st.date);
    const livsMap = {}; // articleId => qty livrée (équivalent articles consommés)
    // ── VOLET 17 ── composition figee a la livraison (voir
    // _compositionLivraison). Avant, modifier un produit reecrivait
    // retroactivement cette colonne pour TOUT l'historique.
    livs.forEach(l=>{
      _compositionLivraison(l).forEach(c=>{
        livsMap[c.articleId] = (livsMap[c.articleId]||0) + ((c.qte||0)*l.qty);
      });
    });

    // ── Solde réel du stock de l'agence (source de vérité — collection
    // stockAgences, voir ajusterStockAgence). C'est un solde COURANT, donc
    // volontairement non filtré par date : contrairement à "Envoyé"/"Livré"
    // ci-dessus qui restent des compteurs d'activité sur la période choisie.
    const soldesAgence = {}; // articleId => solde actuel de l'agence
    DB.stockAgences.filter(s=>s.agenceId===ag._id).forEach(s=>{ soldesAgence[s.articleId]=s.qty||0; });

    // ── Fusionner : articles concernés par envoi, livraison OU ayant un solde agence ──
    let artIdsConcernes = [...new Set([...Object.keys(sortiesMap), ...Object.keys(livsMap), ...Object.keys(soldesAgence)])];
    // ── Filtre code / référence article ──
    if(codeQ){
      artIdsConcernes = artIdsConcernes.filter(aid=>{
        const a = DB.articles.find(x=>x._id===aid);
        return a && ((a.ref||'').toLowerCase().includes(codeQ) || (a.nom||'').toLowerCase().includes(codeQ));
      });
    }

    const rows = artIdsConcernes.map(aid=>{
      const a = DB.articles.find(x=>x._id===aid);
      if(!a) return null;
      const envoye  = sortiesMap[aid]||0;
      const livre   = livsMap[aid]||0;
      const restant = soldesAgence[aid]||0; // solde RÉEL de l'agence (stockAgences), peut être négatif
      const restantColor = restant>0?'var(--accent)':restant===0?'var(--muted)':'var(--danger)';
      return `<tr>
        <td><span class="tag">${esc(a.ref||'—')}</span></td>
        <td class="fw6">${esc(a.nom)}</td>
        <td style="font-weight:700;color:var(--warn);">${envoye} ${esc(a.unite||'pcs')}</td>
        <td style="font-weight:700;color:var(--accent2);">${livre} ${esc(a.unite||'pcs')}</td>
        <td style="font-weight:800;color:${restantColor};">${restant} ${esc(a.unite||'pcs')}</td>
      </tr>`;
    }).filter(Boolean).join('');

    const totalEnvoyes = Object.keys(sortiesMap).length;
    const totalLivres  = Object.keys(livsMap).length;
    const filtresActifs = !!(st.date || codeQ);
    return `<div style="background:var(--surface);border:1px solid rgba(212,137,58,0.2);border-radius:12px;padding:16px;margin-bottom:16px;">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:${st.collapsed?'0':'14px'};flex-wrap:wrap;cursor:pointer;" onclick="_spaToggle('${ag._id}')">
        <div style="width:38px;height:38px;border-radius:9px;background:rgba(212,137,58,0.15);border:1px solid rgba(212,137,58,0.3);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;">🏢</div>
        <div style="flex:1;min-width:0;">
          <div style="font-weight:700;font-size:14px;color:var(--text);">${esc(ag.nom)}${filtresActifs?' <span style="font-size:10px;font-weight:700;color:var(--accent);background:rgba(201,168,76,0.12);border:1px solid rgba(201,168,76,0.3);border-radius:10px;padding:1px 8px;margin-left:4px;">filtré</span>':''}</div>
          <div style="font-size:11px;color:var(--muted);">${esc(ag.ville||'')} &nbsp;·&nbsp; ${comIds.length} commercial(aux) &nbsp;·&nbsp; ${clIds.length} client(s)</div>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;" onclick="event.stopPropagation()">
          <div style="background:rgba(212,137,58,0.1);border:1px solid rgba(212,137,58,0.3);border-radius:8px;padding:6px 14px;text-align:center;">
            <div style="font-size:16px;font-weight:800;color:var(--warn);">${totalEnvoyes}</div>
            <div style="font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;">art. envoyés</div>
          </div>
          <div style="background:rgba(56,201,160,0.08);border:1px solid rgba(56,201,160,0.25);border-radius:8px;padding:6px 14px;text-align:center;">
            <div style="font-size:16px;font-weight:800;color:var(--accent2);">${totalLivres}</div>
            <div style="font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;">art. livrés</div>
          </div>
        </div>
        <button title="${st.collapsed?'Déplier':'Replier'}" onclick="event.stopPropagation();_spaToggle('${ag._id}')" style="background:none;border:1px solid var(--border);border-radius:7px;width:28px;height:28px;color:var(--muted);cursor:pointer;font-size:13px;flex-shrink:0;transition:transform 0.15s;transform:rotate(${st.collapsed?'-90deg':'0deg'});">▾</button>
      </div>
      ${st.collapsed ? '' : `
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-bottom:12px;padding:10px 12px;background:var(--surface2);border:1px solid var(--border);border-radius:9px;">
        <div>
          <label style="font-size:10px;color:var(--muted);display:block;margin-bottom:3px;">📅 Date</label>
          <input type="date" value="${st.date}" onchange="_spaSetDate('${ag._id}',this.value)" style="background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);font-size:12px;">
        </div>
        <div style="flex:1;min-width:140px;">
          <label style="font-size:10px;color:var(--muted);display:block;margin-bottom:3px;">🏷️ Code / Article</label>
          <input type="text" value="${esc(st.code)}" placeholder="Réf. ou nom d'article…" oninput="_spaSetCode('${ag._id}',this.value)" style="width:100%;background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);font-size:12px;">
        </div>
        ${filtresActifs?`<button class="btn btn-ghost btn-xs" onclick="_spaResetFiltres('${ag._id}')">✕ Réinitialiser</button>`:''}
      </div>
      ${rows
        ? `<div class="tw" style="margin:0;">
             <table><thead><tr>
               <th>Réf.</th><th>Article</th>
               <th style="color:var(--warn);">📤 Envoyé${_loadedCols.has('stockMvts')||st.date?'':'<div style="font-weight:400;font-size:10px;color:var(--muted);">période chargée</div>'}</th>
               <th style="color:var(--accent2);">✅ Livré clients</th>
               <th style="color:var(--accent);">📦 Stock agence</th>
             </tr></thead><tbody>${rows}</tbody></table>
           </div>`
        : `<div style="font-size:12px;color:var(--muted);padding:8px 0;">${filtresActifs?'Aucun résultat pour ces filtres.':'Aucune sortie de stock ni livraison pour cette agence.'}</div>`}
      `}
    </div>`;
  }).join('');
};

// ═══ INVENTAIRE GÉNÉRAL ═══
window.renderInventaire = function(){
  const q = (document.getElementById('inv-search')?.value||'').toLowerCase().trim();
  const filtStatut = document.getElementById('inv-filter-statut')?.value||'';
  let arts = [...DB.articles];
  if(q) arts = arts.filter(a=>(a.nom||'').toLowerCase().includes(q)||(a.ref||'').toLowerCase().includes(q)||(a.cat||'').toLowerCase().includes(q));
  if(filtStatut==='ok') arts = arts.filter(a=>a.stock>0&&(a.stock>(a.stockMin||0)));
  if(filtStatut==='bas') arts = arts.filter(a=>a.stock>0&&a.stock<=(a.stockMin||0));
  if(filtStatut==='rupture') arts = arts.filter(a=>a.stock<=0);
  // KPI inventaire
  const total = DB.articles.length;
  const enStock = DB.articles.filter(a=>a.stock>0&&a.stock>(a.stockMin||0)).length;
  const bas = DB.articles.filter(a=>a.stock>0&&a.stock<=(a.stockMin||0)).length;
  const rupture = DB.articles.filter(a=>a.stock<=0).length;
  const invKpi = document.getElementById('inv-kpi-row');
  if(invKpi) invKpi.innerHTML=`
    <div class="kpi-card kc-blue"><div class="kpi-lbl">Total articles</div><div class="kpi-val kv-blue">${total}</div></div>
    <div class="kpi-card kc-green"><div class="kpi-lbl">En stock</div><div class="kpi-val kv-green">${enStock}</div></div>
    <div class="kpi-card kc-yellow"><div class="kpi-lbl">Stock bas</div><div class="kpi-val kv-yellow">${bas}</div></div>
    <div class="kpi-card kc-red"><div class="kpi-lbl">Rupture</div><div class="kpi-val kv-red">${rupture}</div></div>`;
  const tbody = document.getElementById('tb-inventaire');
  if(!tbody) return;
  // ── VOLET 14 ── bandeau explicite : sans lui, l'utilisateur verrait deux
  // colonnes a « — » sans savoir pourquoi ni quoi faire.
  {
    const _fiables = _loadedCols.has('stockMvts');
    let _b = document.getElementById('inv-histo-banniere');
    if (!_fiables && !_b) {
      _b = document.createElement('div');
      _b.id = 'inv-histo-banniere';
      _b.style.cssText = 'margin:8px 0;padding:8px 10px;border-radius:8px;font-size:12px;'
        + 'background:rgba(201,168,76,0.10);border:1px solid rgba(201,168,76,0.35);color:var(--muted);';
      _b.innerHTML = 'Les colonnes <b>Entré</b> et <b>Sorti</b> sont des cumuls sur tout l\'historique. '
        + 'Celui-ci n\'est pas chargé — '
        + '<a href="#" onclick="event.preventDefault();stockChargerToutHistorique();" '
        + 'style="color:var(--accent);font-weight:700;">charger tout l\'historique</a>.';
      const _p = tbody.closest('.tw') || tbody.closest('table')?.parentElement;
      if (_p && _p.parentElement) _p.parentElement.insertBefore(_b, _p);
    } else if (_fiables && _b) {
      _b.remove();
    }
  }
  // Total entré / sorti par article, calculé depuis l'historique des
  // mouvements de stock (indépendant du stock courant, qui peut avoir été
  // corrigé manuellement — ces totaux reflètent le cumul réel des mouvements).
  // ── VOLET 14 / POINT IMPORTANT ──────────────────────────────────────
  // Ces cumuls portent sur TOUT l'historique des mouvements. Depuis que
  // 'stockMvts' n'est plus chargee integralement a l'ouverture de la page,
  // les calculer sur DB.stockMvts donnerait les totaux de la SEULE PERIODE
  // CHARGEE — un chiffre faux, presente comme un cumul, sans rien pour
  // l'indiquer. On prefere afficher « — » et inviter a charger l'historique.
  // (Au passage : avant le volet 6, cette page ne chargeait qu'UNE page de
  // 500 mouvements, donc ces cumuls etaient DEJA faux au-dela de 500.)
  const _cumulsFiables = _loadedCols.has('stockMvts');
  const totauxParArticle = {};
  (_cumulsFiables ? (DB.stockMvts||[]) : []).forEach(m=>{
    if(!totauxParArticle[m.articleId]) totauxParArticle[m.articleId] = {entree:0, sortie:0};
    if(m.type==='entree') totauxParArticle[m.articleId].entree += (Number(m.qty)||0);
    else if(m.type==='sortie') totauxParArticle[m.articleId].sortie += (Number(m.qty)||0);
  });
  tbody.innerHTML = arts.sort((a,b)=>(a.nom||'').localeCompare(b.nom||'')).map(a=>{
    const stockColor = a.stock<=0?'var(--danger)':a.stock<=(a.stockMin||0)?'var(--warn)':'var(--accent2)';
    const statut = a.stock<=0
      ? `<span class="sb sr">🔴 Rupture</span>`
      : a.stock<=(a.stockMin||0)
        ? `<span class="sb sy">⚠️ Stock bas</span>`
        : `<span class="sb sg">✅ OK</span>`;
    const tot = totauxParArticle[a._id] || {entree:0, sortie:0};
    return `<tr>
      <td><span class="tag">${esc(a.ref||'—')}</span></td>
      <td class="fw6">${esc(a.nom)}</td>
      <td class="tm">${esc(a.cat||'—')}</td>
      <td style="font-weight:800;font-size:14px;color:${stockColor};">${a.stock}</td>
      <td style="color:var(--muted);">${a.stockMin||0}</td>
      <td style="color:var(--muted);">${esc(a.unite||'pcs')}</td>
      <!-- ── VOLET 14 ── « +0 » se lirait comme « aucun mouvement », ce qui
           serait FAUX tant que l'historique n'est pas charge. On affiche « — »,
           qui se lit « inconnu ». -->
      <td style="font-weight:700;color:${_cumulsFiables?'var(--accent2)':'var(--muted)'};">${_cumulsFiables?('+'+tot.entree):'—'}</td>
      <td style="font-weight:700;color:${_cumulsFiables?'var(--danger)':'var(--muted)'};">${_cumulsFiables?('-'+tot.sortie):'—'}</td>
      <td>${statut}</td>
    </tr>`;
  }).join('')||'<tr><td colspan="9" class="emp">Aucun article trouvé.</td></tr>';
};

// ── VOLET 54 ── livraison dont le déstockage est à rattraper (admin).
function _livRattrapable(l){
  if(session?.role !== ROLES.ADMIN || !l || l.statut !== 'livre') return false;
  if(l.stockDeduit === false) return true;
  if(l.stockDeduit === undefined){
    const il7 = new Date(new Date(TODAY+'T12:00:00').getTime() - 7*86400000).toISOString().slice(0,10);
    return (l.date||'') >= il7;
  }
  return false;
}

function renderLivraisons(){
  _dlcRenderStaff();   // ── VOLET 43 ── demandes des agents
  // Afficher le bouton "+ Livraison" pour admin, secrétaire et chef d'agence
  // (chef_agence a déjà la permission d'écriture backend sur 'livraisons',
  // voir _WRITE_ROLES — seul le bouton d'accès manquait côté interface)
  const btnLivInline = document.querySelector('#page-livraisons .btn-primary.btn-sm');
  if(btnLivInline) btnLivInline.style.display = ['admin','secretaire','chef_agence'].includes(session?.role) ? '' : 'none';

  // ── Peupler select agences (admin uniquement, une seule fois) ──
  const selAgence = document.getElementById('filter-liv-agence');
  if(selAgence){
    const isAdmin = session?.role ===ROLES.ADMIN;
    selAgence.parentElement.style.display = isAdmin ? '' : 'none';
    if(isAdmin && selAgence.options.length <= 1){
      DB.agences.forEach(ag => {
        const opt = document.createElement('option');
        opt.value = ag._id; opt.textContent = '🏢 ' + ag.nom;
        selAgence.appendChild(opt);
      });
    }
  }
  // ── Barre de filtres : visible pour tous les rôles ayant accès aux livraisons ──
  const barreFiltre = document.querySelector('#page-livraisons .liv-filtres-bar');
  if(barreFiltre) barreFiltre.style.display = '';

  // ── Peupler select commerciaux selon agence sélectionnée ──
  const selCom = document.getElementById('filter-liv-com');
  const agId = selAgence?.value || '';
  // Tous les membres du staff de l'agence (tous rôles confondus) — sert au filtre agence,
  // car une livraison peut être saisie par un commercial, une secrétaire ou un chef d'agence.
  const staffAgenceTous = agId
    ? DB.commerciaux.filter(c => c.agenceId === agId)
    : comsDansAgence();
  // Sous-ensemble "commercial" uniquement — sert seulement à peupler le select de choix.
  const comsSource = staffAgenceTous.filter(c => c.role ===ROLES.COMMERCIAL);
  const prevCom = selCom?.value || '';
  if(selCom){
    selCom.innerHTML = '<option value="">Tous les commerciaux</option>' +
      comsSource.map(c => `<option value="${esc(c._id)}"${c._id===prevCom?' selected':''}>${esc(c.nom)}${c.zone?' — '+esc(c.zone):''}</option>`).join('');
  }

  // ── Peupler select produits (une seule fois) ──
  const selArt = document.getElementById('filter-liv-article');
  if(selArt && selArt.options.length <= 1){
    (DB.produits||[]).filter(p=>p.nom).sort((a,b)=>a.nom.localeCompare(b.nom)).forEach(p=>{
      const opt = document.createElement('option');
      opt.value = p._id; opt.textContent = p.nom;
      selArt.appendChild(opt);
    });
  }

  // ── Lecture des filtres ──
  const q       = (document.getElementById('search-liv-cl')?.value || '').toLowerCase().trim();
  const filtDate   = document.getElementById('filter-liv-date')?.value   || '';
  const filtComId  = selCom?.value || '';
  const filtStatut = document.getElementById('filter-liv-statut')?.value || '';
  const filtArticleId = selArt?.value || '';
  const filtArtCode = (document.getElementById('filter-liv-art-code')?.value || '').trim().toLowerCase();
  // ── VOLET 47 ── période Du / Au. Prioritaire sur le jour unique.
  const filtDu = document.getElementById('filter-liv-du')?.value || '';
  const filtAu = document.getElementById('filter-liv-au')?.value || '';
  const _periodeLiv = !!(filtDu || filtAu);

  // ── Base de livraisons (filtrée par agence de session) ──
  let livs = livraisonsDansAgence();

  // Appliquer filtre agence (admin seulement) — ⚠️ IMPORTANT : on filtre sur
  // l'agence DU CLIENT livré, pas sur le commercialId enregistré dans la
  // livraison. Ce dernier correspond à la personne qui a SAISI la livraison
  // (souvent l'admin/secrétaire), qui n'appartient à aucune agence — filtrer
  // dessus faisait disparaître à tort toutes les livraisons saisies par un
  // admin/secrétaire, alors que le client livré appartient bel et bien à
  // l'agence sélectionnée.
  if(agId){
    const clientIdsAgence = new Set(
      DB.clients.filter(c => {
        const com = DB.commerciaux.find(cc => cc._id === c.commercialId);
        return com && com.agenceId === agId;
      }).map(c => c._id)
    );
    livs = livs.filter(l => clientIdsAgence.has(l.clientId));
  }

  // Filtre date
  if(_periodeLiv){
    if(filtDu) livs = livs.filter(l => (l.date||'') >= filtDu);
    if(filtAu) livs = livs.filter(l => (l.date||'') <= filtAu);
  } else if(filtDate) livs = livs.filter(l => l.date === filtDate);

  // Filtre commercial
  if(filtComId) livs = livs.filter(l => l.commercialId === filtComId);

  // Filtre statut
  if(filtStatut) livs = livs.filter(l => l.statut === filtStatut);

  // Filtre article
  if(filtArticleId) livs = livs.filter(l => l.produitId === filtArticleId);
  // ── VOLET 47 ── le code figé sur la livraison (produitRef, volet 17) est
  // aussi pris en compte : un produit renommé ou supprimé reste retrouvable.
  if(filtArtCode) livs = livs.filter(l => {
    const prod = getProdOuArticle(l.produitId);
    return ((prod && prod.ref) || '').toLowerCase().includes(filtArtCode)
        || (l.produitRef || '').toLowerCase().includes(filtArtCode);
  });

  // Filtre recherche texte (client)
  if(q){
    const matchIds = clientsDansAgence().filter(c =>
      c.nom.toLowerCase().includes(q) ||
      (c.codeClient && c.codeClient.toLowerCase().includes(q)) ||
      (c.tel || '').includes(q)
    ).map(c => c._id);
    livs = livs.filter(l => matchIds.includes(l.clientId));
  }

  livs = [...livs].sort((a,b) => (b.date||'').localeCompare(a.date||''));

  // ── KPI (sur la base filtrée) ──
  const allLivs = livraisonsDansAgence();
  document.getElementById('liv-kpi').innerHTML=`
    <div class="kpi-card kc-yellow"><div class="kpi-lbl">En attente</div><div class="kpi-val kv-yellow">${allLivs.filter(l=>l.statut==='en_attente').length}</div><div class="kpi-sub">total</div></div>
    <div class="kpi-card kc-green"><div class="kpi-lbl">Livrées</div><div class="kpi-val kv-green">${allLivs.filter(l=>l.statut==='livre').length}</div><div class="kpi-sub">total</div></div>
    <div class="kpi-card kc-blue"><div class="kpi-lbl">Résultat filtre</div><div class="kpi-val kv-blue">${livs.length}</div><div class="kpi-sub">sur ${allLivs.length} total</div></div>`;

  // ── Label filtres actifs ──
  const labelEl = document.getElementById('liv-filtre-label');
  if(labelEl){
    const parts = [];
    if(_periodeLiv){ parts.push(`📅 du ${esc(filtDu||'…')} au ${esc(filtAu||'…')}`); }
    else if(filtDate){ const ds = new Date(filtDate+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}); parts.push(`📅 ${ds}`); }
    if(agId){ const ag = DB.agences.find(a=>a._id===agId); if(ag) parts.push(`🏢 ${esc(ag.nom)}`); }
    if(filtComId){ const com = DB.commerciaux.find(c=>c._id===filtComId); if(com) parts.push(`👤 ${esc(com.nom)}`); }
    if(filtStatut){ parts.push(filtStatut==='en_attente'?'⏳ En attente':filtStatut==='livre'?'✅ Livrées':'❌ Annulées'); }
    if(filtArticleId){ const prod = (DB.produits||[]).find(p=>p._id===filtArticleId); if(prod) parts.push(`📦 ${esc(prod.nom)}`); }
    if(filtArtCode){ parts.push(`🏷️ Code: ${esc(filtArtCode.toUpperCase())}`); }
    if(q) parts.push(`🔍 "${q}"`);
    labelEl.innerHTML = parts.length
      ? `<span style="background:rgba(201,168,76,0.08);border:1px solid rgba(201,168,76,0.2);border-radius:6px;padding:3px 10px;">Filtres actifs : ${parts.join(' · ')}</span>`
      : '';
  }

  // ── Tableau ──
  // FIX PERF : sans filtre de date, "livs" peut contenir l'historique complet
  // des livraisons depuis le début de l'activité. On plafonne le rendu DOM
  // (les KPI ci-dessus restent calculés sur la liste complète filtrée).
  // ── VOLET 47 ── bilan par produit des livraisons filtrées (annulées exclues
  // des totaux). Affiché dès qu'une période, un jour ou un produit est filtré.
  _livRenderBilan(livs, _periodeLiv || !!filtDate || !!filtArtCode || !!filtArticleId);

  const livsTronquees = livs.length > _HIST_RENDER_CAP;
  const livsAffichees = livsTronquees ? livs.slice(0, _HIST_RENDER_CAP) : livs;
  const _bandeauTronqueLiv = livsTronquees
    ? `<tr><td colspan="8" style="text-align:center;padding:10px;font-size:11px;color:var(--muted);background:rgba(247,201,79,0.08);">⚠️ Affichage limité aux ${_HIST_RENDER_CAP} livraisons les plus récentes sur ${livs.length} — filtrez par date pour voir le reste.</td></tr>`
    : '';
  document.getElementById('tb-livraisons').innerHTML = _bandeauTronqueLiv + livsAffichees.map(l=>{
    // ── VOLET 17 ── `a` reste lu (d'autres champs peuvent en dependre a
    // l'avenir), mais le NOM affiche vient de la livraison quand il y est fige.
    const c=getCl(l.clientId),a=getProd(l.produitId),com=getCom(l.commercialId);
    const _prodNom = _nomProduitLivraison(l);
    return`<tr><td>${esc(l.date)}</td><td class="fw6">${esc(c.nom)}${c.codeClient?`<div style="font-size:9px;color:var(--accent);font-weight:700;">${esc(c.codeClient)}</div>`:''}</td>
    <td><span class="tag">${esc(com.nom)}</span></td>
    <td style="font-size:11px">${esc(_prodNom)}</td><td>${l.qty}</td><td>${fmt(l.montant)}</td><td>${livStatut(l.statut)}</td>
    <td>${(l.statut==='en_attente'&&['admin','secretaire'].includes(session.role))?`<button class="btn btn-success btn-xs" onclick="marquerLivre('${l._id}')" style="margin-right:3px">✓ Livré</button>`:''}
    ${_livRattrapable(l)?`<button class="btn btn-xs" style="background:rgba(247,201,79,0.15);color:var(--accent);border:1px solid rgba(247,201,79,0.4);margin-right:3px;" onclick="rattraperStockLivraison('${l._id}')" title="Le stock agence n'a pas été (entièrement) déduit — le déduire maintenant">⟳ Stock</button>`:''}
    ${(session.role===ROLES.ADMIN||(session.role===ROLES.SECRETAIRE&&l.date===TODAY))?`<button class="btn btn-xs btn-warn" onclick="delLiv('${l._id}')">✕</button>`:livStatut(l.statut)}</td></tr>`;
  }).join('')||`<tr><td colspan="8" class="emp">${(q||filtDate||filtComId||filtStatut||agId)?'Aucune livraison pour ces filtres':'Aucune livraison'}</td></tr>`;
}

// ── VOLET 47 ── bilan par produit des livraisons filtrées
function _livRenderBilan(livs, actif){
  const zone = document.getElementById('liv-bilan');
  if(!zone) return;
  if(!actif || !livs.length){ zone.innerHTML = ''; window._livBilanDernier = null; return; }
  const parProd = new Map();
  let qL = 0, qA = 0, mt = 0, nbAnn = 0;
  livs.forEach(l => {
    if(l.statut === 'annule'){ nbAnn++; return; }
    const prod = getProdOuArticle(l.produitId) || {};
    const cle = l.produitId || l.produitRef || '?';
    const r = parProd.get(cle) || { ref: prod.ref || l.produitRef || '—', nom: _nomProduitLivraison(l), livre: 0, attente: 0, montant: 0 };
    const q = Number(l.qty) || 0;
    if(l.statut === 'livre'){ r.livre += q; qL += q; } else { r.attente += q; qA += q; }
    r.montant += Number(l.montant) || 0; mt += Number(l.montant) || 0;
    parProd.set(cle, r);
  });
  const lignes = [...parProd.values()].sort((a,b) => (b.livre + b.attente) - (a.livre + a.attente));
  window._livBilanDernier = { lignes, qL, qA, mt };
  zone.innerHTML = `
    <div class="kpi-row" style="margin-bottom:8px;">
      <div class="kpi-card kc-green"><div class="kpi-lbl">Qté livrée</div><div class="kpi-val kv-green">${qL}</div></div>
      <div class="kpi-card kc-yellow"><div class="kpi-lbl">Qté en attente</div><div class="kpi-val kv-yellow">${qA}</div></div>
      <div class="kpi-card kc-blue"><div class="kpi-lbl">Montant (hors annulées)</div><div class="kpi-val kv-blue">${fmt(mt)}</div>${nbAnn?`<div class="kpi-sub">${nbAnn} annulée(s) exclue(s)</div>`:''}</div>
    </div>
    <details ${lignes.length <= 8 ? 'open' : ''} style="margin-bottom:10px;"><summary style="cursor:pointer;font-size:12px;font-weight:700;">📦 Détail par produit (${lignes.length})</summary>
      <div class="tw" style="margin-top:6px;"><table><thead><tr><th>Code</th><th>Produit</th><th style="text-align:center;">Livrée</th><th style="text-align:center;">En attente</th><th style="text-align:right;">Montant</th></tr></thead><tbody>
      ${lignes.map(r => `<tr><td style="color:var(--accent);font-weight:700;">${esc(r.ref)}</td><td>${esc(r.nom)}</td>
        <td style="text-align:center;font-weight:700;color:var(--accent2);">${r.livre}</td><td style="text-align:center;">${r.attente}</td>
        <td style="text-align:right;">${fmt(r.montant)}</td></tr>`).join('')}
      </tbody></table></div>
      <button class="btn btn-ghost btn-xs" style="margin-top:6px;" onclick="livExportBilanCSV()">📄 Export CSV</button>
    </details>`;
}
window.livExportBilanCSV = function(){
  const b = window._livBilanDernier;
  if(!b){ notify('Aucun bilan à exporter','err'); return; }
  const c = v => `"${String(v==null?'':v).replace(/"/g,'""')}"`;
  const L = [['Code','Produit','Qté livrée','Qté en attente','Montant'].map(c).join(';')];
  b.lignes.forEach(r => L.push([r.ref, r.nom, r.livre, r.attente, r.montant].map(c).join(';')));
  L.push(['TOTAL','', b.qL, b.qA, b.mt].map(c).join(';'));
  const blob = new Blob([String.fromCharCode(0xFEFF) + L.join('\n')], {type:'text/csv;charset=utf-8;'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
  a.download = `bilan_livraisons_${TODAY}.csv`; a.click(); URL.revokeObjectURL(a.href);
};

window.livChangerDate = function(delta){
  const el = document.getElementById('filter-liv-date');
  if(!el) return;
  const val = el.value || TODAY;
  const d = new Date(val + 'T12:00:00');
  d.setDate(d.getDate() + delta);
  el.value = d.toISOString().split('T')[0];
  renderLivraisons();
};

window.livAujourdhui = function(){
  const el = document.getElementById('filter-liv-date');
  if(el) el.value = TODAY;
  renderLivraisons();
};

window.livOnAgenceChange = function(){
  // Réinitialiser le filtre commercial quand on change d'agence
  const selCom = document.getElementById('filter-liv-com');
  if(selCom) selCom.value = '';
  renderLivraisons();
};

window.livResetFiltres = function(){
  const ids = ['search-liv-cl','filter-liv-date','filter-liv-du','filter-liv-au','filter-liv-agence','filter-liv-com','filter-liv-statut','filter-liv-article','filter-liv-art-code'];
  ids.forEach(id => { const el = document.getElementById(id); if(el) el.value = ''; });
  renderLivraisons();
};

// Appelé quand le select commercial ou la recherche change
window.onClFilterChange = function(){
  const comVal = document.getElementById('filter-com')?.value || '';
  const qtVal = (document.getElementById('filter-quartier')?.value || '').trim();
  const q = (document.getElementById('search-clients')?.value || '').trim();
  const stVal = document.getElementById('filter-statut-cl')?.value || '';
  const hasFilter = comVal || qtVal.length >= 2 || q.length >= 2 || stVal;
  const prompt = document.getElementById('cl-prompt');
  const tableau = document.getElementById('tw-clients');
  if(!hasFilter){
    if(prompt) prompt.style.display='flex';
    if(tableau) tableau.style.display='none';
    const countEl = document.getElementById('search-clients-count');
    if(countEl) countEl.textContent = '';
    const res = document.getElementById('cl-resume'); if(res) res.innerHTML = '';
    return;
  }
  if(prompt) prompt.style.display='none';
  if(tableau) tableau.style.display='';
  _clPage = 1; // nouveau filtre/recherche : revenir à la première page
  renderTousCls();
};

let _clientsLazyLoadToken = 0;
// ─── Pagination UI de la liste "Clients" (voir renderTousCls) ───
// ✅ PERF (point 2, option A) : réduit de 100 à 50 lignes par page — moins de
// nœuds DOM injectés à chaque rendu/changement de filtre, sans changement
// structurel (pas de virtualisation par fenêtre, juste un pas de pagination
// plus fin). Ajuster ce chiffre est sans risque de casse visuelle.
const _CL_PAGE_SIZE = 50;
let _clPage = 1;
window.clientsChangerPage = function(delta){
  _clPage += delta;
  if (_clPage < 1) _clPage = 1;
  renderTousCls();
};
async function renderTousCls(){
  // ── FIX PERFORMANCE : 'clients' (jusqu'à 30 000 docs) n'est plus chargé
  // automatiquement à l'ouverture de la page — seulement ici, la première
  // fois qu'une recherche/filtre est réellement utilisé(e). Grâce au cache
  // (_CACHE_TTL_MS), les recherches suivantes ne re-téléchargent rien.
  const myToken = ++_clientsLazyLoadToken;
  const tb = document.getElementById('tb-tous-cl');
  if (tb && !DB.clients?.length) tb.innerHTML = '<tr><td colspan="9" class="emp">⏳ Chargement des clients…</td></tr>';
  try {
    await ensureCollectionsLoaded(['clients']);
  } catch(e) {
    if (tb) tb.innerHTML = `<tr><td colspan="9" class="emp">Erreur de chargement : ${esc(e.message||String(e))}</td></tr>`;
    return;
  }
  if (myToken !== _clientsLazyLoadToken) return; // une recherche plus récente a été lancée

  const sel=document.getElementById('filter-com');
  // Remplir le select commercial — uniquement des commerciaux (pas chef d'agence/secrétaire/contrôleur)
  const comsVisibles = comsDansAgence().filter(c=>c.role===ROLES.COMMERCIAL);
  // ✅ PERF : reconstruire ce <select> (innerHTML) est inutile si la liste des
  // commerciaux visibles n'a pas changé depuis le dernier rendu — or ce code
  // s'exécute à CHAQUE frappe dans le champ de recherche clients, alors que
  // seule la liste des commerciaux (rarement modifiée) devrait déclencher
  // une reconstruction. On compare une signature simple (ids concaténés) et
  // on ne touche au DOM que si elle a changé.
  const comsSig = comsVisibles.map(c=>c._id).join(',');
  const prevVal = sel.value;
  if (sel.dataset.comsSig !== comsSig) {
    sel.innerHTML=`<option value="">— Sélectionner un commercial —</option><option value="__tous__">— Tous les commerciaux —</option>`+comsVisibles.map(c=>`<option value="${c._id}"${c._id===prevVal?' selected':''}>${esc(c.nom)}</option>`).join('');
    sel.value = prevVal; // restaurer
    sel.dataset.comsSig = comsSig;
  }

  const q=(document.getElementById('search-clients')?.value||'').toLowerCase().trim();
  const qt=(document.getElementById('filter-quartier')?.value||'').toLowerCase().trim();
  let cls=clientsDansAgence();
  // ── VOLET 46 ── « Tous les commerciaux » = tout le périmètre (agence).
  if(sel.value && sel.value !== '__tous__') cls=cls.filter(c=>c.commercialId===sel.value);
  if(qt) cls=cls.filter(c=>(c.quartier||'').toLowerCase().includes(qt));
  if(q) cls=cls.filter(c=>
    (c.codeClient&&c.codeClient.toLowerCase().includes(q))||
    c.nom.toLowerCase().includes(q)||
    (c.tel||'').includes(q)||
    (c.contrat||'').toLowerCase().includes(q)||
    (c.ville||'').toLowerCase().includes(q)||
    (c.quartier||'').toLowerCase().includes(q)
  );
  // ── VOLET 46 ── BILAN « TERMINÉS / TOTAL » sur la liste filtrée, AVANT le
  // filtre de statut : le total reste celui du commercial / de la recherche.
  // Terminé = contrat soldé à 100 % et non résilié (même définition que
  // « Contrats inactifs » du tableau de bord). statsLite : champs
  // dénormalisés du client, aucune lecture de 'paiements'.
  {
    let nbFin = 0, nbRes = 0;
    const _st = new Map();
    cls.forEach(c => {
      if(c.statutContrat === 'resilie'){ nbRes++; _st.set(c._id,'resilie'); return; }
      if(statsLite(c).pct >= 100){ nbFin++; _st.set(c._id,'termine'); return; }
      _st.set(c._id,'en_cours');
    });
    const tot = cls.length, nbCours = tot - nbFin - nbRes;
    const pc = n => tot ? Math.round(n * 1000 / tot) / 10 : 0;
    const res = document.getElementById('cl-resume');
    if(res) res.innerHTML = `
      <div class="kpi-card kc-blue"><div class="kpi-lbl">Total clients</div><div class="kpi-val kv-blue">${tot}</div></div>
      <div class="kpi-card kc-green"><div class="kpi-lbl">Terminés (soldés)</div><div class="kpi-val kv-green">${nbFin}</div><div class="kpi-sub">${pc(nbFin)} % du total</div></div>
      <div class="kpi-card kc-yellow"><div class="kpi-lbl">En cours</div><div class="kpi-val kv-yellow">${nbCours}</div><div class="kpi-sub">${pc(nbCours)} %</div></div>
      <div class="kpi-card kc-red"><div class="kpi-lbl">Résiliés</div><div class="kpi-val kv-red">${nbRes}</div><div class="kpi-sub">${pc(nbRes)} %</div></div>`;
    const stF = document.getElementById('filter-statut-cl')?.value || '';
    if(stF) cls = cls.filter(c => _st.get(c._id) === stF);
  }
  // ── Tri ──
  const sortVal = (document.getElementById('sort-clients')?.value) || 'nom-asc';
  // ✅ PERF : pour les tris basés sur stats(), pré-calculer une seule fois
  // par client (via une Map) au lieu d'appeler stats(a)/stats(b) à chaque
  // comparaison du .sort() (O(n log n) appels sinon, contre O(n) ici).
  // ── ÉTAPE 2 DU CHANTIER (dénormalisation) : statsLite() au lieu de stats()
  // — cette liste peut afficher TOUS les clients (admin), et ce tri n'a
  // besoin que de m/joursRetard, jamais de l'historique détaillé. Ne
  // dépend donc plus de DB.paiements chargé en mémoire.
  let _sortStatsMap = null;
  if (sortVal === 'retard-desc' || sortVal === 'cotis-desc') {
    _sortStatsMap = new Map(cls.map(c => [c._id, statsLite(c)]));
  }
  cls = [...cls].sort((a,b)=>{
    switch(sortVal){
      case 'nom-asc':   return (a.nom||'').localeCompare(b.nom||'','fr',{sensitivity:'base'});
      case 'nom-desc':  return (b.nom||'').localeCompare(a.nom||'','fr',{sensitivity:'base'});
      case 'id-asc':    return (a.codeClient||a._id||'').localeCompare(b.codeClient||b._id||'');
      case 'id-desc':   return (b.codeClient||b._id||'').localeCompare(a.codeClient||a._id||'');
      case 'date-asc':  return (a.createdAt||a._id||'').localeCompare(b.createdAt||b._id||'');
      case 'date-desc': return (b.createdAt||b._id||'').localeCompare(a.createdAt||a._id||'');
      case 'retard-desc':{ const sa=_sortStatsMap.get(a._id); const sb2=_sortStatsMap.get(b._id); return sb2.joursRetard-sa.joursRetard; }
      case 'cotis-desc':{ const sa=_sortStatsMap.get(a._id); const sb2=_sortStatsMap.get(b._id); return sb2.m-sa.m; }
      default: return 0;
    }
  });
  const countEl=document.getElementById('search-clients-count');
  if(countEl) countEl.textContent=`${cls.length} client(s)`;

  // ✅ PAGINATION UI : avec jusqu'à 30 000 clients, générer TOUTES les lignes
  // <tr> d'un coup peut créer des milliers de nœuds DOM en une seule passe
  // (lent à afficher, lent à scroller). On découpe l'affichage en pages de
  // _CL_PAGE_SIZE lignes ; la liste filtrée/triée `cls` reste en mémoire,
  // seule la page courante est effectivement rendue dans le DOM.
  const totalPages = Math.max(1, Math.ceil(cls.length / _CL_PAGE_SIZE));
  if (_clPage > totalPages) _clPage = totalPages;
  if (_clPage < 1) _clPage = 1;
  const startIdx = (_clPage - 1) * _CL_PAGE_SIZE;
  const clsPage = cls.slice(startIdx, startIdx + _CL_PAGE_SIZE);

  const pagEl = document.getElementById('cl-pagination');
  const pageInfoEl = document.getElementById('cl-page-info');
  if (pagEl) pagEl.style.display = cls.length > _CL_PAGE_SIZE ? 'flex' : 'none';
  if (pageInfoEl) pageInfoEl.textContent = `Page ${_clPage} / ${totalPages} (${startIdx+1}–${Math.min(startIdx+_CL_PAGE_SIZE, cls.length)} sur ${cls.length})`;
  const prevBtn = document.getElementById('cl-page-prev');
  const nextBtn = document.getElementById('cl-page-next');
  if (prevBtn) prevBtn.disabled = _clPage <= 1;
  if (nextBtn) nextBtn.disabled = _clPage >= totalPages;

  document.getElementById('tb-tous-cl').innerHTML=clsPage.map(c=>{
    // ── ÉTAPE 2 DU CHANTIER (dénormalisation) : statsLite() — cette ligne
    // n'affiche que cotisation/%/retard, jamais l'historique détaillé.
    const s=statsLite(c);
    return`<tr>
      <td style="text-align:center;">
        ${['admin','chef_agence'].includes(session.role)?`<input type="checkbox" class="cl-row-check" data-id="${c._id}"
          style="width:14px;height:14px;accent-color:var(--danger);cursor:pointer;"
          onchange="mettreAJourSelectionBar()">`:''}
      </td>
      <td class="fw6">${esc(c.nom)}<div class="tm" style="font-size:10px">${esc(c.ville||'')} · ${esc(c.quartier||'')}</div>${c.codeClient?`<span style="font-size:9.5px;background:rgba(201,168,76,0.15);border:1px solid rgba(201,168,76,0.4);border-radius:4px;padding:0 5px;color:var(--accent);font-weight:700;">${esc(c.codeClient)}</span>`:''}${c.statutContrat==='resilie'?`<span class="resilie-badge" style="font-size:9px;margin-left:5px;">RÉSILIÉ</span>`:''}</td>
      <td>${esc(c.tel||'—')}</td><td><span class="tag">${esc(getCom(c.commercialId).nom)}</span></td>
      <td>${c.adhesionStatut==='paye'?sb('Payée','sg'):sb('Non payée','sr')}<div class="tm" style="font-size:10px">${fmt(c.adhesion)}</div></td>
      <td style="font-size:11px">${(()=>{
        if(c.contratArticles&&c.contratArticles.length){
          return c.contratArticles.map(a=>{
            const art=getProdOuArticle(a.artId);
            const ref=art&&art.ref?art.ref:(a.nom||'?');
            const qty=parseInt(a.qty)||1;
            const label=qty>1?`${ref} x${qty}`:ref;
            return`<span style="display:inline-block;background:rgba(201,168,76,0.12);border:1px solid rgba(201,168,76,0.35);border-radius:4px;padding:1px 6px;font-size:9.5px;font-weight:700;color:var(--accent);margin:1px 2px 1px 0;white-space:nowrap;">${esc(label)}</span>`;
          }).join('<span style="color:var(--muted);font-size:9px;margin:0 1px;">+</span>');
        }
        return esc(c.contrat||'—');
      })()}</td>
      <td><span class="cotis-badge" style="font-size:10px">💰 ${fmt(s.m)}</span></td>
      <td><div class="pgw"><div class="pgb" style="width:${s.pct}%"></div></div><div style="font-size:10px;color:var(--muted)">${s.pct}%</div></td>
      <td style="color:${s.joursRetard>0?'var(--danger)':'var(--accent2)'};font-weight:600;font-size:11px">${s.joursRetard>0?s.joursRetard+'j':'✓'}</td>
      <td style="display:flex;gap:3px;flex-wrap:wrap;">
        ${session.role===ROLES.ADMIN||session.role===ROLES.COMMERCIAL||session.role===ROLES.CHEF_AGENCE?`<button class="btn btn-success btn-xs" onclick="openPay('${c._id}')" title="Payer">💰</button>`:''}
        ${['admin','chef_agence'].includes(session.role)&&c.adhesionStatut!=='paye'?`<button class="btn btn-xs" style="background:rgba(247,201,79,0.15);color:var(--accent);border:1px solid rgba(247,201,79,0.3)" onclick="openAdh('${c._id}')" title="Adhésion">🎫</button>`:''}
        <button class="btn btn-ghost btn-xs" onclick="ouvrirFicheClient('${c._id}')" title="Fiche complète">👁</button>
        ${['admin','chef_agence','secretaire'].includes(session.role)?`<button class="btn btn-xs" style="background:rgba(201,168,76,0.12);color:var(--accent);border:1px solid rgba(201,168,76,0.28)" onclick="ouvrirEditionClient('${c._id}')" title="Modifier">✏️</button>`:''}
        ${['admin','chef_agence','secretaire'].includes(session.role)?`<button class="btn btn-xs" style="background:rgba(56,201,160,0.12);color:var(--accent2);border:1px solid rgba(56,201,160,0.28)" onclick="ouvrirModifContrat('${c._id}')" title="Modifier le contrat">📝</button>`:''}
        ${_clPeutResilier() && c.statutContrat!=='resilie'?`<button class="btn btn-xs" style="background:rgba(224,92,82,0.12);color:var(--danger);border:1px solid rgba(224,92,82,0.35)" onclick="resilierClient('${c._id}')" title="Résilier le contrat">🚫</button>`:''}
        ${session.role===ROLES.ADMIN && c.statutContrat==='resilie'?`<button class="btn btn-xs" style="background:rgba(56,201,160,0.12);color:var(--accent2);border:1px solid rgba(56,201,160,0.28)" onclick="reactiverClient('${c._id}')" title="Réactiver le contrat">↩</button>`:''}
        ${['admin','chef_agence'].includes(session.role)?`<button class="btn btn-xs btn-warn" onclick="supprimerClient('${c._id}')" title="Supprimer">🗑</button>`:''}
      </td></tr>`;
  }).join('')||`<tr><td colspan="10" class="emp">${q?'Aucun client trouvé pour "'+q+'"':'Aucun client'}</td></tr>`;
  mettreAJourSelectionBar();
}

// ═══════════════════════════════════════════════
//  PAGE CONTRÔLE — marquage des clients contrôlés
// ═══════════════════════════════════════════════
let controleTab = 'attente'; // 'attente' | 'fait' | 'fini' (volet 57)

// ── VOLET 57 ── CLIENTS « FINIS ET LIVRÉS » : sortis des listes à contrôler.
// Fini et livré = contrat soldé à 100 % ET au moins une livraison « livrée »
// ET aucune livraison encore « en attente » (les annulées sont ignorées).
// Ces clients n'ont plus rien à contrôler : ils quittent « À contrôler » et
// « Contrôlés » pour un onglet à part « Finis & livrés », de sorte que
//   Total = Finis & livrés + Contrôlés + À contrôler.
// Leur historique de contrôle (volet 48) reste consultable.
function _ctrlIndexLivraisons(){
  const idx = new Map();
  (DB.livraisons||[]).forEach(l => {
    if(!l.clientId) return;
    const r = idx.get(l.clientId) || { livre: 0, attente: 0 };
    if(l.statut === 'livre') r.livre++; else if(l.statut === 'en_attente') r.attente++;
    idx.set(l.clientId, r);
  });
  return idx;
}
function _ctrlFiniLivre(c, idx){
  if(statsLite(c).pct < 100) return false;
  const r = idx.get(c._id);
  return !!r && r.livre > 0 && r.attente === 0;
}

window.setControleTab = function(tab){
  controleTab = tab;
  document.getElementById('ctrl-tab-attente').classList.toggle('active', tab==='attente');
  document.getElementById('ctrl-tab-fait').classList.toggle('active', tab==='fait');
  document.getElementById('ctrl-tab-fini')?.classList.toggle('active', tab==='fini');   // ── VOLET 57 ──
  const selStatut = document.getElementById('ctrl-filter-statut');
  if(selStatut) selStatut.value = tab;
  renderControle();
};

// ── VOLET 49 ── REGROUPEMENT PAR QUARTIER (page Contrôle et son rapport)
// Clé = quartier sans espaces en trop, comparé sans tenir compte des
// majuscules/accents (« Agla » et « agla » forment un seul groupe). Les
// clients sans quartier sont regroupés à la fin sous « Sans quartier ».
function _qrtCle(c){ return String((c && c.quartier) || '').trim(); }
function _qrtComparer(a, b){
  const qa = _qrtCle(a), qb = _qrtCle(b);
  if(!qa && qb) return 1;
  if(qa && !qb) return -1;
  const cq = qa.localeCompare(qb, 'fr', {sensitivity:'base'});
  if(cq) return cq;
  return (a.nom||'').localeCompare(b.nom||'', 'fr', {sensitivity:'base'});
}
// Rend `liste` (déjà triée par _qrtComparer) en insérant une ligne d'en-tête
// avant chaque quartier. ligneFn(c) renvoie le <tr> d'un client.
function _qrtRendreGroupes(liste, ligneFn, nbCol, styleEntete){
  let html = '', cour = null, i = 0;
  while(i < liste.length){
    const cle = _qrtCle(liste[i]);
    let j = i;
    while(j < liste.length && _qrtCle(liste[j]).localeCompare(cle, 'fr', {sensitivity:'base'}) === 0) j++;
    const groupe = liste.slice(i, j);
    const titre = cle ? cle.charAt(0).toLocaleUpperCase('fr') + cle.slice(1) : 'Sans quartier';
    html += `<tr><td colspan="${nbCol}" style="${styleEntete}">🏘️ ${esc(titre)} <span style="font-weight:400;opacity:.75;">— ${groupe.length} client(s)</span></td></tr>`
         + groupe.map(ligneFn).join('');
    i = j;
  }
  return html;
}
window._ctrlGrouperQuartier = true;

function renderControle(){
  // ── VOLET 48 ── chef d'agence : consultation seule (voir _ctrlLectureSeule).
  if(![ROLES.ADMIN, ROLES.CONTROLEUR, ROLES.CHEF_AGENCE].includes(session?.role)) return;
  const selStatutSync = document.getElementById('ctrl-filter-statut');
  if(selStatutSync) selStatutSync.value = controleTab;
  // Peupler le select commercial — ✅ PERF : ne reconstruire (innerHTML) que si
  // la liste des commerciaux a changé, pas à chaque frappe de recherche
  // (oninput="dRender('renderControle')" déclenche cette fonction en continu).
  const selCom = document.getElementById('ctrl-filter-com');
  if(selCom){
    const prevVal = selCom.value;
    const comsVisibles = comsDansAgence().filter(c=>c.role===ROLES.COMMERCIAL);
    const comsSig = comsVisibles.map(c=>c._id).join(',');
    // ── VOLET 7 : selection prealable ────────────────────────────────────
    // AVANT : l'option par defaut etait "— Tous les commerciaux —" (valeur
    // vide), et cette page construisait alors le tableau de TOUS les clients
    // de la structure (~2000 par commercial x 30 = ~60 000 lignes), en une
    // seule chaine innerHTML avec un appel a statsLite() par ligne. C'etait,
    // apres "Mes clients", le rendu le plus lourd de l'application.
    // MAINTENANT : la valeur vide affiche une invite et ne construit AUCUNE
    // ligne. Le controleur choisit un commercial, ou tape une recherche.
    //
    // ⚠️ AUCUNE FONCTIONNALITE RETIREE : l'affichage de tous les commerciaux
    // reste accessible, via une option explicite ('__tous__') signalee comme
    // lente. Ce n'est plus le comportement par defaut, c'est tout.
    if (selCom.dataset.comsSig !== comsSig) {
      selCom.innerHTML =
        `<option value="">— Sélectionner un commercial —</option>`
        + `<option value="__tous__">⚠️ Tous les commerciaux (affichage lent)</option>`
        + comsVisibles.map(c=>`<option value="${c._id}"${c._id===prevVal?' selected':''}>${esc(c.nom)}</option>`).join('');
      selCom.value = prevVal;
      selCom.dataset.comsSig = comsSig;
    }
  }

  const q = (document.getElementById('ctrl-search')?.value||'').toLowerCase().trim();
  const comFiltre = selCom ? selCom.value : '';

  // ── VOLET 7 ── on n'affiche le tableau que si un critere est fourni :
  //   - un commercial selectionne, OU
  //   - l'option explicite "tous les commerciaux", OU
  //   - une recherche d'au moins 2 caracteres (seuil identique a celui des
  //     pages "Clients" de l'admin et "Mes clients" du commercial).
  // La recherche seule reste donc possible a travers tous les commerciaux :
  // c'est le cas d'usage reel du controleur qui a un code client en main.
  const _tousExplicite = comFiltre === '__tous__';
  const _aUnCritere = _tousExplicite || !!comFiltre || q.length >= 2;
  if(!_aUnCritere){
    const tbody0 = document.getElementById('tb-controle');
    if(tbody0){
      const nbCol = document.querySelectorAll('#page-controle thead th').length || 7;
      const total = clientsDansAgence().length;
      tbody0.innerHTML =
        '<tr><td colspan="' + nbCol + '" style="padding:34px 16px;text-align:center;">'
        + '<div style="font-size:26px;margin-bottom:10px;">👤</div>'
        + '<div style="font-family:\'Space Grotesk\',sans-serif;font-size:14px;font-weight:700;color:var(--text);margin-bottom:6px;">Sélectionnez un commercial</div>'
        + '<div style="font-size:12px;color:var(--muted);line-height:1.6;">Choisissez un commercial dans la liste ci-dessus,<br>ou recherchez directement un client (2 caractères minimum).</div>'
        + '<div style="font-size:11px;color:var(--subtle);margin-top:12px;">' + total + ' client(s) au total</div>'
        + '</td></tr>';
    }
    // Compteurs remis a "—" : laisser les valeurs precedentes ferait croire
    // qu'elles correspondent a ce qui est affiche.
    const ca = document.getElementById('ctrl-count-attente'); if(ca) ca.textContent = '—';
    const cf = document.getElementById('ctrl-count-fait');    if(cf) cf.textContent = '—';
    const cfl = document.getElementById('ctrl-count-fini');   if(cfl) cfl.textContent = '—';   // ── VOLET 57 ──
    const crs = document.getElementById('ctrl-resume');       if(crs) crs.innerHTML = '';
    const cs = document.getElementById('ctrl-search-count');  if(cs) cs.textContent = '';
    return;
  }

  let cls = clientsDansAgence();
  // '__tous__' n'est pas un identifiant de commercial : c'est le choix
  // explicite de ne pas filtrer.
  if(comFiltre && !_tousExplicite) cls = cls.filter(c=>c.commercialId===comFiltre);
  if(q) cls = cls.filter(c=>
    (c.codeClient&&c.codeClient.toLowerCase().includes(q))||
    c.nom.toLowerCase().includes(q)||
    (c.tel||'').includes(q)||
    (c.contrat||'').toLowerCase().includes(q)
  );

  // ── VOLET 57 ── les clients finis et livrés sortent des deux listes.
  const _idxLiv = _ctrlIndexLivraisons();
  const finisLivres = cls.filter(c => _ctrlFiniLivre(c, _idxLiv));
  const _setFinis = new Set(finisLivres.map(c => c._id));
  const _actifs = cls.filter(c => !_setFinis.has(c._id));
  const enAttente = _actifs.filter(c=>!c.controle || c.controle.statut!=='controle');
  const dejaFait  = _actifs.filter(c=>c.controle && c.controle.statut==='controle');

  document.getElementById('ctrl-count-attente').textContent = enAttente.length;
  document.getElementById('ctrl-count-fait').textContent = dejaFait.length;
  const _cFini = document.getElementById('ctrl-count-fini'); if(_cFini) _cFini.textContent = finisLivres.length;
  const _res = document.getElementById('ctrl-resume');
  if(_res){
    const _tot = cls.length, _pc = n => _tot ? Math.round(n*100/_tot) : 0;
    _res.innerHTML = `
      <div class="kpi-card kc-blue"><div class="kpi-lbl">Total clients</div><div class="kpi-val kv-blue">${_tot}</div></div>
      <div class="kpi-card kc-green"><div class="kpi-lbl">🏁 Finis & livrés</div><div class="kpi-val kv-green">${finisLivres.length}</div><div class="kpi-sub">${_pc(finisLivres.length)} %</div></div>
      <div class="kpi-card" style="border-color:rgba(94,140,255,0.35);"><div class="kpi-lbl">✅ Contrôlés</div><div class="kpi-val" style="color:#5e8cff;">${dejaFait.length}</div><div class="kpi-sub">${_pc(dejaFait.length)} %</div></div>
      <div class="kpi-card kc-yellow"><div class="kpi-lbl">⏳ À contrôler</div><div class="kpi-val kv-yellow">${enAttente.length}</div><div class="kpi-sub">${_pc(enAttente.length)} %</div></div>`;
  }

  // ── VOLET 37 ── trace de SON PROPRE travail, a l'ecran.
  // « 12 contrôlés » ne dit pas combien le controleur connecte en a fait
  // lui-meme — information qu'il demandait, et que seul le rapport imprime
  // pouvait approcher. On compare sur parId, avec repli sur le nom pour les
  // controles anterieurs au volet 37.
  const _moiEl = document.getElementById('ctrl-count-moi');
  if(_moiEl){
    const monNom = session.nom || session.userId;
    const miens = dejaFait.filter(c => {
      const ct = c.controle || {};
      return ct.parId ? ct.parId === session.userId : ct.par === monNom;
    });
    const duJour = miens.filter(c => (c.controle||{}).date === TODAY).length;
    _moiEl.textContent = miens.length;
    const _moiJour = document.getElementById('ctrl-count-moi-jour');
    if(_moiJour) _moiJour.textContent = duJour ? `dont ${duJour} aujourd'hui` : 'aucun aujourd\'hui';
  }

  const liste = controleTab==='attente' ? enAttente : controleTab==='fini' ? finisLivres : dejaFait;
  // Tri par nom
  // ── VOLET 49 ── regroupement par quartier (case « Regrouper par quartier »).
  const _grpQrt = document.getElementById('ctrl-group-quartier')?.checked ?? window._ctrlGrouperQuartier;
  if(_grpQrt) liste.sort(_qrtComparer);
  else liste.sort((a,b)=>(a.nom||'').localeCompare(b.nom||'','fr',{sensitivity:'base'}));

  const countEl = document.getElementById('ctrl-search-count');
  if(countEl) countEl.textContent = `${liste.length} client(s)`;

  const thInfo = document.getElementById('ctrl-th-info');
  if(thInfo) thInfo.textContent = controleTab==='attente' ? 'Statut' : controleTab==='fini' ? 'Situation' : 'Contrôlé le';

  const _ligneCtrl = c=>{
    const contratLabel = (()=>{
      if(c.contratArticles && c.contratArticles.length){
        return c.contratArticles.map(a=>{
          const art = getProdOuArticle(a.artId);
          const ref = art&&art.ref ? art.ref : (a.nom||'?');
          const qty = parseInt(a.qty)||1;
          return qty>1 ? `${ref} x${qty}` : ref;
        }).join(' + ');
      }
      return c.contrat||'—';
    })();
    // ── ÉTAPE 2 DU CHANTIER (dénormalisation) : statsLite() — le "dernier
    // paiement" vient directement des champs dénormalisés du client
    // (dernierPaiementDate/Heure, tenus à jour à chaque paiement) au lieu
    // de scanner s.pays, donc plus besoin de DB.paiements en mémoire ici.
    const s = statsLite(c);
    const majCell = s.dernierPaiementDate
      ? `<div style="font-size:11px;">${esc(s.dernierPaiementDate)}${s.dernierPaiementHeure?` <span class="tm" style="font-size:10px">${esc(s.dernierPaiementHeure)}</span>`:''}</div>`
      : `<span class="tm" style="font-size:11px;">—</span>`;
    const niveauColor = s.joursCouv>=(c.duree||0) && (c.duree||0)>0 ? 'var(--accent2)' : 'var(--accent)';
    const niveauCell = `<div title="Niveau: ${s.joursCouv}/${c.duree||0} jours" style="font-size:11px;font-weight:700;color:${niveauColor};white-space:nowrap;">${joursEnJM(s.joursCouv)}<span style="font-size:9px;color:var(--muted);font-weight:400;"> /${joursEnJM(c.duree||0)}</span></div>`;
    // ── VOLET 48 ── nombre de contrôles et accès à l'historique complet.
    const _nbCtrl = _ctrlNbControles(c);
    const _btnHist = _nbCtrl || _ctrlHistorique(c).length
      ? `<button class="btn btn-ghost btn-xs" onclick="ouvrirHistoriqueControle('${c._id}')" title="Toutes les dates de contrôle et les notes">📜 Historique (${_nbCtrl})</button>`
      : '';
    const infoCell = controleTab==='fini'
      ? sb('Soldé & livré','sg') + `<div class="tm" style="font-size:10px;margin-top:3px;">${_nbCtrl ? `contrôlé ${_nbCtrl} fois` : 'jamais contrôlé'}</div>`
      : controleTab==='attente'
      ? sb('À contrôler','sy') + (_nbCtrl ? `<div class="tm" style="font-size:10px;margin-top:3px;">déjà contrôlé ${_nbCtrl} fois</div>` : '')
      : `<div style="font-size:11px;">${esc(c.controle.date||'—')} ${esc(c.controle.heure||'')}<div class="tm" style="font-size:10px">par ${esc(c.controle.par||'—')}${_nbCtrl>1?` · ${_nbCtrl}e contrôle`:''}</div>${c.controle.note?`<div class="tm" style="font-size:10px;font-style:italic;">"${esc(c.controle.note)}"</div>`:''}</div>`;
    const actionCell = (_ctrlLectureSeule() || controleTab==='fini')
      ? (_btnHist || '<span class="tm" style="font-size:10px;">—</span>')
      : (controleTab==='attente'
        ? `<button class="btn btn-xs" style="background:rgba(100,160,247,0.15);color:#64a0f7;border:1px solid rgba(100,160,247,0.4);font-weight:700;" onclick="ouvrirMarquerControle('${c._id}')">✓ Marquer contrôlé</button>`
        : `<button class="btn btn-ghost btn-xs" onclick="annulerControle('${c._id}')" title="Annuler le contrôle">↺ Annuler</button>`) + ' ' + _btnHist;
    return `<tr>
      <td class="fw6">${esc(c.nom)}${c.codeClient?` <span style="font-size:9.5px;background:rgba(201,168,76,0.15);border:1px solid rgba(201,168,76,0.4);border-radius:4px;padding:0 5px;color:var(--accent);font-weight:700;">${esc(c.codeClient)}</span>`:''}</td>
      <td>${esc(c.tel||'—')}</td>
      <td><span class="tag">${esc(getCom(c.commercialId).nom)}</span></td>
      <td style="font-size:11px;">${esc(contratLabel)}</td>
      <td class="fw6" style="font-size:11px;">${fmt(s.m)}<span class="tm" style="font-size:9px;">/j</span></td>
      <td>${majCell}</td>
      <td>${niveauCell}</td>
      <td>${infoCell}</td>
      <td>${actionCell}</td>
    </tr>`;
  };
  const _videCtrl = `<tr><td colspan="9" class="emp">${controleTab==='attente'?'Aucun client en attente de contrôle':controleTab==='fini'?'Aucun client fini et livré':'Aucun client contrôlé pour le moment'}</td></tr>`;
  document.getElementById('tb-controle').innerHTML = !liste.length ? _videCtrl
    : (_grpQrt
      ? _qrtRendreGroupes(liste, _ligneCtrl, 9, 'background:rgba(201,168,76,0.10);color:var(--accent);font-weight:700;font-size:12px;padding:7px 10px;border-top:2px solid rgba(201,168,76,0.35);')
      : liste.map(_ligneCtrl).join(''));
}

// ════════════════════════════════════════════════
//  CONTRÔLE AVANT DÉPART — audit complet d'un commercial
// ════════════════════════════════════════════════
// Objectif : avant qu'un commercial ne quitte l'entreprise (ou soit muté),
// donner à l'admin/contrôleur la liste COMPLÈTE des clients avec lesquels
// il a réellement travaillé (= au moins un paiement enregistré à son nom),
// même si ces clients ont depuis été réaffectés à un autre commercial.
// Cela évite qu'un remplaçant hérite d'un portefeuille dont il ne connaît
// pas la totalité, et permet d'exiger un contrôle complet avant le départ.
let _cdLastComId = null;
let _cdLastRows = []; // mémorisé pour l'export, évite de tout recalculer

async function renderControleDepart(){
  if(!['admin','controleur'].includes(session?.role)) return;
  const sel = document.getElementById('cd-com-select');
  if(sel){
    // Liste TOUS les commerciaux (y compris ceux qui ne sont plus assignés à
    // aucun client actuellement) — un départ imminent est justement le cas
    // où l'on veut auditer AVANT que quoi que ce soit ne change.
    const coms = DB.commerciaux.filter(c=>c.role===ROLES.COMMERCIAL)
      .sort((a,b)=>(a.nom||'').localeCompare(b.nom||'','fr',{sensitivity:'base'}));
    const sig = coms.map(c=>c._id).join(',');
    if(sel.dataset.sig !== sig){
      const prev = sel.value;
      sel.innerHTML = '<option value="">— Sélectionner un commercial —</option>' +
        coms.map(c=>`<option value="${c._id}">${esc(c.nom)}${c.zone?' · '+esc(c.zone):''}</option>`).join('');
      if(prev && coms.find(c=>c._id===prev)) sel.value = prev;
      sel.dataset.sig = sig;
    }
  }

  const zone = document.getElementById('cd-result');
  const summary = document.getElementById('cd-summary');
  if(!sel || !sel.value){
    if(zone) zone.innerHTML = '<div class="emp" style="padding:40px;">Sélectionnez un commercial pour voir la liste des clients ayant payé avec lui depuis sa prise de poste (date de sa dernière affectation).</div>';
    if(summary) summary.style.display = 'none';
    _cdLastComId = null; _cdLastRows = [];
    return;
  }

  const comId = sel.value;
  const com = getCom(comId);
  if(zone) zone.innerHTML = '<div class="emp" style="padding:40px;">⏳ Recherche des paiements enregistrés par ce commercial depuis sa prise de poste…</div>';

  let paysCom;
  try {
    paysCom = await _fetchPaiementsParCommercial(comId);
  } catch(e){
    notify('Erreur lors de la recherche : '+(e.message||e), 'err');
    if(zone) zone.innerHTML = '<div class="emp" style="padding:40px;color:var(--danger);">Erreur de chargement.</div>';
    return;
  }
  // Si l'utilisateur a changé de commercial pendant le chargement, on ignore ce résultat obsolète
  if(document.getElementById('cd-com-select')?.value !== comId) return;

  // ── Filtre "après mutation" ──
  // Pour chaque client, dateAffectation = date à laquelle CE commercial a
  // pris le client en charge (enregistrée automatiquement lors d'un transfert
  // ou d'un changement de commercial via la fiche client). Seuls les
  // paiements reçus par ce commercial À PARTIR de cette date comptent : ça
  // permet de vérifier qu'un commercial nouvellement affecté à un marché
  // encaisse bien auprès des clients qui lui ont été confiés, sans compter
  // d'anciens paiements hérités d'avant sa prise de poste. Si le client n'a
  // pas de dateAffectation enregistrée (jamais transféré, avec ce commercial
  // depuis toujours), tous ses paiements comptent normalement.
  const paysFiltres = paysCom.filter(p=>{
    if(!p.clientId) return false;
    const cl = getCl(p.clientId);
    if(!cl || !cl.dateAffectation) return true;
    return (p.date||'') >= cl.dateAffectation;
  });

  // Regrouper par client : nb paiements, total payé À CE commercial (depuis sa prise de poste), dernière date
  const parClient = new Map();
  for(const p of paysFiltres){
    if(!p.clientId) continue;
    const e = parClient.get(p.clientId) || {nb:0, total:0, dernier:null};
    e.nb++;
    e.total += (p.montant||0);
    if(!e.dernier || (p.date||'') > e.dernier) e.dernier = p.date;
    parClient.set(p.clientId, e);
  }

  const rows = [...parClient.entries()].map(([clientId, agg])=>{
    const cl = getCl(clientId);
    const reassigne = cl && cl.commercialId && cl.commercialId !== comId;
    return {
      clientId,
      nom: cl ? cl.nom : '(client supprimé)',
      tel: cl ? (cl.tel||'—') : '—',
      code: cl ? (cl.codeClient||'') : '',
      nb: agg.nb,
      total: agg.total,
      dernier: agg.dernier,
      depuis: cl?.dateAffectation || null,
      statutContrat: cl ? (cl.statutContrat||'actif') : '—',
      reassigneA: reassigne ? (getCom(cl.commercialId)?.nom || '?') : null,
      supprime: !cl,
    };
  }).sort((a,b)=>(b.dernier||'').localeCompare(a.dernier||''));

  _cdLastComId = comId;
  _cdLastRows = rows;

  const nbClients = rows.length;
  const totalGeneral = rows.reduce((a,r)=>a+(Number(r.total)||0), 0);
  const nbReassignes = rows.filter(r=>r.reassigneA).length;
  const nbResilies = rows.filter(r=>r.statutContrat==='resilie').length;

  if(summary){
    summary.style.display = '';
    summary.innerHTML = `
      <div class="kpi-card kc-blue"><div class="kpi-lbl">Clients ayant payé depuis sa prise de poste</div><div class="kpi-val kv-blue">${nbClients}</div></div>
      <div class="kpi-card kc-green"><div class="kpi-lbl">Total encaissé par lui</div><div class="kpi-val kv-green">${fmt(totalGeneral)}</div></div>
      <div class="kpi-card kc-yellow"><div class="kpi-lbl">Déjà réaffectés à un autre</div><div class="kpi-val kv-yellow">${nbReassignes}</div></div>
      <div class="kpi-card kc-red"><div class="kpi-lbl">Résiliés</div><div class="kpi-val kv-red">${nbResilies}</div></div>`;
  }

  if(zone){
    zone.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex-wrap:wrap;gap:8px;">
        <div style="font-size:12.5px;color:var(--muted);">Résultat pour <strong style="color:var(--text);">${esc(com?.nom||'?')}</strong> — ${nbClients} client(s) ayant payé au moins une fois depuis sa prise de poste (triés par activité la plus récente)</div>
        <button class="btn btn-sm no-print" style="background:rgba(34,212,160,0.12);color:var(--accent2);border:1px solid rgba(34,212,160,0.3);font-weight:700;" onclick="exportControleDepart()">📥 Exporter (Excel)</button>
      </div>
      <div class="tw"><table><thead><tr>
        <th>Client</th><th class="no-print">Téléphone</th><th>Paiements</th><th>Total payé (avec lui)</th><th>Depuis (mutation)</th><th>Dernier paiement</th><th>Statut contrat</th><th>Assignation actuelle</th>
      </tr></thead><tbody>
      ${rows.map(r=>`<tr>
        <td class="fw6">${esc(r.nom)}${r.code?` <span style="font-size:9.5px;background:rgba(201,168,76,0.15);border:1px solid rgba(201,168,76,0.4);border-radius:4px;padding:0 5px;color:var(--accent);font-weight:700;">${esc(r.code)}</span>`:''}${r.supprime?' <span class="tm" style="font-size:10px;">(fiche supprimée)</span>':''}</td>
        <td class="no-print">${esc(r.tel)}</td>
        <td>${r.nb}</td>
        <td class="fw6" style="color:var(--accent2);">${fmt(r.total)}</td>
        <td style="font-size:11px;">${esc(r.depuis||'—')}</td>
        <td style="font-size:11px;">${esc(r.dernier||'—')}</td>
        <td>${r.statutContrat==='resilie'?'<span class="resilie-badge" style="font-size:9px;">RÉSILIÉ</span>':(r.statutContrat==='actif'?sb('Actif','sg'):esc(r.statutContrat))}</td>
        <td style="font-size:11px;">${r.reassigneA?`<span style="color:var(--accent3);font-weight:700;">⚠️ Réaffecté → ${esc(r.reassigneA)}</span>`:'<span class="tm">— toujours à lui —</span>'}</td>
      </tr>`).join('') || `<tr><td colspan="8" class="emp">Aucun paiement trouvé pour ce commercial depuis sa prise de poste — aucun client "réel" identifié</td></tr>`}
      </tbody></table></div>`;
  }
}
window.renderControleDepart = renderControleDepart;

window.exportControleDepart = function(){
  if(!_cdLastComId || !_cdLastRows.length){ notify('Aucune donnée à exporter — générez d\'abord le contrôle', 'err'); return; }
  const com = getCom(_cdLastComId);
  const cols = ['Client','Code client','Téléphone','Nb paiements','Total payé (avec lui)','Depuis (mutation)','Dernier paiement','Statut contrat','Assignation actuelle'];
  const data = _cdLastRows.map(r=>[
    r.nom, r.code||'', r.tel, r.nb, r.total, r.depuis||'', r.dernier||'',
    r.statutContrat==='resilie'?'Résilié':(r.statutContrat||''),
    r.reassigneA ? `Réaffecté → ${r.reassigneA}` : 'Toujours à lui'
  ]);
  const ws = XLSX.utils.aoa_to_sheet([cols, ...data]);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Contrôle avant départ');
  XLSX.writeFile(wb, `controle_depart_${(com?.nom||'commercial').replace(/[^a-z0-9]+/gi,'_')}_${TODAY}.xlsx`);
};

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 48 — HISTORIQUE DES CONTRÔLES + CHEF D'AGENCE EN LECTURE ║
// ╚══════════════════════════════════════════════════════════════╝
// AVANT : chaque contrôle ÉCRASAIT le précédent (client.controle ne gardait
// que le dernier), et « Annuler » effaçait tout. Impossible de savoir combien
// de fois un client avait été contrôlé, ni ce qui avait été noté.
// DÉSORMAIS : client.controle.historique conserve chaque contrôle (date,
// heure, auteur, note) et chaque annulation. Il vit DANS l'objet `controle`
// — le seul champ que la règle Firestore laisse modifier au contrôleur :
// aucune modification de règle nécessaire.
// Limite : 100 dernières entrées par client (taille du document).
// Contrôles antérieurs au volet 48 : seul le dernier était conservé ; il
// devient la première entrée de l'historique.
const _CTRL_HIST_MAX = 100;
function _ctrlHistorique(c){
  const ct = (c && c.controle) || {};
  if(Array.isArray(ct.historique)) return ct.historique.slice();
  if(ct.statut === 'controle' && ct.date){
    return [{ type: 'controle', date: ct.date, heure: ct.heure || '', par: ct.par || '', parId: ct.parId || '', note: ct.note || '', anterieur: true }];
  }
  return [];
}
function _ctrlNbControles(c){ return _ctrlHistorique(c).filter(h => h.type !== 'annulation').length; }
function _ctrlLectureSeule(){ return session?.role === ROLES.CHEF_AGENCE; }

window.ouvrirHistoriqueControle = function(cid){
  const c = (DB.clients||[]).find(x => x._id === cid);
  if(!c){ notify('Client introuvable','err'); return; }
  const hist = _ctrlHistorique(c).sort((a,b) => ((b.date||'')+(b.heure||'')).localeCompare((a.date||'')+(a.heure||'')));
  const nb = hist.filter(h => h.type !== 'annulation').length;
  document.getElementById('ctrl-hist-overlay')?.remove();
  const ov = document.createElement('div');
  ov.id = 'ctrl-hist-overlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9998;display:flex;align-items:center;justify-content:center;padding:16px;';
  ov.onclick = e => { if(e.target === ov) ov.remove(); };
  const lignes = hist.length ? hist.map(h => h.type === 'annulation'
    ? `<div style="border-left:3px solid var(--danger);padding:8px 12px;margin-bottom:8px;background:rgba(224,92,82,0.06);border-radius:0 8px 8px 0;">
        <div style="font-size:12px;font-weight:700;color:var(--danger);">↺ Contrôle annulé — ${esc(h.date||'—')} ${esc(h.heure||'')}</div>
        <div style="font-size:11px;color:var(--muted);">par ${esc(h.par||'—')}</div></div>`
    : `<div style="border-left:3px solid var(--accent2);padding:8px 12px;margin-bottom:8px;background:rgba(56,201,160,0.06);border-radius:0 8px 8px 0;">
        <div style="font-size:12px;font-weight:700;">✅ ${esc(h.date||'—')} ${esc(h.heure||'')}</div>
        <div style="font-size:11px;color:var(--muted);">par ${esc(h.par||'—')}${h.anterieur?' · <em>contrôle antérieur à l\'historique</em>':''}</div>
        <div style="font-size:12px;margin-top:4px;${h.note?'':'color:var(--muted);'}">${h.note ? '📝 ' + esc(h.note) : 'Aucune note'}</div></div>`).join('')
    : '<div class="emp" style="padding:20px;">Ce client n\'a encore jamais été contrôlé.</div>';
  ov.innerHTML = `
    <div style="background:var(--card);border:1px solid var(--border);border-radius:14px;max-width:520px;width:100%;max-height:85vh;display:flex;flex-direction:column;overflow:hidden;">
      <div style="display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid var(--border);">
        <div><strong style="font-size:15px;">📜 Historique des contrôles</strong>
          <div style="font-size:12px;color:var(--muted);margin-top:2px;">${esc(c.nom)}${c.codeClient?' · '+esc(c.codeClient):''} — ${nb} contrôle(s)</div></div>
        <button onclick="document.getElementById('ctrl-hist-overlay').remove()" style="background:none;border:none;color:var(--muted);font-size:20px;cursor:pointer;">✕</button>
      </div>
      <div style="overflow-y:auto;padding:14px 18px;">${lignes}</div>
    </div>`;
  document.body.appendChild(ov);
};

window.ouvrirMarquerControle = function(cid){
  if(![ROLES.ADMIN, ROLES.CONTROLEUR].includes(session?.role)){ notify('Consultation seule — le contrôle est réservé au contrôleur et à l\'admin','err'); return; }
  const c = getCl(cid);
  if(!c){ notify('Client introuvable','err'); return; }
  document.getElementById('ctrl-cl-id').value = cid;
  document.getElementById('ctrl-cl-info').innerHTML = `<strong>${esc(c.nom)}</strong> · ${esc(c.tel||'—')}<br><span style="font-size:11px;color:var(--muted);">${esc(c.contrat||'—')}</span>`;
  document.getElementById('ctrl-note').value = '';
  openM('m-controle');
};

window.confirmerControle = _withActionLock('confirmerControle', async function(){
  if(!['admin','controleur'].includes(session?.role)){ notify('Accès non autorisé','err'); return; }
  const cid = document.getElementById('ctrl-cl-id').value;
  if(!cid){ notify('Client introuvable','err'); return; }
  const note = (document.getElementById('ctrl-note').value||'').trim().slice(0,300);
  const now = new Date();
  const heure = String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');
  try {
    // ╔══════════════════════════════════════════════════════════════╗
    // ║  VOLET 37 — ON ENREGISTRE QUI, PAS SEULEMENT SON NOM          ║
    // ╚══════════════════════════════════════════════════════════════╝
    // `par` ne contenait qu'un NOM D'AFFICHAGE. Regrouper les controles par
    // nom est fragile pour deux raisons concretes :
    //   · deux controleurs homonymes se confondraient dans toute statistique ;
    //   · renommer quelqu'un dans la fiche Utilisateurs couperait son
    //     historique en deux, sans que rien ne le signale.
    // `parId` est purement ADDITIF : `par` reste ecrit a l'identique, donc
    // tous les affichages existants continuent de fonctionner, y compris pour
    // les controles deja enregistres avant ce volet qui n'auront pas d'id.
    //
    // ⚠️ La regle Firestore n'autorise le controleur qu'a toucher le champ
    // `controle` (et `_ts`). `parId` vit DANS cet objet : aucun elargissement
    // de droits, aucune modification de regle necessaire pour ce point.
    // ── VOLET 48 ── on ajoute ce contrôle à l'historique au lieu d'écraser.
    const _hist = _ctrlHistorique((DB.clients||[]).find(x => x._id === cid));
    _hist.push({ type: 'controle', date: TODAY, heure, par: session.nom || session.userId, parId: session.userId, note });
    await fbUpdate('clients', cid, {
      controle: {
        statut: 'controle',
        date: TODAY,
        heure,
        par: session.nom || session.userId,
        parId: session.userId,
        parRole: session.role,
        note,
        historique: _hist.slice(-_CTRL_HIST_MAX)
      }
    });
    closeM('m-controle');
    notify('✅ Client marqué comme contrôlé');
    renderControle();
  } catch(e) {
    notify('Erreur lors du marquage : '+(e.message||String(e)), 'err');
  }
});

window.annulerControle = _withActionLock((...a)=>'annulerControle:'+a.join(':'), async function(cid){
  if(!['admin','controleur'].includes(session?.role)){ notify('Accès non autorisé','err'); return; }
  const c = getCl(cid);
  if(!c){ notify('Client introuvable','err'); return; }
  if(!(await confirmDialog(`Annuler le contrôle de « ${esc(c.nom)} » ? Il repassera dans la liste "À contrôler".`,{title:'Annuler le contrôle'}))) return;
  try {
    // ── VOLET 48 ── l'annulation ne détruit plus l'historique : elle y est
    // inscrite (date, heure, auteur).
    const _now = new Date();
    const _h = String(_now.getHours()).padStart(2,'0')+':'+String(_now.getMinutes()).padStart(2,'0');
    const _hist = _ctrlHistorique((DB.clients||[]).find(x => x._id === cid));
    _hist.push({ type: 'annulation', date: TODAY, heure: _h, par: session.nom || session.userId, parId: session.userId });
    await fbUpdate('clients', cid, {
      controle: { statut: 'non_controle', date:'', heure:'', par:'', note:'', historique: _hist.slice(-_CTRL_HIST_MAX) }
    });
    notify('Contrôle annulé');
    renderControle();
  } catch(e) {
    notify('Erreur lors de l\'annulation : '+(e.message||String(e)), 'err');
  }
});

// ── Rapport de contrôle : synthèse imprimable des clients contrôlés / non contrôlés ──
