// ═══════════════ PALIERS MONTANT → DURÉE DE CONTRAT (admin) ═══════════════
// Remplace l'ancienne approche "durée limitée par produit" : l'admin définit
// des paliers {seuil (montant plafond en FCFA), duree (jours)}. Dès qu'un
// montant de contrat est ≤ au seuil d'un palier, la durée de CE palier est
// appliquée et verrouillée automatiquement sur les formulaires de création
// de client (cl-* pour admin/secrétaire, com-ncl-* pour un commercial) — voir
// calcJour()/calcJourComNcl() qui appellent appliquerDureeAutomatiquePalier()
// à chaque changement de montant.
function _labelDureeJours(j){
  const connus = {'93':'3 mois (93 jours)','186':'6 mois (186 jours)','372':'1 an (372 jours)'};
  return connus[String(j)] || `${j} jours`;
}

// Retourne le palier applicable pour un montant donné : le PLUS PETIT seuil
// encore ≥ au montant (ex. paliers 10000→93j et 20000→186j : un montant de
// 15000 tombe dans le palier 20000, pas 10000). Si le montant dépasse tous
// les seuils définis, retourne null — aucune durée n'est alors imposée,
// l'utilisateur reste libre de choisir (il faut ajouter un palier avec un
// seuil très élevé si vous voulez couvrir aussi les gros montants).
// ✅ Prise d'effet : un palier dont `dateEffet` est dans le futur (> TODAY)
// est ignoré — il ne s'appliquera qu'à partir de cette date. Sans dateEffet
// (vide), le palier est actif immédiatement, comme avant.
function trouverPalierDuree(montant){
  const paliers = (DB.paliersDuree||[])
    .filter(p => montant <= Number(p.seuil))
    .filter(p => !p.dateEffet || p.dateEffet <= TODAY)
    .sort((a,b) => Number(a.seuil) - Number(b.seuil));
  return paliers.length ? paliers[0] : null;
}

// Applique (ou retire) le verrouillage de durée pour un formulaire de
// création de client donné (prefix 'cl' ou 'com-ncl'), selon le montant
// actuellement saisi.
function appliquerDureeAutomatiquePalier(prefix, montant){
  const sel = document.getElementById(prefix+'-duree-sel');
  const inp = document.getElementById(prefix+'-duree');
  const note = document.getElementById(prefix+'-duree-lock-note');
  if(!sel || !inp) return;
  const palier = montant>0 ? trouverPalierDuree(montant) : null;
  if(!palier){
    sel.disabled = false; inp.disabled = false;
    if(note) note.style.display = 'none';
    return;
  }
  syncDureeSelect(prefix+'-duree-sel', prefix+'-duree', palier.duree);
  sel.disabled = true; inp.disabled = true;
  if(note){
    note.style.display = 'block';
    note.style.color = 'var(--warn)';
    note.innerHTML = `🔒 Durée fixée automatiquement à ${_labelDureeJours(palier.duree)} — palier${palier.label?' « '+esc(palier.label)+' »':''} : montant ≤ ${fmt(Number(palier.seuil))} FCFA.`;
  }
}

