// ========= ACTIONS =========
window.openPay = async function(cid, forceNewClient){
  payCtx=cid;
  // ✅ Bascule le bouton "Annuler" selon le contexte : voir déclaration de
  // _payForceNewClientId ci-dessus. Toujours remis à l'état normal par
  // défaut (forceNewClient absent/false) pour ne jamais laisser ce mode
  // "collé" sur un appel ultérieur normal d'openPay().
  const btnCancel = document.getElementById('pay-btn-cancel');
  if(forceNewClient){
    _payForceNewClientId = cid;
    if(btnCancel){
      btnCancel.textContent = '🗑 Annuler et supprimer ce client';
      btnCancel.title = "Aucune mise n'a encore été enregistrée pour ce client — annuler ici le supprime.";
      btnCancel.onclick = () => window.annulerEtSupprimerNouveauClient();
    }
  } else {
    _payForceNewClientId = null;
    if(btnCancel){
      btnCancel.textContent = 'Annuler';
      btnCancel.title = '';
      btnCancel.onclick = () => closeM('m-pay');
    }
  }
  // ── OPTION C ── ecran de saisie d'un paiement : le niveau de cotisation
  // affiche et le recu qui suit reposent sur le cumul reel des paiements de
  // ce client. On garantit l'historique complet avant d'ouvrir (no-op si
  // deja charge, requete ciblee sinon).
  await _ensureClientPaysLoaded(cid);
  const c=getCl(cid),s=stats(c);
  // ── Bloquer si contrat résilié ──
  if(c.statutContrat==='resilie'){
    notify(`🚫 Contrat de ${esc(c.nom)} résilié — aucune cotisation possible.`,'err');
    return;
  }
  const contratSolde = c.montantTotal>0 && s.totalPaye>=c.montantTotal;
  // Affichage info + badge contrat soldé si applicable
  const soldeBadge = contratSolde
    ? `<div style="margin-top:7px;background:rgba(34,212,160,0.12);border:1px solid rgba(34,212,160,0.4);border-radius:8px;padding:7px 11px;font-size:12px;color:var(--accent2);font-weight:700;">🏆 Contrat totalement soldé — aucune cotisation supplémentaire requise.<br><span style="font-size:11px;font-weight:400;color:var(--muted);">Modifiez le contrat pour autoriser de nouveaux encaissements.</span></div>`
    : '';
  document.getElementById('pay-info').innerHTML=`<strong>${esc(c.nom)}</strong> · ${esc(c.contrat)}<br>Cotisation/jour : <strong>${fmt(s.m)}</strong> &nbsp;|&nbsp; Restant : <strong style="color:${contratSolde?'var(--accent2)':'var(--text)'}">${fmt(s.totalRestant)}</strong><br>${s.joursRetard>0?`⚠️ Retard : <strong style="color:var(--danger)">${s.joursRetard}j</strong> ≈ ${fmt(s.joursRetard*s.m)}`:'✅ À jour'}${soldeBadge}`;
  document.getElementById('pay-multiples').innerHTML=`<span style="font-size:10px;color:var(--muted);align-self:center">Raccourcis :</span>`+[1,2,3,5].map(n=>`<button class="btn btn-ghost btn-xs" onclick="document.getElementById('pay-amt').value=${s.m*n}">${n}x (${fmt(s.m*n)})</button>`).join('');
  document.getElementById('pay-amt').value=contratSolde?0:s.m;
  document.getElementById('pay-note').value='';
  // Bouton modifier contrat (admin uniquement)
  const editContratWrap = document.getElementById('pay-edit-contrat-wrap');
  if(editContratWrap) editContratWrap.style.display = ['admin','chef_agence','secretaire'].includes(session.role) ? '' : 'none';
  // Désactiver le bouton confirmer si contrat soldé (non-admin bloqué, admin peut forcer)
  const btnConfirm = document.getElementById('pay-btn-confirm');
  if(btnConfirm){
    // ✅ Repart toujours d'un texte propre (au cas où resté sur "⏳
    // Enregistrement…" suite à une fermeture pendant un envoi en cours)
    btnConfirm.textContent = '✓ Confirmer';
    if(contratSolde && !['admin','chef_agence','secretaire'].includes(session.role)){
      btnConfirm.disabled=true; btnConfirm.style.opacity='0.4'; btnConfirm.style.cursor='not-allowed';
      btnConfirm.title='Contrat soldé — modification du contrat requise';
    } else {
      btnConfirm.disabled=false; btnConfirm.style.opacity=''; btnConfirm.style.cursor=''; btnConfirm.title='';
    }
  }
  // Champ date visible uniquement pour l'admin
  const dateRow = document.getElementById('pay-date-row');
  const dateInput = document.getElementById('pay-date');
  const comIdForDate = ['admin','chef_agence'].includes(session.role) ? (getCl(cid)||{}).commercialId : session.userId;
  const effectiveDate = ['admin','chef_agence'].includes(session.role) ? TODAY : getDateEffectiveCommercial(comIdForDate);
  if(['admin','chef_agence'].includes(session.role)){
    dateRow.style.display='';
    dateInput.value=TODAY;
    dateInput.max=TODAY;                 // ── VOLET 30 ── voir _dateSaisieValide
  } else {
    dateRow.style.display='none';
    dateInput.value=effectiveDate;
  }
  const motifRow = document.getElementById('pay-motif-row');
  const motifInput = document.getElementById('pay-motif-correction');
  if(motifRow) motifRow.style.display='none';
  if(motifInput) motifInput.value='';
  openM('m-pay');
};

// ✅ Sur demande : pour un client créé par un commercial via "Nouveau
// client" avec adhésion non payée, la fenêtre de paiement forcée qui
// s'ouvre juste après (voir saveComNouveauClient) ne peut plus être
// simplement fermée sans conséquence — "Annuler" devient "Annuler et
// supprimer ce client" (voir openPay(cid, true)). Le client fraîchement
// créé (aucune mise, aucune adhésion encaissée) est alors supprimé : il n'y
// a rien d'autre à annuler puisqu'aucun paiement n'a encore été enregistré
// pour lui à ce stade. Ne s'applique jamais au paiement normal (payCtx sans
// _payForceNewClientId), qui garde son "Annuler" classique.
window.annulerEtSupprimerNouveauClient = _withActionLock('annulerEtSupprimerNouveauClient', async function(){
  const cid = _payForceNewClientId;
  if(!cid){ closeM('m-pay'); return; } // garde-fou : jamais appelé hors contexte forcé
  const c = getCl(cid);
  const ok = await confirmDialog(
    `Aucune mise n'a été enregistrée pour ${c?esc(c.nom):'ce client'}.<br><br>Annuler maintenant supprimera définitivement ce client (il n'a payé ni adhésion ni cotisation).`,
    {title:'🗑 Annuler et supprimer ce client', okLabel:'Supprimer le client', danger:true}
  );
  if(!ok) return; // reste dans la fenêtre de paiement forcée
  try{
    await fbDelete('clients', cid);
    notify(`Client ${c?esc(c.nom):''} supprimé — aucune mise n'avait été enregistrée`);
  }catch(e){
    console.error('Échec suppression nouveau client non payé:', e);
    notify("Échec de la suppression — vérifiez votre connexion et réessayez.", 'err');
    return; // ne pas fermer si la suppression a échoué, pour ne pas perdre la trace
  }
  _payForceNewClientId = null;
  payCtx = null;
  closeM('m-pay');
});

// ── Affiche le champ "motif de correction" dès que l'admin/chef d'agence
// choisit une date différente d'aujourd'hui. Rend la correction visible
// et justifiée plutôt que silencieuse.
window._payToggleMotifCorrection = function(){
  const dateInput = document.getElementById('pay-date');
  const motifRow = document.getElementById('pay-motif-row');
  if(!dateInput || !motifRow) return;
  motifRow.style.display = (dateInput.value && dateInput.value !== TODAY) ? '' : 'none';
};

window.savePay = _withActionLock('savePay', async function(){
  if(!['admin','commercial','chef_agence'].includes(session?.role)){ notify('Accès refusé','err'); return; }
  if(!payCtx) return;
  // ── Bloquer si contrat résilié ──
  const _clResilie = getCl(payCtx);
  if(_clResilie && _clResilie.statutContrat==='resilie'){
    notify(`🚫 Contrat de ${esc(_clResilie.nom)} résilié — aucune cotisation possible.`,'err');
    closeM('m-pay'); payCtx=null; return;
  }
  // ── Bloquer si montant contrat totalement atteint (non-admin) ──
  if(!['admin','chef_agence'].includes(session.role)){
    const _cl = getCl(payCtx);
    // ✅ FIX COMPLÉTUDE + ROBUSTESSE (étape 2 du chantier) : utilise le champ
    // dénormalisé totalPaye du client (tenu à jour par
    // _recalcClientPaiementRollup à chaque paiement) au lieu de scanner
    // DB.paiements, qui n'est plus garanti complet en mémoire pour ce rôle.
    const _totalPaye = (Number(_cl.totalPaye)||0);
    if(_cl.montantTotal>0 && _totalPaye>=_cl.montantTotal){
      notify(`🔒 Contrat de ${esc(_cl.nom)} totalement soldé (${fmt(_cl.montantTotal)}). Aucun encaissement supplémentaire autorisé.`,'err');
      return;
    }
  }
  const amt=parseFloat(document.getElementById('pay-amt').value)||0;
  if(amt<=0){notify('Montant invalide','err');return;}
  const c=getCl(payCtx),s=stats(c);
  const note=document.getElementById('pay-note').value||'';
  const autoNote=amt===s.m?note:`${Math.round(amt/s.m*10)/10}x cotisation${note?', '+note:''}`;
  const now=new Date();
  const heureSaisie = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
  // L'admin peut choisir la date, le commercial utilise la date effective (J ou J+1 si point versé)
  const isCorrecteur = ['admin','chef_agence'].includes(session.role);
  const payDate = isCorrecteur
    ? (document.getElementById('pay-date').value || TODAY)
    : getDateEffectiveCommercial(session.userId);

  // ── Correction à une date antérieure : transparente, jamais silencieuse ──
  // On exige un motif, on garde la date réelle de saisie (aujourd'hui) et on
  // marque clairement l'enregistrement comme correction : il apparaîtra
  // dans le registre/la fiche du jour concerné avec un badge visible par
  // le commercial, la date réelle de saisie et le nom de l'auteur.
  // ── VOLET 30 ── voir _dateSaisieValide.
  if(!_dateSaisieValide(payDate, 'Un paiement')) return;
  const estCorrection = isCorrecteur && payDate !== TODAY;
  let motifCorrection = '';
  if(estCorrection){
    motifCorrection = (document.getElementById('pay-motif-correction')?.value || '').trim();
    if(!motifCorrection){
      notify('Motif de la correction obligatoire — expliquez pourquoi cette saisie est datée différemment.','err');
      return;
    }
  }

  // ✅ CORRECTIF C1 : même règle d'attribution que "Saisie de mises" (voir
  // _commercialIdPourPaiement). AVANT : `isCorrecteur ? c.commercialId :
  // session.userId` — ce qui créditait la SECRÉTAIRE elle-même quand c'est
  // elle qui saisissait (elle n'est pas dans isCorrecteur), alors qu'elle
  // saisit toujours au nom d'un commercial.
  const comCredite = _commercialIdPourPaiement(c);
  const paiementData = {
    clientId:payCtx,
    commercialId:comCredite,
    cotisJour:s.m,
    montant:amt,
    date:payDate,
    note:autoNote,
    heure:heureSaisie,
    saisiParId:session.userId,
    saisiParNom:session.nom
  };
  // ✅ CORRECTIF C1 (traçabilité) — voir enregistrerMiseSaisie.
  if(c.commercialId && c.commercialId !== comCredite){
    paiementData.clientProprietaireId = c.commercialId;
  }
  if(estCorrection){
    paiementData.estCorrection = true;
    paiementData.dateSaisieReelle = TODAY;
    paiementData.motifCorrection = motifCorrection;
  }

  // ✅ Avertissement doublon : ce formulaire (encaissement rapide depuis la
  // fiche client) n'avait aucune confirmation avant envoi. On n'en ajoute
  // une que si un paiement existe déjà aujourd'hui pour ce client — pour ne
  // pas ralentir la saisie normale, mais forcer une confirmation explicite
  // dans le cas à risque (voir _avertissementDoublonPaiement plus haut).
  const avertDoublonPay = _avertissementDoublonPaiement(payCtx, payDate);
  if(avertDoublonPay){
    if(!(await confirmDialog(`Client : ${esc(c.nom)}\nMontant : ${fmt(amt)}${avertDoublonPay}`,
      {title:'🚨 Paiement déjà saisi aujourd\'hui', okLabel:'Oui, c\'est un nouveau paiement', danger:true}))) return;
  }

  try{
    // ✅ FIX DOUBLONS : désactive le bouton pendant l'envoi. Sans ça, sur une
    // connexion lente/instable (terrain, 2G), un clic sans retour visuel
    // immédiat pousse à retaper "Confirmer" avant que la 1ère requête ait
    // fini — deux paiements identiques (même montant, même minute) partent
    // alors vers Firestore comme deux écritures indépendantes et légitimes
    // (la protection anti-doublon _offlineId ne s'applique qu'au mode
    // hors-ligne, pas à deux clics en ligne). Résultat visible en fiche du
    // jour : badge "×2 mises" alors qu'il ne s'agit que d'un seul paiement
    // voulu par le commercial.
    const btnPay = document.getElementById('pay-btn-confirm');
    if(btnPay){ btnPay.disabled = true; btnPay.textContent = '⏳ Enregistrement…'; }
    const _resPaiement = await fbAdd('paiements',paiementData);
    // ✅ CORRECTIF C2 — voir enregistrerMiseSaisie.
    const _enAttenteSync = (_offlineQueue||[]).some(o => o.id === (_resPaiement && _resPaiement._id));
    window._dernierPaiementEnAttente = _enAttenteSync;
    await _recalcClientPaiementRollup(paiementData.clientId);
    closeM('m-pay');payCtx=null;
    // ✅ Une mise vient d'être enregistrée avec succès pour ce client : le
    // mode "annuler = supprimer" (première mise forcée d'un nouveau client)
    // n'a plus lieu d'être, quel que soit ce qui se passe ensuite avec cette
    // fenêtre.
    _payForceNewClientId = null;
    notify(_enAttenteSync
      ? `⏳ Paiement de ${fmt(amt)} pour ${esc(c.nom)} enregistré SUR CET APPAREIL. Pas encore transmis : envoi automatique dès le retour du réseau. Ne ressaisissez pas.`
      : (estCorrection
        ? `✅ Correction enregistrée sur le ${payDate} — visible dans le registre et la fiche du commercial`
        : `Paiement de ${fmt(amt)} enregistré pour ${esc(c.nom)} ✓`), _enAttenteSync ? 'err' : undefined);
    // ✅ FIX SYNCHRO : rafraîchir immédiatement la page courante si elle
    // affiche ce paiement (fiche/registre), sans attendre le debounce du
    // listener temps réel (qui diffère le rendu pendant l'activité de
    // l'utilisateur pour éviter le clignotement).
    if(curPg==='fiche' && typeof renderFiche==='function') renderFiche();
    else if(curPg==='registre' && typeof renderRegistre==='function') renderRegistre();
  }catch(e){
    console.error('Échec enregistrement paiement:', e);
    notify("Échec de l'enregistrement du paiement — vérifiez votre connexion et réessayez avant de fermer cette fenêtre.", 'err');
    const btnPay = document.getElementById('pay-btn-confirm');
    if(btnPay){ btnPay.disabled = false; btnPay.textContent = '✓ Confirmer'; }
    return;
  }
  // FIX : ce flux de paiement (modale "m-pay", utilisée depuis la fiche
  // client) ne générait PAS de reçu automatiquement, contrairement à la
  // "Saisie de mises" — d'où des reçus manquants dans l'historique pour
  // certains paiements. On l'aligne ici sur le même comportement partout
  // (reçu généré à chaque enregistrement, correction incluse, comme le
  // fait déjà la Saisie de mises).
  await new Promise(r=>setTimeout(r,350));
  // ✅ getCl() (pas la variable locale "c", capturée AVANT le paiement) :
  // reflète le totalPaye/joursCouv tout juste recalculé par
  // _recalcClientPaiementRollup ci-dessus.
  const sApres = stats(getCl(paiementData.clientId));
  const com = getCom(paiementData.commercialId) || {nom:''};
  afficherRecu({
    type: 'cotisation',
    // ✅ CORRECTIF C6 : clientId manquant — voir enregistrerMiseSaisie.
    clientId: paiementData.clientId,
    clientNom: c.nom,
    clientCode: c.codeClient || '',
    commercialNom: com.nom,
    commercialId: paiementData.commercialId,
    // ✅ CORRECTIF C2 : mention imprimée si la saisie n'est pas transmise.
    enAttenteSync: window._dernierPaiementEnAttente === true,
    montant: amt,
    nbCotis: s.m>0 ? Math.round(amt/s.m*10)/10 : 0,
    cotisJour: s.m,
    date: payDate,
    heure: heureSaisie,
    note: autoNote,
    saisiParNom: session.nom,
    totalPaye: sApres.totalPaye,
    totalRestant: sApres.totalRestant,
    pct: sApres.pct
  });
});

// ── ANTIDATAGE DES ENCAISSEMENTS D'ADHÉSION ─────────────────────
// La page « Saisie des adhésions » (ouvrirEncaissementAdh) permettait déjà à
// l'admin ET au chef d'agence de choisir une date antérieure. Les deux
// AUTRES points d'encaissement (bouton 🎫 de « Tous les clients », et le bloc
// adhésion de « Saisie de mises ») forçaient TODAY — y compris pour l'admin.
// D'où l'impression que « le chef d'agence ne peut pas antidater » : tout
// dépendait de l'écran utilisé.
// On injecte donc le même champ date dans ces deux formulaires, en JS
// (aucune modification d'index.html), visible uniquement pour les rôles
// autorisés.
const _ADH_ROLES_ANTIDATE = ['admin', 'chef_agence'];
function _adhPeutAntidater() {
  return !!(session && _ADH_ROLES_ANTIDATE.includes(session.role));
}

// Crée (une seule fois) une ligne « Date de l'encaissement » dans un
// conteneur donné, juste avant l'élément `avantEl`. Retourne l'input.
function _adhInjecterChampDate(conteneur, idInput, avantEl) {
  if (!conteneur) return null;
  let row = document.getElementById(idInput + '-row');
  if (!row) {
    row = document.createElement('div');
    row.id = idInput + '-row';
    row.style.cssText = 'margin-bottom:14px;';
    row.innerHTML = '<label style="display:block;font-size:9.5px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">📅 Date de l\'encaissement</label>'
      + '<input type="date" id="' + idInput + '" style="width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:8px;padding:9px 12px;color:var(--text);font-size:13px;outline:none;font-family:inherit;">'
      + '<div id="' + idInput + '-avert" style="display:none;margin-top:6px;font-size:11px;color:var(--accent);line-height:1.45;"></div>';
    if (avantEl && avantEl.parentNode === conteneur) conteneur.insertBefore(row, avantEl);
    else conteneur.appendChild(row);
    const inp = document.getElementById(idInput);
    // Avertissement immédiat dès qu'une date passée est choisie : une saisie
    // antidatée n'apparaîtra PAS dans le registre du jour, mais dans celui de
    // la date choisie. Le dire au moment du choix évite l'appel au support.
    if (inp) inp.addEventListener('change', () => _adhAvertirDate(idInput));
  }
  const inp = document.getElementById(idInput);
  if (inp) inp.value = TODAY;
  row.style.display = _adhPeutAntidater() ? '' : 'none';
  _adhAvertirDate(idInput);
  return inp;
}

function _adhAvertirDate(idInput) {
  const inp = document.getElementById(idInput);
  const av = document.getElementById(idInput + '-avert');
  if (!inp || !av) return;
  if (inp.value && inp.value !== TODAY) {
    av.style.display = 'block';
    av.textContent = '⚠️ Encaissement daté du ' + inp.value + ' : il apparaîtra dans le registre et la fiche de CE jour-là, pas dans ceux d\'aujourd\'hui.';
  } else {
    av.style.display = 'none';
  }
}

// Date retenue pour un encaissement : celle choisie si le rôle y a droit et
// qu'un champ existe, sinon toujours aujourd'hui.
function _adhDateChoisie(idInput) {
  if (!_adhPeutAntidater()) return TODAY;
  const v = document.getElementById(idInput)?.value;
  return v || TODAY;
}

window.openAdh = function(cid){
  // ── VOLET 40 ── contrat résilié : aucun encaissement (voir _refuserSiResilie)
  if(_refuserSiResilie(getCl(cid))) return;
  adhCtx=cid;const c=getCl(cid);
  document.getElementById('adhesion-info').innerHTML=`<strong>${esc(c.nom)}</strong><br>Adhésion : <strong>${fmt(c.adhesion)}</strong> — Statut : <strong style="color:${c.adhesionStatut==='paye'?'var(--accent2)':'var(--danger)'}">${c.adhesionStatut==='paye'?'Payé':'Non payé'}</strong>`;
  document.getElementById('adh-amt').value=c.adhesion;
  // Champ date injecté avant la barre de boutons du modal (voir index.html,
  // bloc #m-adhesion) — visible pour admin et chef d'agence uniquement.
  const md = document.getElementById('m-adhesion')?.querySelector('.md');
  _adhInjecterChampDate(md, 'adh-date', md ? md.querySelector('.ma') : null);
  openM('m-adhesion');
};

window.saveAdhesion = _withActionLock('saveAdhesion', async function(){
  if(!adhCtx) return;
  const amt = 200;
  const c=DB.clients.find(x=>x._id===adhCtx);
  // ── VOLET 40 ── contrat résilié : aucun encaissement (voir _refuserSiResilie)
  if(_refuserSiResilie(c)){ closeM('m-adhesion'); return; }
  const dateChoisie = _adhDateChoisie('adh-date');
  const now = new Date();
  const heure = String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');
  try{
    if(c){await fbUpdate('clients',c._id,{adhesionStatut:'paye',adhesion:amt});}
    // commercialId stocké pour filtrage correct dans le registre
    await fbAdd('adhesionPays',{
      clientId: adhCtx,
      commercialId: c ? c.commercialId : (session.userId||''),
      montant: amt,
      date: dateChoisie,
      // ✅ Ces trois champs manquaient sur CE seul point d'encaissement :
      // l'heure restait vide (« — » dans le registre et la fiche du jour) et
      // on ne savait pas qui avait saisi. Les deux autres points les
      // écrivaient déjà, les règles Firestore les acceptent donc.
      heure: dateChoisie === TODAY ? heure : '00:00',
      saisiParId: session.userId, saisiParNom: session.nom,
      note: document.getElementById('adh-note').value
        + (dateChoisie !== TODAY ? ' (date modifiée par ' + getRoleLabel(session.role) + ')' : '')
    });
    closeM('m-adhesion');adhCtx=null;notify('Adhésion enregistrée ✓' + (dateChoisie !== TODAY ? ' — datée du ' + dateChoisie : ''));
    if(curPg==='fiche' && typeof renderFiche==='function') renderFiche();
    else if(curPg==='registre' && typeof renderRegistre==='function') renderRegistre();
  }catch(e){
    console.error('Échec enregistrement adhésion:', e);
    notify("Échec de l'enregistrement de l'adhésion — vérifiez votre connexion et vérifiez le statut du client avant de réessayer.", 'err');
  }
});

window.openDet = async function(cid){
  // ── OPTION C ── ce modal liste le detail des paiements (s.pays).
  await _ensureClientPaysLoaded(cid);
  const c=getCl(cid),s=stats(c);
  document.getElementById('det-title').textContent=`👤 ${esc(c.nom)} — ${esc(c.contrat)}`;
  document.getElementById('det-kpi').style.gridTemplateColumns='repeat(auto-fill,minmax(130px,1fr))';
  document.getElementById('det-kpi').innerHTML=`
    <div class="kpi-card kc-green"><div class="kpi-lbl">Total payé</div><div class="kpi-val kv-green" style="font-size:16px">${fmt(s.totalPaye)}</div></div>
    <div class="kpi-card kc-red"><div class="kpi-lbl">Restant dû</div><div class="kpi-val kv-red" style="font-size:16px">${fmt(s.totalRestant)}</div></div>
    <div class="kpi-card kc-blue"><div class="kpi-lbl">Avancement</div><div class="kpi-val kv-blue" style="font-size:16px">${s.pct}%</div></div>
    <div class="kpi-card kc-yellow"><div class="kpi-lbl">Retard</div><div class="kpi-val kv-yellow" style="font-size:16px">${s.joursRetard}j</div></div>
    <div class="kpi-card" style="border-color:${s.soldeNet>=0?'rgba(34,212,160,0.35)':'rgba(247,97,79,0.35)'};background:${s.soldeNet>=0?'rgba(34,212,160,0.07)':'rgba(247,97,79,0.07)'}">
      <div class="kpi-lbl" style="color:${s.soldeNet>=0?'var(--accent2)':'var(--danger)'}">💳 Solde dispo.</div>
      <div class="kpi-val" style="font-size:14px;color:${s.soldeNet>=0?'var(--accent2)':'var(--danger)'};">${fmt(s.soldeNet)}</div>
      <div style="font-size:9px;color:var(--muted);margin-top:2px;">Livraisons : −${fmt(s.totalLivraisons)}</div>
    </div>`;
  const pays=[...s.pays].sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  // Calcul du niveau cumulatif par paiement (du plus ancien au plus récent)
  const paysTries2 = [...s.pays].sort((a,b)=>a.date.localeCompare(b.date));
  const cotisJ2 = s.m; const duree2 = c.duree||372;
  let cumul2 = 0;
  const niveauxMap2 = new Map();
  paysTries2.forEach(p => {
    cumul2 += p.montant;
    niveauxMap2.set(p._id||(p.date+p.montant), Math.min(duree2, cotisJ2>0?Math.floor(cumul2/cotisJ2):0));
  });
  document.getElementById('det-pays-list').innerHTML=pays.map(p=>{
    const locked = p.verrouille||p.source==='commercial';
    const key2 = p._id||(p.date+p.montant);
    const niv2 = niveauxMap2.get(key2);
    const nivLabel2 = niv2!==undefined ? joursEnJM(niv2) : '—';
    const nivColor2 = niv2!==undefined && niv2>=duree2 ? 'var(--accent2)' : 'var(--accent)';
    const btnDelPai2 = (session&&['admin','chef_agence'].includes(session.role)&&!p.verrouille)
      ? `<td style="text-align:center;"><button onclick="delPaiement('${p._id}')" title="Supprimer ce paiement" style="background:rgba(224,92,82,0.12);border:1px solid rgba(224,92,82,0.35);border-radius:6px;padding:2px 7px;color:var(--danger);font-size:11px;cursor:pointer;" onmouseover="this.style.background='rgba(224,92,82,0.28)'" onmouseout="this.style.background='rgba(224,92,82,0.12)'">🗑</button></td>`
      : (session&&['admin','chef_agence'].includes(session.role) ? `<td style="text-align:center;"><button onclick="delPaiementVerrouille('${p._id}')" title="Paiement verrouillé — cliquer pour une suppression exceptionnelle" style="background:rgba(201,168,76,0.1);border:1px solid rgba(201,168,76,0.3);border-radius:6px;padding:2px 7px;color:var(--accent);font-size:11px;cursor:pointer;">🔒</button></td>` : '<td></td>');
    return`<tr><td>${p.date}</td><td class="tm">${p.heure||'—'}</td><td><span class="cotis-badge" style="font-size:10px">💰 ${fmt(p.cotisJour||s.m)}</span></td><td style="color:var(--accent2);font-weight:700">${fmt(p.montant)}</td><td>${ratio(p.montant,p.cotisJour||s.m)}</td><td style="font-size:12px;font-weight:700;color:${nivColor2};white-space:nowrap;">${nivLabel2}<span style="font-size:9px;color:var(--muted);font-weight:400;"> /${joursEnJM(duree2)}</span></td><td class="tm" style="font-size:10px">${esc(p.note||'—')}${locked?'<span style="margin-left:4px;color:var(--accent2);" title="Saisi par commercial — verrouillé">🔒</span>':''}${badgeCorrection(p)}</td>${btnDelPai2}</tr>`;
  }).join('')||`<tr><td colspan="${session&&['admin','chef_agence'].includes(session.role)?8:7}" class="emp">Aucun paiement</td></tr>`;
  const detPaysTh = document.getElementById('det-pays-th-actions');
  if(detPaysTh) detPaysTh.style.display = (session&&['admin','chef_agence'].includes(session.role)) ? '' : 'none';
  const livs=DB.livraisons.filter(l=>l.clientId===cid).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  document.getElementById('det-liv-list').innerHTML=livs.map(l=>`<tr><td>${esc(l.date)}</td><td class="fw6">${esc(_nomProduitLivraison(l))}</td><td>${esc(String(l.qty||""))}</td><td>${fmt(l.montant)}</td><td>${livStatut(l.statut)}</td></tr>`).join('')||'<tr><td colspan="5" class="emp">Aucune livraison</td></tr>';
  const adhPays=DB.adhesionPays.filter(a=>a.clientId===cid);
  const detAdhIsAdmin = session && session.role===ROLES.ADMIN;
  document.getElementById('det-adh-content').innerHTML=`<div class="ib ${c.adhesionStatut==='paye'?'ib-green':'ib-red'}" style="margin-bottom:8px;"><strong>Adhésion : ${fmt(c.adhesion)}</strong> — ${c.adhesionStatut==='paye'?'✅ Payé':'❌ Non payé'}${c.adhesionStatut!=='paye'&&session.role===ROLES.ADMIN?`<br><button class="btn btn-success btn-xs no-print" onclick="closeM('m-detail');openAdh('${cid}')" style="margin-top:5px">Encaisser</button>`:''}</div>${adhPays.length>0?`<div class="tw" style="margin:0"><table><thead><tr><th>Date</th><th>Montant</th><th>Note</th>${detAdhIsAdmin?'<th class="no-print"></th>':''}</tr></thead><tbody>${adhPays.map(a=>`<tr><td>${esc(a.date)}</td><td style="color:var(--accent2);font-weight:600">${fmt(a.montant)}</td><td class="tm" style="font-size:10px">${esc(a.note||'—')}</td>${detAdhIsAdmin?`<td class="no-print" style="text-align:center;"><button onclick="supprimerAdhesionPay('${a._id}','${cid}')" title="Supprimer ce frais d'adhésion" style="background:rgba(224,92,82,0.12);border:1px solid rgba(224,92,82,0.35);border-radius:6px;padding:2px 7px;color:var(--danger);font-size:11px;cursor:pointer;">🗑</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="emp" style="padding:16px">Aucun paiement d\'adhésion</div>'}`;
  document.querySelectorAll('.det-tab').forEach(t=>t.classList.remove('active'));
  document.querySelector('.det-tab').classList.add('active');
  ['paiements','livraisons','adhesion'].forEach(t=>document.getElementById('det-'+t).style.display=t==='paiements'?'':'none');
  document.getElementById('det-pay-btn').style.display = (session.role===ROLES.ADMIN||session.role===ROLES.COMMERCIAL||session.role===ROLES.CHEF_AGENCE) ? '' : 'none';
  document.getElementById('det-pay-btn').onclick=()=>{closeM('m-detail');openPay(cid);};
  openM('m-detail');
};

// ========= PRODUITS DU CONTRAT (PAR CODE) =========
// Stockage interne des produits ajoutés par prefix
const _articlesAdded = { 'cl': [], 'com-ncl': [] };

// Appelé au reset du formulaire
function resetArticlesAdded(prefix){
  _articlesAdded[prefix] = [];
  const listEl = document.getElementById(prefix+'-articles-list');
  if(listEl){ listEl.innerHTML=''; listEl.style.display='none'; }
  const recap = document.getElementById(prefix+'-articles-recap');
  if(recap) recap.style.display='none';
  const codeEl = document.getElementById(prefix+'-art-code');
  if(codeEl) codeEl.value='';
  const msgEl = document.getElementById(prefix+'-art-code-msg');
  if(msgEl) msgEl.style.display='none';
}

window.ajouterArticleParCode = function(prefix){
  const codeEl = document.getElementById(prefix+'-art-code');
  const msgEl  = document.getElementById(prefix+'-art-code-msg');
  if(!codeEl||!msgEl) return;
  const code = codeEl.value.trim().toUpperCase();
  if(!code){ showMsg(msgEl,'Veuillez saisir un code produit.','err'); return; }

  // Recherche par ref (insensible à la casse) ou par nom exact
  const prod = (DB.produits||[]).find(p=>
    (p.ref||'').toUpperCase()===code ||
    (p.nom||'').toUpperCase()===code
  );
  if(!prod){ showMsg(msgEl,`Aucun produit trouvé pour le code « ${code} ».`,'err'); return; }

  // ── VOLET 23 ── souscription refusee si le produit n'est plus vendable.
  if(_prodIndispo(prod)){ showMsg(msgEl, _msgProdIndispo(prod), 'err'); return; }

  // ── VOLET 55 ── QUANTITÉ PAR PRODUIT. Avant : un même produit était refusé
  // (« déjà dans le contrat »). Maintenant : re-saisir son code ajoute 1 à sa
  // quantité ; la quantité se règle aussi avec − / + sur la ligne.
  const _existant = _articlesAdded[prefix].find(x=>x._id===prod._id);
  if(_existant){
    if((_existant._qte||1) >= _QTE_PROD_MAX){ showMsg(msgEl,`Quantité maximale (${_QTE_PROD_MAX}) atteinte pour « ${esc(prod.nom)} ».`,'warn'); return; }
    _existant._qte = (_existant._qte||1) + 1;
    codeEl.value='';
    showMsg(msgEl,`✓ « ${esc(prod.nom)} » : quantité portée à ${_existant._qte}.`,'ok');
    renderArticlesList(prefix);
    return;
  }

  // Copie : on ne modifie jamais l'objet de DB.produits (champ _qte).
  _articlesAdded[prefix].push({...prod, _qte: 1});
  codeEl.value='';
  showMsg(msgEl,`✓ « ${esc(prod.nom)} » ajouté.`,'ok');
  renderArticlesList(prefix);
};

// ── VOLET 55 ── quantité d'un produit du contrat
const _QTE_PROD_MAX = 99;
function _qteProd(p){ const q = parseInt(p && p._qte, 10); return Number.isFinite(q) && q >= 1 ? Math.min(q, _QTE_PROD_MAX) : 1; }
window.changerQteArticle = function(prefix, idx, delta){
  const p = _articlesAdded[prefix][idx]; if(!p) return;
  p._qte = Math.max(1, Math.min(_QTE_PROD_MAX, _qteProd(p) + delta));
  renderArticlesList(prefix);
};
window.saisirQteArticle = function(prefix, idx, val){
  const p = _articlesAdded[prefix][idx]; if(!p) return;
  const q = parseInt(val, 10);
  p._qte = Number.isFinite(q) ? Math.max(1, Math.min(_QTE_PROD_MAX, q)) : 1;
  renderArticlesList(prefix);
};

function showMsg(el, txt, type){
  el.style.display='block';
  const colors={ok:'rgba(34,212,160,0.15)',err:'rgba(224,92,82,0.14)',warn:'rgba(247,201,79,0.15)'};
  const tcol={ok:'var(--accent2)',err:'var(--danger)',warn:'var(--accent3)'};
  el.style.background=colors[type]||colors.ok;
  el.style.color=tcol[type]||tcol.ok;
  el.style.border='1px solid '+(tcol[type]||tcol.ok);
  el.style.borderRadius='5px';
  el.style.padding='4px 8px';
  el.textContent=txt;
}

function renderArticlesList(prefix){
  const list = _articlesAdded[prefix];
  const listEl = document.getElementById(prefix+'-articles-list');
  const recap  = document.getElementById(prefix+'-articles-recap');
  const montantEl = document.getElementById(prefix==='cl'?'cl-montant':'com-ncl-montant');
  const contratEl = document.getElementById(prefix==='cl'?'cl-contrat':'com-ncl-contrat');

  if(!list.length){
    if(listEl){ listEl.innerHTML=''; listEl.style.display='none'; }
    if(recap) recap.style.display='none';
    if(montantEl) montantEl.value='';
    if(contratEl) contratEl.value='';
    if(prefix==='cl') calcJour(); else calcJourComNcl();
    return;
  }

  // Affichage des lignes produit
  if(listEl){
    listEl.style.display='flex';
    // ── VOLET 55 ── − / quantité / + sur chaque ligne ; prix unitaire × qté.
    const _btnQ = 'background:var(--surface);border:1px solid var(--border);border-radius:5px;color:var(--text);width:26px;height:26px;cursor:pointer;font-size:14px;font-weight:700;line-height:1;';
    listEl.innerHTML = list.map((p,i)=>`
      <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px;background:var(--surface2);border:1px solid var(--border);border-radius:7px;padding:6px 10px;font-size:12px;">
        <div>
          <span style="color:var(--accent);font-weight:700;font-size:10px;margin-right:6px;">${esc(p.ref)||'—'}</span>
          <span style="font-weight:600;">${esc(p.nom)}</span>
          ${_qteProd(p)>1?`<div style="font-size:10px;color:var(--muted);">${fmt(p.prix)} × ${_qteProd(p)}</div>`:''}
        </div>
        <div style="display:flex;align-items:center;gap:8px;">
          <div style="display:flex;align-items:center;gap:3px;" title="Quantité">
            <button type="button" style="${_btnQ}" onclick="changerQteArticle('${prefix}',${i},-1)">−</button>
            <input type="number" min="1" max="${_QTE_PROD_MAX}" value="${_qteProd(p)}" onchange="saisirQteArticle('${prefix}',${i},this.value)"
              style="width:44px;text-align:center;padding:3px;border:1px solid var(--border);border-radius:5px;background:var(--surface);color:var(--text);font-weight:700;">
            <button type="button" style="${_btnQ}" onclick="changerQteArticle('${prefix}',${i},1)">+</button>
          </div>
          <span style="color:var(--accent2);font-weight:700;">${fmt((parseFloat(p.prix)||0)*_qteProd(p))}</span>
          <button onclick="supprimerArticle('${prefix}',${i})"
            style="background:rgba(224,92,82,0.14);border:1px solid rgba(247,97,79,0.4);border-radius:5px;color:var(--danger);padding:2px 7px;cursor:pointer;font-size:11px;">✕</button>
        </div>
      </div>`).join('');
  }

  // Calcul total + désignation auto
  const total = list.reduce((s,p)=>s+(parseFloat(p.prix)||0)*_qteProd(p),0);
  // Désignation : « Matelas ×2 + Ventilateur » (×1 non affiché : identique à avant)
  const noms  = list.map(p=>_qteProd(p)>1 ? `${p.nom} ×${_qteProd(p)}` : p.nom);
  const _nbUnites = list.reduce((s,p)=>s+_qteProd(p),0);
  if(montantEl) montantEl.value = total;
  if(contratEl) contratEl.value = noms.join(' + ');

  if(recap){
    recap.style.display='block';
    recap.innerHTML=`📦 ${list.length} produit(s)${_nbUnites>list.length?` · ${_nbUnites} unités`:''} : <strong>${noms.join(', ')}</strong> &mdash; Montant total : <strong style="color:var(--accent2)">${fmt(total)}</strong>`;
  }
  if(prefix==='cl') calcJour(); else calcJourComNcl();
}

window.supprimerArticle = function(prefix, idx){
  _articlesAdded[prefix].splice(idx,1);
  renderArticlesList(prefix);
};


// Compat: ces fonctions ne font plus rien (les selects checkbox n'existent plus)
function chargerArticlesSelect(containerId, prefix){ /* obsolète */ }
function majMontantArticles(prefix){ /* obsolète */ }

// ========= FORMS =========
window.calcJour = function(){
  const p=parseFloat(document.getElementById('cl-montant').value)||0;
  appliquerDureeAutomatiquePalier('cl', p);
  const d=parseInt(document.getElementById('cl-duree').value)||365;
  const el=document.getElementById('cl-calc-info');
  if(p>0){el.style.display='block';const jmv=Math.ceil(p/d);const debut=document.getElementById('cl-debut').value||TODAY;const fin=new Date(debut+'T12:00:00');fin.setDate(fin.getDate()+d);el.innerHTML=`💰 Cotisation : <strong style="font-size:14px">${fmt(jmv)}/jour</strong> sur ${d} jours → Fin : <strong>${fin.toLocaleDateString('fr-FR')}</strong>`;}
  else el.style.display='none';
};

window.saveCl = _withActionLock('saveCl', async function(){
  const nom=document.getElementById('cl-nom').value.trim();
  const tel=document.getElementById('cl-tel').value.trim();
  const ct=document.getElementById('cl-contrat').value.trim();
  const mt=parseFloat(document.getElementById('cl-montant').value)||0;
  const debut=document.getElementById('cl-debut').value;
  if(!nom||!tel||!ct||mt<=0||!debut){notify('Champs obligatoires manquants','err');return;}
  // ✅ FIX DOUBLONS : verrou de ré-entrance, même principe que
  // enregistrerMiseSaisie(). Sans ça, un clic répété (connexion lente, pas
  // de retour visuel immédiat) relance tout le flux — génération de code
  // client incluse — et crée deux clients distincts pour une seule
  // intention de saisie.
  if(window._saveClEnCours){ return; }
  window._saveClEnCours = true;
  const btnCl = document.getElementById('cl-btn-confirm');
  if(btnCl){ btnCl.disabled = true; btnCl.style.opacity = '0.5'; btnCl.style.cursor = 'not-allowed'; btnCl.textContent = '⏳ Enregistrement…'; }
  const comId=document.getElementById('cl-com').value||session.userId;
  // Adhésion fixe 200 FCFA — lire statut depuis les boutons radio
  const adhRadio = document.querySelector('input[name="cl-adh-statut-r"]:checked');
  const adhesionStatut = adhRadio ? adhRadio.value : 'non_paye';
  try{
    const codeClient = await genererCodeClient(comId);
    // Figer les prix des produits au moment de la création du contrat
    const produitsPrixFiges = _articlesAdded['cl'].map(p=>({produitId:p._id, pvFige:p.prix, nom:p.nom, qte:_qteProd(p)}));   // ── VOLET 55 ── + qte
    const newClRef = await fbAdd('clients',{nom,tel,ville:document.getElementById('cl-ville').value,quartier:document.getElementById('cl-qrt').value,contrat:ct,montantTotal:mt,duree:parseInt(document.getElementById('cl-duree').value)||365,debut,note:document.getElementById('cl-note').value,commercialId:comId,adhesion:200,adhesionStatut,codeClient,produitsPrixFiges});
    // ── VOLET 18 ── un nouveau client = un carnet remis. Le debit est
    // impute au commercial DU CLIENT (comId), pas a celui qui saisit : c'est
    // lui qui detient le carnet physique. Non bloquant par construction :
    // _carnetDebiter n'echoue jamais (voir sa definition).
    await _carnetDebiter(comId, 'Nouveau client', newClRef?._id || null, nom);
    // Si adhésion payée à la création → enregistrer dans adhesionPays pour le registre
    if(adhesionStatut === 'paye' && newClRef && newClRef._id){
      const now = new Date();
      const heure = String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0');
      try{
        await fbAdd('adhesionPays',{
          clientId: newClRef._id, commercialId: comId,
          montant: 200, date: TODAY, heure,
          note: "Adhésion encaissée à l'inscription",
          saisiParId: session.userId, saisiParNom: session.nom,
          verrouille: true
        });
      }catch(e){
        console.error('Échec enregistrement adhésion à la création:', e);
        notify(`Client ${nom} créé ✓ — Code : ${codeClient}, mais l'adhésion n'a pas pu être enregistrée (vérifiez la connexion et ressaisissez-la depuis le registre)`, 'err');
        closeM('m-client');
        return;
      }
    }
    closeM('m-client');notify(`Client ${nom} créé ✓ — Code : ${codeClient}`);
    // ── Nouveau client + adhésion non payée à la création → on redirige
    // immédiatement vers la saisie de la première cotisation (mise),
    // obligatoire avant de pouvoir faire autre chose avec ce client.
    if(adhesionStatut!=='paye' && newClRef && newClRef._id){
      setTimeout(()=>openPay(newClRef._id), 250);
    }
  }catch(e){
    console.error('Échec création client:', e);
    notify("Échec de la création du client — vérifiez votre connexion et réessayez. Si le problème persiste, contactez l'administrateur.", 'err');
  } finally {
    window._saveClEnCours = false;
    if(btnCl){ btnCl.disabled = false; btnCl.style.opacity = ''; btnCl.style.cursor = ''; btnCl.textContent = 'Enregistrer'; }
  }
});

window.saveArticle = _withActionLock('saveArticle', async function(){
  if(!['admin'].includes(session?.role)){ notify('Accès refusé','err'); return; }
  const nom=document.getElementById('art-nom').value.trim();
  const pv=parseFloat(document.getElementById('art-prix-vente').value)||0;
  if(!nom||pv<=0){notify('Désignation et prix obligatoires','err');return;}
  const editId = document.getElementById('art-edit-id').value;
  const type = document.getElementById('art-type').value||'article';
  const isPack = type==='pack';
  if(isPack && !_packComposition.length){ notify('Ajoutez au moins un composant au pack','err'); return; }
  const stock = isPack ? 0 : (parseInt(document.getElementById('art-stock').value)||0);
  const data={
    ref:document.getElementById('art-ref').value||`ART-${Date.now()}`,
    nom, cat:document.getElementById('art-cat').value,
    pv, pa:parseFloat(document.getElementById('art-prix-achat').value)||0,
    stock, stockMin: isPack ? 0 : (parseInt(document.getElementById('art-stock-min').value)||5),
    unite:document.getElementById('art-unite').value||'pièce',
    desc:document.getElementById('art-desc').value.trim(),
    type,
    composition: isPack ? _packComposition.map(c=>({articleId:c.articleId,nom:c.nom,ref:c.ref,qte:c.qte})) : []
  };
  // Images
  if(artEditImages.length){
    data.images = artEditImages;
    data.image  = artEditImages[0];
  }
  if(editId){
    const artActuel = DB.articles.find(a=>a._id===editId);
    const ancienPv = artActuel ? artActuel.pv : null;
    await fbUpdate('articles', editId, data);
    closeM('m-article');
    if(ancienPv !== null && ancienPv !== data.pv){
      // Compatibilité : anciens contrats créés avant le passage aux produits pouvaient figer un prix d'article
      const clientsProtéges = DB.clients.filter(c=>(c.articlesPrixFiges||[]).some(x=>x.articleId===editId));
      if(clientsProtéges.length>0){
        notify(`Article modifié ✓ — Prix ${fmt(ancienPv)} → ${fmt(data.pv)} · ${clientsProtéges.length} ancien(s) contrat(s) conservent leur prix 🔒`);
      } else { notify(`Article modifié ✓`); }
    } else { notify('Article modifié ✓'); }
  } else {
    if(!artEditImages.length) data.images=[]; data.image='';
    const art=await fbAdd('articles',data);
    if(stock>0) await fbAdd('stockMvts',{articleId:art._id,type:'entree',qty:stock,stockApres:stock,date:TODAY,note:'Stock initial'});
    closeM('m-article');notify('Article créé ✓');
  }
});

window.saveMvt = _withActionLock('saveMvt', async function(){
  if(session?.role===ROLES.CONTROLEUR){ notify('Accès refusé — lecture seule','err'); return; }
  const artId=document.getElementById('mvt-art').value;
  const type=document.getElementById('mvt-type').value;
  const qty=parseInt(document.getElementById('mvt-qty').value)||0;
  if(!artId||qty<=0){notify('Article et quantité obligatoires','err');return;}
  const art=DB.articles.find(a=>a._id===artId);
  if(!art){notify('Article introuvable','err');return;}
  if(type==='sortie'&&qty>art.stock){notify(`Stock insuffisant (${art.stock})','err`);return;}
  // Destination pour les sorties
  let destinationId='', destinationNom='', destinationLibre='';
  if(type==='sortie'){
    const selDest = document.getElementById('mvt-dest-agence');
    const libDest = document.getElementById('mvt-dest-libre');
    const destVal = selDest?.value||'';
    if(destVal==='__autre__'){
      destinationLibre = (libDest?.value||'').trim();
      if(!destinationLibre){ notify('Précisez le motif de sortie','err'); return; }
    } else if(destVal){
      destinationId = destVal;
      const ag = DB.agences.find(a=>a._id===destVal);
      destinationNom = ag ? ag.nom : destVal;
    } else {
      notify('Précisez la destination de la sortie','err'); return;
    }
  }
  const newStock=art.stock+(type==='entree'?qty:-qty);
  await fbUpdate('articles',artId,{stock:newStock});
  const mvtData={articleId:artId,type,qty,stockApres:newStock,
    date:document.getElementById('mvt-date').value||TODAY,
    note:document.getElementById('mvt-note').value};
  if(type==='sortie'){
    if(destinationId) mvtData.destinationId=destinationId;
    if(destinationNom) mvtData.destinationNom=destinationNom;
    if(destinationLibre) mvtData.destinationLibre=destinationLibre;
  }
  // ✅ Sortie vers une agence précise (destinationId renseigné) : en plus de
  // déduire le stock global (ci-dessus), on crédite le solde de stock propre
  // à cette agence — c'est CE solde qui sera ensuite débité par les
  // livraisons clients de cette agence (voir deduireStockLivraison), et non
  // plus le stock global directement.
  if(type==='sortie' && destinationId){
    const nouveauSoldeAgence = await ajusterStockAgence(destinationId, artId, qty);
    mvtData.stockAgenceApres = nouveauSoldeAgence;
  }
  await fbAdd('stockMvts',mvtData);
  closeM('m-stock-mvt');notify('Mouvement enregistré ✓');
});

window.openMvtFor = function(artId){
  openM('m-stock-mvt');
  setTimeout(()=>{
    const art = DB.articles.find(a=>a._id===artId);
    if(art) mvtSelectArt(art);
  }, 150);
};

window.saveLivraison = _withActionLock('saveLivraison', async function(){
  if(!['admin','secretaire','commercial','chef_agence'].includes(session?.role)){ notify('Accès refusé','err'); return; }
  const cId=document.getElementById('liv-client').value;
  const pId=document.getElementById('liv-article').value;
  const qty=parseInt(document.getElementById('liv-qty').value)||1;
  const date=document.getElementById('liv-date').value;
  if(!cId||!pId||!date){notify('Client, produit et date obligatoires','err');return;}
  const statut=document.getElementById('liv-statut').value;
  const prod=getProd(pId);
  const montantLivraison = parseFloat(document.getElementById('liv-montant').value)||0;

  const client = DB.clients.find(c=>c._id===cId);

  // ── BLOCAGE ADHÉSION NON PAYÉE ──
  // Un client dont l'adhésion n'est pas encore réglée ne peut recevoir aucune
  // livraison, quel que soit son solde disponible — l'adhésion est un
  // prérequis, pas juste un élément de solde.
  // ✅ FIX FRAÎCHEUR (secrétaire voit "non payée" alors que CA/admin voient
  // "payée") : DB.clients est une copie locale tenue à jour par le listener
  // temps réel + le cache persistant (IndexedDB). Sur le poste de la personne
  // qui vient d'encaisser, la copie locale est mise à jour immédiatement
  // (voir fbUpdate) ; sur un AUTRE poste, elle ne se corrige que quand le
  // listener reçoit l'événement — ce qui peut prendre du retard (onglet resté
  // ouvert longtemps, micro-coupure réseau, etc.). On revérifie donc le
  // statut directement sur Firestore juste avant de bloquer, pour ne jamais
  // bloquer une livraison sur la base d'une donnée locale obsolète. Le reste
  // de la fonction continue d'utiliser la copie locale `client` (solde, prix
  // figés, commercialId...), qu'on resynchronise ici pour rester cohérent.
  let adhesionStatutVerifie = client ? (client.adhesionStatut||'non_paye') : 'non_paye';
  if (client && db_fs && isOnline) {
    try {
      const freshSnap = await getDoc(doc(db_fs, 'clients', cId));
      if (freshSnap.exists()) {
        const freshData = freshSnap.data();
        adhesionStatutVerifie = freshData.adhesionStatut || 'non_paye';
        // Resynchronise la copie locale tout de suite (au lieu d'attendre le
        // prochain événement du listener) pour que l'affichage se corrige.
        client.adhesionStatut = freshData.adhesionStatut;
        client.adhesion = freshData.adhesion;
      }
    } catch(e) {
      // Lecture fraîche impossible (réseau, permissions) : on retombe sur la
      // copie locale déjà connue plutôt que de bloquer l'utilisateur à tort.
      console.warn('[saveLivraison] Vérification adhésion à jour impossible, repli sur cache local :', e);
    }
  }
  // ✅ RECONDITIONNÉ (sur demande) : une adhésion non payée ne bloque plus
  // systématiquement la livraison. On compare le solde disponible du client
  // aux frais d'adhésion (200, même montant fixe que saveAdhesion()/
  // encaisserAdhesion()) : si le solde les couvre, la livraison est
  // autorisée (l'adhésion reste "non payée" — elle n'est PAS encaissée
  // automatiquement ici, il faudra toujours l'encaisser explicitement) ;
  // sinon, blocage avec demande de régler l'adhésion. Le blocage "solde
  // insuffisant pour le produit" ci-dessous reste inchangé et s'applique en
  // plus (le solde doit donc couvrir les deux, séparément).
  const ADHESION_MONTANT_LIVRAISON = 200;
  // ✅ AUDIT SYNCHRO (point #1) : un seul solde "frais" calculé ici (relu sur
  // Firestore quand c'est possible, sinon replié sur le cache local), et
  // réutilisé pour les deux blocages ci-dessous — évite à la fois de payer
  // deux fois la vérification et toute incohérence entre les deux blocages.
  let solde = client ? soldeClient(client) : 0; // valeur locale par défaut
  if (client) {
    const soldeFrais = await _soldeClientFrais(cId);
    if (soldeFrais !== null) solde = soldeFrais;
  }
  // ── CORRECTIF REGLE METIER ────────────────────────────────────────────
  // AVANT : deux controles INDEPENDANTS, tous deux sur le solde AVANT la
  // livraison — `solde <= 200` d'un cote, `solde < coutProduit` de l'autre.
  // Un client avec 1000 de solde et un produit a 900 passait les deux
  // (1000 > 200 ET 1000 >= 900), alors qu'il ne lui restait que 100 apres la
  // livraison : les 200 de frais d'adhesion n'etaient plus couverts. La
  // garantie voulue n'etait donc jamais verifiee.
  // MAINTENANT : le cout du produit est calcule d'abord, puis le solde
  // RESTANT (solde - cout) doit couvrir les frais d'adhesion.
  // Egalite acceptee : un solde restant de exactement 200 passe.
  const _coutProduitLiv = (() => {
    if (!client || !prod) return 0;
    // Prix figé au contrat du client (protège contre les changements de prix produit)
    const prixFige = (client.produitsPrixFiges||[]).find(x=>x.produitId===pId);
    const pvUtilise = prixFige ? prixFige.pvFige : prod.prix;
    return pvUtilise * qty;
  })();

  // ── BLOCAGE 1 : solde insuffisant pour le produit lui-meme ──
  if(client && prod && solde < _coutProduitLiv){
    notify(`⛔ Livraison bloquée — Solde client insuffisant : ${fmt(solde)} disponible, ${fmt(_coutProduitLiv)} requis.`, 'err');
    return;
  }

  // ── BLOCAGE 2 : adhesion non payee — le solde RESTANT doit la couvrir ──
  if(client && adhesionStatutVerifie !== 'paye'){
    const soldeApres = solde - _coutProduitLiv;
    if(soldeApres < ADHESION_MONTANT_LIVRAISON){
      notify(`⛔ Livraison bloquée — Adhésion non payée : il ne resterait que ${fmt(soldeApres)} après cette livraison, alors que ${fmt(ADHESION_MONTANT_LIVRAISON)} de frais d'adhésion doivent rester couverts. Encaissez d'abord l'adhésion.`, 'err');
      return;
    }
    // Solde restant suffisant : on laisse passer, l'adhésion reste "non payée".
  }

  // Sauvegarder le prix figé dans la livraison pour l'historique
  const _prixFigeLiv = (() => {
    if(!client) return prod ? prod.prix : 0;
    const pf = (client.produitsPrixFiges||[]).find(x=>x.produitId===pId);
    return pf ? pf.pvFige : (prod ? prod.prix : 0);
  })();
  const montantFinal = montantLivraison || (_prixFigeLiv * qty);

  let _livStockEtat = {};   // ── VOLET 54 ── trace du déstockage
  try{
    if(statut==='livre'&&prod){
      // Agence du client livré : champ dénormalisé si présent (voir
      // _withAgenceId), sinon retrouvé via son commercial — c'est le solde
      // de CETTE agence qui sera déduit (voir deduireStockLivraison).
      const agenceIdLivraison = _agenceLivraison(client, null);   // ── VOLET 54 ──
      const warnings = await deduireStockLivraison(prod, qty, getCl(cId)?.nom||'', agenceIdLivraison);
      _livStockEtat = { stockDeduit: warnings.complet !== false, stockNonDeduit: warnings.nonDeduits || [] };
      if(warnings.length) notify(`⚠️ Stock : ${warnings.join(', ')}`,'warn');
    }
    // ── commercialId = commercial RÉEL du client (garantit que la livraison
    // reste toujours rattachée à la bonne agence, même quand c'est un
    // admin/secrétaire/chef d'agence qui saisit l'opération). Qui a
    // effectivement saisi la livraison reste tracé via saisiParId/saisiParNom.
    const commercialReel = client ? (client.commercialId || session.userId) : session.userId;
    // ── VOLET 17 ── copie du produit tel qu'il est A CET INSTANT. `.map` avec
    // copie de chaque ligne : sans cela on stockerait une reference vers
    // l'objet de DB.produits, et un rendu ulterieur pourrait le modifier.
    const _compFigee = ((prod && prod.composition) || []).map(c => ({
      articleId: c.articleId, nom: c.nom || '', qte: Number(c.qte) || 0, unite: c.unite || ''
    }));
    const _livCree = await fbAdd('livraisons',{clientId:cId,commercialId:commercialReel,produitId:pId,qty,montant:montantFinal,pvFige:_prixFigeLiv,date,statut,note:document.getElementById('liv-note').value,saisiParId:session.userId,saisiParNom:session.nom,
      compositionFigee: _compFigee,
      produitNom: (prod && prod.nom) || '',
      produitRef: (prod && prod.ref) || '',
      figeLe: TODAY, ..._livStockEtat});
    closeM('m-livraison');notify('Livraison enregistrée ✓');
    await _dlcApresLivraison(cId, _livCree && _livCree._id);   // ── VOLET 43 ──
  }catch(e){
    console.error('Échec enregistrement livraison:', e);
    notify("Échec de l'enregistrement de la livraison — vérifiez votre connexion et vérifiez le stock avant de réessayer.", 'err');
  }
});

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 43 — DEMANDES DE LIVRAISON CLIENT (AGENT → AGENCE)     ║
// ╚══════════════════════════════════════════════════════════════╝
// Collection 'demandesLivraisonClient' — DISTINCTE de 'demandesLivraison'
// (réapprovisionnement d'agence par le chef d'agence auprès du stock) :
// ici l'agent demande qu'UN client précis soit livré d'UN produit.
//   Création      : l'agent (pour ses propres clients), statut 'en_attente'.
//   Traitement    : chef d'agence / secrétaire de l'agence, ou admin —
//                   « Créer la livraison » (formulaire habituel prérempli,
//                   tous les contrôles de solde/adhésion s'appliquent) ou
//                   « Refuser » avec motif.
//   Annulation    : l'agent peut annuler sa demande tant qu'elle attend.
// Page agent 'com-livraisons' : clients « presque à la fin » (≥ seuil, 70 %
// par défaut, réglable 50/70/80/90), formulaire, suivi de ses demandes.
// Lecture des soldes : statsLite() (champs dénormalisés) — aucune lecture
// de 'paiements'.

const _DLC_STATUTS = {
  en_attente: { lib: 'En attente', cls: 'sb sy' },
  traitee:    { lib: 'Livraison créée', cls: 'sb sg' },
  refusee:    { lib: 'Refusée', cls: 'sb sr' },
  annulee:    { lib: 'Annulée', cls: 'sb' }
};
let _dlcClientId = null;        // client choisi dans le formulaire agent
let _dlcEnTraitement = null;    // demande en cours de traitement (formulaire livraison)

function _dlcProduitDuClient(c){
  const ref = String((c && c.contrat) || '').toLowerCase().trim();
  if(!ref) return null;
  return (DB.produits||[]).find(p => (p.ref||'').toLowerCase() === ref) || null;
}
function _dlcBadge(st){
  const s = _DLC_STATUTS[st] || { lib: st || '—', cls: 'sb' };
  return `<span class="${s.cls}" style="font-size:10px;">${esc(s.lib)}</span>`;
}
function _dlcEnAttentePour(clientId){
  return (DB.demandesLivraisonClient||[]).find(d => d.clientId === clientId && d.statut === 'en_attente') || null;
}

// ── PAGE AGENT ──────────────────────────────────────────────────
function renderComLivraisons(){
  if(!session || session.role !== ROLES.COMMERCIAL){ go(getRoleHome(session?.role)); return; }
  _dlcRenderProches();
  _dlcRenderForm();
  _dlcRenderMesDemandes();
}

function _dlcRenderProches(){
  const body = document.getElementById('dlc-proches-body');
  if(!body) return;
  const seuil = parseInt(document.getElementById('dlc-seuil')?.value || '70', 10);
  const q = (document.getElementById('dlc-proches-search')?.value || '').toLowerCase().trim();
  // ── VOLET 44 ── filtres : produit du contrat, masquer les déjà demandés.
  const prodF = document.getElementById('dlc-proches-produit')?.value || '';
  const masquerDem = !!document.getElementById('dlc-proches-sans-demande')?.checked;
  const mesClients = (DB.clients||[]).filter(c => c.commercialId === session.userId && !_estResilie(c));
  const selP = document.getElementById('dlc-proches-produit');
  if(selP){
    const refs = [...new Set(mesClients.map(c => String(c.contrat||'').trim()).filter(Boolean))].sort();
    const sig = refs.join('|');
    if(selP.dataset.sig !== sig){
      selP.innerHTML = '<option value="">Tous les produits</option>' + refs.map(r => {
        const p = (DB.produits||[]).find(x => (x.ref||'').toLowerCase() === r.toLowerCase());
        return `<option value="${esc(r.toLowerCase())}">${esc(p ? (p.ref + ' — ' + p.nom) : r)}</option>`;
      }).join('');
      selP.dataset.sig = sig;
      selP.value = refs.some(r => r.toLowerCase() === prodF) ? prodF : '';
    }
  }
  const prodActif = selP ? selP.value : prodF;
  const rows = mesClients
    .filter(c => !prodActif || String(c.contrat||'').trim().toLowerCase() === prodActif)
    .filter(c => !masquerDem || !_dlcEnAttentePour(c._id))
    .map(c => ({ c, s: statsLite(c) }))
    .filter(r => r.s.pct >= seuil)
    .filter(r => !q || (r.c.nom||'').toLowerCase().includes(q) || (r.c.codeClient||'').toLowerCase().includes(q) || (r.c.tel||'').includes(q))
    .sort((a,b) => b.s.pct - a.s.pct || (a.c.nom||'').localeCompare(b.c.nom||''));
  const cnt = document.getElementById('dlc-proches-count');
  if(cnt) cnt.textContent = `${rows.length} client(s) à ${seuil} % ou plus`;
  if(!rows.length){
    body.innerHTML = `<tr><td colspan="5" class="emp">Aucun client à ${seuil} % ou plus.</td></tr>`;
    return;
  }
  body.innerHTML = rows.map(({c,s}) => {
    const att = _dlcEnAttentePour(c._id);
    const couleur = s.pct >= 100 ? 'var(--accent2)' : 'var(--accent)';
    return `<tr>
      <td><strong>${esc(c.nom||'—')}</strong>${c.codeClient?`<div style="font-size:10px;color:var(--accent);">${esc(c.codeClient)}</div>`:''}</td>
      <td style="font-size:11px;">${esc(c.tel||'—')}</td>
      <td><span style="font-weight:700;color:${couleur};">${s.pct >= 100 ? '🏆 Soldé' : s.pct + ' %'}</span></td>
      <td style="font-size:11px;">${fmt(s.totalRestant)}</td>
      <td>${att ? _dlcBadge('en_attente') : `<button class="btn btn-ghost btn-xs" onclick="dlcChoisirClient('${c._id}', true)">📦 Demander</button>`}</td>
    </tr>`;
  }).join('');
}
window._dlcRenderProches = _dlcRenderProches;

window.dlcRecherche = function(){
  const q = (document.getElementById('dlc-search')?.value || '').toLowerCase().trim();
  const box = document.getElementById('dlc-search-results');
  if(!box) return;
  if(q.length < 2){ box.style.display = 'none'; return; }
  const found = (DB.clients||[])
    .filter(c => c.commercialId === session.userId)
    .filter(c => (c.codeClient||'').toLowerCase().includes(q) || (c.nom||'').toLowerCase().includes(q) || (c.tel||'').includes(q))
    .slice(0, 8);
  box.style.display = 'block';
  if(!found.length){ box.innerHTML = '<div style="padding:8px;font-size:12px;color:var(--muted);">Aucun client trouvé parmi vos clients.</div>'; return; }
  box.innerHTML = found.map(c => {
    const s = statsLite(c);
    return `<div onclick="dlcChoisirClient('${c._id}')" style="padding:8px 10px;cursor:pointer;border-radius:7px;border:1px solid var(--border);margin-bottom:4px;background:var(--surface2);">
      <strong style="font-size:12px;">${esc(c.nom||'—')}</strong>
      ${c.codeClient?`<span class="tag" style="margin-left:6px;">${esc(c.codeClient)}</span>`:''}
      ${_estResilie(c)?'<span class="resilie-badge" style="font-size:9px;margin-left:6px;">RÉSILIÉ</span>':`<span style="font-size:11px;color:var(--accent2);margin-left:6px;">${s.pct} % payé</span>`}
    </div>`;
  }).join('');
};

window.dlcChoisirClient = function(id, defiler){
  const c = (DB.clients||[]).find(x => x._id === id);
  if(!c) return;
  if(_estResilie(c)){ notify(`🚫 Contrat de ${esc(c.nom)} résilié — aucune livraison possible.`,'err'); return; }
  _dlcClientId = id;
  const box = document.getElementById('dlc-search-results'); if(box) box.style.display = 'none';
  const inp = document.getElementById('dlc-search'); if(inp) inp.value = c.codeClient || c.nom || '';
  const p = _dlcProduitDuClient(c);
  ['dlc-prod-code','dlc-prod-cat'].forEach(k => { const el = document.getElementById(k); if(el) el.value = ''; });
  _dlcRenderProduitsSelect();
  const sel = document.getElementById('dlc-produit');
  if(sel) sel.value = p ? p._id : '';
  _dlcRenderForm();
  if(defiler) document.getElementById('dlc-form-card')?.scrollIntoView({behavior:'smooth', block:'start'});
};

// ── VOLET 44 ── choix du produit : code produit (saisie directe), catégorie
// et recherche texte filtrent la liste ; un code exact sélectionne le produit.
function _dlcRenderProduitsSelect(){
  const sel = document.getElementById('dlc-produit');
  if(!sel) return;
  const selCat = document.getElementById('dlc-prod-cat');
  const cats = [...new Set((DB.produits||[]).map(p => p.cat || '').filter(Boolean))].sort();
  if(selCat && selCat.dataset.sig !== cats.join('|')){
    const prev = selCat.value;
    selCat.innerHTML = '<option value="">Toutes catégories</option>' + cats.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join('');
    selCat.dataset.sig = cats.join('|');
    selCat.value = cats.includes(prev) ? prev : '';
  }
  const cat = selCat ? selCat.value : '';
  const q = (document.getElementById('dlc-prod-code')?.value || '').toLowerCase().trim();
  const prev = sel.value;
  const liste = (DB.produits||[])
    .filter(p => !cat || p.cat === cat)
    .filter(p => !q || (p.ref||'').toLowerCase().includes(q) || (p.nom||'').toLowerCase().includes(q))
    .sort((a,b) => (a.nom||'').localeCompare(b.nom||''));
  // Le produit déjà choisi reste dans la liste même s'il ne correspond plus au filtre.
  const choisi = (DB.produits||[]).find(p => p._id === prev);
  if(choisi && !liste.includes(choisi)) liste.unshift(choisi);
  sel.innerHTML = `<option value="">— ${liste.length} produit(s) — choisir —</option>`
    + liste.map(p => `<option value="${esc(p._id)}">${esc(p.ref ? p.ref + ' — ' : '')}${esc(p.nom||'')}${p.cat ? ' · ' + esc(p.cat) : ''}</option>`).join('');
  sel.value = prev;
}
window.dlcFiltrerProduits = function(){
  _dlcRenderProduitsSelect();
  const q = (document.getElementById('dlc-prod-code')?.value || '').toLowerCase().trim();
  if(!q) return;
  const exact = (DB.produits||[]).find(p => (p.ref||'').toLowerCase() === q);
  const sel = document.getElementById('dlc-produit');
  if(exact && sel){ sel.value = exact._id; }
};

function _dlcRenderForm(){
  _dlcRenderProduitsSelect();
  const info = document.getElementById('dlc-client-info');
  const c = _dlcClientId ? (DB.clients||[]).find(x => x._id === _dlcClientId) : null;
  const idEl = document.getElementById('dlc-client-code');
  const nomEl = document.getElementById('dlc-client-nom');
  if(idEl) idEl.value = c ? (c.codeClient || '(sans code)') : '';
  if(nomEl) nomEl.value = c ? (c.nom || '') : '';
  if(info){
    if(!c){ info.style.display = 'none'; return; }
    const s = statsLite(c);
    const att = _dlcEnAttentePour(c._id);
    info.style.display = 'block';
    info.innerHTML = `Payé : <strong>${fmt(s.totalPaye)}</strong> sur ${fmt(c.montantTotal||0)} — <strong>${s.pct} %</strong>`
      + (s.pct < 100 ? ` · reste <strong>${fmt(s.totalRestant)}</strong>` : ' · 🏆 contrat soldé')
      + (att ? `<div style="margin-top:4px;color:var(--accent);">⏳ Une demande est déjà en attente pour ce client (du ${esc(att.dateDemande||'—')}).</div>` : '');
  }
}

window.dlcReset = function(){
  _dlcClientId = null;
  ['dlc-search','dlc-note','dlc-prod-code','dlc-prod-cat'].forEach(id => { const el = document.getElementById(id); if(el) el.value = ''; });
  const sel = document.getElementById('dlc-produit'); if(sel) sel.value = '';
  const box = document.getElementById('dlc-search-results'); if(box) box.style.display = 'none';
  _dlcRenderForm();
};

window.dlcEnvoyer = _withActionLock('dlcEnvoyer', async function(){
  if(!session || session.role !== ROLES.COMMERCIAL){ notify('Accès refusé','err'); return; }
  const c = _dlcClientId ? (DB.clients||[]).find(x => x._id === _dlcClientId) : null;
  if(!c){ notify('Recherchez et sélectionnez un client','err'); return; }
  if(c.commercialId !== session.userId){ notify("Ce client n'est pas dans votre portefeuille",'err'); return; }
  if(_estResilie(c)){ notify(`🚫 Contrat de ${esc(c.nom)} résilié — aucune livraison possible.`,'err'); return; }
  const pid = document.getElementById('dlc-produit')?.value || '';
  const p = (DB.produits||[]).find(x => x._id === pid);
  if(!p){ notify('Choisissez le produit à livrer','err'); return; }
  const note = (document.getElementById('dlc-note')?.value || '').trim().slice(0, 300);
  const s = statsLite(c);
  const avert = [];
  if(s.pct < 100) avert.push(`⚠️ ${c.nom} n'a payé que ${s.pct} % (reste ${fmt(s.totalRestant)}). La livraison pourra être refusée au bureau si le solde ne couvre pas le produit.`);
  const att = _dlcEnAttentePour(c._id);
  if(att) avert.push(`⚠️ Une demande est déjà en attente pour ce client (du ${att.dateDemande||'—'}, ${att.produitNom||''}).`);
  const ok = await confirmDialog(
    `Client : ${esc(c.nom)}${c.codeClient?' ('+esc(c.codeClient)+')':''}\nProduit : ${esc(p.ref?p.ref+' — ':'')}${esc(p.nom||'')}`
    + (avert.length ? '\n\n' + avert.join('\n\n') : '') + '\n\nEnvoyer la demande de livraison ?',
    { title: '📦 Demande de livraison', okLabel: 'Envoyer', danger: avert.length > 0 });
  if(!ok) return;
  const now = new Date();
  const heure = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
  const moi = getCom(session.userId);
  try{
    await fbAdd('demandesLivraisonClient', {
      clientId: c._id, clientNom: c.nom || '', clientCode: c.codeClient || '',
      commercialId: session.userId, commercialNom: session.nom || '',
      agenceId: moi.agenceId || c.agenceId || '',
      produitId: p._id, produitNom: p.nom || '', produitRef: p.ref || '',
      pctPayeALaDemande: s.pct, resteALaDemande: s.totalRestant,
      note, statut: 'en_attente', dateDemande: TODAY, heureDemande: heure
    });
  }catch(e){
    notify("Échec de l'envoi de la demande : " + (e.message || e), 'err');
    return;
  }
  // Hors du try : un souci d'affichage ne doit pas faire croire à un échec
  // d'envoi alors que la demande est bien partie.
  notify(`✅ Demande envoyée — ${esc(c.nom)} · ${esc(p.nom||'')}`);
  window.dlcReset();
  renderComLivraisons();
});

window._dlcRenderMesDemandes = function(){ _dlcRenderMesDemandes(); };
function _dlcRenderMesDemandes(){
  const body = document.getElementById('dlc-mes-body');
  if(!body) return;
  const stF = document.getElementById('dlc-mes-statut')?.value || '';
  const liste = (DB.demandesLivraisonClient||[])
    .filter(d => d.commercialId === session.userId)
    .filter(d => !stF || d.statut === stF)
    .sort((a,b) => ((b.dateDemande||'')+(b.heureDemande||'')).localeCompare((a.dateDemande||'')+(a.heureDemande||'')));
  if(!liste.length){ body.innerHTML = `<tr><td colspan="5" class="emp">${stF ? 'Aucune demande avec ce statut.' : 'Aucune demande envoyée.'}</td></tr>`; return; }
  body.innerHTML = liste.map(d => `<tr>
    <td style="font-size:11px;white-space:nowrap;">${esc(d.dateDemande||'—')}</td>
    <td><strong>${esc(d.clientNom||'—')}</strong>${d.clientCode?`<div style="font-size:10px;color:var(--accent);">${esc(d.clientCode)}</div>`:''}</td>
    <td style="font-size:11px;">${esc(d.produitNom||'—')}</td>
    <td>${_dlcBadge(d.statut)}${d.statut==='refusee'&&d.motifRefus?`<div style="font-size:10px;color:var(--muted);margin-top:3px;">${esc(d.motifRefus)}</div>`:''}${d.statut==='traitee'&&d.traiteParNom?`<div style="font-size:10px;color:var(--muted);margin-top:3px;">par ${esc(d.traiteParNom)} le ${esc(d.dateTraitement||'')}</div>`:''}</td>
    <td>${d.statut==='en_attente'?`<button class="btn btn-ghost btn-xs" onclick="dlcAnnuler('${d._id}')">Annuler</button>`:''}</td>
  </tr>`).join('');
}

window.dlcAnnuler = _withActionLock((...a)=>'dlcAnnuler:'+a.join(':'), async function(id){
  const d = (DB.demandesLivraisonClient||[]).find(x => x._id === id);
  if(!d || d.statut !== 'en_attente'){ notify('Cette demande ne peut plus être annulée','err'); return; }
  if(session.role === ROLES.COMMERCIAL && d.commercialId !== session.userId){ notify('Accès refusé','err'); return; }
  if(!(await confirmDialog(`Annuler la demande de livraison pour ${esc(d.clientNom||'ce client')} ?`, {title:'Annuler la demande', okLabel:'Annuler la demande', danger:true}))) return;
  try{
    await fbUpdate('demandesLivraisonClient', id, { statut: 'annulee', annuleLe: TODAY });
    notify('Demande annulée');
  }catch(e){ notify("Échec de l'annulation : " + (e.message || e), 'err'); }
  _dlcRafraichir();
});

// ── TRAITEMENT (chef d'agence / secrétaire / admin) — page Livraisons ──
function _dlcPeutTraiter(){ return !!session && [ROLES.ADMIN, ROLES.CHEF_AGENCE, ROLES.SECRETAIRE].includes(session.role); }

// ── VOLET 44 ── Page dédiée « Demandes des agents » (menu admin, chef
// d'agence, secrétaire). Dans la page Livraisons, il ne reste qu'un bandeau
// qui affiche le nombre en attente et mène à cette page.
function _dlcRenderStaff(){
  const ban = document.getElementById('dlc-staff-banner');
  if(!ban) return;
  if(!_dlcPeutTraiter()){ ban.style.display = 'none'; return; }
  const nb = (DB.demandesLivraisonClient||[]).filter(d => d.statut === 'en_attente').length;
  ban.style.display = '';
  ban.innerHTML = `📦 <strong>${nb}</strong> demande(s) de livraison d'agents en attente
    <button class="btn btn-ghost btn-xs" style="margin-left:8px;" onclick="go('demandes-agents')">Voir les demandes →</button>`;
}
window._dlcRenderStaff = _dlcRenderStaff;

function _dlcFiltresStaff(){
  const g = id => document.getElementById(id)?.value || '';
  return { du: g('dla-du'), au: g('dla-au'), agent: g('dla-agent'), statut: g('dla-statut'),
           produit: g('dla-produit'), agence: g('dla-agence'), q: g('dla-search').toLowerCase().trim() };
}

function renderDemandesAgents(){
  if(!_dlcPeutTraiter()){ go(getRoleHome(session?.role)); return; }
  const all = (DB.demandesLivraisonClient||[]);
  const isAdm = session.role === ROLES.ADMIN;
  // Listes des filtres, construites depuis les données réelles
  const remplir = (id, paires, vide) => {
    const sel = document.getElementById(id); if(!sel) return;
    const sig = paires.map(x => x[0]).join('|');
    if(sel.dataset.sig === sig) return;
    const prev = sel.value;
    sel.innerHTML = `<option value="">${vide}</option>` + paires.map(([v,l]) => `<option value="${esc(v)}">${esc(l)}</option>`).join('');
    sel.dataset.sig = sig;
    sel.value = paires.some(x => x[0] === prev) ? prev : '';
  };
  const agents = new Map(), prods = new Map(), ags = new Map();
  all.forEach(d => {
    if(d.commercialId) agents.set(d.commercialId, d.commercialNom || getCom(d.commercialId).nom || d.commercialId);
    if(d.produitId) prods.set(d.produitId, (d.produitRef ? d.produitRef + ' — ' : '') + (d.produitNom || ''));
    if(d.agenceId) ags.set(d.agenceId, getAgence(d.agenceId).nom || d.agenceId);
  });
  const tri = m => [...m.entries()].sort((a,b) => String(a[1]).localeCompare(String(b[1])));
  remplir('dla-agent', tri(agents), 'Tous les agents');
  remplir('dla-produit', tri(prods), 'Tous les produits');
  remplir('dla-agence', tri(ags), 'Toutes les agences');
  const wAg = document.getElementById('dla-agence-wrap'); if(wAg) wAg.style.display = isAdm ? '' : 'none';

  const f = _dlcFiltresStaff();
  const body = document.getElementById('dla-body');
  const kpi = document.getElementById('dla-kpi');
  if(f.du && f.au && f.du > f.au){
    if(body) body.innerHTML = '<tr><td colspan="7" class="emp">La date de début est postérieure à la date de fin.</td></tr>';
    if(kpi) kpi.innerHTML = '';
    return;
  }
  const base = all.filter(d => {
    if(f.du && (d.dateDemande||'') < f.du) return false;
    if(f.au && (d.dateDemande||'') > f.au) return false;
    if(f.agent && d.commercialId !== f.agent) return false;
    if(f.produit && d.produitId !== f.produit) return false;
    if(f.agence && d.agenceId !== f.agence) return false;
    if(f.q){
      const foin = [d.clientNom, d.clientCode, d.commercialNom, d.produitNom, d.produitRef, d.note].join(' ').toLowerCase();
      if(!foin.includes(f.q)) return false;
    }
    return true;
  });
  const n = st => base.filter(d => d.statut === st).length;
  if(kpi) kpi.innerHTML = `
    <div class="kpi-card kc-yellow"><div class="kpi-lbl">En attente</div><div class="kpi-val kv-yellow">${n('en_attente')}</div></div>
    <div class="kpi-card kc-green"><div class="kpi-lbl">Livraisons créées</div><div class="kpi-val kv-green">${n('traitee')}</div></div>
    <div class="kpi-card kc-red"><div class="kpi-lbl">Refusées</div><div class="kpi-val kv-red">${n('refusee')}</div></div>
    <div class="kpi-card"><div class="kpi-lbl">Annulées par l'agent</div><div class="kpi-val">${n('annulee')}</div></div>`;
  const liste = base.filter(d => !f.statut || d.statut === f.statut)
    .sort((a,b) => ((b.dateDemande||'')+(b.heureDemande||'')).localeCompare((a.dateDemande||'')+(a.heureDemande||'')));
  if(!body) return;
  if(!liste.length){ body.innerHTML = '<tr><td colspan="7" class="emp">Aucune demande pour ces filtres.</td></tr>'; return; }
  body.innerHTML = liste.map(d => {
    const c = (DB.clients||[]).find(x => x._id === d.clientId);
    const pct = c ? statsLite(c).pct : d.pctPayeALaDemande;
    const actions = d.statut === 'en_attente'
      ? `<button class="btn btn-primary btn-xs" onclick="dlcCreerLivraison('${d._id}')">🚚 Créer la livraison</button>
         <button class="btn btn-ghost btn-xs" onclick="dlcRefuser('${d._id}')">✖ Refuser</button>`
      : (d.traiteParNom ? `<span style="font-size:10px;color:var(--muted);">${esc(d.traiteParNom)} · ${esc(d.dateTraitement||'')}</span>` : '');
    return `<tr>
      <td style="font-size:11px;white-space:nowrap;">${esc(d.dateDemande||'—')}<div style="font-size:9px;color:var(--muted);">${esc(d.heureDemande||'')}</div></td>
      <td style="font-size:11px;">${esc(d.commercialNom||'—')}${isAdm && d.agenceId ? `<div style="font-size:9px;color:var(--muted);">${esc(getAgence(d.agenceId).nom||'')}</div>` : ''}</td>
      <td><strong>${esc(d.clientNom||'—')}</strong>${d.clientCode?`<div style="font-size:10px;color:var(--accent);">${esc(d.clientCode)}</div>`:''}</td>
      <td style="font-size:11px;">${esc(d.produitRef?d.produitRef+' — ':'')}${esc(d.produitNom||'—')}${d.note?`<div style="font-size:10px;color:var(--muted);">📝 ${esc(d.note)}</div>`:''}</td>
      <td style="font-weight:700;color:${(pct||0)>=100?'var(--accent2)':'var(--accent)'};">${pct!=null?pct+' %':'—'}</td>
      <td>${_dlcBadge(d.statut)}${d.statut==='refusee'&&d.motifRefus?`<div style="font-size:10px;color:var(--muted);">${esc(d.motifRefus)}</div>`:''}</td>
      <td style="white-space:nowrap;">${actions}</td>
    </tr>`;
  }).join('');
}
window.renderDemandesAgents = renderDemandesAgents;
window.dlaResetFiltres = function(){
  ['dla-du','dla-au','dla-agent','dla-produit','dla-agence','dla-search'].forEach(id => { const el = document.getElementById(id); if(el) el.value = ''; });
  const st = document.getElementById('dla-statut'); if(st) st.value = 'en_attente';
  renderDemandesAgents();
};
function _dlcRafraichir(){
  if(typeof curPg !== 'undefined' && curPg === 'demandes-agents') renderDemandesAgents();
  else if(typeof curPg !== 'undefined' && curPg === 'com-livraisons') renderComLivraisons();
  else renderLivraisons();
}

// Ouvre le formulaire de livraison HABITUEL, prérempli. Rien n'est
// contourné : saveLivraison() applique ses contrôles (solde, adhésion,
// stock). La demande n'est marquée « traitée » qu'APRÈS l'enregistrement
// réussi de la livraison (voir le crochet dans saveLivraison).
window.dlcCreerLivraison = async function(id){
  if(!_dlcPeutTraiter()){ notify('Accès refusé','err'); return; }
  const d = (DB.demandesLivraisonClient||[]).find(x => x._id === id);
  if(!d || d.statut !== 'en_attente'){ notify('Demande introuvable ou déjà traitée','err'); return; }
  openM('m-livraison');           // réinitialise le formulaire (et _dlcEnTraitement)
  _dlcEnTraitement = { demandeId: id, clientId: d.clientId };
  const code = document.getElementById('liv-search-code');
  if(code){ code.value = d.clientCode || ''; livFiltrerClients(); }
  const selCl = document.getElementById('liv-client');
  if(selCl){
    selCl.value = d.clientId;
    if(selCl.value !== d.clientId) notify("Client introuvable dans la liste — vérifiez qu'il appartient bien à votre agence.",'err');
    else await onLivClientChange();
  }
  const art = document.getElementById('liv-art-code');
  if(art && d.produitRef){ art.value = String(d.produitRef).toUpperCase(); onLivArtCodeInput(true); }
  const note = document.getElementById('liv-note');
  if(note) note.value = `Demande de ${d.commercialNom||'l\'agent'} du ${d.dateDemande||''}${d.note?' — '+d.note:''}`.slice(0, 300);
};

// Appelé par saveLivraison() juste après l'enregistrement réussi.
async function _dlcApresLivraison(clientId, livraisonId){
  const t = _dlcEnTraitement;
  _dlcEnTraitement = null;
  if(!t || t.clientId !== clientId) return;
  try{
    await fbUpdate('demandesLivraisonClient', t.demandeId, {
      statut: 'traitee', livraisonId: livraisonId || null, dateTraitement: TODAY,
      traiteParId: session.userId, traiteParNom: session.nom || session.userId
    });
  }catch(e){
    notify("Livraison enregistrée, mais la demande de l'agent n'a pas pu être marquée traitée : " + (e.message||e), 'err');
  }
  _dlcRafraichir();
}

window.dlcRefuser = _withActionLock((...a)=>'dlcRefuser:'+a.join(':'), async function(id){
  if(!_dlcPeutTraiter()){ notify('Accès refusé','err'); return; }
  const d = (DB.demandesLivraisonClient||[]).find(x => x._id === id);
  if(!d || d.statut !== 'en_attente'){ notify('Demande introuvable ou déjà traitée','err'); return; }
  const motif = (prompt(`Motif du refus pour ${d.clientNom||'ce client'} (obligatoire, visible par l'agent) :`) || '').trim();
  if(!motif){ notify('Refus abandonné — un motif est obligatoire','err'); return; }
  try{
    await fbUpdate('demandesLivraisonClient', id, {
      statut: 'refusee', motifRefus: motif.slice(0, 300), dateTraitement: TODAY,
      traiteParId: session.userId, traiteParNom: session.nom || session.userId
    });
    notify('Demande refusée — l\'agent verra le motif');
  }catch(e){ notify('Échec du refus : ' + (e.message||e), 'err'); }
  _dlcRafraichir();
});
// ═══════════════ FIN VOLET 43 ═══════════════════════════════════


window.marquerLivre = _withActionLock((...a)=>'marquerLivre:'+a.join(':'), async function(id){
  if(!['admin','secretaire'].includes(session?.role)){ notify('Accès refusé','err'); return; }
  const l=DB.livraisons.find(l=>l._id===id);
  if(!l) return;
  // ── VOLET 17 ── c'etait le defaut le plus concret : une livraison saisie
  // avant une modification de produit, puis marquee « livree » apres, faisait
  // sortir du stock les articles de la NOUVELLE composition. On destocke
  // desormais ce qui avait ete fige a l'enregistrement.
  const prod = _prodPourDeduction(l);
  try{
    if(!prod || !prod._id){ await fbUpdate('livraisons',id,{statut:'livre'}); notify('Livraison marquée livrée ✓'); return; }
    const clientLiv = DB.clients.find(c=>c._id===l.clientId);
    const agenceIdLivraison = _agenceLivraison(clientLiv, l);   // ── VOLET 54 ──
    const warnings = await deduireStockLivraison(prod, l.qty, clientLiv?.nom||l.clientId||'', agenceIdLivraison);
    // ── VOLET 54 ── on garde la trace d'un déstockage incomplet, pour pouvoir
    // le rattraper (bouton ⟳ Stock, admin) au lieu de le perdre.
    await fbUpdate('livraisons',id,{statut:'livre', stockDeduit: warnings.complet !== false, stockNonDeduit: warnings.nonDeduits || []});
    if(warnings.length){
      notify(`⚠️ Livraison marquée livrée — Stock : ${warnings.join(', ')}`,'warn');
    } else {
      notify('Livraison marquée livrée ✓');
    }
  }catch(e){
    console.error('Échec marquage livraison:', e);
    notify("Échec de la mise à jour de la livraison — vérifiez votre connexion et réessayez.", 'err');
  }
});

// ═══════════════ STOCK PAR AGENCE ═══════════════
// Solde de stock propre à une agence (collection stockAgences, un document
// par couple agenceId/articleId). Alimenté par les sorties du gestionnaire
// vers l'agence (saveMvt), débité par les livraisons clients de cette agence
// (deduireStockLivraison). Le stock global (articles.stock) n'est lui touché
// QUE par les entrées et les sorties (mouvements manuels/import) — plus par
// les livraisons, depuis la bascule vers le stock par agence.
function getAgenceStockDoc(agenceId, articleId){
  return DB.stockAgences.find(s=>s.agenceId===agenceId && s.articleId===articleId);
}
function getAgenceStockQty(agenceId, articleId){
  return getAgenceStockDoc(agenceId, articleId)?.qty || 0;
}
// delta positif = crédit (réception d'une sortie du gestionnaire), delta
// négatif = débit (consommation par une livraison). Autorisé à devenir
// négatif : pour l'instant on ne bloque pas une livraison faute de stock au
// niveau de l'agence, on se contente de le signaler (voir warnings plus bas).
async function ajusterStockAgence(agenceId, articleId, delta){
  const docExistant = getAgenceStockDoc(agenceId, articleId);
  if(docExistant){
    const nouveauQty = (docExistant.qty||0) + delta;
    await fbUpdate('stockAgences', docExistant._id, {qty:nouveauQty});
    docExistant.qty = nouveauQty; // maj immédiate du cache local
    return nouveauQty;
  }
  const cree = await fbAdd('stockAgences', {agenceId, articleId, qty: delta});
  return cree.qty;
}

// Décompose le produit livré en ses articles (composition de la recette) et
// déduit le stock de chacun — au niveau du solde de l'AGENCE du client livré
// (agenceId), plus du stock global directement. Si l'agence n'a pas assez de
// stock, la livraison n'est pas bloquée : le solde de l'agence passe en
// négatif et une alerte est remontée à l'utilisateur.
// Retourne la liste des alertes de manque de stock.
// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 17 — UNE LIVRAISON GARDE LE PRODUIT TEL QU'IL ETAIT    ║
// ╚══════════════════════════════════════════════════════════════╝
// LE PROBLEME
// Le PRIX etait deja protege deux fois : par client.produitsPrixFiges (fixe a
// l'adhesion) et par livraison.montant / livraison.pvFige (stockes). Les
// soldes clients et les blocages de livraison etaient donc deja immunises.
// En revanche, la COMPOSITION du produit (quels articles, en quelle quantite)
// n'etait stockee NULLE PART sur la livraison : elle etait relue en direct.
// Trois traitements portant sur des livraisons DEJA enregistrees s'en
// servaient, et changeaient donc de resultat des qu'un produit etait modifie :
//   1. marquerLivre()        — destockait les articles d'AUJOURD'HUI pour une
//                              livraison saisie avant le changement ;
//   2. renderStockParAgence()— recalculait « Livre clients » sur tout
//                              l'historique avec la composition actuelle ;
//   3. migrerStockParAgence()— recalculait TOUS les soldes stockAgences de la
//                              meme facon, et les ECRIVAIT.
// Le nom et la reference n'etaient pas stockes non plus : renommer un produit
// reecrivait retroactivement tout l'historique a l'ecran ; le supprimer le
// vidait.
//
// LA REGLE RETENUE
// La composition, le nom et la reference sont COPIES sur le document de
// livraison au moment ou elle est enregistree. C'est le reflet exact de ce qui
// est sorti du magasin ce jour-la. Une modification de produit ne peut donc
// plus rien changer au passe.
//
// COMPATIBILITE ASCENDANTE — AUCUNE MIGRATION NECESSAIRE
// Les livraisons anterieures a ce volet n'ont pas ces champs. Les trois
// helpers ci-dessous retombent alors sur le produit actuel, exactement comme
// avant : leur comportement est inchange. Le gel ne s'applique qu'aux
// livraisons enregistrees a partir du deploiement.

// Composition a utiliser pour une livraison donnee.
function _compositionLivraison(l){
  if (l && Array.isArray(l.compositionFigee) && l.compositionFigee.length) return l.compositionFigee;
  const prod = (DB.produits||[]).find(p => p._id === (l && l.produitId));
  return (prod && prod.composition) || [];
}

// Nom / reference a afficher pour une livraison donnee.
function _nomProduitLivraison(l){
  if (l && l.produitNom) return l.produitNom;
  return (getProd(l && l.produitId) || {}).nom || '—';
}
function _refProduitLivraison(l){
  if (l && l.produitRef) return l.produitRef;
  return (getProd(l && l.produitId) || {}).ref || '';
}

// Objet « produit » reconstitue a partir de ce qui a ete fige sur la
// livraison, pour le passer a deduireStockLivraison() sans modifier celle-ci.
function _prodPourDeduction(l){
  const prod = (DB.produits||[]).find(p => p._id === (l && l.produitId)) || {};
  return {
    _id: (l && l.produitId) || prod._id || '',
    nom: _nomProduitLivraison(l),
    ref: _refProduitLivraison(l),
    composition: _compositionLivraison(l)
  };
}

// ── VOLET 54 ── Agence d'une livraison, de façon robuste.
// AVANT : client.agenceId ?? agence du commercial. Un agenceId vide ('') sur
// le client bloquait le repli, et un client absent de la mémoire n'avait
// aucun repli sur le commercial enregistré sur la livraison.
// MAINTENANT : client.agenceId, puis agence du commercial du client, puis
// agence du commercial enregistré sur la livraison.
function _agenceLivraison(client, l){
  const agCom = id => (id && (DB.commerciaux||[]).find(c => c._id === id)?.agenceId) || null;
  return (client && client.agenceId) || agCom(client && client.commercialId) || agCom(l && l.commercialId) || null;
}

// ── VOLET 54 ── renvoie toujours un tableau d'avertissements, enrichi de :
//   .nonDeduits = articleIds dont le stock agence n'a PAS été déduit
//   .complet    = true si tout a été déduit
// seulementArticleIds (facultatif) : ne traiter que ces composants (reprise
// d'une déduction incomplète, sans re-déduire ce qui l'a déjà été).
async function deduireStockLivraison(prod, qty, clientNom, agenceId, seulementArticleIds){
  const warnings=[];
  warnings.nonDeduits = [];
  // Les articles DOIVENT être en mémoire : c'est l'oubli qui produisait
  // « composant inconnu » quand on ouvrait Livraisons sans être passé par
  // Articles / Produits / Stock dans la session.
  try { await ensureCollectionsLoaded(['articles']); } catch(e){ console.warn('[stock] articles non chargés', e); }
  let comp = prod.composition||[];
  if(Array.isArray(seulementArticleIds)) comp = comp.filter(c => seulementArticleIds.includes(c.articleId));
  if(!comp.length){
    if(!Array.isArray(seulementArticleIds)) warnings.push(`(« ${esc(prod.nom)} » n'a pas de composition d'articles définie)`);
    warnings.complet = true;
    return warnings;
  }
  if(!agenceId){
    warnings.push(`(agence introuvable pour le client « ${esc(clientNom||'?')} » : ni le client ni son commercial n'ont d'agence — stock agence NON déduit pour « ${esc(prod.nom)} »)`);
    warnings.nonDeduits = comp.map(c => c.articleId);
    warnings.complet = false;
    return warnings;
  }
  for(const c of comp){
    const compArt=DB.articles.find(x=>x._id===c.articleId);
    if(!compArt){
      warnings.push(`(article « ${esc(c.nom||c.articleId||'?')} » introuvable dans les articles — non déduit)`);
      warnings.nonDeduits.push(c.articleId);
      continue;
    }
    const needed=c.qte*qty;
    const nouveauSoldeAgence = await ajusterStockAgence(agenceId, c.articleId, -needed);
    // ✅ Sur demande : plus de ligne créée dans stockMvts pour une livraison
    // client — ces livraisons ne touchent plus le stock global, seulement le
    // solde de l'agence (ajusterStockAgence ci-dessus).
    if(nouveauSoldeAgence<0) warnings.push(`${esc(compArt.nom)} (stock agence négatif : ${nouveauSoldeAgence})`);
  }
  warnings.complet = warnings.nonDeduits.length === 0;
  return warnings;
}

// ── VOLET 54 ── Rattrapage d'un déstockage incomplet (admin).
// Proposé sur une livraison « livrée » marquée stockDeduit:false, ou livrée
// dans les 7 derniers jours sans marqueur (livraisons faites juste avant ce
// correctif). Ne retraite QUE les articles notés non déduits quand on les
// connaît ; sinon toute la composition (confirmation explicite).
window.rattraperStockLivraison = _withActionLock((...a)=>'rattraperStock:'+a.join(':'), async function(id){
  if(session?.role !== ROLES.ADMIN){ notify("Réservé à l'administrateur",'err'); return; }
  const l = (DB.livraisons||[]).find(x => x._id === id);
  if(!l || l.statut !== 'livre'){ notify('Livraison introuvable ou non livrée','err'); return; }
  const prod = _prodPourDeduction(l);
  const client = (DB.clients||[]).find(c => c._id === l.clientId);
  const agenceId = _agenceLivraison(client, l);
  if(!agenceId){
    notify(`Agence toujours introuvable pour « ${esc((client||{}).nom||'ce client')} ». Attribuez d'abord une agence à son commercial (menu Utilisateurs), puis réessayez.`,'err');
    return;
  }
  const cibles = Array.isArray(l.stockNonDeduit) && l.stockNonDeduit.length ? l.stockNonDeduit : null;
  const detail = (prod.composition||[]).filter(c => !cibles || cibles.includes(c.articleId))
    .map(c => `• ${c.nom||c.articleId} × ${(Number(c.qte)||0) * (Number(l.qty)||0)}`).join('\n');
  const ok = await confirmDialog(
    `Déduire maintenant du stock de l'agence « ${esc(getAgence(agenceId).nom||agenceId)} » :\n${detail}\n\n`+
    (cibles ? 'Seuls les articles non déduits lors de la livraison sont repris.'
            : '⚠️ À n\'utiliser QUE si la livraison avait affiché « agence inconnue » ou « composant inconnu » : sinon le stock serait déduit deux fois.'),
    { title: '⟳ Rattraper le déstockage', okLabel: 'Déduire', danger: !cibles });
  if(!ok) return;
  try{
    const w = await deduireStockLivraison(prod, l.qty, (client||{}).nom||'', agenceId, cibles || undefined);
    await fbUpdate('livraisons', id, { stockDeduit: w.complet, stockNonDeduit: w.nonDeduits, stockRattrapeLe: TODAY });
    notify(w.complet ? '✅ Stock agence déduit' : `⚠️ Encore incomplet : ${w.join(', ')}`, w.complet ? 'ok' : 'warn');
  }catch(e){ notify('Erreur : ' + (e.message||e), 'err'); }
  renderLivraisons();
});

// ── OUTIL DE MIGRATION UNIQUE (admin) : bascule vers le stock par agence ──
// À exécuter UNE FOIS après le déploiement de ce correctif, connecté en tant
// qu'admin, en tapant `migrerStockParAgence()` dans la console du navigateur
// (F12). Fait deux choses :
//  1) Reconstitue le solde de stockAgences pour chaque couple agence/article
//     à partir de l'historique complet : (sorties déjà envoyées à l'agence)
//     − (livraisons déjà "livrées" aux clients de cette agence). Recalcul
//     total à partir des sources (stockMvts + livraisons), donc rejouable
//     sans risque : relancer l'outil ne fait que rafraîchir la valeur, ça ne
//     l'incrémente pas une seconde fois.
//  2) Réintègre, UNE SEULE FOIS par article (marqué par le champ
//     `stockGlobalRecaleAgence`), le total déjà déduit du stock global par
//     les livraisons passées — puisque désormais seules les entrées/sorties
//     touchent articles.stock (voir deduireStockLivraison). Cette partie
//     N'EST PAS rejouable : un second lancement sur un article déjà marqué
//     est ignoré, pour ne jamais réintégrer deux fois le même montant.
window.migrerStockParAgence = async function(){
  if(!session || session.role !== 'admin'){ console.error('Réservé à l\'admin.'); return; }
  await ensureCollectionsLoaded(['agences','commerciaux','clients','articles','produits']);
  // ── VOLET 6 ── ces trois appels fonctionnent toujours : _forceFullLoad()
  // contourne desormais explicitement le regime "a la demande" (voir
  // _forceFullLoadCols). Sans ce contournement, l'appel sur 'stockMvts'
  // aurait boucle indefiniment.
  await _forceFullLoad('stockMvts');
  await _forceFullLoad('livraisons');
  await _forceFullLoad('stockAgences');

  const agenceOfCommercial = new Map(DB.commerciaux.map(c => [c._id, c.agenceId ?? null]));
  const agenceOfClient = (client) => client?.agenceId ?? agenceOfCommercial.get(client?.commercialId) ?? null;

  // needed[articleId] par agence (pour stockAgences) ET tous agences confondues (pour le recalage global)
  const neededParAgenceEtArticle = {}; // `${agenceId}|${articleId}` -> qty
  const neededTotalParArticle = {};    // articleId -> qty (toutes agences + clients sans agence connue)
  let livraisonsSansAgence = 0;

  for(const l of DB.livraisons){
    if(l.statut !== 'livre') continue;
    // ── VOLET 17 ── celui-ci n'affiche pas : il ECRIT dans stockAgences. Sans
    // le gel, relancer cet outil apres une modification de produit reecrivait
    // tous les soldes d'agence avec une composition qui n'avait jamais ete
    // expediee.
    const comp = _compositionLivraison(l);
    if(!comp.length) continue;
    const client = DB.clients.find(c=>c._id===l.clientId);
    const agenceId = agenceOfClient(client);
    if(!agenceId) livraisonsSansAgence++;
    comp.forEach(c=>{
      const q = (c.qte||0) * l.qty;
      neededTotalParArticle[c.articleId] = (neededTotalParArticle[c.articleId]||0) + q;
      if(agenceId){
        const key = agenceId+'|'+c.articleId;
        neededParAgenceEtArticle[key] = (neededParAgenceEtArticle[key]||0) + q;
      }
    });
  }

  // envoye[agenceId|articleId] : total historique des sorties du gestionnaire vers cette agence
  const envoyeParAgenceEtArticle = {};
  DB.stockMvts.filter(m=>m.type==='sortie' && m.destinationId).forEach(m=>{
    const key = m.destinationId+'|'+m.articleId;
    envoyeParAgenceEtArticle[key] = (envoyeParAgenceEtArticle[key]||0) + (m.qty||0);
  });

  // 1) Reconstitution des soldes stockAgences (recalcul complet, donc rejouable)
  const toutesLesClesAgenceArticle = new Set([...Object.keys(envoyeParAgenceEtArticle), ...Object.keys(neededParAgenceEtArticle)]);
  let soldesEcrits = 0;
  for(const key of toutesLesClesAgenceArticle){
    const [agenceId, articleId] = key.split('|');
    const solde = (envoyeParAgenceEtArticle[key]||0) - (neededParAgenceEtArticle[key]||0);
    const docExistant = getAgenceStockDoc(agenceId, articleId);
    if(docExistant){
      await fbUpdate('stockAgences', docExistant._id, {qty: solde});
      docExistant.qty = solde;
    } else {
      const cree = await fbAdd('stockAgences', {agenceId, articleId, qty: solde});
      DB.stockAgences.push(cree);
    }
    soldesEcrits++;
  }

  // 2) Recalage UNIQUE du stock global (réintégration du total déjà livré, jamais deux fois)
  let stocksRecales = 0, stocksDejaFaits = 0;
  for(const art of DB.articles){
    if(art.stockGlobalRecaleAgence){ stocksDejaFaits++; continue; }
    const dejaLivre = neededTotalParArticle[art._id] || 0;
    const nouveauStock = (art.stock||0) + dejaLivre;
    await fbUpdate('articles', art._id, {stock: nouveauStock, stockGlobalRecaleAgence: true});
    art.stock = nouveauStock;
    art.stockGlobalRecaleAgence = true;
    stocksRecales++;
  }

  notify(`Migration stock par agence : ${soldesEcrits} solde(s) agence recalculé(s), ${stocksRecales} article(s) recalé(s) au global (${stocksDejaFaits} déjà fait avant), ${livraisonsSansAgence} livraison(s) sans agence connue (ignorées pour le solde agence, incluses dans le recalage global).`, 'success');
};

window.verifierPrefix = function(input){
  const p = input.value.trim().toUpperCase();
  input.value = p;
  const status  = document.getElementById('com-prefix-status');
  const preview = document.getElementById('com-prefix-preview');
  if(!p){ status.innerHTML=''; preview.textContent=''; return; }
  const existing = DB.commerciaux.filter(c=>c.role!=='admin').map(c=>(c.codePrefix||'').toUpperCase());
  if(existing.includes(p)){
    status.innerHTML=`<span style="color:var(--danger);">❌ Ce préfixe est déjà utilisé par un autre commercial.</span>`;
    input.style.borderColor='var(--danger)';
    preview.textContent='';
  } else {
    status.innerHTML=`<span style="color:var(--accent2);">✓ Disponible</span>`;
    input.style.borderColor='var(--accent2)';
    preview.innerHTML=`→ <strong style="color:var(--accent);">${p}0001</strong>, <strong style="color:var(--accent);">${p}0002</strong>…`;
  }
};

