// ─── Réinitialisation du mot de passe d'un utilisateur (admin uniquement) ───
// L'admin déclenche l'envoi d'un email de réinitialisation Firebase Auth
// standard à la place de l'utilisateur — utile car les commerciaux n'ont
// pas forcément un accès email fiable/immédiat pour faire la démarche
// eux-mêmes depuis l'écran de connexion.
window.resetPasswordCom = async function(id){
  if(session?.role!=='admin'){ notify('Accès réservé à l\'administrateur','err'); return; }
  const m = DB.commerciaux.find(c=>c._id===id);
  if(!m){ notify('Utilisateur introuvable','err'); return; }
  if(!m.email){ notify('Cet utilisateur n\'a pas d\'email enregistré — réinitialisation impossible','err'); return; }
  const ok = await confirmDialog(
    `Envoyer un email de réinitialisation du mot de passe à <strong>${esc(m.nom)}</strong> (${esc(m.email)}) ?`,
    {title:'🔑 Réinitialiser le mot de passe', okLabel:'Envoyer', danger:false}
  );
  if(!ok) return;
  try{
    await sendPasswordResetEmail(auth, m.email);
    notify(`✉️ Email de réinitialisation envoyé à ${m.email}`);
  }catch(e){
    console.error('Échec envoi réinitialisation mot de passe:', e);
    // Message adapté selon le code d'erreur Firebase le plus courant
    const msg = e?.code === 'auth/user-not-found'
      ? `Aucun compte Firebase Auth trouvé pour ${m.email} — vérifiez qu'il a bien été créé dans la Console Firebase.`
      : `Échec de l'envoi — vérifiez la connexion et réessayez.`;
    notify(msg, 'err');
  }
};

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 58 — CHANGER L'E-MAIL DE CONNEXION D'UN UTILISATEUR    ║
// ╚══════════════════════════════════════════════════════════════╝
// Les clients portent commercialId == UID Firebase == ID de la fiche
// commerciaux. On change donc l'e-mail SUR LE MÊME COMPTE (l'UID ne bouge
// pas) : aucun client, paiement ou historique n'est touché.
// Le navigateur ne peut pas modifier le compte d'un autre : c'est la Cloud
// Function 'adminChangerEmail' (functions/index.js) qui le fait, après avoir
// revérifié côté serveur que l'appelant est admin et vient de ressaisir son
// mot de passe. Les contrôles ci-dessous ne sont que du confort.
// Le module Functions est chargé À LA DEMANDE (import dynamique) : il ne
// pèse rien au démarrage des agents de terrain et ne peut pas le casser.
const _FN_REGION = 'europe-west1';   // ⚠️ identique à REGION dans functions/index.js
const _EMAIL_RE_V58 = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

window.ouvrirChangementEmail = function(id){
  if(session?.role!==ROLES.ADMIN){ notify('Accès réservé à l\'administrateur','err'); return; }
  const m = (DB.commerciaux||[]).find(c=>c._id===id);
  if(!m){ notify('Utilisateur introuvable','err'); return; }
  document.getElementById('ce-id').value = id;
  document.getElementById('ce-nom').textContent = m.nom || '—';
  document.getElementById('ce-ancien').textContent = m.email || '(aucun e-mail sur la fiche)';
  const nbCl = (DB.clients||[]).filter(cl=>cl.commercialId===id).length;
  document.getElementById('ce-info-clients').textContent = m.role===ROLES.COMMERCIAL
    ? `Ses clients${nbCl?` (${nbCl} chargés sur cet appareil)`:''} restent rattachés : son identifiant ne change pas.`
    : 'Son identifiant ne change pas : tout son historique reste rattaché.';
  ['ce-nouvel','ce-confirm','ce-motif','ce-mdp'].forEach(k=>{ const el=document.getElementById(k); if(el) el.value=''; });
  const err = document.getElementById('ce-err'); err.style.display='none'; err.textContent='';
  const btn = document.getElementById('ce-btn'); btn.disabled=false; btn.textContent='✓ Changer l\'e-mail';
  openM('m-change-email');
  setTimeout(()=>document.getElementById('ce-nouvel')?.focus(), 50);
};

window.validerChangementEmail = _withActionLock('validerChangementEmail', async function(){
  const errEl = document.getElementById('ce-err');
  const btn   = document.getElementById('ce-btn');
  const echec = msg => { errEl.textContent = msg; errEl.style.display = 'block'; };
  errEl.style.display = 'none';

  if(session?.role!==ROLES.ADMIN){ echec('Accès réservé à l\'administrateur.'); return; }
  const id     = document.getElementById('ce-id').value;
  const nouvel = (document.getElementById('ce-nouvel').value||'').trim().toLowerCase();
  const conf   = (document.getElementById('ce-confirm').value||'').trim().toLowerCase();
  const motif  = (document.getElementById('ce-motif').value||'').trim();
  const mdp    = document.getElementById('ce-mdp').value||'';
  const m = (DB.commerciaux||[]).find(c=>c._id===id);
  if(!m){ echec('Utilisateur introuvable.'); return; }
  if(!nouvel || nouvel.length>150 || !_EMAIL_RE_V58.test(nouvel)){ echec('Nouvel e-mail invalide.'); return; }
  if(nouvel!==conf){ echec('Les deux saisies du nouvel e-mail ne correspondent pas.'); return; }
  if(m.email && m.email.toLowerCase()===nouvel){ echec('C\'est déjà l\'adresse actuelle.'); return; }
  const doublon = (DB.commerciaux||[]).find(c=>c._id!==id && (c.email||'').toLowerCase()===nouvel);
  if(doublon){ echec(`Adresse déjà utilisée par ${doublon.nom||'un autre utilisateur'}.`); return; }
  if(!mdp){ echec('Saisissez VOTRE mot de passe administrateur pour confirmer.'); return; }
  if(!navigator.onLine){ echec('Connexion Internet requise pour cette opération.'); return; }
  const user = auth?.currentUser;
  if(!user || !user.email){ echec('Session expirée — reconnectez-vous.'); return; }

  btn.disabled = true; btn.textContent = '⏳ En cours…';
  try{
    // 1. Ressaisie du mot de passe : la fonction exige une connexion < 5 min.
    try{
      await reauthenticateWithCredential(user, EmailAuthProvider.credential(user.email, mdp));
      await user.getIdToken(true);
    }catch(e){
      const c = e?.code||'';
      echec(c==='auth/too-many-requests'
        ? 'Trop de tentatives — patientez quelques minutes.'
        : (c==='auth/wrong-password'||c==='auth/invalid-credential'||c==='auth/invalid-login-credentials')
          ? 'Mot de passe administrateur incorrect.'
          : 'Vérification du mot de passe impossible — vérifiez la connexion.');
      return;
    }
    // 2. Appel serveur
    const { getFunctions, httpsCallable } = await import('https://www.gstatic.com/firebasejs/10.12.2/firebase-functions.js');
    const fn = httpsCallable(getFunctions(getApp(), _FN_REGION), 'adminChangerEmail');
    const res = await fn({ uid: id, nouvelEmail: nouvel, motif });
    const ancien = res?.data?.ancienEmail || m.email || '';

    // 3. Copie locale (la fiche Firestore est déjà à jour côté serveur)
    m.email = nouvel;
    (DB.commerciaux||[]).forEach(c=>{ if(c._id===id) c.email = nouvel; });
    Promise.resolve().then(()=>_cacheWrite('commerciaux', DB.commerciaux)).catch(()=>{ /* cache : non bloquant */ });
    closeM('m-change-email');
    notify(`✉️ E-mail de ${m.nom} changé : ${ancien||'—'} → ${nouvel}. Il se connecte désormais avec ce nouvel e-mail et son mot de passe habituel.`, 'success');
    if(typeof renderComs==='function') renderComs();
  }catch(e){
    console.error('[volet 58] changement e-mail', e);
    const c = String(e?.code||'').replace('functions/','');
    const msgs = {
      'permission-denied':   "Refusé : réservé à l'administrateur.",
      'failed-precondition': 'Confirmation expirée — ressaisissez votre mot de passe.',
      'already-exists':      e?.message || 'Adresse déjà utilisée.',
      'not-found':           e?.message || 'Compte introuvable.',
      'invalid-argument':    e?.message || 'Données invalides.',
      'unauthenticated':     'Session expirée — reconnectez-vous.',
      'unavailable':         'Service injoignable — vérifiez la connexion.',
      'internal':            e?.message && e.message!=='internal' ? e.message
                               : "Erreur serveur. Si elle persiste, vérifiez que la fonction 'adminChangerEmail' est bien déployée."
    };
    echec(msgs[c] || "Échec — rien n'a été modifié. Vérifiez la connexion et réessayez.");
  }finally{
    btn.disabled = false; btn.textContent = '✓ Changer l\'e-mail';
    const p = document.getElementById('ce-mdp'); if(p) p.value = '';
  }
});

