// ========= RESPONSIVE — SIDEBAR MOBILE =========
function toggleSidebar(){
  const sidebar = document.getElementById('sidebar');
  const overlay = document.getElementById('sidebar-overlay');
  const isOpen = sidebar.classList.contains('open');
  if(isOpen){
    sidebar.classList.remove('open');
    overlay.classList.remove('visible');
  } else {
    sidebar.classList.add('open');
    overlay.classList.add('visible');
  }
}

// Fermer la sidebar quand on clique sur un item de nav en mobile
function closeSidebarMobile(){
  if(window.innerWidth <= 768){
    document.getElementById('sidebar').classList.remove('open');
    document.getElementById('sidebar-overlay').classList.remove('visible');
  }
}

// Attacher l'événement closeSidebarMobile à tous les .nav-item (après leur création)
const _navObserver = new MutationObserver(()=>{
  document.querySelectorAll('.nav-item').forEach(el=>{
    if(!el.dataset.mobileListener){
      el.dataset.mobileListener = '1';
      el.addEventListener('click', closeSidebarMobile);
    }
  });
});
_navObserver.observe(document.getElementById('nav-menu'), {childList:true, subtree:true});

// ========= BOOT =========
document.getElementById('reg-date').value=TODAY;
const ficheDateEl = document.getElementById('fiche-date');
if(ficheDateEl) ficheDateEl.value=TODAY;
const histDateEl = document.getElementById('h-date');
if(histDateEl) histDateEl.value=TODAY;

// ✅ FIX DATE : détection du changement de jour pendant que l'app reste
// ouverte. Met à jour TODAY et les filtres de date qui affichaient encore
// "l'ancien aujourd'hui" (ceux que l'utilisateur a changés volontairement
// ne sont pas touchés). `rerender` = true uniquement au retour dans l'app
// (visibilitychange/pageshow), jamais depuis le minuteur, pour ne pas
// réinitialiser un formulaire pendant qu'un agent tape.
function _rafraichirTODAY(rerender) {
  const nouveau = _dateLocaleISO();
  if (nouveau === TODAY) return false;
  const ancien = TODAY;
  TODAY = nouveau;
  ['reg-date', 'fiche-date', 'h-date'].forEach(id => {
    const el = document.getElementById(id);
    if (el && el.value === ancien) el.value = nouveau;
  });
  console.info('[date] Changement de jour détecté :', ancien, '→', nouveau);
  if (rerender === true && session && curPg) {
    try { renderPg(curPg); } catch (e) { console.warn('[date] Re-rendu après changement de jour échoué :', e); }
  }
  return true;
}
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') _rafraichirTODAY(true);
});
window.addEventListener('pageshow', () => _rafraichirTODAY(true));
setInterval(() => _rafraichirTODAY(false), 60 * 1000);

// =========================================================
// IMPRESSION BLUETOOTH ESC/POS — TRIOMPHANT MMB SERVICE
// Compatible : Xprinter, GOOJPRT, Peripage, MUNBYN, etc.
// Navigateur requis : Chrome Android (Web Bluetooth API)
// =========================================================

const _ESC = 0x1B, _GS = 0x1D;
const _escCmd = (...b) => new Uint8Array(b);

const BT_ESC_INIT        = _escCmd(_ESC, 0x40);
const BT_ALIGN_CTR       = _escCmd(_ESC, 0x61, 0x01);
const BT_ALIGN_LEFT      = _escCmd(_ESC, 0x61, 0x00);
const BT_BOLD_ON         = _escCmd(_ESC, 0x45, 0x01);
const BT_BOLD_OFF        = _escCmd(_ESC, 0x45, 0x00);
const BT_FONT_LARGE      = _escCmd(_ESC, 0x21, 0x30);
const BT_FONT_NORMAL     = _escCmd(_ESC, 0x21, 0x00);
const BT_FONT_SMALL      = _escCmd(_ESC, 0x21, 0x01);
const BT_CUT             = _escCmd(_GS,  0x56, 0x01);
const BT_LF              = _escCmd(0x0A);

function _btText(str){
  const map={'é':'e','è':'e','ê':'e','ë':'e','à':'a','â':'a','ù':'u','û':'u','ô':'o','î':'i','ï':'i','ç':'c','É':'E','È':'E','Ê':'E','À':'A','Ô':'O','Î':'I','Û':'U','Ç':'C','²':'2','€':'EUR'};
  const s=(str||'').replace(/[éèêëàâùûôîïçÉÈÊÀÔÎÛÇ²€]/g,m=>map[m]||m);
  // Convertir les \n en octet 0x0A (LF imprimante)
  const bytes=[];
  for(let i=0;i<s.length;i++){
    if(s[i]==='\n') bytes.push(0x0A);
    else bytes.push(s.charCodeAt(i)&0xFF);
  }
  return new Uint8Array(bytes);
}

function _btLine(left, right, cols){
  cols=cols||32;
  const l=String(left||'');
  const r=String(right||'');
  const maxRight = cols - l.length - 1;
  if(r.length > maxRight){
    // Valeur trop longue : label sur ligne 1, valeur alignée à droite sur ligne 2
    const sp2 = Math.max(0, cols - r.length);
    return _btText(l + '\n' + ' '.repeat(sp2) + r);
  }
  const sp=Math.max(1, cols-l.length-r.length);
  return _btText(l+' '.repeat(sp)+r);
}

function _btSep(cols){ return _btText('-'.repeat(cols||32)); }

function _buildEscPos(data, recuNum, emissionDate, emissionHeure, agenceLabel){
  const chunks=[];
  const add=(...a)=>a.forEach(x=>chunks.push(x));
  const COLS=32;

  add(BT_ESC_INIT);
  add(BT_FONT_SMALL);

  // En-tête
  add(BT_ALIGN_CTR, BT_BOLD_ON);
  add(_btText('TRIOMPHANT MMB SERVICE'), BT_LF);
  add(BT_BOLD_OFF);

  const typeLabel = data.type==='adhesion' ? 'ENCAISSEMENT ADHESION' : 'PAIEMENT COTISATION(S)';
  add(BT_BOLD_ON, _btText(typeLabel), BT_BOLD_OFF, BT_LF);
  // ✅ CORRECTIF C2 : même mention que sur le reçu HTML, sur le ticket
  // thermique — c'est celui que le client emporte réellement.
  if(data.enAttenteSync){
    add(BT_BOLD_ON, _btText('** EN ATTENTE **'), BT_LF);
    add(_btText('NON TRANSMIS AU BUREAU'), BT_BOLD_OFF, BT_LF);
  }
  add(_btSep(COLS), BT_LF);

  // Infos reçu
  add(BT_ALIGN_LEFT);
  add(_btLine('N Recu:', recuNum, COLS), BT_LF);
  add(_btLine('Date:', emissionDate, COLS), BT_LF);
  add(_btLine('Heure:', emissionHeure, COLS), BT_LF);
  add(_btSep(COLS), BT_LF);

  // Client
  if(data.clientCode) add(_btLine('Code:', data.clientCode, COLS), BT_LF);
  add(_btLine('Client:', (data.clientNom||''), COLS), BT_LF);
  add(_btSep(COLS), BT_LF);

  // Montant
  add(BT_ALIGN_CTR, BT_BOLD_ON);
  add(_btText(String(Number(data.montant||0)).replace(/\B(?=(\d{3})+(?!\d))/g,' ')+' FCFA'), BT_LF);
  add(BT_BOLD_OFF);
  if(data.type!=='adhesion'){
    add(_btText(`${data.nbCotis} cotis. x ${String(Number(data.cotisJour||0)).replace(/\B(?=(\d{3})+(?!\d))/g,' ')} FCFA`), BT_LF);
  }
  add(_btSep(COLS), BT_LF);

  // Saisi par
  add(BT_ALIGN_LEFT);
  add(_btLine('Saisi par:', (data.saisiParNom||''), COLS), BT_LF);
  if(agenceLabel && agenceLabel!=='—'){
    add(_btLine('Agence:', agenceLabel, COLS), BT_LF);
  }
  add(_btSep(COLS), BT_LF);

  // Pied de page
  add(BT_ALIGN_CTR, BT_BOLD_ON);
  add(_btText('Paiement enregistre'), BT_LF);
  add(BT_BOLD_OFF);
  add(_btText('Conservez ce recu'), BT_LF);
  add(_btText('preuve officielle'), BT_LF, BT_LF);

  // Coupe papier
  add(BT_CUT);

  // Fusionner
  let total=0; chunks.forEach(c=>total+=c.length);
  const result=new Uint8Array(total);
  let off=0; chunks.forEach(c=>{result.set(c,off);off+=c.length;});
  return result;
}

// ════════════════════════════════════════════════════
// SUIVI DE PÉRIODE — Gestionnaire de stock
// ════════════════════════════════════════════════════

let _gpCharts = {};

function _toISODate(d){ return d.toISOString().slice(0,10); }
function _fmtDate(s){ if(!s) return '—'; const d=new Date(s); return d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit',year:'numeric'}); }

window.setGperiodeShortcut = function(type, el){
  document.querySelectorAll('.gperiode-shortcut').forEach(b=>b.classList.remove('active'));
  if(el) el.classList.add('active');
  const now = new Date();
  let debut, fin = _toISODate(now);
  if(type==='semaine'){
    const day=now.getDay(), diff=(day===0?-6:1-day);
    const d=new Date(now); d.setDate(now.getDate()+diff);
    debut=_toISODate(d);
  } else if(type==='mois'){
    debut=_toISODate(new Date(now.getFullYear(),now.getMonth(),1));
  } else if(type==='trimestre'){
    debut=_toISODate(new Date(now.getFullYear(),Math.floor(now.getMonth()/3)*3,1));
  } else if(type==='semestre'){
    debut=_toISODate(new Date(now.getFullYear(),now.getMonth()<6?0:6,1));
  } else {
    debut=_toISODate(new Date(now.getFullYear(),0,1));
  }
  document.getElementById('gp-date-debut').value=debut;
  document.getElementById('gp-date-fin').value=fin;
  renderGstockPeriode();
};

function initGstockPeriode(){
  // Pré-remplir avec le mois en cours si vide
  const d=document.getElementById('gp-date-debut');
  const f=document.getElementById('gp-date-fin');
  if(!d.value){
    const now=new Date();
    d.value=_toISODate(new Date(now.getFullYear(),now.getMonth(),1));
    f.value=_toISODate(now);
    // Activer le raccourci "Ce mois"
    const btns=document.querySelectorAll('.gperiode-shortcut');
    if(btns[1]) btns[1].classList.add('active');
  }
  if(d.value) renderGstockPeriode();
}

window.renderGstockPeriode = function(){
  const debut_str = document.getElementById('gp-date-debut')?.value;
  const fin_str   = document.getElementById('gp-date-fin')?.value;
  const body = document.getElementById('gp-body');

  if(!debut_str||!fin_str){
    body.innerHTML='<div style="text-align:center;padding:40px;color:var(--muted);font-size:13px;">📅 Sélectionnez une date de début et une date de fin.</div>';
    return;
  }
  if(debut_str > fin_str){
    body.innerHTML='<div style="text-align:center;padding:40px;color:var(--danger);font-size:13px;">⚠️ La date de début doit être antérieure à la date de fin.</div>';
    return;
  }

  const debut = new Date(debut_str+'T00:00:00');
  const fin   = new Date(fin_str+'T23:59:59');

  // Badge
  const badge = document.getElementById('gp-periode-badge');
  const txt   = document.getElementById('gp-periode-txt');
  if(badge){ badge.style.display=''; }
  if(txt) txt.textContent = `${_fmtDate(debut_str)} → ${_fmtDate(fin_str)}`;

  // Filtrer les données
  const inP = (x) => {
    const ds = x.date || x.createdAt;
    if(!ds) return false;
    const d = new Date(ds); return d>=debut && d<=fin;
  };

  const mvts      = (DB.stockMvts||[]).filter(inP);
  const entrees   = mvts.filter(m=>m.type==='entree');
  const sorties   = mvts.filter(m=>m.type==='sortie');
  const livraisons= (DB.livraisons||[]).filter(inP);

  // Mouvements par article
  const parArticle = {};
  mvts.forEach(m=>{
    const a = (DB.articles||[]).find(x=>x._id===m.articleId);
    const nom = a?a.nom:`Art. ${m.articleId?.slice(-4)||'?'}`;
    if(!parArticle[m.articleId]) parArticle[m.articleId]={nom, entrees:0, sorties:0, qteEntree:0, qteSortie:0};
    if(m.type==='entree'){ parArticle[m.articleId].entrees++; parArticle[m.articleId].qteEntree+=(Number(m.qty)||0); }
    else                 { parArticle[m.articleId].sorties++; parArticle[m.articleId].qteSortie+=(Number(m.qty)||0); }
  });
  const artList = Object.values(parArticle).sort((a,b)=>(b.qteEntree+b.qteSortie)-(a.qteEntree+a.qteSortie));

  // Évolution journalière des mouvements
  const jours = {};
  mvts.forEach(m=>{
    const ds=(m.date||m.createdAt||'').slice(0,10);
    if(!ds) return;
    if(!jours[ds]) jours[ds]={e:0,s:0};
    if(m.type==='entree') jours[ds].e+=(Number(m.qty)||0);
    else jours[ds].s+=(Number(m.qty)||0);
  });
  const joursLabels=Object.keys(jours).sort();

  // Destinations des sorties
  const destMap = {};
  sorties.forEach(m=>{
    const k = m.destinationNom||m.destinationLibre||'Non spécifié';
    destMap[k]=(destMap[k]||0)+(Number(m.qty)||0);
  });

  // Livraisons par statut
  const livStatuts = {};
  livraisons.forEach(l=>{ const s=l.statut||'inconnu'; livStatuts[s]=(livStatuts[s]||0)+1; });

  // Détruire anciens charts
  Object.values(_gpCharts).forEach(c=>{try{c.destroy();}catch(e){}});
  _gpCharts={};

  body.innerHTML = `
    <!-- KPI GLOBAUX -->
    <div class="gperiode-section">
      <div class="gperiode-section-title">📊 Vue d'ensemble</div>
      <div class="gperiode-kpi-grid">
        <div class="gperiode-kpi green">
          <div class="gk-lbl">Entrées de stock</div>
          <div class="gk-val">${entrees.length} <span style="font-size:12px;font-weight:400;">mvt(s)</span></div>
        </div>
        <div class="gperiode-kpi red">
          <div class="gk-lbl">Sorties de stock</div>
          <div class="gk-val">${sorties.length} <span style="font-size:12px;font-weight:400;">mvt(s)</span></div>
        </div>
        <div class="gperiode-kpi">
          <div class="gk-lbl">Qté totale entrée</div>
          <div class="gk-val">${entrees.reduce((s,m)=>s+(Number(m.qty)||0),0)}</div>
        </div>
        <div class="gperiode-kpi red">
          <div class="gk-lbl">Qté totale sortie</div>
          <div class="gk-val">${sorties.reduce((s,m)=>s+(Number(m.qty)||0),0)}</div>
        </div>
        <div class="gperiode-kpi muted">
          <div class="gk-lbl">Articles concernés</div>
          <div class="gk-val">${artList.length}</div>
        </div>
        <div class="gperiode-kpi muted">
          <div class="gk-lbl">Livraisons</div>
          <div class="gk-val">${livraisons.length}</div>
        </div>
      </div>
    </div>

    <!-- GRAPHIQUE ÉVOLUTION -->
    <div class="gperiode-section">
      <div class="gperiode-section-title">📈 Évolution journalière (quantités)</div>
      ${joursLabels.length===0?'<div style="color:var(--muted);font-size:12px;padding:8px;">Aucun mouvement sur cette période.</div>':
        '<div class="gperiode-chart-wrap"><canvas id="gp-chart-evolution"></canvas></div>'}
    </div>

    <!-- MOUVEMENTS PAR ARTICLE -->
    <div class="gperiode-section">
      <div class="gperiode-section-title">📦 Mouvements par article</div>
      ${artList.length===0
        ? '<div style="color:var(--muted);font-size:12px;padding:8px;">Aucun mouvement sur cette période.</div>'
        : `<div class="tw"><table>
            <thead><tr><th>Article</th><th>Entrées (qté)</th><th>Sorties (qté)</th><th>Solde net</th></tr></thead>
            <tbody>${artList.map(a=>{
              const net = a.qteEntree - a.qteSortie;
              return `<tr>
                <td class="fw6">${esc(a.nom)}</td>
                <td style="color:var(--accent2);font-weight:700;">+${a.qteEntree} <span style="color:var(--muted);font-weight:400;font-size:10px;">(${a.entrees} mvt)</span></td>
                <td style="color:var(--danger);font-weight:700;">-${a.qteSortie} <span style="color:var(--muted);font-weight:400;font-size:10px;">(${a.sorties} mvt)</span></td>
                <td style="font-weight:700;color:${net>=0?'var(--accent2)':'var(--danger)'};">${net>=0?'+':''}${net}</td>
              </tr>`;
            }).join('')}</tbody>
          </table></div>`}
    </div>

    <!-- DESTINATIONS DES SORTIES -->
    <div class="gperiode-section">
      <div class="gperiode-section-title">📤 Destinations des sorties</div>
      ${Object.keys(destMap).length===0
        ? '<div style="color:var(--muted);font-size:12px;padding:8px;">Aucune sortie enregistrée sur cette période.</div>'
        : `<div class="gperiode-chart-wrap"><canvas id="gp-chart-dest"></canvas></div>
           <div class="tw" style="margin-top:10px;"><table>
             <thead><tr><th>Destination</th><th>Quantité sortie</th></tr></thead>
             <tbody>${Object.entries(destMap).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${esc(k)}</td><td style="font-weight:700;color:var(--warn);">${v}</td></tr>`).join('')}</tbody>
           </table></div>`}
    </div>

    <!-- LISTE DÉTAILLÉE DES MOUVEMENTS -->
    <div class="gperiode-section">
      <div class="gperiode-section-title" style="margin-bottom:8px;">📋 Détail des mouvements</div>
      <div style="display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap;">
        <input type="text" id="gp-search" placeholder="🔍 Filtrer article, note..."
          style="background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:5px 10px;color:var(--text);font-size:11px;outline:none;flex:1;min-width:150px;"
          oninput="filterGpMvts()">
        <select id="gp-type-filter"
          style="background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:5px 10px;color:var(--text);font-size:11px;outline:none;"
          onchange="filterGpMvts()">
          <option value="">Tous les types</option>
          <option value="entree">📥 Entrées seulement</option>
          <option value="sortie">📤 Sorties seulement</option>
        </select>
      </div>
      <div id="gp-mvts-table">
        ${_buildGpMvtsTable(mvts)}
      </div>
    </div>

    <!-- LIVRAISONS SUR LA PÉRIODE -->
    <div class="gperiode-section">
      <div class="gperiode-section-title">🚚 Livraisons sur la période</div>
      ${livraisons.length===0
        ? '<div style="color:var(--muted);font-size:12px;padding:8px;">Aucune livraison sur cette période.</div>'
        : `<div class="gperiode-kpi-grid" style="margin-bottom:10px;">
            ${Object.entries(livStatuts).map(([s,n])=>`<div class="gperiode-kpi muted"><div class="gk-lbl">${s}</div><div class="gk-val">${n}</div></div>`).join('')}
           </div>
           <div class="tw"><table>
             <thead><tr><th>Date</th><th>Client</th><th>Statut</th><th>Note</th></tr></thead>
             <tbody>${livraisons.slice().reverse().map(l=>{
               const cl=(DB.clients||[]).find(c=>c._id===l.clientId);
               return `<tr><td>${l.date||'—'}</td><td class="fw6">${cl?esc(cl.nom):'—'}</td><td>${l.statut||'—'}</td><td class="tm">${esc(l.note||'—')}</td></tr>`;
             }).join('')}</tbody>
           </table></div>`}
    </div>
  `;

  // Stocker mvts pour le filtre
  window._gpAllMvts = mvts;

  // Dessiner graphiques
  requestAnimationFrame(()=>{
    const warn='rgba(212,137,58,0.85)', green='rgba(56,201,160,0.85)', danger='rgba(224,92,82,0.85)';
    const gridColor='rgba(255,255,255,0.06)', tickColor='rgba(255,255,255,0.35)';

    // Graphique évolution
    const c1=document.getElementById('gp-chart-evolution');
    if(c1 && joursLabels.length){
      _gpCharts.evol=new Chart(c1.getContext('2d'),{
        type:'bar',
        data:{
          labels:joursLabels,
          datasets:[
            {label:'Entrées',data:joursLabels.map(j=>jours[j].e),backgroundColor:green,borderRadius:4,stack:'s'},
            {label:'Sorties',data:joursLabels.map(j=>jours[j].s),backgroundColor:danger,borderRadius:4,stack:'s2'}
          ]
        },
        options:{
          responsive:true,maintainAspectRatio:true,
          plugins:{legend:{labels:{color:tickColor,font:{size:10}}}},
          scales:{
            x:{ticks:{color:tickColor,font:{size:9},maxRotation:45},grid:{color:gridColor}},
            y:{ticks:{color:tickColor,font:{size:9}},grid:{color:gridColor}}
          }
        }
      });
    }

    // Graphique destinations
    const c2=document.getElementById('gp-chart-dest');
    if(c2 && Object.keys(destMap).length){
      const dkeys=Object.keys(destMap);
      const colors=[warn,'rgba(201,168,76,0.8)',danger,'rgba(100,130,200,0.8)','rgba(150,100,200,0.8)'];
      _gpCharts.dest=new Chart(c2.getContext('2d'),{
        type:'doughnut',
        data:{labels:dkeys,datasets:[{data:dkeys.map(k=>destMap[k]),backgroundColor:dkeys.map((_,i)=>colors[i%colors.length]),borderWidth:0}]},
        options:{responsive:true,plugins:{legend:{labels:{color:tickColor,font:{size:10}}}}}
      });
    }
  });
};

function _buildGpMvtsTable(mvts){
  if(!mvts.length) return '<div style="color:var(--muted);font-size:12px;padding:8px;">Aucun mouvement.</div>';
  return `<div class="tw"><table>
    <thead><tr><th>Date</th><th>Article</th><th>Type</th><th>Quantité</th><th>Stock après</th><th>Destination / Motif</th><th>Note</th></tr></thead>
    <tbody>${[...mvts].reverse().map(m=>{
      const a=(DB.articles||[]).find(x=>x._id===m.articleId)||{};
      const dest = m.type==='sortie'?(m.destinationNom||m.destinationLibre||'—'):'—';
      return `<tr>
        <td>${m.date||'—'}</td>
        <td class="fw6">${esc(a.nom||'?')}</td>
        <td>${m.type==='entree'?'<span style="background:rgba(56,201,160,0.15);color:var(--accent2);border-radius:5px;padding:2px 7px;font-size:10px;">📥 Entrée</span>':'<span style="background:rgba(224,92,82,0.15);color:var(--danger);border-radius:5px;padding:2px 7px;font-size:10px;">📤 Sortie</span>'}</td>
        <td style="font-weight:700;color:${m.type==='entree'?'var(--accent2)':'var(--danger)'};">${m.type==='entree'?'+':'-'}${m.qty} ${esc(a.unite||'')}</td>
        <td>${m.stockApres!=null?m.stockApres+' '+esc(a.unite||''):'—'}</td>
        <td style="font-size:11px;color:var(--subtle);">${esc(dest)}</td>
        <td class="tm" style="font-size:11px;">${esc(m.note||'—')}</td>
      </tr>`;
    }).join('')}</tbody>
  </table></div>`;
}

window.filterGpMvts = function(){
  const q=(document.getElementById('gp-search')?.value||'').toLowerCase().trim();
  const typ=document.getElementById('gp-type-filter')?.value||'';
  let mvts=window._gpAllMvts||[];
  if(typ) mvts=mvts.filter(m=>m.type===typ);
  if(q) mvts=mvts.filter(m=>{
    const a=(DB.articles||[]).find(x=>x._id===m.articleId)||{};
    return (a.nom||'').toLowerCase().includes(q)||(m.note||'').toLowerCase().includes(q)||(m.destinationNom||'').toLowerCase().includes(q)||(m.destinationLibre||'').toLowerCase().includes(q);
  });
  const wrap=document.getElementById('gp-mvts-table');
  if(wrap) wrap.innerHTML=_buildGpMvtsTable(mvts);
};

window.exportGstockCSV = function(){
  const debut_str=document.getElementById('gp-date-debut')?.value;
  const fin_str=document.getElementById('gp-date-fin')?.value;
  if(!debut_str||!fin_str){ notify('Sélectionnez une période d\'abord','err'); return; }
  const debut=new Date(debut_str+'T00:00:00'), fin=new Date(fin_str+'T23:59:59');
  const inP=(x)=>{ const ds=x.date||x.createdAt; if(!ds) return false; const d=new Date(ds); return d>=debut&&d<=fin; };
  const mvts=(DB.stockMvts||[]).filter(inP);
  const livraisons=(DB.livraisons||[]).filter(inP);

  let csv=`Suivi de période — ${_fmtDate(debut_str)} au ${_fmtDate(fin_str)}\n\n`;
  csv+=`MOUVEMENTS DE STOCK\nDate;Article;Type;Quantité;Stock après;Destination;Note\n`;
  mvts.forEach(m=>{
    const a=(DB.articles||[]).find(x=>x._id===m.articleId)||{};
    csv+=`${_csvCell(m.date||'')};${_csvCell(a.nom||'')};${_csvCell(m.type)};${m.qty};${m.stockApres!=null?m.stockApres:''};${_csvCell(m.destinationNom||m.destinationLibre||'')};${_csvCell(m.note||'')}\n`;
  });
  csv+=`\nLIVRAISONS\nDate;Client;Statut;Note\n`;
  livraisons.forEach(l=>{
    const cl=(DB.clients||[]).find(c=>c._id===l.clientId);
    csv+=`${_csvCell(l.date||'')};${_csvCell(cl?cl.nom:'')};${_csvCell(l.statut||'')};${_csvCell(l.note||'')}\n`;
  });

  const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download=`suivi_stock_${debut_str}_${fin_str}.csv`;
  a.click();
  notify('✅ Export CSV téléchargé','ok');
};

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 33 — RECOUVREMENTS PAR DATE ET PAR COMMERCIAL          ║
// ╚══════════════════════════════════════════════════════════════╝
// Un tableau croise : une ligne par jour du mois, une colonne par commercial,
// et dans chaque case ce que ce commercial a encaisse ce jour-la. Le rapport
// d'activite donne des totaux et des classements ; il ne disait pas QUI a
// encaisse QUOI, QUEL JOUR. C'est pourtant la question posee au controle :
// « le 14, Moise a verse combien ? » — et il fallait ouvrir sa fiche du jour,
// une date apres l'autre.
//
// ── CHARGEMENT A LA DEMANDE, STRICTEMENT ──
// Un mois de paiements, c'est ~30 agents x ~2 000 clients : potentiellement
// des dizaines de milliers de documents. Rien n'est lu tant que l'utilisateur
// n'a pas clique « Charger le mois ». Le bloc est meme replie par defaut.
//
// ── UNE SEULE REQUETE, SANS INDEX COMPOSITE ──
// On lit la periode avec _fetchPaiementsDateRange (where date >= / <=), un
// filtre sur un SEUL champ : l'index automatique de Firestore suffit. Les
// filtres agence et commercial sont ensuite appliques EN MEMOIRE, sur ce qui
// a deja ete lu — changer de filtre ne coute donc aucune lecture
// supplementaire. C'est la lecon du volet 31.
//
// ⚠️ RESERVE A L'ADMIN. La page entiere l'est deja, mais chaque fonction le
// revalide : un controle qui depend du seul affichage n'est pas un controle.

const _REC_DETAIL_ROLES = ['admin'];
let _recDetailData  = null;     // { mois, lignes:[{date, parCom:Map, total}], coms:[], total }
let _recDetailCle   = '';       // mois deja charge, pour ne pas relire inutilement

function _recDetailAutorise(){ return _REC_DETAIL_ROLES.includes(session?.role); }

// Bornes d'un mois 'AAAA-MM' → ['AAAA-MM-01', 'AAAA-MM-dernier'].
// On passe par Date(y, m, 0) qui donne le dernier jour du mois precedent,
// donc le nombre de jours du mois demande — annees bissextiles comprises,
// sans table en dur.
function _recDetailBornes(mois){
  const [y, m] = String(mois||'').split('-').map(Number);
  if(!y || !m || m < 1 || m > 12) return null;
  const dernier = new Date(y, m, 0).getDate();
  const p2 = n => String(n).padStart(2,'0');
  return { debut: `${y}-${p2(m)}-01`, fin: `${y}-${p2(m)}-${p2(dernier)}`, jours: dernier, y, m };
}

window.recDetailCharger = _withActionLock('recDetailCharger', async function(){
  if(!_recDetailAutorise()){ notify('Accès refusé', 'err'); return; }
  const mois = document.getElementById('rec-detail-mois')?.value || '';
  const b = _recDetailBornes(mois);
  if(!b){ notify('Choisissez un mois.', 'err'); return; }
  if(b.debut > TODAY){ notify('Ce mois est dans le futur — aucun recouvrement à afficher.', 'err'); return; }

  const etat = document.getElementById('rec-detail-etat');
  if(_recDetailCle === mois && _recDetailData){ renderRecDetail(); return; }   // deja en memoire

  if(etat) etat.textContent = '⏳ Lecture du mois…';
  try {
    if(!isOnline){
      notify("📵 Hors ligne — seules les données déjà présentes seront affichées.", 'err');
    } else {
      await _fetchPaiementsDateRange(b.debut, b.fin);
      // Les commerciaux et les agences sont necessaires pour nommer les
      // colonnes et filtrer : on s'assure qu'ils sont la.
      await ensureCollectionsLoaded(['commerciaux','agences']);
    }
    _recDetailCle = mois;
    _recDetailData = { mois, bornes: b };
    if(etat) etat.textContent = '';
  } catch(e){
    console.error('[rec-detail] chargement du mois', mois, e);
    if(etat) etat.textContent = '⚠️ ' + ((e && e.code) || 'erreur');
    notify("Le mois n'a pas pu être chargé : " + ((e && e.code) || e), 'err');
    return;
  }
  renderRecDetail();
});

// Construit le tableau croise a partir de ce qui est EN MEMOIRE. Aucune
// lecture : changer de filtre est instantane et gratuit.
function _recDetailCalculer(){
  const b = _recDetailData?.bornes;
  if(!b) return null;
  const nature  = document.getElementById('rec-detail-nature')?.value || 'cotisations';
  const agence  = document.getElementById('rec-detail-agence')?.value || '';
  // ── VOLET 34 ── filtre commercial. Comme les deux autres, il s'applique
  // EN MEMOIRE sur le mois deja lu : en changer ne coute aucune lecture.
  const comSeul = document.getElementById('rec-detail-com')?.value || '';

  // Perimetre des commerciaux affiches.
  let coms = (DB.commerciaux||[]).filter(c => c.role === ROLES.COMMERCIAL);
  if(agence)  coms = coms.filter(c => c.agenceId === agence);
  // ⚠️ Le commercial choisi est applique APRES l'agence, et il la surclasse
  // uniquement s'il en fait partie. Si l'utilisateur change d'agence alors
  // qu'un commercial d'une autre agence etait selectionne, le filtre
  // commercial ne doit pas ressusciter quelqu'un hors perimetre : le tableau
  // sort alors vide, ce qui est exact. _recDetailPeuplerComs() remet de toute
  // facon le selecteur a « Tous » dans ce cas.
  if(comSeul) coms = coms.filter(c => c._id === comSeul);
  coms = coms.slice().sort((a,b2)=>(a.nom||'').localeCompare(b2.nom||''));
  const comIds = new Set(coms.map(c=>c._id));

  // Sources selon la nature demandee. 'import_historique' et les transferts
  // sont ecartes comme partout ailleurs : ce ne sont pas des encaissements
  // du terrain.
  const sources = [['paiements', DB.paiements]];
  if(nature === 'tout'){
    sources.push(['adhesionPays', DB.adhesionPays]);
    sources.push(['rachatCarnetPays', DB.rachatCarnetPays]);
  }

  const parJour = new Map();          // 'AAAA-MM-JJ' → Map(comId → {montant, nb})
  const totauxCom = new Map();        // comId → {montant, nb}
  let totalGeneral = 0, nbGeneral = 0;

  for(const [nom, tableau] of sources){
    for(const d of (tableau||[])){
      const dt = d.date || '';
      if(dt < b.debut || dt > b.fin) continue;
      if(nom === 'paiements' && (d.origine === 'import_historique' || d.source === 'transfert')) continue;
      const cid = d.commercialId;
      if(!comIds.has(cid)) continue;
      const montant = Number(d.montant);
      if(!Number.isFinite(montant)) continue;     // volet 27 : jamais de NaN silencieux
      if(!parJour.has(dt)) parJour.set(dt, new Map());
      const jour = parJour.get(dt);
      const cur = jour.get(cid) || {montant:0, nb:0};
      cur.montant += montant; cur.nb += 1;
      jour.set(cid, cur);
      const tc = totauxCom.get(cid) || {montant:0, nb:0};
      tc.montant += montant; tc.nb += 1;
      totauxCom.set(cid, tc);
      totalGeneral += montant; nbGeneral += 1;
    }
  }

  // Une ligne par jour REELLEMENT travaille. Afficher les 31 jours dont 20
  // vides noierait l'information ; la case vide d'un jour ouvre reste
  // visible, puisque la colonne du commercial existe.
  const lignes = [...parJour.keys()].sort().map(dt => {
    const jour = parJour.get(dt);
    let total = 0, nb = 0;
    jour.forEach(v => { total += v.montant; nb += v.nb; });
    return { date: dt, parCom: jour, total, nb };
  });

  // On n'affiche que les commerciaux ayant encaisse au moins une fois : avec
  // 30 agents, 25 colonnes vides rendraient le tableau illisible.
  const comsActifs = coms.filter(c => totauxCom.has(c._id));

  return { lignes, coms: comsActifs, comsTous: coms, totauxCom, totalGeneral, nbGeneral,
           nature, agence, comSeul, bornes: b };
}

window.renderRecDetail = function(){
  if(!_recDetailAutorise()) return;
  const body = document.getElementById('rec-detail-body');
  if(!body) return;
  if(!_recDetailData){
    body.innerHTML = `<div class="emp" style="padding:26px;">Choisissez un mois puis cliquez <strong>⇣ Charger le mois</strong>.</div>`;
    return;
  }
  const r = _recDetailCalculer();
  if(!r){ body.innerHTML = '<div class="emp" style="padding:26px;">—</div>'; return; }

  const moisLbl = new Date(r.bornes.debut+'T12:00:00')
    .toLocaleDateString('fr-FR',{month:'long',year:'numeric'});

  if(!r.lignes.length){
    // ── VOLET 34 ── on nomme le ou les filtres actifs. « Aucun encaissement »
    // tout court laisse croire a une panne quand c'est un filtre qui restreint.
    const qui = r.comSeul
      ? ` pour ${esc((r.comsTous.find(c=>c._id===r.comSeul)||{}).nom || 'ce commercial')}`
      : (r.agence ? ` pour ${esc(getAgence(r.agence).nom||'cette agence')}` : '');
    body.innerHTML = `<div class="emp" style="padding:26px;">Aucun encaissement en ${esc(moisLbl)}${qui}.`
      + (r.nature !== 'tout' ? `<div style="margin-top:7px;font-size:11px;">Essayez la nature `
          + `<strong>« Cotisations + adhésions + rachats »</strong>.</div>` : '')
      + '</div>';
    return;
  }

  const jourLbl = dt => {
    const d = new Date(dt+'T12:00:00');
    return d.toLocaleDateString('fr-FR',{weekday:'short',day:'2-digit',month:'2-digit'});
  };

  const enTetes = r.coms.map(c =>
    `<th style="text-align:right;white-space:nowrap;font-size:10px;">${esc(c.nom||'—')}</th>`).join('');

  const corps = r.lignes.map(l => {
    const cases = r.coms.map(c => {
      const v = l.parCom.get(c._id);
      if(!v) return `<td style="text-align:right;color:var(--muted);opacity:.35;">·</td>`;
      return `<td style="text-align:right;white-space:nowrap;" title="${v.nb} encaissement(s)">`
        + `<span style="color:var(--accent2);font-weight:700;">${_fmtNum(v.montant)}</span></td>`;
    }).join('');
    const estDimanche = new Date(l.date+'T12:00:00').getDay() === 0;
    return `<tr${estDimanche?' style="background:rgba(255,255,255,0.025);"':''}>`
      + `<td class="fw6" style="white-space:nowrap;">${esc(jourLbl(l.date))}`
      + `<div style="font-size:9px;color:var(--muted);">${esc(l.date)}</div></td>`
      + cases
      + `<td style="text-align:right;font-weight:800;color:var(--accent);white-space:nowrap;">${_fmtNum(l.total)}</td>`
      + `<td style="text-align:center;color:var(--muted);font-size:11px;">${l.nb}</td></tr>`;
  }).join('');

  const pied = `<tr style="border-top:2px solid var(--border);">`
    + `<td class="fw6" style="color:var(--accent);">TOTAL</td>`
    + r.coms.map(c => {
        const t = r.totauxCom.get(c._id) || {montant:0};
        return `<td style="text-align:right;font-weight:800;color:var(--accent);white-space:nowrap;">${_fmtNum(t.montant)}</td>`;
      }).join('')
    + `<td style="text-align:right;font-weight:800;color:var(--accent2);white-space:nowrap;">${_fmtNum(r.totalGeneral)}</td>`
    + `<td style="text-align:center;font-weight:700;color:var(--muted);">${r.nbGeneral}</td></tr>`;

  const natureLbl = r.nature === 'tout'
    ? 'cotisations + adhésions + rachats' : 'cotisations seules';
  const masques = r.comsTous.length - r.coms.length;
  // ── VOLET 34 ── quand un seul commercial est demande, « 1 commercial(aux) »
  // ne dit pas LEQUEL. On le nomme, et on precise la moyenne par jour
  // travaille — le chiffre qu'on cherche quand on isole un agent.
  const unSeul = r.comSeul && r.coms.length === 1 ? r.coms[0] : null;
  const moyenne = unSeul && r.lignes.length
    ? Math.round(r.totalGeneral / r.lignes.length) : 0;

  body.innerHTML = `
    <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:baseline;margin-bottom:9px;font-size:11.5px;color:var(--muted);">
      <span><strong style="color:var(--text);">${esc(moisLbl)}</strong></span>
      <span>${r.lignes.length} jour(s) travaillé(s)</span>
      ${unSeul
        ? `<span>👤 <strong style="color:var(--accent);">${esc(unSeul.nom||'')}</strong>`
          + `<span style="opacity:.7;"> · ${esc(getAgence(unSeul.agenceId).nom||'—')}</span></span>`
          + `<span>moyenne ${_fmtNum(moyenne)} / jour travaillé</span>`
        : `<span>${r.coms.length} commercial(aux)${masques?` <span title="Commerciaux sans aucun encaissement sur la période — colonnes masquées pour garder le tableau lisible">(+${masques} sans encaissement)</span>`:''}</span>`}
      <span>${natureLbl}</span>
      <span style="color:var(--accent2);font-weight:700;">${_fmtMoney(r.totalGeneral)}</span>
    </div>
    <div class="tw" style="max-height:62vh;overflow:auto;"><table><thead><tr>
      <th style="white-space:nowrap;">Jour</th>${enTetes}
      <th style="text-align:right;">Total</th><th style="text-align:center;">Nb</th>
    </tr></thead><tbody>${corps}${pied}</tbody></table></div>
    <div style="margin-top:7px;font-size:10.5px;color:var(--muted);">
      Montants en FCFA. Un point « · » signifie aucun encaissement ce jour-là.
      Survolez une case pour voir le nombre d'encaissements.
    </div>`;
};

window.recDetailExportCSV = function(){
  if(!_recDetailAutorise()){ notify('Accès refusé', 'err'); return; }
  const r = _recDetailData ? _recDetailCalculer() : null;
  if(!r || !r.lignes.length){ notify('Rien à exporter — chargez d\'abord un mois.', 'err'); return; }
  // Separateur « ; » et BOM : c'est ce qu'attend Excel en configuration
  // francaise. Sans le BOM, les accents sortent illisibles.
  const esc2 = v => `"${String(v==null?'':v).replace(/"/g,'""')}"`;
  const lignes = [];
  lignes.push(['Date','Commercial','Agence','Montant','Nb encaissements'].map(esc2).join(';'));
  for(const l of r.lignes){
    for(const c of r.coms){
      const v = l.parCom.get(c._id);
      if(!v) continue;                       // on n'exporte pas les cases vides
      lignes.push([l.date, c.nom||'', getAgence(c.agenceId).nom||'', v.montant, v.nb].map(esc2).join(';'));
    }
  }
  // Le BOM (U+FEFF) est ce qui fait qu'Excel en configuration francaise
  // affiche correctement les accents. On l'ecrit par son code plutot que
  // comme un caractere invisible dans le source : un editeur ou un outil
  // de build peut supprimer un caractere invisible sans que personne ne
  // s'en apercoive, et l'export sortirait alors illisible.
  const BOM = String.fromCharCode(0xFEFF);
  const blob = new Blob([BOM+lignes.join('\n')], {type:'text/csv;charset=utf-8;'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  // ── VOLET 34 ── le nom du fichier porte le filtre : sans cela, deux
  // exports du meme mois pour deux commerciaux differents se recouvrent dans
  // le dossier Telechargements.
  const _suffixe = r.comSeul
    ? '_' + String((r.comsTous.find(c=>c._id===r.comSeul)||{}).nom || 'commercial')
        .normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9]+/g,'-').slice(0,40)
    : (r.agence ? '_' + String(getAgence(r.agence).nom||'agence')
        .normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9]+/g,'-').slice(0,40) : '');
  a.download = `recouvrements_${r.bornes.mois||r.bornes.debut.slice(0,7)}${_suffixe}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
  notify('✅ Export CSV téléchargé');
};

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 38 — PAGE « JOURNAL D'AUDIT » (ADMIN UNIQUEMENT)       ║
// ╚══════════════════════════════════════════════════════════════╝
// Qui a supprime quoi, quand, et pourquoi.
//
// ── LECTURE A LA DEMANDE, SUR UN SEUL CHAMP ──
// Une seule requete : where('horodatageJour','>=',d) + where('<=',f).
// Un SEUL champ filtre, donc l'index automatique de Firestore suffit —
// aucun index composite a deployer. C'est la lecon des volets 28 a 31,
// appliquee d'emblee. Tous les autres filtres (agence, commercial, type,
// auteur, recherche) s'appliquent ENSUITE en memoire : en changer ne coute
// aucune lecture.
//
// ⚠️ 'horodatageJour' (AAAA-MM-JJ, jour de la SUPPRESSION) n'existe que
// depuis ce volet. Les deux actions journalisees avant lui ne le portent pas :
// pour elles, on se rabat sur 'horodatage' (ISO complet), en memoire, et
// elles sont signalees « antérieur » dans la liste. Rien n'est perdu, et
// l'incertitude est affichee plutot que masquee.
//
// ── DEUX DATES, A NE JAMAIS CONFONDRE ──
//   horodatage → QUAND la suppression a eu lieu
//   date       → la date du DOCUMENT supprime (un paiement du 14/09 peut
//                etre efface le 02/10)
// Les deux colonnes sont affichees cote a cote, etiquetees sans ambiguite.

const _AUDIT_ROLES = ['admin'];
function _auditAutorise(){ return _AUDIT_ROLES.includes(session?.role); }

let _auditData = null;      // tableau des entrees chargees
let _auditCle  = '';        // periode deja chargee

window.renderAudit = function(){
  if(!_auditAutorise()) return;
  const selAg = document.getElementById('audit-agence');
  if(selAg){
    const ags = (DB.agences||[]).slice().sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
    const sig = ags.map(a=>a._id).join(',');
    if(selAg.dataset.sig !== sig){
      const prev = selAg.value;
      selAg.innerHTML = '<option value="">Toutes les agences</option>'
        + ags.map(a=>`<option value="${esc(a._id)}">${esc(a.nom||'(sans nom)')}</option>`).join('');
      selAg.dataset.sig = sig;
      if(prev && ags.some(a=>a._id===prev)) selAg.value = prev;
    }
  }
  const selType = document.getElementById('audit-type');
  if(selType && !selType.dataset.rempli){
    selType.innerHTML = '<option value="">Tous les types</option>'
      + Object.entries(_AUDIT_TYPES).sort((a,b)=>a[1].libelle.localeCompare(b[1].libelle))
          .map(([col,c])=>`<option value="${esc(col)}">${esc(c.libelle)}</option>`).join('');
    selType.dataset.rempli = '1';
  }
  const d = document.getElementById('audit-date-debut');
  const f = document.getElementById('audit-date-fin');
  if(d && !d.value){
    const il30 = new Date(Date.now() - 30*86400000).toISOString().slice(0,10);
    d.value = il30; f.value = TODAY;
  }
  if(d) d.max = TODAY;
  if(f) f.max = TODAY;
  _auditPeuplerListes();
  _auditRendre();
};

// Commerciaux et auteurs : construits a partir des entrees REELLEMENT
// chargees, jamais d'une liste figee — un utilisateur supprime depuis doit
// rester selectionnable, sinon ses suppressions deviennent introuvables.
function _auditPeuplerListes(){
  const remplir = (id, paires, vide) => {
    const sel = document.getElementById(id);
    if(!sel) return;
    const sig = paires.map(p=>p[0]).join(',');
    if(sel.dataset.sig === sig) return;
    const prev = sel.value;
    sel.innerHTML = `<option value="">${vide}</option>`
      + paires.sort((a,b)=>a[1].localeCompare(b[1]))
          .map(([id2,nom])=>`<option value="${esc(id2)}">${esc(nom)}</option>`).join('');
    sel.dataset.sig = sig;
    sel.value = paires.some(p=>p[0]===prev) ? prev : '';
  };
  const entrees = _auditData || [];
  const coms = new Map(), auteurs = new Map();
  entrees.forEach(e=>{
    if(e.commercialId) coms.set(e.commercialId, e.commercialNom || e.commercialId);
    if(e.effectuePar)  auteurs.set(e.effectuePar, e.effectueParNom || e.effectuePar);
  });
  remplir('audit-commercial', [...coms.entries()],    'Tous les commerciaux');
  remplir('audit-auteur',     [...auteurs.entries()], 'Tous les auteurs');
}

window.auditCharger = _withActionLock('auditCharger', async function(){
  if(!_auditAutorise()){ notify('Accès refusé', 'err'); return; }
  const d = document.getElementById('audit-date-debut')?.value || '';
  const f = document.getElementById('audit-date-fin')?.value || '';
  const etat = document.getElementById('audit-etat');
  if(!d || !f){ notify('Renseignez les deux dates.', 'err'); return; }
  if(d > f){ notify('La date de début est postérieure à la date de fin.', 'err'); return; }
  const cle = d + ':' + f;
  if(_auditCle === cle && _auditData){ _auditRendre(); return; }
  if(!isOnline){ notify('📵 Hors ligne — le journal ne peut pas être lu.', 'err'); return; }
  if(!db_fs){ notify('Mode local — journal indisponible.', 'err'); return; }

  if(etat) etat.textContent = '⏳ Lecture du journal…';
  try {
    // Un seul champ filtre : aucun index composite requis.
    const snap = await getDocs(query(collection(db_fs,'auditLog'),
      where('horodatageJour','>=', d), where('horodatageJour','<=', f)));
    const recentes = snap.docs.map(x => ({...x.data(), _id: x.id}));

    // Les entrees anterieures au volet 38 n'ont pas 'horodatageJour'. Elles
    // sont invisibles a la requete ci-dessus : on les recupere separement et
    // on les filtre en memoire sur 'horodatage'. Sans cela, le journal
    // paraitrait vide avant le 06/10 — et on en conclurait a tort qu'il ne
    // s'est rien passe.
    let anciennes = [];
    try {
      const snapA = await getDocs(query(collection(db_fs,'auditLog'),
        where('horodatage','>=', d), where('horodatage','<=', f + 'T23:59:59.999Z')));
      anciennes = snapA.docs.map(x => ({...x.data(), _id: x.id}))
        .filter(e => !e.horodatageJour);
    } catch(e){
      console.warn('[audit] entrées antérieures non relues :', e);
    }

    const parId = new Map();
    [...recentes, ...anciennes].forEach(e => parId.set(e._id, e));
    _auditData = [...parId.values()].map(_auditNormaliser).sort((a,b)=>
      String(b.horodatage||'').localeCompare(String(a.horodatage||'')));
    _auditCle = cle;
    if(etat) etat.textContent = '';
  } catch(e){
    console.error('[audit] lecture', e);
    if(etat) etat.textContent = '⚠️ ' + ((e && e.code) || 'erreur');
    notify("Le journal n'a pas pu être lu : " + ((e && e.code) || e), 'err');
    return;
  }
  _auditPeuplerListes();
  _auditRendre();
});

// ── VOLET 40 ── Les entrées écrites par delPaiementVerrouille et
// supprimerRachatCarnet AVANT ce volet n'ont ni 'collection', ni 'agenceId',
// ni 'typeLibelle' : le filtre Type les excluait toujours, le filtre Agence
// aussi. On complète EN MÉMOIRE (rien n'est réécrit : le journal est en
// ajout seul). L'agence ainsi déduite est celle ACTUELLE du commercial,
// d'où la marque _agenceDeduite affichée dans la liste.
const _AUDIT_ACTIONS_ANCIENNES = {
  suppression_paiement_verrouille: 'paiements',
  suppression_rachat_carnet:       'rachatCarnetPays'
};
function _auditNormaliser(e){
  const o = {...e};
  if(!o.collection){
    o.collection = _AUDIT_ACTIONS_ANCIENNES[o.action]
      || (String(o.action||'').startsWith('suppression_') ? String(o.action).slice(12) : '');
  }
  if(!o.typeLibelle && o.collection) o.typeLibelle = _auditLibelle(o.collection);
  if(!o.documentId) o.documentId = o.paiementId || o.rachatId || '';
  if(!o.agenceId && o.commercialId){
    const ag = _auditAgence({commercialId: o.commercialId});
    if(ag){ o.agenceId = ag; o._agenceDeduite = true; }
  }
  if(o.date === '—') o.date = '';
  if(o.heure === '—') o.heure = '';
  return o;
}

function _auditFiltrer(){
  const g = id => document.getElementById(id)?.value || '';
  const agence = g('audit-agence'), com = g('audit-commercial');
  const type = g('audit-type'), auteur = g('audit-auteur');
  const q = g('audit-recherche').toLowerCase().trim();
  const dDoc = g('audit-doc-debut'), fDoc = g('audit-doc-fin');
  return (_auditData || []).filter(e => {
    if(agence && e.agenceId !== agence) return false;
    if(com    && e.commercialId !== com) return false;
    if(type   && e.collection !== type) return false;
    if(auteur && e.effectuePar !== auteur) return false;
    // Filtre sur la date du DOCUMENT supprimé — distinct de la date de
    // suppression. Une entrée sans date de document est exclue dès qu'il est
    // actif : on ne peut pas savoir si elle y entre.
    if(dDoc && !(e.date && e.date >= dDoc)) return false;
    if(fDoc && !(e.date && e.date <= fDoc)) return false;
    if(q){
      const foin = [e.clientNom, e.clientCode, e.commercialNom, e.effectueParNom,
        e.motif, e.libelleCourt, e.typeLibelle, e.note, String(e.montant||'')]
        .join(' ').toLowerCase();
      if(!foin.includes(q)) return false;
    }
    return true;
  });
}

window._auditRendre = function(){ _auditRendre(); };

// ── VOLET 40 ── changer une date de la période rechargeait RIEN : seul le
// bouton « Charger » lisait le journal, et l'en-tête affichait pourtant les
// nouvelles dates au-dessus des anciennes données. Désormais la période se
// recharge d'elle-même dès que les deux dates sont valides (une lecture par
// période : le cache _auditCle évite toute relecture inutile).
window.auditPeriodeChangee = function(){
  const d = document.getElementById('audit-date-debut')?.value || '';
  const f = document.getElementById('audit-date-fin')?.value || '';
  if(!d || !f || d > f){
    const etat = document.getElementById('audit-etat');
    if(etat) etat.textContent = (d && f && d > f) ? '⚠️ Début postérieur à la fin' : '';
    return;
  }
  return window.auditCharger();
};

function _auditRendre(){
  const body = document.getElementById('audit-body');
  const kpi  = document.getElementById('audit-kpi');
  if(!body) return;
  if(!_auditData){
    body.innerHTML = `<div class="emp" style="padding:28px;">Choisissez une période puis cliquez <strong>⇣ Charger le journal</strong>.</div>`;
    if(kpi) kpi.innerHTML = '';
    return;
  }
  const liste = _auditFiltrer();

  const montantTotal = liste.reduce((a,e)=>a+(Number(e.montant)||0),0);
  const auteurs = new Set(liste.map(e=>e.effectueParNom||e.effectuePar).filter(Boolean));
  const sansMotif = liste.filter(e=>!(e.motif||'').trim()).length;
  if(kpi) kpi.innerHTML = `
    <div class="kpi-card kc-red"><div class="kpi-lbl">Suppressions</div><div class="kpi-val kv-red">${liste.length}</div></div>
    <div class="kpi-card kc-yellow"><div class="kpi-lbl">Montant effacé</div><div class="kpi-val kv-yellow">${fmt(montantTotal)}</div><div class="kpi-sub">somme des montants tracés</div></div>
    <div class="kpi-card kc-blue"><div class="kpi-lbl">Auteurs</div><div class="kpi-val kv-blue">${auteurs.size}</div></div>
    <div class="kpi-card"><div class="kpi-lbl">Sans motif</div><div class="kpi-val">${sansMotif}</div><div class="kpi-sub">motif facultatif non renseigné</div></div>`;

  if(!liste.length){
    body.innerHTML = `<div class="emp" style="padding:28px;">Aucune suppression ne correspond à ces filtres.</div>`;
    return;
  }

  const cap = (typeof _HIST_RENDER_CAP === 'number') ? _HIST_RENDER_CAP : 300;
  const tronque = liste.length > cap;
  const bandeau = tronque
    ? `<tr><td colspan="8" style="text-align:center;padding:10px;font-size:11px;color:var(--muted);background:rgba(247,201,79,0.08);">⚠️ Affichage limité aux ${cap} entrées les plus récentes sur ${liste.length} — affinez la période ou les filtres. <strong>L'export CSV, lui, contient tout.</strong></td></tr>`
    : '';

  body.innerHTML = `
    <div style="margin-bottom:8px;font-size:11.5px;color:var(--muted);">
      ${liste.length} entrée(s) sur ${_auditData.length} chargée(s) · suppressions du ${esc(_auditCle.split(':')[0]||'')} au ${esc(_auditCle.split(':')[1]||'')}
    </div>
    <div class="tw" style="max-height:62vh;overflow:auto;"><table><thead><tr>
      <th>Supprimé le</th><th>Type</th><th>Élément</th>
      <th style="text-align:right;">Montant</th><th>Date du document</th>
      <th>Commercial · Agence</th><th>Par</th><th>Motif</th>
    </tr></thead><tbody>${bandeau + (tronque?liste.slice(0,cap):liste).map(e=>{
      const h = String(e.horodatage||'');
      const quand = h ? `${esc(h.slice(0,10))}<div style="font-size:9px;color:var(--muted);">${esc(h.slice(11,16))}</div>` : '—';
      const ancien = !e.horodatageJour
        ? ` <span title="Entrée antérieure au journal complet — certains champs peuvent manquer" style="font-size:9px;background:rgba(255,255,255,0.06);border:1px solid var(--border);border-radius:8px;padding:0 5px;color:var(--muted);">antérieur</span>`
        : '';
      const ag = (e.agenceNom || (e.agenceId ? (getAgence(e.agenceId).nom||'—') : ''))
        + (e._agenceDeduite ? ' (agence actuelle)' : '');
      return `<tr>
        <td class="tm" style="white-space:nowrap;">${quand}</td>
        <td><span class="sb sy">${esc(e.typeLibelle || e.collection || '—')}</span>${ancien}</td>
        <td class="fw6" style="font-size:11.5px;">${esc(e.libelleCourt || e.clientNom || e.documentId || '—')}
          ${e.clientCode?`<div style="font-size:9px;color:var(--accent);">${esc(e.clientCode)}</div>`:''}</td>
        <td style="text-align:right;white-space:nowrap;${Number(e.montant)?'color:var(--danger);font-weight:700;':'color:var(--muted);'}">${Number(e.montant)?fmt(e.montant):'—'}</td>
        <td class="tm" style="font-size:11px;white-space:nowrap;">${esc(e.date||'—')}${e.heure?`<div style="font-size:9px;color:var(--muted);">${esc(e.heure)}</div>`:''}</td>
        <td style="font-size:11px;">${esc(e.commercialNom||'—')}${ag?`<div style="font-size:9px;color:var(--muted);">${esc(ag)}</div>`:''}</td>
        <td style="font-size:11px;">${esc(e.effectueParNom||'—')}${e.effectueParRole?`<div style="font-size:9px;color:var(--muted);">${esc(e.effectueParRole)}</div>`:''}</td>
        <td style="font-size:11px;max-width:240px;">${e.motif?`<span style="font-style:italic;">${esc(e.motif)}</span>`:'<span style="color:var(--muted);">—</span>'}</td>
      </tr>`;
    }).join('')}</tbody></table></div>`;
}

window.auditExportCSV = function(){
  if(!_auditAutorise()){ notify('Accès refusé', 'err'); return; }
  const liste = _auditData ? _auditFiltrer() : [];
  if(!liste.length){ notify("Rien à exporter — chargez d'abord une période.", 'err'); return; }
  const e2 = v => `"${String(v==null?'':v).replace(/"/g,'""')}"`;
  const cols = [['Supprimé le','horodatage'],['Type','typeLibelle'],['Élément','libelleCourt'],
    ['Identifiant','documentId'],['Client','clientNom'],['Code client','clientCode'],
    ['Montant','montant'],['Date du document','date'],['Heure du document','heure'],
    ['Commercial','commercialNom'],['Agence','agenceNom'],
    ['Supprimé par','effectueParNom'],['Rôle','effectueParRole'],['Motif','motif'],['Note','note']];
  const lignes = [cols.map(c=>e2(c[0])).join(';')];
  liste.forEach(e => lignes.push(cols.map(c=>e2(e[c[1]])).join(';')));
  const BOM = String.fromCharCode(0xFEFF);
  const blob = new Blob([BOM + lignes.join('\n')], {type:'text/csv;charset=utf-8;'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `journal_audit_${(_auditCle||'').replace(':','_')}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
  notify(`✅ ${liste.length} entrée(s) exportée(s)`);
};

window.auditResetFiltres = function(){
  ['audit-agence','audit-commercial','audit-type','audit-auteur','audit-recherche',
   'audit-doc-debut','audit-doc-fin'].forEach(id=>{
    const el = document.getElementById(id); if(el) el.value = '';
  });
  _auditRendre();
};

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 39 — ECRAN « ERREURS APPLICATIVES » (ADMIN)            ║
// ╚══════════════════════════════════════════════════════════════╝
// La collection 'logs_erreurs_app' etait ecrite depuis des mois et AUCUN
// ecran ne la lisait : pour voir une panne, il fallait ouvrir la console
// Firebase. Exactement la situation ou etait 'auditLog' avant le volet 38.
//
// ── REGROUPEMENT PAR MESSAGE ──
// Afficher 200 lignes brutes ne dit rien. Ce qui compte, c'est : « quelle
// panne revient, chez combien d'agents, depuis quand, et est-elle corrigee ? »
// L'ecran regroupe donc par message, et n'ouvre le detail qu'a la demande.
//
// ── UNE SEULE REQUETE, UN SEUL CHAMP ──
// where('createdAt','>=',…) + where('<=',…) : aucun index composite.
// Les filtres (page, agent, type, version) s'appliquent ensuite en memoire.

const _ERR_ROLES = ['admin'];
function _errAutorise(){ return _ERR_ROLES.includes(session?.role); }

let _errData = null, _errCle = '', _errGroupeOuvert = null;

window.renderErreurs = function(){
  if(!_errAutorise()) return;
  const d = document.getElementById('err-date-debut');
  const f = document.getElementById('err-date-fin');
  if(d && !d.value){
    d.value = new Date(Date.now() - 7*86400000).toISOString().slice(0,10);
    f.value = TODAY;
  }
  if(d) d.max = TODAY;
  if(f) f.max = TODAY;
  _errMajBandeauTelemesure();
  _errPeuplerFiltres();
  _errRendre();
};

// Etat de la telemesure, en tete d'ecran. Sans cela, une collection vide
// signifierait indifferemment « aucune panne » ou « rien n'est enregistre ».
function _errMajBandeauTelemesure(){
  const el = document.getElementById('err-telemesure');
  if(!el) return;
  const e = (typeof _errLogEtat === 'function') ? _errLogEtat() : {ok:null, texte:'—'};
  const couleur = e.ok === false ? 'var(--danger)' : e.ok === true ? 'var(--accent2)' : 'var(--muted)';
  const bord    = e.ok === false ? 'rgba(224,92,82,0.45)' : 'var(--border)';
  const icone   = e.ok === false ? '⛔' : e.ok === true ? '✅' : 'ℹ️';
  el.style.borderColor = bord;
  el.innerHTML = `<span style="color:${couleur};font-weight:700;">${icone} ${esc(e.texte)}</span>`
    + `<span style="color:var(--muted);"> · version en cours : <strong>${esc(typeof APP_VERSION!=='undefined'?APP_VERSION:'?')}</strong></span>`
    + (e.ok === false
        ? `<div style="margin-top:5px;font-weight:400;color:var(--muted);">Une collection vide ne signifie alors <strong>pas</strong> qu'il n'y a pas eu de panne : vérifiez la règle Firestore <code>logs_erreurs_app</code>.</div>`
        : '');
}

function _errPeuplerFiltres(){
  const remplir = (id, valeurs, vide) => {
    const sel = document.getElementById(id);
    if(!sel) return;
    const sig = valeurs.join(',');
    if(sel.dataset.sig === sig) return;
    const prev = sel.value;
    sel.innerHTML = `<option value="">${vide}</option>`
      + valeurs.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');
    sel.dataset.sig = sig;
    sel.value = valeurs.includes(prev) ? prev : '';
  };
  const d = _errData || [];
  remplir('err-page',    [...new Set(d.map(e=>e.page).filter(Boolean))].sort(), 'Toutes les pages');
  remplir('err-agent',   [...new Set(d.map(e=>e.commercialNom).filter(Boolean))].sort(), 'Tous les utilisateurs');
  remplir('err-version', [...new Set(d.map(e=>e.appVersion||'(avant v39)'))].sort(), 'Toutes les versions');
}

window.errCharger = _withActionLock('errCharger', async function(){
  if(!_errAutorise()){ notify('Accès refusé','err'); return; }
  const d = document.getElementById('err-date-debut')?.value || '';
  const f = document.getElementById('err-date-fin')?.value || '';
  const etat = document.getElementById('err-etat');
  if(!d || !f){ notify('Renseignez les deux dates.','err'); return; }
  if(d > f){ notify('La date de début est postérieure à la date de fin.','err'); return; }
  const cle = d+':'+f;
  if(_errCle === cle && _errData){ _errRendre(); return; }
  if(!isOnline){ notify('📵 Hors ligne — les erreurs ne peuvent pas être lues.','err'); return; }
  if(!db_fs){ notify('Mode local — indisponible.','err'); return; }

  if(etat) etat.textContent = '⏳ Lecture…';
  try {
    // createdAt est un Timestamp serveur : on borne avec des Timestamp, pas
    // des chaines, sinon la comparaison ne porterait sur rien.
    const t0 = Timestamp.fromDate(new Date(d + 'T00:00:00'));
    const t1 = Timestamp.fromDate(new Date(f + 'T23:59:59.999'));
    const snap = await getDocs(query(collection(db_fs,'logs_erreurs_app'),
      where('createdAt','>=', t0), where('createdAt','<=', t1)));
    _errData = snap.docs.map(x=>({...x.data(), _id:x.id}))
      .sort((a,b)=> (b.createdAt?.seconds||0) - (a.createdAt?.seconds||0));
    _errCle = cle;
    if(etat) etat.textContent = '';
  } catch(e){
    console.error('[erreurs] lecture', e);
    if(etat) etat.textContent = '⚠️ ' + ((e && e.code) || 'erreur');
    notify("Les erreurs n'ont pas pu être lues : " + ((e && e.code) || e), 'err');
    return;
  }
  _errPeuplerFiltres();
  _errRendre();
});

function _errFiltrer(){
  const g = id => document.getElementById(id)?.value || '';
  const page = g('err-page'), agent = g('err-agent'), type = g('err-type'), ver = g('err-version');
  const q = g('err-recherche').toLowerCase().trim();
  return (_errData||[]).filter(e=>{
    if(page  && e.page !== page) return false;
    if(agent && e.commercialNom !== agent) return false;
    if(type  && e.type !== type) return false;
    if(ver   && (e.appVersion||'(avant v39)') !== ver) return false;
    if(q && !((e.message||'')+' '+(e.stack||'')+' '+(e.page||'')).toLowerCase().includes(q)) return false;
    return true;
  });
}
window._errRendre = function(){ _errRendre(); };

// Normalise un message pour regrouper ce qui est la MEME panne : les
// identifiants, nombres et URL varient d'une occurrence a l'autre sans rien
// changer a la cause. Sans cela, une seule panne apparaitrait 40 fois.
function _errSignature(msg){
  return String(msg||'(sans message)')
    .replace(/https?:\/\/\S+/g, '<url>')
    .replace(/\b[0-9a-f]{16,}\b/gi, '<id>')
    .replace(/\d+/g, '<n>')
    .slice(0, 160);
}

function _errRendre(){
  const body = document.getElementById('err-body');
  const kpi  = document.getElementById('err-kpi');
  if(!body) return;
  _errMajBandeauTelemesure();
  if(!_errData){
    body.innerHTML = `<div class="emp" style="padding:28px;">Choisissez une période puis cliquez <strong>⇣ Charger</strong>.</div>`;
    if(kpi) kpi.innerHTML = '';
    return;
  }
  const liste = _errFiltrer();

  const groupes = new Map();
  liste.forEach(e=>{
    const sig = _errSignature(e.message);
    if(!groupes.has(sig)) groupes.set(sig, {
      sig, exemple:e, nb:0, agents:new Set(), pages:new Set(), versions:new Set(),
      premier:null, dernier:null, entrees:[]
    });
    const g = groupes.get(sig);
    g.nb++;
    if(e.commercialNom) g.agents.add(e.commercialNom);
    if(e.page) g.pages.add(e.page);
    g.versions.add(e.appVersion || '(avant v39)');
    const s = e.createdAt?.seconds || 0;
    if(s){ if(!g.premier || s < g.premier) g.premier = s; if(!g.dernier || s > g.dernier) g.dernier = s; }
    g.entrees.push(e);
  });
  const rangs = [...groupes.values()].sort((a,b)=> b.nb - a.nb || (b.dernier||0)-(a.dernier||0));

  const agents = new Set(liste.map(e=>e.commercialNom).filter(Boolean));
  if(kpi) kpi.innerHTML = `
    <div class="kpi-card kc-red"><div class="kpi-lbl">Occurrences</div><div class="kpi-val kv-red">${liste.length}</div></div>
    <div class="kpi-card kc-yellow"><div class="kpi-lbl">Pannes distinctes</div><div class="kpi-val kv-yellow">${rangs.length}</div><div class="kpi-sub">messages regroupés</div></div>
    <div class="kpi-card kc-blue"><div class="kpi-lbl">Utilisateurs touchés</div><div class="kpi-val kv-blue">${agents.size}</div></div>
    <div class="kpi-card"><div class="kpi-lbl">Plafond par session</div><div class="kpi-val">20</div><div class="kpi-sub">au-delà, un appareil cesse d'envoyer</div></div>`;

  if(!liste.length){
    body.innerHTML = `<div class="emp" style="padding:28px;">Aucune erreur sur cette période avec ces filtres.</div>`;
    return;
  }

  const dt = s => s ? new Date(s*1000).toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}) : '—';

  body.innerHTML = rangs.map((g,i)=>{
    const ouvert = _errGroupeOuvert === g.sig;
    const corrigee = g.versions.size === 1 && !g.versions.has(APP_VERSION) && !g.versions.has('(avant v39)');
    return `<div style="border:1px solid var(--border);border-radius:10px;margin-bottom:9px;background:var(--card);overflow:hidden;">
      <div role="button" tabindex="0" onclick="errBasculerGroupe('${esc(g.sig).replace(/'/g,"\\'")}')"
           onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();errBasculerGroupe('${esc(g.sig).replace(/'/g,"\\'")}');}"
           style="padding:11px 13px;cursor:pointer;display:flex;gap:11px;align-items:flex-start;">
        <span style="color:var(--accent);font-size:12px;width:12px;flex-shrink:0;">${ouvert?'▾':'▸'}</span>
        <div style="flex:1;min-width:0;">
          <div style="font-family:'Space Grotesk',monospace;font-size:11.5px;color:var(--text);word-break:break-word;">${esc(g.exemple.message||'(sans message)')}</div>
          <div style="margin-top:5px;font-size:10.5px;color:var(--muted);display:flex;gap:12px;flex-wrap:wrap;">
            <span><strong style="color:var(--danger);">${g.nb}</strong> fois</span>
            <span>${g.agents.size} utilisateur(s)</span>
            <span>pages : ${esc([...g.pages].join(', ')||'—')}</span>
            <span>versions : ${esc([...g.versions].join(', '))}</span>
            <span>${dt(g.premier)} → ${dt(g.dernier)}</span>
            ${corrigee?`<span title="Cette panne n'a jamais été vue sur la version actuellement déployée" style="color:var(--accent2);font-weight:700;">✅ plus vue depuis</span>`:''}
          </div>
        </div>
      </div>
      ${ouvert ? `<div style="border-top:1px solid var(--border);padding:11px 13px;background:rgba(0,0,0,0.18);">
        <div style="font-size:10.5px;color:var(--muted);margin-bottom:7px;">${g.entrees.length} occurrence(s) — ${Math.min(g.entrees.length,10)} affichée(s)</div>
        ${g.entrees.slice(0,10).map(e=>`<div style="margin-bottom:9px;padding-bottom:9px;border-bottom:1px solid rgba(42,49,66,0.5);">
          <div style="font-size:10.5px;color:var(--muted);">${esc(dt(e.createdAt?.seconds))} · ${esc(e.commercialNom||'—')} · page ${esc(e.page||'—')} · ${esc(e.type||'—')} · ${esc(e.appVersion||'(avant v39)')} · ${e.online?'en ligne':'hors ligne'}</div>
          ${e.stack?`<pre style="margin:5px 0 0;padding:7px;background:rgba(0,0,0,0.3);border-radius:6px;font-size:10px;color:var(--muted);white-space:pre-wrap;word-break:break-word;max-height:150px;overflow:auto;">${esc(e.stack)}</pre>`:''}
          <div style="font-size:9.5px;color:var(--muted);opacity:.7;margin-top:4px;">${esc((e.userAgent||'').slice(0,120))}</div>
        </div>`).join('')}
      </div>` : ''}
    </div>`;
  }).join('');
}

window.errBasculerGroupe = function(sig){
  _errGroupeOuvert = (_errGroupeOuvert === sig) ? null : sig;
  _errRendre();
};

window.errResetFiltres = function(){
  ['err-page','err-agent','err-type','err-version','err-recherche'].forEach(id=>{
    const el = document.getElementById(id); if(el) el.value = '';
  });
  _errGroupeOuvert = null;
  _errRendre();
};

window.errExportCSV = function(){
  if(!_errAutorise()){ notify('Accès refusé','err'); return; }
  const liste = _errData ? _errFiltrer() : [];
  if(!liste.length){ notify("Rien à exporter — chargez d'abord une période.",'err'); return; }
  const e2 = v => `"${String(v==null?'':v).replace(/"/g,'""')}"`;
  const lignes = [['Date','Type','Message','Page','Utilisateur','Version','En ligne','Appareil','Trace']
    .map(e2).join(';')];
  liste.forEach(e=>lignes.push([
    e.createdAt?.seconds ? new Date(e.createdAt.seconds*1000).toISOString() : '',
    e.type||'', e.message||'', e.page||'', e.commercialNom||'',
    e.appVersion||'(avant v39)', e.online?'oui':'non',
    (e.userAgent||'').slice(0,160), (e.stack||'').slice(0,800)
  ].map(e2).join(';')));
  const BOM = String.fromCharCode(0xFEFF);
  const blob = new Blob([BOM+lignes.join('\n')], {type:'text/csv;charset=utf-8;'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `erreurs_${document.getElementById('err-date-debut').value}_${document.getElementById('err-date-fin').value}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
  notify(`✅ ${liste.length} ligne(s) exportée(s)`);
};

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 39 — SANTE DES DONNEES (ADMIN)                         ║
// ╚══════════════════════════════════════════════════════════════╝
// Les filets existants attrapent les erreurs TECHNIQUES. Aucun ne voyait les
// anomalies METIER — et ce sont elles qui ont coute le plus de temps :
//   · la saisie post-datee du 29/09, invisible pendant deux mois et demi ;
//   · un montant en chaine de caracteres qui faisait afficher « 0 FCFA » ;
//   · un stock devenu negatif sans que rien ne le signale.
// Cette page les cherche, a la demande.
//
// ── COUT MAITRISE ──
// Chaque controle est soit calcule sur des donnees DEJA en memoire, soit une
// requete sur UN SEUL champ (aucun index composite). Rien ne part tant que
// « Lancer les contrôles » n'a pas ete clique.
//
// ── CE QUE CETTE PAGE NE FAIT PAS ──
// Elle ne corrige rien. Elle designe, et c'est tout : une correction
// automatique sur des donnees comptables ferait plus de degats qu'un defaut
// signale. Chaque anomalie est rendue avec de quoi la retrouver a la main.

const _SANTE_ROLES = ['admin'];
function _santeAutorise(){ return _SANTE_ROLES.includes(session?.role); }
let _santeResultats = null, _santeQuand = '';

// Collections ou une date dans le futur n'a aucun sens.
const _SANTE_COLS_DATEES = ['paiements','adhesionPays','rachatCarnetPays','depenses','carnetMvts','livraisons'];

window.renderSante = function(){
  if(!_santeAutorise()) return;
  _santeRendre();
};

window.santeLancer = _withActionLock('santeLancer', async function(){
  if(!_santeAutorise()){ notify('Accès refusé','err'); return; }
  const etat = document.getElementById('sante-etat');
  if(etat) etat.textContent = '⏳ Contrôles en cours…';
  const res = [];

  // ── 1. Saisies datées dans le futur ─────────────────────────────────
  // Le defaut du 29/09 : un paiement post-date reste invisible jusqu'a ce que
  // le calendrier le rattrape, puis surgit comme une recette que personne n'a
  // encaissee. Une requete par collection, sur un seul champ.
  const futures = [];
  if(isOnline && db_fs){
    for(const col of _SANTE_COLS_DATEES){
      try {
        const snap = await getDocs(query(collection(db_fs, col), where('date','>', TODAY)));
        snap.docs.forEach(d=>{
          const v = d.data();
          futures.push({ col, id:d.id, date:v.date||'', montant:v.montant,
            qui: v.commercialNom || (v.commercialId ? (getCom(v.commercialId).nom||'') : ''),
            saisiPar: v.saisiParNom||'' });
        });
      } catch(e){ console.warn('[santé] futur', col, e); }
    }
  }
  res.push({
    cle:'futur', gravite: futures.length ? 'grave' : 'ok',
    titre:'Saisies datées dans le futur',
    pourquoi:"Une saisie post-datée est invisible jusqu'au jour venu, puis apparaît comme une recette que personne n'a encaissée. Elle fausse aussi le solde du client dès maintenant.",
    nb: futures.length,
    lignes: futures.map(f=>`${f.date} · ${_auditLibelle(f.col)} · ${f.qui||'—'}`
      + (Number(f.montant)?` · ${fmt(f.montant)}`:'') + (f.saisiPar?` · saisi par ${f.saisiPar}`:'')),
    remede: "Ouvrir la fiche concernée, supprimer la ligne (la suppression est tracée au journal d'audit) et la ressaisir à la bonne date.",
    horsLigne: !isOnline
  });

  // ── 2. Montants inutilisables ───────────────────────────────────────
  // Un montant stocke en chaine ou absent fait basculer une somme entiere.
  // On ne controle que ce qui est DEJA en memoire : annoncer un balayage
  // complet serait mentir, le detail n'est pas charge pour tous les clients.
  const montantsKO = [];
  [['paiements',DB.paiements],['adhesionPays',DB.adhesionPays],['rachatCarnetPays',DB.rachatCarnetPays],
   ['depenses',DB.depenses],['livraisons',DB.livraisons],['mises',DB.mises]].forEach(([col,tab])=>{
    (tab||[]).forEach(d=>{
      if(d.montant === undefined || d.montant === null) return;   // champ absent : traite ailleurs
      if(!Number.isFinite(Number(d.montant)))
        montantsKO.push(`${_auditLibelle(col)} · ${d.date||'—'} · montant « ${String(d.montant)} » (${typeof d.montant})`);
      else if(typeof d.montant === 'string')
        montantsKO.push(`${_auditLibelle(col)} · ${d.date||'—'} · montant en texte « ${d.montant} » — converti à l'affichage, mais à corriger`);
    });
  });
  res.push({
    cle:'montants', gravite: montantsKO.length ? 'grave' : 'ok',
    titre:'Montants non numériques',
    pourquoi:"Un montant stocké en texte fait basculer une somme entière en concaténation ou en NaN — et NaN s'affiche « 0 FCFA », donc l'erreur passe pour un zéro légitime.",
    nb: montantsKO.length, lignes: montantsKO,
    remede:"Corriger le document en base. La console affiche le détail à chaque calcul concerné (lignes commençant par [montant]).",
    portee:'Porte sur les documents actuellement chargés sur cet appareil, pas sur toute la base.'
  });

  // ── 3. Stocks négatifs ──────────────────────────────────────────────
  const stockKO = (DB.articles||[]).filter(a=>Number(a.stock) < 0)
    .map(a=>`${a.nom||'—'} · ${Number(a.stock)} ${a.unite||''}`);
  let stockAgKO = [];
  if(isOnline && db_fs){
    try {
      const snap = await getDocs(collection(db_fs,'stockAgences'));
      stockAgKO = snap.docs.map(d=>({...d.data(), _id:d.id}))
        .filter(x=>Number(x.solde) < 0)
        .map(x=>`${getAgence(x.agenceId).nom||x.agenceId||'—'} · ${(DB.articles||[]).find(a=>a._id===x.articleId)?.nom||x.articleId||'—'} · ${Number(x.solde)}`);
    } catch(e){ console.warn('[santé] stockAgences', e); }
  }
  res.push({
    cle:'stock', gravite: (stockKO.length+stockAgKO.length) ? 'grave' : 'ok',
    titre:'Stocks négatifs',
    pourquoi:"Un stock négatif signifie qu'on a livré plus que ce qui est entré : soit une entrée manque, soit une sortie est comptée deux fois.",
    nb: stockKO.length + stockAgKO.length,
    lignes: [...stockKO.map(s=>'Stock général · '+s), ...stockAgKO.map(s=>'Agence · '+s)],
    remede:"Vérifier les mouvements de l'article concerné. migrerStockParAgence() recalcule les soldes d'agence depuis les sources."
  });

  // ── 4. Clients rattachés à un commercial inexistant ──────────────────
  const comIds = new Set((DB.commerciaux||[]).map(c=>c._id));
  const orphelins = (DB.clients||[]).filter(c=>c.commercialId && !comIds.has(c.commercialId))
    .map(c=>`${c.nom||'—'}${c.codeClient?' ('+c.codeClient+')':''} · commercial ${c.commercialId}`);
  res.push({
    cle:'orphelins', gravite: orphelins.length ? 'attention' : 'ok',
    titre:'Clients sans commercial valide',
    pourquoi:"Ces clients n'apparaissent dans aucune fiche du jour ni aucun rapport par commercial : leurs encaissements sortent des totaux sans que rien ne le signale.",
    nb: orphelins.length, lignes: orphelins,
    remede:"Réaffecter le client via Transfert & Résiliation, ou recréer l'utilisateur supprimé."
  });

  // ── 5. Clients livrés au-delà de ce qu'ils ont payé ──────────────────
  // Calcul sur les champs denormalises : c'est une ALERTE, pas une preuve.
  // On le dit, plutot que de laisser croire a un controle exhaustif.
  const soldesKO = [];
  (DB.clients||[]).forEach(c=>{
    const paye = Number(c.totalPaye);
    if(!Number.isFinite(paye)) return;
    const livre = cumulLivraisons(c._id);
    if(livre > 0 && (paye - livre) < 0)
      soldesKO.push(`${c.nom||'—'}${c.codeClient?' ('+c.codeClient+')':''} · payé ${fmt(paye)} · livré ${fmt(livre)} · écart ${fmt(paye-livre)}`);
  });
  res.push({
    cle:'soldes', gravite: soldesKO.length ? 'attention' : 'ok',
    titre:'Clients livrés au-delà du montant payé',
    pourquoi:"Une livraison n'aurait pas dû passer : soit un paiement a été supprimé après coup, soit le blocage a été contourné.",
    nb: soldesKO.length, lignes: soldesKO,
    remede:"Ouvrir la fiche du client et comparer paiements et livraisons. Le bouton 🔄 de la fenêtre de livraison relit les paiements réels.",
    portee:"Calculé sur le champ dénormalisé totalPaye et sur les livraisons chargées : c'est une alerte à vérifier, pas une preuve."
  });

  // ── 6. Utilisateurs sans agence ─────────────────────────────────────
  const agIds = new Set((DB.agences||[]).map(a=>a._id));
  const sansAgence = (DB.commerciaux||[]).filter(c=>c.role!=='admin' && (!c.agenceId || !agIds.has(c.agenceId)))
    .map(c=>`${c.nom||'—'} · ${c.role||'—'}${c.agenceId?' · agence '+c.agenceId+' introuvable':' · aucune agence'}`);
  res.push({
    cle:'sansagence', gravite: sansAgence.length ? 'attention' : 'ok',
    titre:'Utilisateurs sans agence valide',
    pourquoi:"Tout filtre par agence les exclut — rapports, carnets, dépenses, contrôle. Leur activité devient invisible aux chefs d'agence.",
    nb: sansAgence.length, lignes: sansAgence,
    remede:"Renseigner l'agence dans la fiche Utilisateurs."
  });

  // ── 7. Saisies hors ligne jamais transmises ─────────────────────────
  const enAttente = (_offlineQueue||[]).filter(o=>(o.nbTentatives||0) >= 3)
    .map(o=>`${o.op||'—'} ${o.col||''} · ${o.nbTentatives} tentative(s) · ${o.derniereErreur||'cause inconnue'}`);
  res.push({
    cle:'queue', gravite: enAttente.length ? 'grave' : 'ok',
    titre:'Saisies bloquées dans la file hors ligne',
    pourquoi:"Ces opérations ont échoué trois fois et ne repartiront pas seules. L'argent a été encaissé, le serveur ne le sait pas.",
    nb: enAttente.length, lignes: enAttente,
    remede:"Ouvrir le panneau de synchronisation (clic sur l'indicateur) pour le détail et le motif exact du refus.",
    portee:'Porte sur CET appareil uniquement — chaque téléphone a sa propre file.'
  });

  _santeResultats = res;
  _santeQuand = new Date().toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
  if(etat) etat.textContent = '';
  _santeRendre();
});

function _santeRendre(){
  const body = document.getElementById('sante-body');
  const kpi  = document.getElementById('sante-kpi');
  if(!body) return;
  if(!_santeResultats){
    body.innerHTML = `<div class="emp" style="padding:28px;">Cliquez <strong>▶ Lancer les contrôles</strong>.<div style="margin-top:8px;font-size:11px;">Rien n'est lu tant que vous ne l'avez pas demandé.</div></div>`;
    if(kpi) kpi.innerHTML = '';
    return;
  }
  const graves = _santeResultats.filter(r=>r.gravite==='grave' && r.nb);
  const attn   = _santeResultats.filter(r=>r.gravite==='attention' && r.nb);
  const sains  = _santeResultats.filter(r=>!r.nb);
  const total  = _santeResultats.reduce((a,r)=>a+r.nb,0);

  if(kpi) kpi.innerHTML = `
    <div class="kpi-card kc-red"><div class="kpi-lbl">Anomalies graves</div><div class="kpi-val kv-red">${graves.reduce((a,r)=>a+r.nb,0)}</div><div class="kpi-sub">${graves.length} contrôle(s)</div></div>
    <div class="kpi-card kc-yellow"><div class="kpi-lbl">À vérifier</div><div class="kpi-val kv-yellow">${attn.reduce((a,r)=>a+r.nb,0)}</div><div class="kpi-sub">${attn.length} contrôle(s)</div></div>
    <div class="kpi-card kc-green"><div class="kpi-lbl">Contrôles au vert</div><div class="kpi-val kv-green">${sains.length}/${_santeResultats.length}</div></div>
    <div class="kpi-card kc-blue"><div class="kpi-lbl">Total signalé</div><div class="kpi-val kv-blue">${total}</div><div class="kpi-sub">${esc(_santeQuand)}</div></div>`;

  const CAP = 40;
  body.innerHTML = [...graves, ...attn, ...sains].map(r=>{
    const vert = !r.nb;
    const coul = vert ? 'var(--accent2)' : (r.gravite==='grave' ? 'var(--danger)' : 'var(--warn)');
    const ico  = vert ? '✅' : (r.gravite==='grave' ? '⛔' : '⚠️');
    const tronque = r.lignes.length > CAP;
    return `<div style="border:1px solid var(--border);border-left:3px solid ${coul};border-radius:9px;margin-bottom:10px;padding:12px 14px;background:var(--card);">
      <div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap;">
        <div style="font-weight:700;font-size:13px;color:${coul};">${ico} ${esc(r.titre)}</div>
        <div style="font-family:'Space Grotesk',sans-serif;font-weight:800;font-size:16px;color:${coul};">${r.nb}</div>
      </div>
      <div style="margin-top:6px;font-size:11.5px;color:var(--muted);line-height:1.5;">${esc(r.pourquoi)}</div>
      ${r.portee?`<div style="margin-top:5px;font-size:10.5px;color:var(--muted);opacity:.85;">⚠️ ${esc(r.portee)}</div>`:''}
      ${r.horsLigne?`<div style="margin-top:5px;font-size:10.5px;color:var(--warn);">📵 Hors ligne — ce contrôle n'a pas pu être exécuté.</div>`:''}
      ${r.nb ? `<div style="margin-top:9px;max-height:230px;overflow:auto;border-top:1px solid var(--border);padding-top:8px;">
        ${r.lignes.slice(0,CAP).map(l=>`<div style="font-size:11px;padding:3px 0;border-bottom:1px solid rgba(42,49,66,0.4);">${esc(l)}</div>`).join('')}
        ${tronque?`<div style="font-size:10.5px;color:var(--muted);padding-top:6px;">… et ${r.lignes.length-CAP} autre(s). <strong>L'export CSV contient tout.</strong></div>`:''}
      </div>
      <div style="margin-top:9px;font-size:11px;color:var(--accent);">→ ${esc(r.remede)}</div>` : ''}
    </div>`;
  }).join('');
}

window.santeExportCSV = function(){
  if(!_santeAutorise()){ notify('Accès refusé','err'); return; }
  if(!_santeResultats){ notify("Lancez d'abord les contrôles.",'err'); return; }
  const e2 = v => `"${String(v==null?'':v).replace(/"/g,'""')}"`;
  const lignes = [['Contrôle','Gravité','Détail'].map(e2).join(';')];
  _santeResultats.forEach(r=>{
    if(!r.nb) lignes.push([r.titre,'ok','aucune anomalie'].map(e2).join(';'));
    else r.lignes.forEach(l=>lignes.push([r.titre, r.gravite, l].map(e2).join(';')));
  });
  const BOM = String.fromCharCode(0xFEFF);
  const blob = new Blob([BOM+lignes.join('\n')], {type:'text/csv;charset=utf-8;'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `sante_donnees_${TODAY}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
  notify('✅ Rapport de santé exporté');
};

// ════════════════════════════════════════════════════
// RAPPORT D'ACTIVITÉ — Admin uniquement
// ════════════════════════════════════════════════════

// ── VOLET 33 ── Prepare le bloc sans declencher la moindre lecture.
function _recDetailPreparer(){
  if(!_recDetailAutorise()) return;
  const selMois = document.getElementById('rec-detail-mois');
  if(selMois && !selMois.value){
    selMois.value = TODAY.slice(0,7);                 // mois en cours
    selMois.max   = TODAY.slice(0,7);                 // jamais un mois futur
  }
  const selAg = document.getElementById('rec-detail-agence');
  if(selAg){
    const ags = (DB.agences||[]).slice().sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
    const sig = ags.map(a=>a._id).join(',');
    if(selAg.dataset.sig !== sig){
      const prev = selAg.value;
      selAg.innerHTML = '<option value="">Toutes les agences</option>'
        + ags.map(a=>`<option value="${esc(a._id)}">${esc(a.nom||'(sans nom)')}</option>`).join('');
      selAg.dataset.sig = sig;
      if(prev && ags.some(a=>a._id===prev)) selAg.value = prev;
    }
  }
  _recDetailPeuplerComs();
  if(typeof sectionAppliquer === 'function')
    sectionAppliquer('rapport-rec-detail', 'rec-detail-bloc', 'rec-detail-chev');
}

// ── VOLET 34 ── Remplit le selecteur de commerciaux en suivant l'agence
// choisie. La selection en cours est CONSERVEE si le commercial appartient
// encore au perimetre, REMISE A « Tous » sinon — sans quoi on garderait un
// filtre invisible qui viderait le tableau sans explication.
function _recDetailPeuplerComs(){
  const sel = document.getElementById('rec-detail-com');
  if(!sel) return;
  const agence = document.getElementById('rec-detail-agence')?.value || '';
  let coms = (DB.commerciaux||[]).filter(c => c.role === ROLES.COMMERCIAL);
  if(agence) coms = coms.filter(c => c.agenceId === agence);
  coms = coms.slice().sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  const sig = agence + '|' + coms.map(c=>c._id).join(',');
  if(sel.dataset.sig === sig) return;              // rien n'a bouge
  const prev = sel.value;
  sel.innerHTML = '<option value="">Tous les commerciaux</option>'
    + coms.map(c=>`<option value="${esc(c._id)}">${esc(c.nom||'(sans nom)')}</option>`).join('');
  sel.dataset.sig = sig;
  sel.value = (prev && coms.some(c=>c._id===prev)) ? prev : '';
}

// Changer d'agence doit refaire la liste des commerciaux AVANT de redessiner.
window.recDetailAgenceChange = function(){
  _recDetailPeuplerComs();
  renderRecDetail();
};

let _rapportPeriod = 'semaine';
let _rapportCharts = {};

window.setRapportPeriod = function(p){
  _rapportPeriod = p;
  document.querySelectorAll('.rapport-tab').forEach(t=>{
    t.classList.toggle('active', t.textContent.toLowerCase().includes(
      p==='semaine'?'semaine':p==='mois'?'mois':p==='trimestre'?'trimestre':p==='semestre'?'semestre':'ann'
    ));
  });
  // ✅ FIX CRASH SILENCIEUX : ce point d'entrée (clic sur un onglet de
  // période) appelait renderRapportActivite() sans aucune protection —
  // contrairement au premier affichage de la page (protégé par le
  // try/catch de renderPg). Une erreur ici restait donc totalement
  // silencieuse pour l'utilisateur, avec la page bloquée à mi-rendu.
  renderRapportActivite().catch(e => {
    console.error('[setRapportPeriod] Erreur lors du calcul du rapport :', e);
    notify("⚠️ Erreur lors du calcul du rapport pour cette période.", 'err');
  });
};

function _getPeriodeBornes(p){
  const now = new Date();
  let debut, fin = new Date(now);
  fin.setHours(23,59,59,999);
  if(p==='semaine'){
    const day = now.getDay();
    const diff = (day===0?-6:1-day);
    debut = new Date(now); debut.setDate(now.getDate()+diff); debut.setHours(0,0,0,0);
  } else if(p==='mois'){
    debut = new Date(now.getFullYear(), now.getMonth(), 1);
  } else if(p==='trimestre'){
    const qStart = Math.floor(now.getMonth()/3)*3;
    debut = new Date(now.getFullYear(), qStart, 1);
  } else if(p==='semestre'){
    const sStart = now.getMonth()<6 ? 0 : 6;
    debut = new Date(now.getFullYear(), sStart, 1);
  } else { // annee
    debut = new Date(now.getFullYear(), 0, 1);
  }
  return {debut, fin};
}

function _periodeLabel(p){
  const now = new Date();
  const mois = ['Janv','Févr','Mars','Avr','Mai','Juin','Juil','Août','Sept','Oct','Nov','Déc'];
  if(p==='semaine'){
    const {debut,fin}=_getPeriodeBornes(p);
    return `Sem. du ${debut.getDate()} ${mois[debut.getMonth()]} au ${fin.getDate()} ${mois[fin.getMonth()]} ${fin.getFullYear()}`;
  }
  if(p==='mois') return `${mois[now.getMonth()]} ${now.getFullYear()}`;
  if(p==='trimestre'){const q=Math.floor(now.getMonth()/3)+1;return `T${q} ${now.getFullYear()}`;}
  if(p==='semestre'){return (now.getMonth()<6?'1er':'2e')+` semestre ${now.getFullYear()}`;}
  return `Année ${now.getFullYear()}`;
}

function _inPeriod(dateStr, debut, fin){
  if(!dateStr) return false;
  const d = new Date(dateStr);
  return d>=debut && d<=fin;
}

function _fmtMoney(v){ return Number(v||0).toLocaleString('fr-FR')+ ' FCFA'; }
function _fmtNum(v){ return Number(v||0).toLocaleString('fr-FR'); }

function _destroyRapportCharts(){
  Object.values(_rapportCharts).forEach(c=>{ try{c.destroy();}catch(e){} });
  _rapportCharts = {};
}

async function renderRapportActivite(){
  if(session?.role !== 'admin'){ return; }
  // ── VOLET 33 ── on prepare le bloc « recouvrements par date » SANS rien
  // charger : selecteurs peuples, mois courant propose, etat replie restaure.
  try { _recDetailPreparer(); } catch(e){ console.warn('[rec-detail] préparation :', e); }
  const p = _rapportPeriod;
  const {debut, fin} = _getPeriodeBornes(p);

  // Mettre à jour le badge période
  document.getElementById('rapport-periode-txt').textContent = _periodeLabel(p);

  const body = document.getElementById('rapport-body');
  body.innerHTML = '<div class="rapport-loading">⏳ Calcul du rapport…</div>';

  // Détruire les anciens charts
  _destroyRapportCharts();

  // ✅ FIX COMPLÉTUDE (retrait de 'paiements' de _AUTO_FULL_LOAD_COLS) : ce
  // rapport a besoin de TOUS les paiements de la période, pas seulement de ce
  // qui est déjà chargé en mémoire (potentiellement une fraction arbitraire
  // depuis que 'paiements' n'est plus auto-chargé en entier). On va donc les
  // chercher directement sur Firestore, ciblés sur la période affichée —
  // même principe que le Registre/Historique (_fetchColByDate).
  // ── VOLET 6 ── ce rapport lisait DB.adhesionPays / DB.rachatCarnetPays /
  // DB.stockMvts en supposant qu'elles etaient completes en memoire. Elles
  // relevent desormais du regime "jour courant + a la demande" : sans les
  // recuperer ici, le rapport n'aurait montre que la journee en cours pour
  // ces trois collections, quelle que soit la periode choisie — un faux
  // silencieux sur les adhesions, les rachats et les mouvements de stock.
  // On recupere donc la periode pour les quatre collections concernees, en
  // parallele. 'livraisons' et 'mises' ne sont pas dans le regime, elles
  // restent completes en memoire.
  try {
    const _d0 = _toISODate(debut), _f0 = _toISODate(fin);
    await Promise.all([
      _fetchPaiementsDateRange(_d0, _f0),
      _fetchColDateRange('adhesionPays',     _d0, _f0),
      _fetchColDateRange('rachatCarnetPays', _d0, _f0),
      _fetchColDateRange('stockMvts',        _d0, _f0)
    ]);
  } catch(e) {
    console.error('[renderRapportActivite] Échec du chargement des données de la période :', e);
    body.innerHTML = '<div class="rapport-loading">⚠️ Erreur lors du chargement des données de cette période.</div>';
    notify("⚠️ Impossible de charger les données de cette période — rapport potentiellement incomplet.", 'err');
    return;
  }

  // Filtrer les données
  const paiements = (DB.paiements||[]).filter(x=>_inPeriod(x.date||x.createdAt, debut, fin));
  const adhesions = (DB.adhesionPays||[]).filter(x=>_inPeriod(x.date||x.createdAt, debut, fin));
  // ✅ FIX : rachats de carnet absents des KPI/classements de ce rapport
  // (même bug que le Registre et la page Commerciaux, corrigé de la même façon).
  const rachats = (DB.rachatCarnetPays||[]).filter(x=>_inPeriod(x.date||x.createdAt, debut, fin));
  const livraisons = (DB.livraisons||[]).filter(x=>_inPeriod(x.date||x.createdAt, debut, fin));
  const mises = (DB.mises||[]).filter(x=>_inPeriod(x.date||x.createdAt, debut, fin));
  const stockMvts = (DB.stockMvts||[]).filter(x=>_inPeriod(x.date||x.createdAt, debut, fin));
  // ╔══════════════════════════════════════════════════════════════╗
  // ║  VOLET 35 — « NOUVEAUX CLIENTS » COMPTAIT L'EXACT CONTRAIRE   ║
  // ╚══════════════════════════════════════════════════════════════╝
  // LE DEFAUT. Ce compteur lisait « x.dateAdhesion || x.createdAt ». Or, en
  // relisant la creation d'un client dans ce fichier :
  //
  //   · `dateAdhesion` n'est ECRIT NULLE PART. Le champ n'apparaissait que
  //     dans cette ligne et dans l'export CSV — jamais a la creation. Il n'a
  //     donc jamais existe sur aucun document.
  //   · `createdAt` n'est pose que sur les clients IMPORTES
  //     (origine:'import'). Un client saisi normalement ne l'a pas : il porte
  //     `debut`, comme le lit la Fiche du jour.
  //
  // Resultat : pour un client reellement enregistre, les deux champs valaient
  // `undefined`, _inPeriod() renvoyait false, et il n'etait JAMAIS compte. Le
  // seul cas ou le compteur bougeait etait un IMPORT de donnees — c'est-a-dire
  // precisement ce qu'il ne faut pas compter comme activite commerciale.
  // Le KPI affichait donc 0 en permanence, et aurait affiche un chiffre
  // trompeur le jour d'une reprise de donnees.
  //
  // LA CORRECTION. On lit `debut` en premier — le champ reellement ecrit — et
  // on ecarte les imports, exactement comme le fait renderFiche() pour sa
  // propre liste « Nouveaux clients enregistres ce jour ». Les deux ecrans
  // repondent desormais a la meme definition.
  const clients = (DB.clients||[]).filter(x =>
    x.origine !== 'import' && _inPeriod(x.debut || x.createdAt, debut, fin));
  const agences = DB.agences||[];
  const coms = (DB.commerciaux||[]).filter(c=>c.role!=='admin');
  const primes = DB.primesPaliers||[];

  // ── KPI financiers ──
  const totalPaiements = paiements.reduce((s,x)=>s+(Number(x.montant)||0),0);
  // ── VOLET 35 ── renomme : cette somme porte sur `adhesions`, pas sur les
  // cotisations. Le nom de variable entretenait la confusion que le libelle
  // affichait. Les cotisations, elles, sont dans `totalPaiements`.
  const totalAdhesions = adhesions.reduce((s,x)=>s+(Number(x.montant)||0),0);
  const totalRachats = rachats.reduce((s,x)=>s+(Number(x.montant)||0),0);

  // ✅ FIX PERFORMANCE (cause réelle du plantage/gel du navigateur) : cette
  // section faisait, pour CHAQUE paiement et CHAQUE rachat, un .find() sur
  // la liste ENTIÈRE des clients (recherche linéaire) — et pire, pour CHAQUE
  // commercial, un nouveau passage complet sur TOUS les paiements de la
  // période avec un .find() client à chaque fois (primesAtteintes ET
  // perfCom, chacun indépendamment). Avec une vraie base (plusieurs
  // milliers de clients, dizaines de commerciaux, milliers de paiements sur
  // un trimestre/semestre/année), ça représentait des dizaines à centaines
  // de millions d'opérations — assez pour geler complètement l'onglet
  // plusieurs secondes, voire le faire tuer par le navigateur sur un
  // appareil modeste ("l'app plante"). Remplacé par un index client_id→client
  // (Map, lecture en O(1)) construit UNE seule fois, et un regroupement des
  // paiements/rachats par commercial fait en un seul passage — la
  // complexité globale passe de O(commerciaux × paiements × clients) à
  // O(paiements + rachats + clients + commerciaux), donc linéaire.
  const clientById = new Map((DB.clients||[]).map(c=>[c._id,c]));

  // CA par agence
  const caParAgence = {};
  agences.forEach(a=>{ caParAgence[a._id]={nom:a.nom, total:0}; });
  paiements.forEach(p=>{
    const cl = clientById.get(p.clientId);
    if(cl){ const ag=cl.agenceId||'inconnue'; if(!caParAgence[ag]) caParAgence[ag]={nom:ag,total:0}; caParAgence[ag].total+=(Number(p.montant)||0); }
  });
  rachats.forEach(r=>{
    const cl = clientById.get(r.clientId);
    if(cl){ const ag=cl.agenceId||'inconnue'; if(!caParAgence[ag]) caParAgence[ag]={nom:ag,total:0}; caParAgence[ag].total+=(Number(r.montant)||0); }
  });

  // Regroupement paiements/rachats par commercial — un seul passage sur
  // chaque liste (au lieu d'un passage complet PAR commercial ci-dessus).
  const paiementsParCom = new Map(); // commercialId -> {ca, nb}
  const touch = (map,id) => { if(!map.has(id)) map.set(id,{ca:0,nb:0}); return map.get(id); };
  paiements.forEach(p=>{
    const cl = clientById.get(p.clientId);
    if(cl && cl.commercialId){ const e=touch(paiementsParCom, cl.commercialId); e.ca+=(Number(p.montant)||0); e.nb++; }
  });
  const rachatsParCom = new Map();
  rachats.forEach(r=>{
    if(r.commercialId){ const e=touch(rachatsParCom, r.commercialId); e.ca+=(Number(r.montant)||0); }
  });
  const clientsParCom = new Map();
  clients.forEach(c=>{
    if(c.commercialId){ const e=touch(clientsParCom, c.commercialId); e.nb++; }
  });

  // Primes atteintes — chercher commerciaux ayant atteint un palier sur la période
  const paliersTries = [...primes].sort((a,b)=>b.seuil-a.seuil); // trié une seule fois, réutilisé pour tous les commerciaux
  const primesAtteintes = [];
  coms.forEach(com=>{
    const totalCom = (paiementsParCom.get(com._id)?.ca||0) + (rachatsParCom.get(com._id)?.ca||0);
    const palier = paliersTries.find(pr=>totalCom>=(Number(pr.seuil)||0));
    // ✅ FIX CHAMPS INEXISTANTS : les documents primesPaliers ont les champs
    // {seuil, montant, label} (voir ajouterPalier) — pas {nom, prime}. Avec
    // les mauvais noms, palier.nom était toujours undefined (repli correct
    // sur "Palier X") mais palier.prime était TOUJOURS undefined→0 : chaque
    // ligne de cette section affichait donc une prime à 0 FCFA, quel que
    // soit le palier réellement configuré.
    if(palier) primesAtteintes.push({com:com.nom, palier:palier.label||`Palier ${palier.seuil}`, montant:palier.montant||0, ca:totalCom});
  });

  // Performance par commercial
  const perfCom = coms.map(com=>{
    const pay = paiementsParCom.get(com._id) || {ca:0, nb:0};
    const rach = rachatsParCom.get(com._id) || {ca:0};
    const cl = clientsParCom.get(com._id) || {nb:0};
    return { nom:com.nom, ca: pay.ca + rach.ca, nbClients: cl.nb, nbPay: pay.nb };
  }).sort((a,b)=>b.ca-a.ca);

  const maxCa = perfCom.length ? perfCom[0].ca : 1;

  // ── Données pour graphiques par période (jours/semaines/mois selon la période) ──
  function _buildTimeSeries(liste, champDate, champVal){
    const buckets = {};
    const fmt = (d) => {
      if(p==='semaine'||p==='mois') return d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'});
      if(p==='trimestre') return `Sem.${_weekNum(d)}`;
      if(p==='semestre'||p==='annee') return d.toLocaleDateString('fr-FR',{month:'short',year:'2-digit'});
      return d.toISOString().slice(0,7);
    };
    liste.forEach(x=>{
      const d=new Date(x[champDate]||x.createdAt||x.date);
      if(!d||isNaN(d)) return;
      const k=fmt(d);
      if(!buckets[k]) buckets[k]=0;
      buckets[k]+=(Number(x[champVal])||0);
    });
    return buckets;
  }
  function _weekNum(d){ const s=new Date(d.getFullYear(),0,1); return Math.ceil(((d-s)/86400000+s.getDay()+1)/7); }

  const tsPaiements = _buildTimeSeries(paiements,'date','montant');
  const tsAdhesions = _buildTimeSeries(adhesions,'date','montant');
  const labels = [...new Set([...Object.keys(tsPaiements),...Object.keys(tsAdhesions)])].sort();

  // Livraisons par statut
  const livrStatuts = {};
  livraisons.forEach(l=>{ const s=l.statut||'inconnu'; livrStatuts[s]=(livrStatuts[s]||0)+1; });

  // Mouvements stock par type
  const stockEntrees = stockMvts.filter(m=>m.type==='entree').length;
  const stockSorties = stockMvts.filter(m=>m.type==='sortie').length;

  // ── Construire le HTML ──
  body.innerHTML = `
    <!-- ░░ KPI FINANCIERS ░░ -->
    <div class="rapport-section-title">💰 Données financières</div>
    <div class="rapport-kpi-grid">
      <div class="rapport-kpi accent">
        <div class="rk-label">Total encaissements</div>
        <div class="rk-val">${_fmtMoney(totalPaiements)}</div>
        <div class="rk-sub">${paiements.length} paiement(s)</div>
      </div>
      <div class="rapport-kpi green">
        <div class="rk-label">Adhésions collectées</div>
        <div class="rk-val">${_fmtMoney(totalAdhesions)}</div>
        <div class="rk-sub">${adhesions.length} adhésion(s)</div>
      </div>
      <div class="rapport-kpi" style="border-color:rgba(100,160,247,0.35);">
        <div class="rk-label">Rachats de carnet</div>
        <div class="rk-val">${_fmtMoney(totalRachats)}</div>
        <div class="rk-sub">${rachats.length} rachat(s)</div>
      </div>
      <div class="rapport-kpi">
        <div class="rk-label">Nouveaux clients</div>
        <div class="rk-val">${clients.length}</div>
        <div class="rk-sub">sur la période</div>
      </div>
      <div class="rapport-kpi warn">
        <div class="rk-label">Livraisons</div>
        <div class="rk-val">${livraisons.length}</div>
        <div class="rk-sub">${livrStatuts['livre']||0} livrée(s)</div>
      </div>
    </div>

    <!-- ░░ GRAPHIQUE ENCAISSEMENTS ░░ -->
    <div class="rapport-chart-wrap">
      <div class="rapport-chart-label">Évolution des encaissements vs cotisations</div>
      <canvas id="chart-rapport-encaiss"></canvas>
    </div>

    <!-- ░░ CA PAR AGENCE ░░ -->
    <div class="rapport-section-title">🏢 Chiffre d'affaires par agence</div>
    <div class="rapport-kpi-grid">
      ${Object.values(caParAgence).sort((a,b)=>b.total-a.total).map(ag=>`
        <div class="rapport-kpi">
          <div class="rk-label">${esc(ag.nom||'—')}</div>
          <div class="rk-val" style="font-size:14px;">${_fmtMoney(ag.total)}</div>
        </div>
      `).join('')||'<div style="color:var(--muted);font-size:12px;padding:8px;">Aucune donnée agence</div>'}
    </div>
    <div class="rapport-chart-wrap">
      <div class="rapport-chart-label">CA par agence (FCFA)</div>
      <canvas id="chart-rapport-agences" style="max-height:180px;"></canvas>
    </div>

    <!-- ░░ PERFORMANCE COMMERCIAUX ░░ -->
    <div class="rapport-section-title">👤 Performance par commercial</div>
    ${perfCom.length===0?'<div style="color:var(--muted);font-size:12px;padding:8px;">Aucun commercial trouvé</div>':
      perfCom.map((c,i)=>`
        <div class="com-rank-row">
          <div class="com-rank-pos">${i+1}</div>
          <div class="com-rank-name">${esc(c.nom)}</div>
          <div class="com-rank-bar-wrap"><div class="com-rank-bar" style="width:${maxCa>0?Math.round(c.ca/maxCa*100):0}%"></div></div>
          <div class="com-rank-val">${_fmtMoney(c.ca)}</div>
          <div style="font-size:10px;color:var(--muted);margin-left:6px;">${c.nbClients} client(s)</div>
        </div>
      `).join('')}
    <div class="rapport-chart-wrap" style="margin-top:12px;">
      <div class="rapport-chart-label">Encaissements par commercial</div>
      <canvas id="chart-rapport-coms" style="max-height:200px;"></canvas>
    </div>

    <!-- ░░ PRIMES ET PALIERS ░░ -->
    <div class="rapport-section-title">🏆 Primes et paliers atteints</div>
    ${primesAtteintes.length===0
      ? '<div style="color:var(--muted);font-size:12px;padding:8px;">Aucun palier atteint sur cette période.</div>'
      : `<div class="tw"><table><thead><tr><th>Commercial</th><th>Palier atteint</th><th>CA généré</th><th>Prime</th></tr></thead><tbody>
          ${primesAtteintes.map(p=>`<tr><td>${p.com}</td><td>${p.palier}</td><td>${_fmtMoney(p.ca)}</td><td style="color:var(--accent);font-weight:700;">${_fmtMoney(p.montant)}</td></tr>`).join('')}
        </tbody></table></div>`}

    <!-- ░░ LIVRAISONS ░░ -->
    <div class="rapport-section-title">🚚 Livraisons effectuées</div>
    <div class="rapport-kpi-grid">
      ${Object.entries(livrStatuts).map(([s,n])=>`<div class="rapport-kpi"><div class="rk-label">${s}</div><div class="rk-val">${n}</div></div>`).join('') || '<div style="color:var(--muted);font-size:12px;padding:8px;">Aucune livraison sur cette période.</div>'}
    </div>
    <div class="rapport-chart-wrap">
      <div class="rapport-chart-label">Livraisons par statut</div>
      <canvas id="chart-rapport-livr" style="max-height:180px;"></canvas>
    </div>

    <!-- ░░ STOCK ░░ -->
    <div class="rapport-section-title">📦 Mouvements de stock</div>
    <div class="rapport-kpi-grid">
      <div class="rapport-kpi green">
        <div class="rk-label">Entrées de stock</div>
        <div class="rk-val">${stockEntrees}</div>
        <div class="rk-sub">mouvements</div>
      </div>
      <div class="rapport-kpi warn">
        <div class="rk-label">Sorties de stock</div>
        <div class="rk-val">${stockSorties}</div>
        <div class="rk-sub">mouvements</div>
      </div>
      <div class="rapport-kpi">
        <div class="rk-label">Total mouvements</div>
        <div class="rk-val">${stockMvts.length}</div>
        <div class="rk-sub">sur la période</div>
      </div>
    </div>
    <div class="rapport-chart-wrap">
      <div class="rapport-chart-label">Entrées vs Sorties de stock</div>
      <canvas id="chart-rapport-stock" style="max-height:160px;"></canvas>
    </div>
  `;

  // ── Dessiner les graphiques ──
  // ✅ FIX CRASH SILENCIEUX : ce bloc s'exécute dans requestAnimationFrame,
  // donc APRÈS que renderPg()/setupPageListeners() ait déjà quitté son
  // try/catch — une erreur ici (ex: Chart.js jette si des données ne sont
  // pas au format attendu) n'était donc JAMAIS rattrapée : elle remontait
  // comme exception non gérée dans la console, sans aucun message pour
  // l'utilisateur, laissant la page à moitié affichée (KPI visibles, mais
  // aucun graphique, et rien d'autre ne réagissait plus sur cette page —
  // ce qui donne l'impression que "l'app plante").
  requestAnimationFrame(()=>{
   try{
    const gold='rgba(201,168,76,0.85)', goldFill='rgba(201,168,76,0.15)';
    const green='rgba(56,201,160,0.85)', greenFill='rgba(56,201,160,0.15)';
    const warn='rgba(212,137,58,0.85)', warnFill='rgba(212,137,58,0.15)';
    const gridColor='rgba(255,255,255,0.06)', tickColor='rgba(255,255,255,0.35)';

    const baseOpts = (yLabel)=>({
      responsive:true, maintainAspectRatio:true,
      plugins:{legend:{labels:{color:tickColor,font:{size:10}}},tooltip:{callbacks:{label:c=>' '+Number(c.parsed.y).toLocaleString('fr-FR')+' FCFA'}}},
      scales:{
        x:{ticks:{color:tickColor,font:{size:9}},grid:{color:gridColor}},
        y:{ticks:{color:tickColor,font:{size:9},callback:v=>Number(v).toLocaleString('fr-FR')},grid:{color:gridColor},title:{display:!!yLabel,text:yLabel,color:tickColor,font:{size:9}}}
      }
    });

    // 1. Encaissements vs cotisations
    const c1=document.getElementById('chart-rapport-encaiss');
    if(c1){
      _rapportCharts.encaiss=new Chart(c1.getContext('2d'),{
        type:'line',
        data:{
          labels,
          datasets:[
            {label:'Encaissements',data:labels.map(l=>tsPaiements[l]||0),borderColor:gold,backgroundColor:goldFill,tension:0.4,fill:true,pointRadius:3},
            {label:'Cotisations',data:labels.map(l=>tsAdhesions[l]||0),borderColor:green,backgroundColor:greenFill,tension:0.4,fill:true,pointRadius:3}
          ]
        },
        options:baseOpts()
      });
    }

    // 2. CA par agence — barre horizontale
    const c2=document.getElementById('chart-rapport-agences');
    if(c2){
      const agData=Object.values(caParAgence).sort((a,b)=>b.total-a.total);
      _rapportCharts.agences=new Chart(c2.getContext('2d'),{
        type:'bar',
        data:{
          labels:agData.map(a=>a.nom),
          datasets:[{label:'CA (FCFA)',data:agData.map(a=>a.total),backgroundColor:gold,borderRadius:6}]
        },
        options:{...baseOpts(),...{indexAxis:'y',plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>' '+Number(c.parsed.x).toLocaleString('fr-FR')+' FCFA'}}}}}
      });
    }

    // 3. Performance commerciaux
    const c3=document.getElementById('chart-rapport-coms');
    if(c3){
      _rapportCharts.coms=new Chart(c3.getContext('2d'),{
        type:'bar',
        data:{
          labels:perfCom.map(c=>c.nom),
          datasets:[{label:'Encaissements',data:perfCom.map(c=>c.ca),backgroundColor:green,borderRadius:6}]
        },
        options:{...baseOpts(),...{plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>' '+Number(c.parsed.y).toLocaleString('fr-FR')+' FCFA'}}}}}
      });
    }

    // 4. Livraisons par statut — doughnut
    const c4=document.getElementById('chart-rapport-livr');
    if(c4){
      const livrKeys=Object.keys(livrStatuts);
      _rapportCharts.livr=new Chart(c4.getContext('2d'),{
        type:'doughnut',
        data:{
          labels:livrKeys,
          datasets:[{data:livrKeys.map(k=>livrStatuts[k]),backgroundColor:[gold,green,warn,'rgba(224,92,82,0.8)'],borderWidth:0}]
        },
        options:{responsive:true,plugins:{legend:{labels:{color:tickColor,font:{size:10}}}}}
      });
    }

    // 5. Stock entrées/sorties
    const c5=document.getElementById('chart-rapport-stock');
    if(c5){
      _rapportCharts.stock=new Chart(c5.getContext('2d'),{
        type:'bar',
        data:{
          labels:['Entrées','Sorties'],
          datasets:[{data:[stockEntrees,stockSorties],backgroundColor:[green,warn],borderRadius:8}]
        },
        options:{...baseOpts(),...{plugins:{legend:{display:false}},scales:{x:{ticks:{color:tickColor,font:{size:11}},grid:{color:gridColor}},y:{ticks:{color:tickColor,font:{size:9}},grid:{color:gridColor}}}}}
      });
    }
   } catch(e) {
     console.error('[renderRapportActivite] Erreur lors de la génération des graphiques :', e);
     notify("⚠️ Les graphiques du rapport n'ont pas pu s'afficher, mais les chiffres ci-dessus restent à jour.", 'err');
   }
  });
}

window.exportRapportCSV = async function(){
  if(session?.role!=='admin'){ notify("Accès réservé à l'administrateur",'err'); return; }
  const p=_rapportPeriod;
  const {debut,fin}=_getPeriodeBornes(p);
  // ✅ FIX COMPLÉTUDE (retrait de 'paiements' de _AUTO_FULL_LOAD_COLS) : même
  // fix que renderRapportActivite() — l'export doit être exact même si
  // l'admin exporte sans être passé par l'écran du rapport juste avant.
  try {
    await _fetchPaiementsDateRange(_toISODate(debut), _toISODate(fin));
  } catch(e) {
    console.error('[exportRapportCSV] Échec du chargement des paiements de la période :', e);
    notify("⚠️ Impossible de charger les paiements de cette période — export annulé.", 'err');
    return;
  }
  const paiements=(DB.paiements||[]).filter(x=>_inPeriod(x.date||x.createdAt,debut,fin));
  const adhesions=(DB.adhesionPays||[]).filter(x=>_inPeriod(x.date||x.createdAt,debut,fin));
  const livraisons=(DB.livraisons||[]).filter(x=>_inPeriod(x.date||x.createdAt,debut,fin));
  const stockMvts=(DB.stockMvts||[]).filter(x=>_inPeriod(x.date||x.createdAt,debut,fin));
  // ── VOLET 35 ── meme correction que dans le rapport a l'ecran : sans elle,
  // l'export et l'ecran auraient affiche deux chiffres differents.
  const clients=(DB.clients||[]).filter(x =>
    x.origine !== 'import' && _inPeriod(x.debut || x.createdAt, debut, fin));

  let csv=`Rapport d'activité — ${_periodeLabel(p)}\n\n`;
  csv+=`FINANCIER\nTotal encaissements;${paiements.reduce((s,x)=>s+(Number(x.montant)||0),0)} FCFA\nAdhésions collectées;${adhesions.reduce((s,x)=>s+(Number(x.montant)||0),0)} FCFA\nNouveaux clients;${clients.length}\n\n`;
  csv+=`PAIEMENTS\nDate;Client;Montant;Note\n`;
  paiements.forEach(x=>{ const cl=(DB.clients||[]).find(c=>c._id===x.clientId); csv+=`${_csvCell(x.date||'')};${_csvCell(cl?cl.nom:'—')};${x.montant||0};${_csvCell(x.note||'')}\n`; });
  csv+=`\nLIVRAISONS\nDate;Client;Statut\n`;
  livraisons.forEach(x=>{ const cl=(DB.clients||[]).find(c=>c._id===x.clientId); csv+=`${_csvCell(x.date||'')};${_csvCell(cl?cl.nom:'—')};${_csvCell(x.statut||'')}\n`; });
  csv+=`\nSTOCK\nDate;Article;Type;Quantité\n`;
  stockMvts.forEach(x=>{ csv+=`${_csvCell(x.date||'')};${_csvCell(x.articleNom||x.articleId||'')};${_csvCell(x.type||'')};${x.qte||0}\n`; });

  const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download=`rapport_${p}_${new Date().toISOString().slice(0,10)}.csv`;
  a.click();
  notify('✅ Export CSV téléchargé','ok');
};

// ── État connexion Bluetooth ──
let _btDevice=null, _btChar=null;

async function _btConnect(){
  if(!navigator.bluetooth){
    notify('❌ Web Bluetooth non supporté. Utilisez Chrome sur Android.','err');
    return false;
  }
  try{
    notify('🔵 Recherche imprimante Bluetooth...','info');
    _btDevice = await navigator.bluetooth.requestDevice({
      filters:[
        {services:['000018f0-0000-1000-8000-00805f9b34fb']},
      ],
      optionalServices:[
        '000018f0-0000-1000-8000-00805f9b34fb',
        '0000ff00-0000-1000-8000-00805f9b34fb',
        '0000ffe0-0000-1000-8000-00805f9b34fb',
        '00001101-0000-1000-8000-00805f9b34fb',
        '0000fff0-0000-1000-8000-00805f9b34fb',
      ]
    });
    const server = await _btDevice.gatt.connect();

    // Tentative sur plusieurs UUID de service connus
    const svcs=[
      '000018f0-0000-1000-8000-00805f9b34fb',
      '0000ff00-0000-1000-8000-00805f9b34fb',
      '0000ffe0-0000-1000-8000-00805f9b34fb',
      '0000fff0-0000-1000-8000-00805f9b34fb',
    ];
    let svc=null;
    for(const u of svcs){ try{svc=await server.getPrimaryService(u);break;}catch(e){} }
    if(!svc){
      // Dernier recours : toutes les services disponibles
      const allSvcs = await server.getPrimaryServices();
      svc = allSvcs[0] || null;
    }
    if(!svc){ notify('❌ Service imprimante introuvable','err'); return false; }

    // Tentative sur plusieurs UUID de caractéristique
    const chars=[
      '00002af1-0000-1000-8000-00805f9b34fb',
      '0000ff02-0000-1000-8000-00805f9b34fb',
      '0000ffe1-0000-1000-8000-00805f9b34fb',
      '0000fff2-0000-1000-8000-00805f9b34fb',
    ];
    _btChar=null;
    for(const u of chars){ try{_btChar=await svc.getCharacteristic(u);break;}catch(e){} }
    if(!_btChar){
      // Fallback : première caractéristique avec écriture
      const allChars=await svc.getCharacteristics();
      _btChar=allChars.find(c=>c.properties.writeWithoutResponse||c.properties.write)||null;
    }
    if(!_btChar){ notify('❌ Caractéristique écriture introuvable','err'); return false; }

    // Détecter déconnexion
    _btDevice.addEventListener('gattserverdisconnected',()=>{
      _btChar=null;
      notify('🔌 Imprimante Bluetooth déconnectée','err');
      // Mettre à jour statuts
      const statusEl=document.getElementById('bn-bt-status');
      if(statusEl){statusEl.textContent='🔴 Non connectée';statusEl.style.color='var(--muted)';}
    });

    notify('✅ Imprimante connectée : '+(_btDevice.name||'Imprimante BT'),'ok');
    // Mettre à jour le bouton de statut sidebar desktop
    const statusEl=document.getElementById('bt-printer-status');
    if(statusEl){ statusEl.textContent='🟢 '+(_btDevice.name||'Connectée'); statusEl.style.color='var(--accent2)'; }
    // Mettre à jour le statut dans le drawer mobile
    const bnStatusEl=document.getElementById('bn-bt-status');
    if(bnStatusEl){ bnStatusEl.textContent='🟢 '+(_btDevice.name||'Connectée'); bnStatusEl.style.color='var(--accent2)'; }
    return true;
  }catch(e){
    if(e.name!=='NotFoundError') notify('❌ Connexion Bluetooth échouée : '+e.message,'err');
    return false;
  }
}

async function _btSend(data){
  const CHUNK=128;
  // Séparer le contenu texte de la commande de coupe (3 derniers octets : 0x1D 0x56 0x01)
  const body = data.slice(0, data.length-3);
  const cut  = data.slice(data.length-3);
  // Envoyer le contenu par petits blocs avec délai suffisant
  for(let i=0;i<body.length;i+=CHUNK){
    const chunk=body.slice(i,i+CHUNK);
    try{
      if(_btChar.properties.writeWithoutResponse){
        await _btChar.writeValueWithoutResponse(chunk);
      }else{
        await _btChar.writeValue(chunk);
      }
      await new Promise(r=>setTimeout(r,80));
    }catch(e){
      throw new Error('Envoi échoué : '+e.message);
    }
  }
  // Pause finale : laisser l'imprimante terminer avant la coupe
  await new Promise(r=>setTimeout(r,250));
  try{
    if(_btChar.properties.writeWithoutResponse){
      await _btChar.writeValueWithoutResponse(cut);
    }else{
      await _btChar.writeValue(cut);
    }
  }catch(e){
    throw new Error('Coupe échouée : '+e.message);
  }
}

// Fonction publique appelée depuis la popup
window.imprimerBluetooth = async function(data, recuNum, emissionDate, emissionHeure, agenceLabel, onDone){
  try{
    if(!_btChar || !_btDevice?.gatt?.connected){
      const ok=await _btConnect();
      if(!ok) return;
    }
    notify('🖨️ Impression en cours...','info');
    const ticket=_buildEscPos(data, recuNum, emissionDate, emissionHeure, agenceLabel);
    await _btSend(ticket);
    notify('✅ Ticket imprimé avec succès !','ok');
    if(typeof onDone==='function') onDone();
  }catch(e){
    notify('❌ Erreur impression Bluetooth : '+e.message,'err');
    _btChar=null;
  }
};

// Connexion manuelle depuis les paramètres
window.connecterImprimanteBT = async function(){
  _btChar=null; _btDevice=null;
  const result = await _btConnect();
  // Mettre à jour le statut dans le drawer mobile si présent
  const statusEl = document.getElementById('bn-bt-status');
  if(statusEl){
    const connected = _btDevice && _btDevice.gatt && _btDevice.gatt.connected;
    statusEl.textContent = connected ? ('🟢 '+(_btDevice.name||'Connectée')) : '🔴 Non connectée';
    statusEl.style.color = connected ? 'var(--accent2)' : 'var(--muted)';
  }
  return result;
};

