// ═══════════════════════════════════════════════════════════
//  TRANSFERT DE SOLDE & RÉSILIATION DE CONTRAT
//  Accès : admin + secrétaire + chef d'agence
//  Logique :
//   1. Chercher client SOURCE → afficher solde total versé
//   2. Chercher client DESTINATION → afficher montant contrat
//   3. Saisir montant manuel → avertissement si dépassement
//   4. Confirmer → fbAdd paiement sur destination + fbUpdate client source statut='resilie' + trace dans 'transferts'
// ═══════════════════════════════════════════════════════════

let _trSrcId = null;   // id client source sélectionné
let _trDstId = null;   // id client destination sélectionné

// ── Accès guard ──────────────────────────────────────────────
function _trCheckAccess(){
  if(!session){ notify('Non connecté','err'); return false; }
  if(!['admin','secretaire','chef_agence'].includes(session.role)){
    notify('Accès refusé — réservé admin, secrétaire & chef d\'agence','err');
    go(getRoleHome(session.role));
    return false;
  }
  return true;
}

// ── VOLET 40 ── Contrat résilié : AUCUN nouvel encaissement ─────────────
// Point unique de vérité, appelé par TOUS les chemins qui créent un
// encaissement pour un client existant (mise, paiement rapide, adhésion,
// rachat de carnet, destination d'un transfert). Avant ce volet, seuls
// openPay/savePay bloquaient : la « Saisie de mises » — le chemin
// principal du terrain — laissait passer un paiement sur un contrat résilié.
// La règle Firestore (firestore.rules, clientNonResilie) double ce contrôle
// côté serveur pour les rôles non-admin.
function _estResilie(c){ return !!c && c.statutContrat === 'resilie'; }
function _refuserSiResilie(c){
  if(!_estResilie(c)) return false;
  notify(`🚫 Contrat de ${esc(c.nom||'ce client')} résilié — aucun encaissement possible.`,'err');
  return true;
}

// ── Render page (historique) ──────────────────────────────────
// ── VOLET 40 ── filtres (période + commercial) et actions admin
// (annuler / supprimer). Le commercial d'un transfert = celui du client
// source OU du client destination : un transfert concerne les deux.
function _trCommerciauxDuTransfert(t){
  const ids = new Set();
  if(t.srcCommercialId) ids.add(t.srcCommercialId);
  if(t.dstCommercialId) ids.add(t.dstCommercialId);
  // Transferts antérieurs au volet 40 : ces champs n'existaient pas, on
  // les déduit des clients chargés.
  if(!t.srcCommercialId){ const s=(DB.clients||[]).find(c=>c._id===t.srcClientId); if(s&&s.commercialId) ids.add(s.commercialId); }
  if(!t.dstCommercialId){ const d=(DB.clients||[]).find(c=>c._id===t.dstClientId); if(d&&d.commercialId) ids.add(d.commercialId); }
  return ids;
}

function _trRemplirFiltreCommercial(){
  const sel = document.getElementById('trf-commercial');
  if(!sel) return;
  const actuel = sel.value;
  const coms = (DB.commerciaux||[])
    .filter(c=>c.role===ROLES.COMMERCIAL)
    .sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  sel.innerHTML = '<option value="">Tous les commerciaux</option>'
    + coms.map(c=>`<option value="${esc(c._id)}">${esc(c.nom||c._id)}</option>`).join('');
  if(actuel && coms.some(c=>c._id===actuel)) sel.value = actuel;
}

window.trFiltresReset = function(){
  ['trf-du','trf-au','trf-commercial','trf-statut'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.value='';
  });
  renderTransfertResiliation();
};

function renderTransfertResiliation(){
  if(!_trCheckAccess()) return;
  const tbody = document.getElementById('tr-historique-body');
  if(!tbody) return;
  _trRemplirFiltreCommercial();
  const isAdminTr = session.role === ROLES.ADMIN;
  const thAct = document.getElementById('tr-th-actions');
  if(thAct) thAct.style.display = isAdminTr ? '' : 'none';
  const nbCols = isAdminTr ? 9 : 8;

  const du   = document.getElementById('trf-du')?.value || '';
  const au   = document.getElementById('trf-au')?.value || '';
  const comF = document.getElementById('trf-commercial')?.value || '';
  const stF  = document.getElementById('trf-statut')?.value || '';
  if(du && au && du > au){
    tbody.innerHTML = `<tr><td colspan="${nbCols}" class="emp">La date de début est postérieure à la date de fin.</td></tr>`;
    const r=document.getElementById('trf-resume'); if(r) r.textContent='';
    return;
  }

  const transferts = (DB.transferts || []).slice()
    .sort((a,b)=>((b.date||'')+(b.heure||'')).localeCompare((a.date||'')+(a.heure||'')))
    .filter(t=>{
      if(du && (t.date||'') < du) return false;
      if(au && (t.date||'') > au) return false;
      if(stF==='actif'  && t.annule) return false;
      if(stF==='annule' && !t.annule) return false;
      if(comF && !_trCommerciauxDuTransfert(t).has(comF)) return false;
      return true;
    });

  const resume = document.getElementById('trf-resume');
  if(resume){
    const actifs = transferts.filter(t=>!t.annule);
    const total = actifs.reduce((s,t)=>s+(Number(t.montant)||0),0);
    resume.textContent = `${transferts.length} transfert(s) · ${actifs.length} actif(s) · ${fmt(total)} transférés (hors annulés)`;
  }

  if(!transferts.length){
    tbody.innerHTML=`<tr><td colspan="${nbCols}" class="emp">${(DB.transferts||[]).length?'Aucun transfert pour ces filtres':'Aucun transfert enregistré'}</td></tr>`;
    return;
  }
  tbody.innerHTML = transferts.map(t=>{
    const src = (DB.clients||[]).find(c=>c._id===t.srcClientId);
    const dst = (DB.clients||[]).find(c=>c._id===t.dstClientId);
    const srcNom = src ? src.nom : (t.srcClientNom || '—');
    const dstNom = dst ? dst.nom : (t.dstClientNom || '—');
    const coms = [..._trCommerciauxDuTransfert(t)].map(id=>getCom(id).nom||'—');
    const badge = t.annule
      ? `<span class="sb sb2" style="font-size:9px;">ANNULÉ</span>`
      : `<span class="resilie-badge" style="font-size:9px;">RÉSILIÉ</span>`;
    const infoAnnul = t.annule
      ? `<div style="font-size:10px;color:var(--muted);margin-top:3px;">Annulé le ${esc(t.annuleLe||'—')} par ${esc(t.annuleParNom||'—')}${t.annuleMotif?' — '+esc(t.annuleMotif):''}</div>`
      : '';
    const actions = !isAdminTr ? '' : `<td style="white-space:nowrap;">
        ${t.annule?'':`<button class="btn btn-ghost btn-xs" title="Annuler : supprime le paiement transféré et réactive le contrat source" onclick="trAnnulerTransfert('${t._id}')">↩ Annuler</button>`}
        <button class="btn btn-xs" style="background:rgba(224,92,82,0.15);color:var(--danger);border:1px solid rgba(224,92,82,0.4);" title="${t.annule?'Supprimer la ligne de l\'historique':'Annuler le transfert puis supprimer la ligne de l\'historique'}" onclick="trSupprimerTransfert('${t._id}')">🗑 Supprimer</button>
      </td>`;
    return `<tr style="${t.annule?'opacity:0.6;':''}">
      <td>${esc(t.date||'—')}</td>
      <td class="tm">${esc(t.heure||'—')}</td>
      <td><strong>${esc(srcNom)}</strong><br>${badge}${infoAnnul}</td>
      <td><strong>${esc(dstNom)}</strong></td>
      <td class="tm" style="font-size:11px;">${esc(coms.join(' / ')||'—')}</td>
      <td style="color:var(--accent2);font-weight:700;${t.annule?'text-decoration:line-through;':''}">${fmt(t.montant||0)}</td>
      <td class="tm" style="font-size:11px;">${esc(t.motif||'—')}</td>
      <td class="tm" style="font-size:11px;">${esc(t.operateur||'—')}</td>
      ${actions}
    </tr>`;
  }).join('');
}

// ── VOLET 40 ── appelée depuis les onchange des filtres (index.html) :
// doit être exposée, sinon elle disparaît à la minification (contrôle 11).
window.renderTransfertResiliation = renderTransfertResiliation;

// ── VOLET 40 ── Annulation d'un transfert (admin) ────────────────────
// Défait les DEUX effets du transfert, dans cet ordre :
//   1. supprime le paiement « source: transfert » du contrat destination
//      (journal d'audit écrit AVANT, comme toute suppression de paiement),
//      puis recalcule son total payé ;
//   2. réactive le contrat source (statutContrat → 'actif') ;
//   3. marque la ligne d'historique « annulée » (elle reste visible).
// Rejouable : si l'opération s'interrompt, la relancer ne trouve plus le
// paiement (déjà supprimé), le signale, et termine les étapes 2 et 3.
// getCl() renvoie un objet factice {nom:'—'} pour un id inconnu : ici on
// veut savoir si le client est réellement chargé, d'où ce find direct.
function _trClient(id){ return (DB.clients||[]).find(c=>c._id===id) || null; }

async function _trTrouverPaiementTransfert(t){
  await _ensureClientPaysLoaded(t.dstClientId);
  const pays = (DB.paiements||[]).filter(p=>p.clientId===t.dstClientId);
  if(t.paiementId){
    const p = pays.find(x=>x._id===t.paiementId);
    return { paiement: p || null, ambigu: false };
  }
  // Transferts antérieurs au volet 40 : l'id du paiement n'était pas
  // conservé. On le retrouve par ses caractéristiques exactes.
  let cands = pays.filter(p=>p.source==='transfert'
    && Number(p.montant)===Number(t.montant) && (p.date||'')===(t.date||''));
  if(cands.length > 1 && t.heure) cands = cands.filter(p=>(p.heure||'')===t.heure);
  if(cands.length === 1) return { paiement: cands[0], ambigu: false };
  return { paiement: null, ambigu: cands.length > 1 };
}

async function _trAnnulerEffets(t, motif){
  // 1. Paiement transféré
  const { paiement, ambigu } = await _trTrouverPaiementTransfert(t);
  if(ambigu){
    notify("Plusieurs paiements de transfert identiques sur le contrat destination — impossible de savoir lequel supprimer. Supprimez le bon paiement depuis l'historique du client, puis relancez l'annulation.",'err');
    return false;
  }
  const dst = _trClient(t.dstClientId) || {};
  if(paiement){
    if(!(await _auditAvantSuppression('paiements', paiement._id, {
      clientId: t.dstClientId, clientNom: dst.nom||t.dstClientNom||'', clientCode: dst.codeClient||'',
      commercialId: paiement.commercialId, montant: paiement.montant,
      date: paiement.date||'', heure: paiement.heure||'', note: paiement.note||'',
      libelleCourt: `Annulation transfert — ${fmt(paiement.montant)} retiré de ${dst.nom||t.dstClientNom||'—'}`,
      extra: { transfertId: t._id },
      motifImpose: motif
    }))) return false;
    await fbDelete('paiements', paiement._id);
    await _recalcClientPaiementRollup(t.dstClientId);
  } else {
    if(!isOnline){ notify('Annulation impossible hors connexion — le paiement transféré doit être vérifié sur le serveur.','err'); return false; }
    const cont = await confirmDialog(
      `Le paiement de ${fmt(t.montant||0)} sur le contrat destination est introuvable (déjà supprimé ?).\n\nContinuer en réactivant seulement le contrat source ?`,
      {title:'Paiement introuvable', okLabel:'Continuer', danger:true});
    if(!cont) return false;
  }
  // 2. Réactivation du contrat source
  const src = _trClient(t.srcClientId);
  // Client absent de la mémoire (non chargé) : on réactive quand même —
  // fbUpdate ne touche que ces champs.
  if(!src || src.statutContrat === 'resilie'){
    try{
      await fbUpdate('clients', t.srcClientId, {
        statutContrat: 'actif',
        dateResiliation: null, motifResiliation: null, resiliePar: null,
        reactiveLe: TODAY, reactiveParNom: session.nom || session.userId,
        reactiveMotif: 'Annulation transfert — ' + motif
      });
    }catch(e){
      notify('Paiement retiré, mais le contrat source n\'a pas pu être réactivé : '+(e.message||e)+' — relancez l\'annulation.','err');
      return false;
    }
  }
  return true;
}

window.trAnnulerTransfert = _withActionLock((...a)=>'trAnnuler:'+a.join(':'), async function(id){
  if(!session || session.role !== ROLES.ADMIN){ notify('Accès refusé — réservé à l\'administrateur','err'); return; }
  const t = (DB.transferts||[]).find(x=>x._id===id);
  if(!t){ notify('Transfert introuvable','err'); return; }
  if(t.annule){ notify('Ce transfert est déjà annulé','err'); return; }
  const srcNom = (_trClient(t.srcClientId)||{}).nom || t.srcClientNom || '—';
  const dstNom = (_trClient(t.dstClientId)||{}).nom || t.dstClientNom || '—';
  const ok = await confirmDialog(
    `Transfert du ${t.date||'—'} : ${esc(srcNom)} → ${esc(dstNom)} (${fmt(t.montant||0)})\n\n`+
    `L'annulation va :\n• supprimer le paiement de ${fmt(t.montant||0)} sur le contrat de ${esc(dstNom)}\n`+
    `• réactiver le contrat de ${esc(srcNom)}\n• garder la ligne dans l'historique, marquée ANNULÉ.`,
    {title:'↩ Annuler ce transfert ?', okLabel:'Annuler le transfert', danger:true});
  if(!ok) return;
  const motif = (prompt("Motif de l'annulation (obligatoire, enregistré au journal d'audit) :")||'').trim();
  if(!motif){ notify('Annulation abandonnée — un motif est obligatoire','err'); return; }
  try{
    if(!(await _trAnnulerEffets(t, motif))) return;
    await fbUpdate('transferts', id, {
      annule: true, annuleLe: TODAY, annuleParId: session.userId,
      annuleParNom: session.nom || session.userId, annuleMotif: motif
    });
    notify(`✅ Transfert annulé — ${esc(srcNom)} réactivé, ${fmt(t.montant||0)} retiré de ${esc(dstNom)}`);
  }catch(e){
    notify("Erreur lors de l'annulation : "+(e.message||e),'err');
  }
  renderTransfertResiliation();
});

window.trSupprimerTransfert = _withActionLock((...a)=>'trSupprimer:'+a.join(':'), async function(id){
  if(!session || session.role !== ROLES.ADMIN){ notify('Accès refusé — réservé à l\'administrateur','err'); return; }
  const t = (DB.transferts||[]).find(x=>x._id===id);
  if(!t){ notify('Transfert introuvable','err'); return; }
  const srcNom = (_trClient(t.srcClientId)||{}).nom || t.srcClientNom || '—';
  const dstNom = (_trClient(t.dstClientId)||{}).nom || t.dstClientNom || '—';
  const msg = t.annule
    ? `Supprimer définitivement la ligne du transfert annulé ${esc(srcNom)} → ${esc(dstNom)} (${fmt(t.montant||0)}) ?\n\nLa trace restera dans le journal d'audit.`
    : `Ce transfert est ACTIF. Le supprimer va d'abord l'annuler :\n• suppression du paiement de ${fmt(t.montant||0)} sur ${esc(dstNom)}\n• réactivation du contrat de ${esc(srcNom)}\npuis effacer la ligne de l'historique.\n\nLa trace restera dans le journal d'audit.`;
  if(!(await confirmDialog(msg,{title:'🗑 Supprimer ce transfert ?', okLabel:'Supprimer', danger:true}))) return;
  const motif = (prompt("Motif de la suppression (obligatoire, enregistré au journal d'audit) :")||'').trim();
  if(!motif){ notify('Suppression abandonnée — un motif est obligatoire','err'); return; }
  try{
    if(!t.annule && !(await _trAnnulerEffets(t, motif))) return;
    const comSrc = t.srcCommercialId || (_trClient(t.srcClientId)||{}).commercialId || '';
    if(!(await _auditAvantSuppression('transferts', id, {
      clientId: t.srcClientId, clientNom: srcNom, commercialId: comSrc,
      montant: t.montant, date: t.date||'', heure: t.heure||'', note: t.motif||'',
      libelleCourt: `Transfert ${srcNom} → ${dstNom} — ${fmt(t.montant||0)}${t.annule?' (déjà annulé)':''}`,
      extra: { dstClientId: t.dstClientId, dstClientNom: dstNom, paiementId: t.paiementId||null, etaitAnnule: !!t.annule },
      motifImpose: motif
    }))) return;
    await fbDelete('transferts', id);
    notify('✅ Transfert supprimé (tracé au journal d\'audit)');
  }catch(e){
    notify('Erreur lors de la suppression : '+(e.message||e),'err');
  }
  renderTransfertResiliation();
});

// ── Live search SOURCE ────────────────────────────────────────
window.trSrcLiveSearch = function(){
  const q = (document.getElementById('tr-src-search').value||'').toLowerCase().trim();
  const box = document.getElementById('tr-src-results');
  if(q.length < 2){ box.style.display='none'; return; }
  const results = (DB.clients||[]).filter(c=>{
    if(c.statutContrat==='resilie') return false;
    return (c.nom||'').toLowerCase().includes(q)
        || (c.codeClient||'').toLowerCase().includes(q)
        || (c.tel||'').includes(q);
  }).slice(0,8);
  if(!results.length){ box.innerHTML='<div style="padding:8px;font-size:12px;color:var(--muted);">Aucun client trouvé</div>'; box.style.display='block'; return; }
  // ── ÉTAPE 2 DU CHANTIER (dénormalisation) : lecture directe de
  // c.totalPaye (tenu à jour à chaque paiement) au lieu de scanner
  // DB.paiements pour chaque client trouvé — cette recherche porte sur
  // TOUS les clients de l'organisation, pas un seul.
  box.innerHTML = results.map(c=>{
    const totalPaye = (Number(c.totalPaye)||0);
    return `<div onclick="trSelectSrc('${c._id}')" style="padding:8px 10px;cursor:pointer;border-radius:7px;border:1px solid var(--border);margin-bottom:4px;background:var(--surface2);">
      <strong style="font-size:12px;">${esc(c.nom)}</strong>
      <span class="tag" style="margin-left:6px;">${esc(c.codeClient||'—')}</span>
      <span style="font-size:11px;color:var(--accent2);margin-left:6px;">${fmt(totalPaye)} versés</span>
    </div>`;
  }).join('');
  box.style.display='block';
};

window.trSelectSrc = function(id){
  _trSrcId = id;
  const c = DB.clients.find(cl=>cl._id===id);
  if(!c){ return; }
  document.getElementById('tr-src-results').style.display='none';
  document.getElementById('tr-src-search').value = c.nom + (c.codeClient?' ('+c.codeClient+')':'');
  const totalPaye = (Number(c.totalPaye)||0);
  const info = document.getElementById('tr-src-info');
  info.style.display='block';
  info.innerHTML=`<div class="ib ib-red">
    <strong>📋 ${esc(c.nom)}</strong> — ${esc(c.contrat||'—')}<br>
    💰 Total versé : <strong style="color:var(--accent2);">${fmt(totalPaye)}</strong>
    &nbsp;/&nbsp; Contrat : <strong>${fmt(c.montantTotal||0)}</strong><br>
    <span style="font-size:10px;color:var(--muted);">Tel: ${esc(c.tel||'—')} · Commercial : ${esc((DB.commerciaux||[]).find(x=>x._id===c.commercialId)?.nom||'—')}</span>
  </div>`;
  _trCheckBothSelected();
};

// ── Live search DESTINATION ───────────────────────────────────
window.trDstLiveSearch = function(){
  const q = (document.getElementById('tr-dst-search').value||'').toLowerCase().trim();
  const box = document.getElementById('tr-dst-results');
  if(q.length < 2){ box.style.display='none'; return; }
  const results = (DB.clients||[]).filter(c=>{
    if(c._id===_trSrcId) return false; // exclure le source
    // ── VOLET 40 ── un contrat résilié ne peut plus recevoir d'encaissement,
    // y compris un solde transféré.
    if(_estResilie(c)) return false;
    return (c.nom||'').toLowerCase().includes(q)
        || (c.codeClient||'').toLowerCase().includes(q)
        || (c.tel||'').includes(q);
  }).slice(0,8);
  if(!results.length){ box.innerHTML='<div style="padding:8px;font-size:12px;color:var(--muted);">Aucun client trouvé</div>'; box.style.display='block'; return; }
  // ── ÉTAPE 2 DU CHANTIER (dénormalisation) : idem trSrcLiveSearch ci-dessus.
  box.innerHTML = results.map(c=>{
    const totalPaye = (Number(c.totalPaye)||0);
    const restant = Math.max(0,(c.montantTotal||0)-totalPaye);
    return `<div onclick="trSelectDst('${c._id}')" style="padding:8px 10px;cursor:pointer;border-radius:7px;border:1px solid var(--border);margin-bottom:4px;background:var(--surface2);">
      <strong style="font-size:12px;">${esc(c.nom)}</strong>
      <span class="tag" style="margin-left:6px;">${esc(c.codeClient||'—')}</span>
      <span style="font-size:11px;color:var(--accent);margin-left:6px;">${fmt(restant)} restant</span>
    </div>`;
  }).join('');
  box.style.display='block';
};

window.trSelectDst = function(id){
  _trDstId = id;
  const c = DB.clients.find(cl=>cl._id===id);
  if(!c){ return; }
  document.getElementById('tr-dst-results').style.display='none';
  document.getElementById('tr-dst-search').value = c.nom + (c.codeClient?' ('+c.codeClient+')':'');
  const totalPaye = (Number(c.totalPaye)||0);
  const restant = Math.max(0,(c.montantTotal||0)-totalPaye);
  const info = document.getElementById('tr-dst-info');
  info.style.display='block';
  info.innerHTML=`<div class="ib ib-green">
    <strong>📋 ${esc(c.nom)}</strong> — ${esc(c.contrat||'—')}<br>
    💰 Déjà versé : <strong style="color:var(--accent2);">${fmt(totalPaye)}</strong>
    &nbsp;·&nbsp; Restant à couvrir : <strong style="color:var(--accent);">${fmt(restant)}</strong><br>
    <span style="font-size:10px;color:var(--muted);">Montant total contrat : ${fmt(c.montantTotal||0)}</span>
  </div>`;
  _trCheckBothSelected();
};

// ── Afficher zone montant si les deux sont sélectionnés ───────
function _trCheckBothSelected(){
  const zone = document.getElementById('tr-montant-zone');
  if(_trSrcId && _trDstId && zone) zone.style.display='block';
}

// ── Vérification avertissement dépassement ────────────────────
window.trCheckWarn = function(){
  const warn = document.getElementById('trs-warn');
  if(!warn || !_trDstId) return;
  const montant = parseFloat(document.getElementById('tr-montant').value)||0;
  const dst = DB.clients.find(c=>c._id===_trDstId);
  if(!dst){ warn.style.display='none'; return; }
  const totalPayeDst = (Number(dst.totalPaye)||0);
  const restant = Math.max(0,(dst.montantTotal||0)-totalPayeDst);
  if(montant > restant){
    warn.style.display='block';
    warn.innerHTML=`⚠️ Attention : le montant transféré (${fmt(montant)}) dépasse le solde restant du contrat destination (${fmt(restant)}). L'opération est quand même autorisée.`;
  } else {
    warn.style.display='none';
  }
};

// ── Confirmer le transfert ────────────────────────────────────
window.trConfirmer = _withActionLock('trConfirmer', async function(){
  if(!_trCheckAccess()) return;
  if(!_trSrcId || !_trDstId){ notify('Sélectionnez les deux clients','err'); return; }
  const montant = parseFloat(document.getElementById('tr-montant').value)||0;
  if(montant <= 0){ notify('Montant invalide','err'); return; }
  const motif = (document.getElementById('tr-motif').value||'').trim();
  const srcClient = DB.clients.find(c=>c._id===_trSrcId);
  const dstClient = DB.clients.find(c=>c._id===_trDstId);
  if(!srcClient || !dstClient){ notify('Client introuvable','err'); return; }
  // ── VOLET 40 ── revérifié ici : le statut a pu changer depuis la sélection.
  if(_estResilie(srcClient)){ notify(`${esc(srcClient.nom)} est déjà résilié.`,'err'); return; }
  if(_refuserSiResilie(dstClient)) return;

  // Confirmation double
  const ok = await confirmDialog(
    `Source (à résilier) : ${esc(srcClient.nom)}\n`+
    `Destination : ${esc(dstClient.nom)}\n`+
    `Montant : ${fmt(montant)}\n\n`+
    `Le contrat de ${esc(srcClient.nom)} sera marqué RÉSILIÉ.\n`+
    `Cette action est irréversible.`,
    {title:'⚠️ Confirmation du transfert', okLabel:'Continuer', danger:true}
  );
  if(!ok) return;

  const btn = document.getElementById('tr-btn-confirm');
  if(btn){ btn.disabled=true; btn.textContent='⏳ En cours…'; }

  try {
    const now = new Date();
    const heure = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
    const operateur = session.nom || session.userId;

    // 1. Enregistrer le paiement sur le contrat destination
    const _paiTr = await fbAdd('paiements',{
      clientId: _trDstId,
      commercialId: dstClient.commercialId || session.userId,
      cotisJour: 0,
      montant: montant,
      date: TODAY,
      heure: heure,
      note: `Transfert depuis ${esc(srcClient.nom)}${srcClient.codeClient?' ('+srcClient.codeClient+')':''} · ${motif||'Transfert de contrat'}`,
      saisiParId: session.userId,
      saisiParNom: operateur,
      source: 'transfert',
      verrouille: true
    });
    await _recalcClientPaiementRollup(_trDstId);

    // 2. Marquer le contrat source comme résilié (ne pas supprimer)
    await fbUpdate('clients', _trSrcId, {
      statutContrat: 'resilie',
      dateResiliation: TODAY,
      motifResiliation: motif || 'Transfert vers contrat '+dstClient.nom,
      resiliePar: operateur
    });

    // 3. Enregistrer la trace dans la collection 'transferts'
    await fbAdd('transferts',{
      srcClientId: _trSrcId,
      dstClientId: _trDstId,
      montant: montant,
      motif: motif || '—',
      date: TODAY,
      heure: heure,
      operateur: operateur,
      operateurId: session.userId,
      // ── VOLET 40 ── champs ajoutés pour l'annulation et les filtres :
      // l'id du paiement créé (sinon il faut le retrouver par montant/date),
      // les commerciaux et noms figés au moment du transfert.
      paiementId: (_paiTr && _paiTr._id) || null,
      srcCommercialId: srcClient.commercialId || '',
      dstCommercialId: dstClient.commercialId || '',
      srcClientNom: srcClient.nom || '', srcClientCode: srcClient.codeClient || '',
      dstClientNom: dstClient.nom || '', dstClientCode: dstClient.codeClient || ''
    });

    notify(`✅ Transfert effectué — ${esc(srcClient.nom)} résilié · ${fmt(montant)} ajouté au contrat de ${esc(dstClient.nom)}`);
    trReset();
    renderTransfertResiliation();

  } catch(e){
    notify('Erreur lors du transfert : '+e.message,'err');
    if(btn){ btn.disabled=false; btn.textContent='🔄 Confirmer le transfert & résilier'; }
  }
});

// ── Réinitialiser le formulaire ───────────────────────────────
window.trReset = function(){
  _trSrcId = null;
  _trDstId = null;
  const ids = ['tr-src-search','tr-src-results','tr-src-info','tr-dst-search','tr-dst-results','tr-dst-info','tr-montant','tr-motif','trs-warn'];
  ids.forEach(id=>{
    const el = document.getElementById(id);
    if(!el) return;
    if(el.tagName==='INPUT') el.value='';
    else el.style.display='none';
  });
  const zone = document.getElementById('tr-montant-zone');
  if(zone) zone.style.display='none';
  const btn = document.getElementById('tr-btn-confirm');
  if(btn){ btn.disabled=false; btn.textContent='🔄 Confirmer le transfert & résilier'; }
};
// ═══════════════ FIN TRANSFERT RÉSILIATION ═══════════════════

// ═══════════════ DÉPENSES COMMERCIAUX ═════════════════════════
// Saisie de dotations de fonds par commercial (entraide, carburant,
// vidange, réparation, etc.) — réservé à l'admin et au chef d'agence.

function _depCheckAccess(){
  if(!session){ notify('Non connecté','err'); return false; }
  if(!['admin','chef_agence'].includes(session.role)){
    notify("Accès refusé — réservé à l'administrateur ou au chef d'agence","err");
    go(getRoleHome(session.role));
    return false;
  }
  return true;
}

window.depToggleAutre = function(){
  const sel = document.getElementById('dep-nature');
  const zone = document.getElementById('dep-autre-zone');
  if(!sel || !zone) return;
  zone.style.display = (sel.value==='Autre') ? '' : 'none';
};

function _depPopulateSelects(){
  const coms = comsDansAgence().filter(c=>c.role===ROLES.COMMERCIAL).sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  const selForm = document.getElementById('dep-commercial');
  const selFiltre = document.getElementById('dep-filtre-commercial');
  if(selForm){
    const prev = selForm.value;
    selForm.innerHTML = `<option value="">— Sélectionner un commercial —</option>` +
      coms.map(c=>`<option value="${c._id}"${c._id===prev?' selected':''}>${esc(c.nom)}</option>`).join('');
  }
  if(selFiltre){
    const prev = selFiltre.value;
    selFiltre.innerHTML = `<option value="">— Tous les commerciaux —</option>` +
      coms.map(c=>`<option value="${c._id}"${c._id===prev?' selected':''}>${esc(c.nom)}</option>`).join('');
  }
  // ✅ Filtre par nature de dépense — construit à partir des natures
  // réellement présentes dans les données (pas une liste figée), pour ne
  // jamais rater une nature personnalisée saisie via "Autre (préciser)"
  // (voir depEnregistrer : nature = texte libre si "Autre" est choisi).
  const selNature = document.getElementById('dep-filtre-nature');
  if(selNature){
    const comIds = new Set(coms.map(c=>c._id));
    const natures = [...new Set((DB.depenses||[])
      .filter(d=>comIds.has(d.commercialId))
      .map(d=>d.nature||'')
      .filter(Boolean))].sort((a,b)=>a.localeCompare(b));
    const prev = selNature.value;
    selNature.innerHTML = `<option value="">— Toutes les natures —</option>` +
      natures.map(n=>`<option value="${esc(n)}"${n===prev?' selected':''}>${esc(n)}</option>`).join('');
    selNature.value = prev; // si la nature sélectionnée a disparu (dépense supprimée), retombe sur ""
  }
}

window.depResetForm = function(){
  const ids = ['dep-commercial','dep-nature-autre','dep-montant','dep-note'];
  ids.forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  const nat = document.getElementById('dep-nature'); if(nat) nat.value='Entraide';
  const dt = document.getElementById('dep-date'); if(dt) dt.value = TODAY;
  const zone = document.getElementById('dep-autre-zone'); if(zone) zone.style.display='none';
  const btn = document.getElementById('dep-btn-save');
  if(btn){ btn.disabled=false; btn.textContent='💾 Enregistrer la dépense'; }
};

window.depResetFiltres = function(){
  const ids = ['dep-filtre-commercial','dep-filtre-nature','dep-filtre-date-debut','dep-filtre-date-fin'];
  ids.forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  renderDepensesCommerciaux();
};

// ── VOLET 42 ── Lundi et dimanche (AAAA-MM-JJ) de la semaine d'une date.
// Calcul en heure locale à midi : pas de décalage de jour lié au fuseau.
function _depSemaine(dateIso){
  const d = new Date(dateIso + 'T12:00:00');
  const decal = (d.getDay() + 6) % 7;          // lundi = 0 … dimanche = 6
  const lundi = new Date(d); lundi.setDate(d.getDate() - decal);
  const dim   = new Date(lundi); dim.setDate(lundi.getDate() + 6);
  const iso = x => `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;
  return { lundi: iso(lundi), dimanche: iso(dim) };
}

window.depEnregistrer = _withActionLock('depEnregistrer', async function(){
  if(!_depCheckAccess()) return;
  const commercialId = (document.getElementById('dep-commercial')||{}).value;
  if(!commercialId){ notify('Sélectionnez un commercial','err'); return; }
  const natureSel = (document.getElementById('dep-nature')||{}).value || 'Autre';
  const montant = parseFloat((document.getElementById('dep-montant')||{}).value)||0;
  if(montant <= 0){ notify('Montant invalide','err'); return; }
  const note = ((document.getElementById('dep-note')||{}).value||'').trim();
  const dateChoisie = (document.getElementById('dep-date')||{}).value || TODAY;
  const nature = natureSel==='Autre'
    ? (((document.getElementById('dep-nature-autre')||{}).value||'').trim() || 'Autre')
    : natureSel;

  if(natureSel==='Autre' && !nature){ notify('Précisez la nature de la dépense','err'); return; }

  const com = DB.commerciaux.find(c=>c._id===commercialId);
  if(!com){ notify('Commercial introuvable','err'); return; }

  // ╔══════════════════════════════════════════════════════════════╗
  // ║  VOLET 36 — PRIME DU SAMEDI : DEUX RISQUES, DEUX AVERTIS     ║
  // ╚══════════════════════════════════════════════════════════════╝
  // Cette nature est saisie a la main, alors que « Prime journaliere » est
  // generee automatiquement par le bouton 🏆. Deux erreurs deviennent donc
  // possibles, et aucune ne se voit apres coup :
  //
  //   1. SE TROMPER DE JOUR. Une « prime du samedi » datee d'un mardi passe
  //      inapercue dans la liste : la colonne Date est lue en diagonale, et
  //      le libelle, lui, dit « samedi ». Le controle de fin de mois ne
  //      rattrape rien.
  //   2. PAYER DEUX FOIS. Le commercial peut deja avoir recu une prime pour
  //      cette date — la prime automatique, ou une prime du samedi saisie par
  //      quelqu'un d'autre. Rien ne l'empechait.
  //
  // CHOIX RETENU : AVERTIR, PAS BLOQUER. Un blocage dur empecherait une
  // regularisation legitime (prime d'un samedi passe, saisie le lundi avec la
  // bonne date ; ou double prime volontaire sur decision du chef d'agence).
  // L'avertissement nomme precisement ce qui cloche et demande une
  // confirmation explicite.
  //
  // ⚠️ LIMITE ASSUMEE : le controle de doublon porte sur ce qui est EN
  // MEMOIRE (DB.depenses). Si la depense jumelle a ete saisie ailleurs et
  // n'est pas encore synchronisee sur cet appareil, elle ne sera pas vue.
  // C'est la meme base que le controle de doublon de la generation
  // automatique ; l'absence d'avertissement ne prouve donc pas l'absence de
  // doublon.
  // ── VOLET 42 ── PRIME HEBDOMADAIRE : saisie à la main, comme la prime du
  // samedi, et même principe : AVERTIR, PAS BLOQUER. Le risque principal est
  // de la payer deux fois la même semaine. Semaine = du LUNDI au DIMANCHE
  // contenant la date choisie. Même limite que ci-dessous : seules les
  // dépenses présentes en mémoire sont contrôlées.
  if(nature === 'Prime hebdomadaire'){
    const sem = _depSemaine(dateChoisie);
    const deja = (DB.depenses||[]).filter(d =>
      d.commercialId === commercialId && d.nature === 'Prime hebdomadaire'
      && (d.date||'') >= sem.lundi && (d.date||'') <= sem.dimanche);
    if(deja.length){
      const detail = deja.map(d=>`${fmt(d.montant)} le ${d.date}`).join(', ');
      const ok = await confirmDialog(
        `${com.nom} a déjà une prime hebdomadaire pour la semaine du ${sem.lundi} au ${sem.dimanche} : ${detail}.\n\nEnregistrer quand même ?`,
        { title:'⚠️ Prime hebdomadaire déjà versée', okLabel:'Enregistrer quand même', danger:true });
      if(!ok) return;
    }
  }

  if(nature === 'Prime journalière samedi'){
    const anomalies = [];
    const jour = new Date(dateChoisie + 'T12:00:00').getDay();   // 6 = samedi
    if(jour !== 6){
      const nomJour = new Date(dateChoisie + 'T12:00:00')
        .toLocaleDateString('fr-FR',{weekday:'long', day:'numeric', month:'long', year:'numeric'});
      anomalies.push(`La date choisie est un ${nomJour} — ce n'est pas un samedi.`);
    }
    const dejaPrime = (DB.depenses||[]).filter(d =>
      d.commercialId === commercialId && d.date === dateChoisie &&
      String(d.nature||'').startsWith('Prime journalière'));
    if(dejaPrime.length){
      const detail = dejaPrime.map(d=>`« ${d.nature} » de ${fmt(d.montant)}`).join(', ');
      anomalies.push(`${com.nom} a déjà ${detail} à cette date.`);
    }
    if(anomalies.length){
      const ok = await confirmDialog(
        anomalies.join('\n\n') + '\n\nEnregistrer quand même ?',
        { title:'⚠️ Vérifiez cette prime', okLabel:'Enregistrer quand même', danger:true });
      if(!ok) return;
    }
  }

  const btn = document.getElementById('dep-btn-save');
  if(btn){ btn.disabled=true; btn.textContent='⏳ Enregistrement…'; }

  try {
    const now = new Date();
    const heure = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
    await fbAdd('depenses',{
      commercialId: commercialId,
      commercialNom: com.nom,
      nature: nature,
      montant: montant,
      note: note,
      date: dateChoisie,
      heure: heure,
      saisiParId: session.userId,
      saisiParNom: session.nom || session.userId
    });
    notify(`✅ Dépense enregistrée — ${fmt(montant)} (${nature}) pour ${esc(com.nom)}`);
    depResetForm();
    renderDepensesCommerciaux();
  } catch(e){
    notify("Erreur lors de l'enregistrement : "+e.message,'err');
    if(btn){ btn.disabled=false; btn.textContent='💾 Enregistrer la dépense'; }
  }
});

window.depSupprimer = _withActionLock((...a)=>'depSupprimer:'+a.join(':'), async function(id){
  if(!session || session.role!=='admin'){ notify('Suppression réservée à l\'administrateur','err'); return; }
  const ok = await confirmDialog('Supprimer définitivement cette dépense ?',{title:'🗑 Suppression',okLabel:'Supprimer',danger:true});
  if(!ok) return;
  // ── VOLET 38 ──
  const _d = (DB.depenses||[]).find(x=>x._id===id) || {};
  if(!(await _auditAvantSuppression('depenses', id, {
    commercialId: _d.commercialId||'', commercialNom: _d.commercialNom||'',
    montant: _d.montant, date: _d.date||'', heure: _d.heure||'', note: _d.note||'',
    libelleCourt: `${fmt(_d.montant)} — ${_d.nature||'—'} — ${_d.commercialNom||'—'}`,
    extra: { nature: _d.nature||'' }
  }))) return;
  try {
    await fbDelete('depenses', id);
    notify('Dépense supprimée');
    renderDepensesCommerciaux();
  } catch(e){
    notify('Erreur lors de la suppression : '+e.message,'err');
  }
});

// ── Génération automatique des primes journalières ────────────
// Calcule, pour chaque commercial visible (filtré par agence pour un chef
// d'agence), le total encaissé du jour choisi (cotisations + adhésions,
// même logique que le registre), détermine la prime via les paliers
// définis (calculerPrime) et l'enregistre comme une dépense de nature
// "Prime journalière". Une prime déjà générée pour ce commercial à cette
// date n'est jamais dupliquée (elle est simplement ignorée).
window.depGenererPrimesJour = async function(){
  if(!_depCheckAccess()) return;
  const date = (document.getElementById('dep-prime-date')||{}).value;
  if(!date){ notify('Sélectionnez une date','err'); return; }

  const btn = document.getElementById('dep-btn-gen-primes');
  const resume = document.getElementById('dep-prime-resume');
  if(btn){ btn.disabled=true; btn.textContent='⏳ Calcul en cours…'; }

  try {
    const [paysDate, adhDate] = await Promise.all([
      _fetchColByDate('paiements', date),
      _fetchColByDate('adhesionPays', date)
    ]);

    let coms = comsDansAgence().filter(c=>c.role===ROLES.COMMERCIAL);
    const comIds = new Set(coms.map(c=>c._id));

    const pays = paysDate.filter(p=>p.origine!=='import_historique' && p.source!=='transfert' && comIds.has(p.commercialId));
    const adh = adhDate.filter(a=>comIds.has(a.commercialId));
    // Dépenses déjà enregistrées pour cette date (pour éviter les doublons)
    const dejaGenerees = new Set(
      (DB.depenses||[])
        .filter(d=>d.date===date && d.nature==='Prime journalière')
        .map(d=>d.commercialId)
    );

    const now = new Date();
    const heure = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
    const operateur = session.nom || session.userId;

    let totalEncaisse = 0, totalPrimesGenerees = 0, nbPrimees = 0, nbIgnorees = 0, nbSansPrime = 0;
    const details = [];

    for(const c of coms){
      const montantCotis = pays.filter(p=>p.commercialId===c._id).reduce((a,p)=>a+(Number(p.montant)||0),0);
      const montantAdh = adh.filter(a=>a.commercialId===c._id).reduce((a,x)=>a+Number(x.montant||0),0);
      const montantTotal = montantCotis + montantAdh;
      if(montantTotal<=0) continue;
      totalEncaisse += montantTotal;

      // Nouveaux clients enregistrés ce jour par ce commercial — condition
      // de validation de la prime (au moins 2 requis).
      const nbNouveauxClients = DB.clients.filter(cl=>
        cl.commercialId===c._id &&
        (cl.debut===date || cl.createdAt===date) &&
        cl.origine!=='import'
      ).length;

      const palier = calculerPrime(montantCotis, nbNouveauxClients);
      if(!palier){ nbSansPrime++; continue; }

      if(dejaGenerees.has(c._id)){
        nbIgnorees++;
        details.push({nom:c.nom, montantTotal, prime:Number(palier.montant), statut:'déjà générée'});
        continue;
      }

      await fbAdd('depenses',{
        commercialId: c._id,
        commercialNom: c.nom,
        nature: 'Prime journalière',
        montant: Number(palier.montant),
        note: `Palier "${palier.label||'—'}" atteint · total du jour ${fmt(montantTotal)}`,
        date: date,
        heure: heure,
        saisiParId: session.userId,
        saisiParNom: operateur,
        autoGenere: true
      });
      totalPrimesGenerees += Number(palier.montant);
      nbPrimees++;
      details.push({nom:c.nom, montantTotal, prime:Number(palier.montant), statut:'générée'});
    }

    if(resume){
      resume.style.display='block';
      const netApres = totalEncaisse - totalPrimesGenerees;
      resume.innerHTML = `<div class="ib ib-green">
        📅 <strong>${date}</strong> — ${fmt(totalEncaisse)} encaissé sur la journée<br>
        🏆 <strong>${nbPrimees}</strong> prime(s) générée(s) pour un total de <strong style="color:var(--accent);">${fmt(totalPrimesGenerees)}</strong>
        ${nbIgnorees?` &nbsp;·&nbsp; ${nbIgnorees} déjà généré(s) aujourd'hui (ignoré)`:''}
        ${nbSansPrime?` &nbsp;·&nbsp; ${nbSansPrime} commercial(aux) sous le seuil minimum`:''}<br>
        💵 Net après primes : <strong style="color:var(--accent2);">${fmt(netApres)}</strong>
      </div>`;
    }

    if(nbPrimees>0){
      notify(`✅ ${nbPrimees} prime(s) générée(s) — ${fmt(totalPrimesGenerees)} au total`);
    } else if(nbIgnorees>0){
      notify('Toutes les primes de cette date avaient déjà été générées','err');
    } else {
      notify('Aucun commercial n\'atteint un palier de prime pour cette date','err');
    }

    renderDepensesCommerciaux();
  } catch(e){
    notify('Erreur lors de la génération des primes : '+e.message,'err');
  } finally {
    if(btn){ btn.disabled=false; btn.textContent='🏆 Générer les primes du jour'; }
  }
};

// ── VOLET 6 ── meme principe que pour 'recus' (voir _recusAssurerPlage).
let _depRangeEnCours = null;
function _depAssurerPlage(){
  const d = (document.getElementById('dep-filtre-date-debut')||{}).value||'';
  const f = (document.getElementById('dep-filtre-date-fin')||{}).value||'';
  if(!d || !f) return;
  const cle = d + ':' + f;
  if(_depRangeEnCours === cle) return;
  _depRangeEnCours = cle;
  _fetchColDateRange('depenses', d, f)
    .then(() => { if(curPg === 'depenses-commerciaux') renderDepensesCommerciaux(); })
    .catch(e => console.error('[depenses] plage', e));
}

function renderDepensesCommerciaux(){
  if(!_depCheckAccess()) return;
  _depPopulateSelects();
  _depAssurerPlage();

  const dateInput = document.getElementById('dep-date');
  if(dateInput && !dateInput.value) dateInput.value = TODAY;
  const primeDateInput = document.getElementById('dep-prime-date');
  if(primeDateInput && !primeDateInput.value) primeDateInput.value = TODAY;

  const comIdsVisibles = new Set(comsDansAgence().map(c=>c._id));
  let depenses = (DB.depenses||[]).filter(d=>comIdsVisibles.has(d.commercialId));

  const filtreCom = (document.getElementById('dep-filtre-commercial')||{}).value||'';
  const filtreNature = (document.getElementById('dep-filtre-nature')||{}).value||'';
  const filtreDebut = (document.getElementById('dep-filtre-date-debut')||{}).value||'';
  const filtreFin = (document.getElementById('dep-filtre-date-fin')||{}).value||'';

  if(filtreCom) depenses = depenses.filter(d=>d.commercialId===filtreCom);
  if(filtreNature) depenses = depenses.filter(d=>(d.nature||'')===filtreNature);
  if(filtreDebut) depenses = depenses.filter(d=>(d.date||'') >= filtreDebut);
  if(filtreFin) depenses = depenses.filter(d=>(d.date||'') <= filtreFin);

  depenses = depenses.slice().sort((a,b)=>{
    const da = (a.date||'')+(a.heure||''), db = (b.date||'')+(b.heure||'');
    return db.localeCompare(da);
  });

  const total = depenses.reduce((a,d)=>a+(d.montant||0),0);
  const totalEl = document.getElementById('dep-total-filtre');
  if(totalEl) totalEl.textContent = `Total : ${fmt(total)} (${depenses.length} dépense${depenses.length>1?'s':''})`;

  const tbody = document.getElementById('dep-historique-body');
  if(!tbody) return;
  if(!depenses.length){
    tbody.innerHTML = '<tr><td colspan="7" class="emp">Aucune dépense enregistrée</td></tr>';
    return;
  }
  const canDelete = session && session.role===ROLES.ADMIN;
  // FIX PERF : idem reçus — on plafonne le rendu DOM, pas les données/totaux.
  const depTronquees = depenses.length > _HIST_RENDER_CAP;
  const depAffichees = depTronquees ? depenses.slice(0, _HIST_RENDER_CAP) : depenses;
  const _bandeauTronqueDep = depTronquees
    ? `<tr><td colspan="7" style="text-align:center;padding:10px;font-size:11px;color:var(--muted);background:rgba(247,201,79,0.08);">⚠️ Affichage limité aux ${_HIST_RENDER_CAP} dépenses les plus récentes sur ${depenses.length} — affinez les filtres (date, commercial) pour voir le reste.</td></tr>`
    : '';
  tbody.innerHTML = _bandeauTronqueDep + depAffichees.map(d=>`<tr>
    <td class="tm">${d.date||'—'}</td>
    <td><strong>${esc(d.commercialNom||'—')}</strong></td>
    <td>${esc(d.nature||'—')}${d.autoGenere?' <span style="font-size:9px;background:rgba(247,201,79,0.15);border:1px solid rgba(247,201,79,0.35);border-radius:4px;padding:1px 5px;color:var(--accent);">🏆 auto</span>':''}</td>
    <td style="color:var(--accent);font-weight:700;">${fmt(d.montant||0)}</td>
    <td class="tm" style="font-size:11px;">${esc(d.note||'—')}</td>
    <td class="tm" style="font-size:11px;">${esc(d.saisiParNom||'—')}</td>
    <td style="text-align:center;">${canDelete?`<button class="btn btn-xs btn-warn" onclick="depSupprimer('${d._id}')" title="Supprimer">🗑</button>`:''}</td>
  </tr>`).join('');
}
// ═══════════════ FIN DÉPENSES COMMERCIAUX ═════════════════════

// ═══════════════ HISTORIQUE DES REÇUS (réimpression) ═══════════
// Accès réservé à l'administrateur, au chef d'agence et à la secrétaire.
function _recuCheckAccess(){
  if(!session){ notify('Non connecté','err'); return false; }
  if(!['admin','chef_agence','secretaire'].includes(session.role)){
    notify("Accès refusé — réservé à l'administrateur, au chef d'agence ou à la secrétaire","err");
    go(getRoleHome(session.role));
    return false;
  }
  return true;
}

function _recuPopulateSelects(){
  const sel = document.getElementById('recu-filtre-commercial');
  if(!sel) return;
  // ✅ PERF : ne reconstruire (innerHTML) que si la liste des commerciaux a
  // changé — cette fonction est appelée à CHAQUE frappe dans la recherche
  // via renderHistoriqueRecus() → dRender('renderHistoriqueRecus').
  const coms = comsDansAgence().filter(c=>c.role===ROLES.COMMERCIAL).sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  const comsSig = coms.map(c=>c._id).join(',');
  if (sel.dataset.comsSig === comsSig) return;
  const prev = sel.value;
  sel.innerHTML = `<option value="">— Tous les commerciaux —</option>` +
    coms.map(c=>`<option value="${c._id}"${c._id===prev?' selected':''}>${esc(c.nom)}</option>`).join('');
  sel.value = prev;
  sel.dataset.comsSig = comsSig;
}

window.recuResetFiltres = function(){
  const ids = ['recu-filtre-commercial','recu-filtre-type','recu-filtre-date-debut','recu-filtre-date-fin','recu-filtre-recherche'];
  ids.forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  renderHistoriqueRecus();
};

// ── VOLET 6 ── 'recus' ne contient plus que la journee en cours. Cette
// fonction reste SYNCHRONE (elle est appelee par renderPg, qui n'attend pas),
// mais un filtre de periode declenche desormais une recuperation en tache de
// fond, suivie d'un re-rendu. Sans cela, selectionner une plage anterieure
// n'afficherait rien du tout.
// La garde _recusRangeEnCours evite une boucle : le re-rendu declenche par la
// recuperation ne doit pas relancer une recuperation.
let _recusRangeEnCours = null;
function _recusAssurerPlage(){
  const d = (document.getElementById('recu-filtre-date-debut')||{}).value||'';
  const f = (document.getElementById('recu-filtre-date-fin')||{}).value||'';
  if(!d || !f) return;                       // pas de periode demandee
  const cle = d + ':' + f;
  if(_recusRangeEnCours === cle) return;     // deja en cours ou deja fait
  _recusRangeEnCours = cle;
  _fetchColDateRange('recus', d, f)
    .then(() => { if(curPg === 'historique-recus') renderHistoriqueRecus(); })
    .catch(e => console.error('[recus] plage', e));
}

function renderHistoriqueRecus(){
  if(!_recuCheckAccess()) return;
  _recuPopulateSelects();
  _recusAssurerPlage();

  const comIdsVisibles = new Set(comsDansAgence().map(c=>c._id));
  // ── VOLET 66 ── exclure les alertes « reçu non imprimé » : ce ne sont pas
  // des reçus, elles ne doivent pas apparaître dans l'historique des reçus.
  let recus = (DB.recus||[]).filter(r=>comIdsVisibles.has(r.commercialId) && r.type!=='alerte_non_impression');

  const filtreCom = (document.getElementById('recu-filtre-commercial')||{}).value||'';
  const filtreType = (document.getElementById('recu-filtre-type')||{}).value||'';
  const filtreDebut = (document.getElementById('recu-filtre-date-debut')||{}).value||'';
  const filtreFin = (document.getElementById('recu-filtre-date-fin')||{}).value||'';
  const q = (document.getElementById('recu-filtre-recherche')||{}).value.trim().toLowerCase();

  if(filtreCom) recus = recus.filter(r=>r.commercialId===filtreCom);
  if(filtreType) recus = recus.filter(r=>(r.type||'cotisation')===filtreType);
  if(filtreDebut) recus = recus.filter(r=>(r.date||'') >= filtreDebut);
  if(filtreFin) recus = recus.filter(r=>(r.date||'') <= filtreFin);
  if(q){
    recus = recus.filter(r =>
      (r.recuNum||'').toLowerCase().includes(q) ||
      (r.clientNom||'').toLowerCase().includes(q) ||
      (r.clientCode||'').toLowerCase().includes(q)
    );
  }

  recus = recus.slice().sort((a,b)=>{
    const da = (a.date||'')+(a.heure||''), db = (b.date||'')+(b.heure||'');
    return db.localeCompare(da);
  });

  const total = recus.reduce((a,r)=>a+(Number(r.montant)||0),0);
  const totalEl = document.getElementById('recu-total-filtre');
  if(totalEl) totalEl.textContent = `Total : ${fmt(total)} (${recus.length} reçu${recus.length>1?'s':''})`;

  const tbody = document.getElementById('recu-historique-body');
  if(!tbody) return;
  if(!recus.length){
    tbody.innerHTML = '<tr><td colspan="8" class="emp">Aucun reçu enregistré</td></tr>';
    return;
  }
  const typeLabels = {cotisation:'💳 Cotisation(s)', adhesion:'🤝 Adhésion', rachat_carnet:'📘 Rachat carnet'};
  // FIX PERF : on ne rend que les _HIST_RENDER_CAP reçus les plus récents ;
  // le total affiché juste au-dessus reste calculé sur la liste complète.
  const recusTronques = recus.length > _HIST_RENDER_CAP;
  const recusAffiches = recusTronques ? recus.slice(0, _HIST_RENDER_CAP) : recus;
  const _bandeauTronque = recusTronques
    ? `<tr><td colspan="8" style="text-align:center;padding:10px;font-size:11px;color:var(--muted);background:rgba(247,201,79,0.08);">⚠️ Affichage limité aux ${_HIST_RENDER_CAP} reçus les plus récents sur ${recus.length} — affinez les filtres (date, commercial, recherche) pour voir le reste.</td></tr>`
    : '';
  tbody.innerHTML = _bandeauTronque + recusAffiches.map(r=>`<tr>
    <td class="tm" style="font-weight:700;color:var(--accent);">${esc(r.recuNum||'—')}</td>
    <td class="tm">${esc(r.date||'—')} ${esc(r.heure||'')}</td>
    <td>${typeLabels[r.type||'cotisation']||'💳 Cotisation(s)'}</td>
    <td><strong>${esc(r.clientNom||'—')}</strong>${r.clientCode?` <span style="font-size:9px;color:var(--muted);">(${esc(r.clientCode)})</span>`:''}</td>
    <td class="tm">${esc(r.commercialNom||'—')}</td>
    <td style="color:var(--accent);font-weight:700;">${fmt(r.montant||0)}</td>
    <td class="tm" style="font-size:11px;">${esc(r.saisiParNom||'—')}</td>
    <td style="text-align:center;white-space:nowrap;">
      <button class="btn btn-xs" style="background:rgba(120,140,255,0.12);color:#8fa4ff;border:1px solid rgba(120,140,255,0.3)" onclick="reimprimerRecu('${r._id}')" title="Réimprimer ce reçu">🖨️ Réimprimer</button>
      <button class="btn btn-xs" style="background:rgba(201,168,76,0.12);color:var(--accent);border:1px solid rgba(201,168,76,0.3);margin-left:4px;" onclick="envoyerRecuAuCommercial('${r._id}')" title="Envoyer ce reçu au commercial via la messagerie">📨 Envoyer</button>
    </td>
  </tr>`).join('');
}
window.renderHistoriqueRecus = renderHistoriqueRecus;

// Délai avant expiration d'un reçu envoyé par message à un commercial.
// Passé ce délai, le bouton "Ouvrir / Imprimer le reçu" du message n'est
// plus consultable (voir renderChatMessages et ouvrirRecuDepuisChat).
const RECU_MSG_TTL_MS = 24*60*60*1000; // 24h

// Envoi d'un reçu au commercial concerné via la messagerie interne — celui-ci
// reçoit un message avec un bouton lui permettant d'ouvrir et d'imprimer le
// reçu directement (sans avoir accès à l'historique complet des reçus).
// Le lien du message expire après RECU_MSG_TTL_MS (24h) : passé ce délai, le
// reçu n'est plus consultable depuis ce message.
window.envoyerRecuAuCommercial = _withActionLock((...a)=>'envoyerRecuAuCommercial:'+a.join(':'), async function(id){
  if(!_recuCheckAccess()) return;
  const r = (DB.recus||[]).find(x=>x._id===id);
  if(!r){ notify('Reçu introuvable','err'); return; }
  const commercialId = r.commercialId;
  if(!commercialId){ notify('Ce reçu n\'est rattaché à aucun commercial','err'); return; }
  const com = DB.commerciaux.find(c=>c._id===commercialId);
  if(!com){ notify('Commercial introuvable','err'); return; }
  const typeLabels = {cotisation:'💳 Cotisation(s)', adhesion:'🤝 Adhésion', rachat_carnet:'📘 Rachat carnet'};
  const texte = `📄 Reçu ${r.recuNum||''} — ${typeLabels[r.type||'cotisation']||'Reçu'} — ${r.clientNom||''} — ${fmt(r.montant||0)}`;
  const convId = _chatPairId(session.userId, commercialId);
  try{
    await _chatEnsureConversation(convId, commercialId);
    const now = Date.now();
    await addDoc(collection(db_fs,'chatMessages'), {
      conversationId: convId,
      type: 'recu',
      recuId: r._id,
      authorId: session.userId,
      authorNom: session.nom,
      authorRole: session.role,
      texte,
      tsMs: now,
      expireAt: now + RECU_MSG_TTL_MS,
      date: TODAY,
      heure: _chatHeureNow(),
      _ts: serverTimestamp()
    });
    const conv = _chatConversations.get(convId) || {};
    const otherUnread = (conv.unread?.[commercialId] || 0) + 1;
    await setDoc(doc(db_fs,'chatConversations',convId), {
      lastMsg: texte.slice(0,120),
      lastAuthorId: session.userId,
      lastAuthorRole: session.role,
      updatedAt: now,
      unread: {[commercialId]: otherUnread, [session.userId]: 0}
    }, {merge:true});
    notify(`Reçu envoyé à ${com.nom} via la messagerie ✓`);
  } catch(e){
    console.error('[envoyerRecuAuCommercial]', e);
    notify("Erreur lors de l'envoi du reçu","err");
  }
});

// Ouverture d'un reçu depuis un message de chat (staff ou commercial) — va
// chercher le document à jour dans Firestore plutôt que de dépendre d'un
// DB.recus potentiellement non chargé pour le rôle courant (ex : commercial).
window.ouvrirRecuDepuisChat = async function(recuId, expireAt){
  if(!recuId){ notify('Reçu introuvable','err'); return; }
  // ✅ Double vérification de l'expiration côté client (en plus du masquage
  // du bouton dans renderChatMessages) : au cas où le bouton serait activé
  // via un affichage non rafraîchi.
  if(expireAt && Date.now() > Number(expireAt)){
    notify('Ce reçu a expiré et ne peut plus être ouvert','err');
    return;
  }
  try{
    const snap = await getDoc(doc(db_fs,'recus',recuId));
    if(!snap.exists()){ notify('Reçu introuvable ou supprimé','err'); return; }
    const r = snap.data();
    afficherRecu({
      type: r.type,
      clientNom: r.clientNom,
      clientCode: r.clientCode,
      clientTel: r.clientTel,
      clientVille: r.clientVille,
      commercialId: r.commercialId,
      commercialNom: r.commercialNom,
      montant: r.montant,
      nbCotis: r.nbCotis,
      cotisJour: r.cotisJour,
      note: r.note,
      saisiParNom: r.saisiParNom
    }, { recuNum: r.recuNum, emissionDate: r.emissionDate, emissionHeure: r.emissionHeure, reprint: true });
  } catch(e){
    console.error('[ouvrirRecuDepuisChat]', e);
    notify("Accès refusé ou erreur lors de l'ouverture du reçu","err");
  }
};

// Réimpression à l'identique d'un reçu déjà émis (même numéro, même date d'émission).
window.reimprimerRecu = function(id){
  if(!_recuCheckAccess()) return;
  const r = (DB.recus||[]).find(x=>x._id===id);
  if(!r){ notify('Reçu introuvable','err'); return; }
  afficherRecu({
    type: r.type,
    clientNom: r.clientNom,
    clientCode: r.clientCode,
    clientTel: r.clientTel,
    clientVille: r.clientVille,
    commercialId: r.commercialId,
    commercialNom: r.commercialNom,
    montant: r.montant,
    nbCotis: r.nbCotis,
    cotisJour: r.cotisJour,
    note: r.note,
    saisiParNom: r.saisiParNom,
    // ── VOLET 16 ── sans ces champs, la reimpression d'un recu annule ne
    // porterait aucune mention et servirait de justificatif pour un
    // encaissement supprime.
    annule: !!r.annule,
    annuleLe: r.annuleLe || '',
    annuleParNom: r.annuleParNom || '',
    annuleMotif: r.annuleMotif || ''
  }, { recuNum: r.recuNum, emissionDate: r.emissionDate, emissionHeure: r.emissionHeure, reprint: true });
};
// ═══════════════ FIN HISTORIQUE DES REÇUS ══════════════════════

// ✅ FIX RÉACTIVITÉ FILTRES/RECHERCHE (tous écrans) ═══════════════
// Ce script est chargé en <script type="module">. Dans un module JS, les
// fonctions déclarées normalement (function xxx(){...}) restent invisibles
// depuis les attributs HTML inline (onchange="...", oninput="...") — ceux-ci
// s'exécutent dans le contexte global, hors du scope du module. Seules les
// fonctions explicitement assignées à window sont accessibles depuis eux.
// dRender() (utilisée par presque tous les champs de recherche) et plusieurs
// fonctions de rendu appelées directement en onchange n'étaient PAS exposées
// sur window : chaque frappe/sélection déclenchait une erreur silencieuse
// (aucun message visible), et le filtre ne s'appliquait qu'après un
// rechargement complet de la page (qui, lui, passe par go() → exposé sur
// window → appelle ces fonctions en interne, dans le scope du module).
window.dRender = dRender;
window.safeRender = safeRender;
window.toggleSidebar = toggleSidebar;
window.mettreAJourSelectionBar = mettreAJourSelectionBar;
window.renderArticles = renderArticles;
// ✅ FIX BUG : ces fonctions sont appelées via dRender('nomFonction') → safeRender
// → window[nomFonction], donc elles DOIVENT être exposées sur window, sinon
// "Uncaught ReferenceError: ... is not defined" dès qu'un filtre/recherche
// correspondant est utilisé.
window.renderCatalogue = renderCatalogue;
window.renderFiche = renderFiche;
window.renderHist = renderHist;
window.renderRapportProduitsEnCours = renderRapportProduitsEnCours;
window.renderRegistre = renderRegistre;
window.renderStock = renderStock;
window.renderComClients = renderComClients;
window.renderControle = renderControle;
window.renderDepensesCommerciaux = renderDepensesCommerciaux;
window.renderLivraisons = renderLivraisons;
window.renderProduits = renderProduits;
window.renderSaisieAdhesions = renderSaisieAdhesions;

// ── VOLET 39 ── affichage de la version dans la barre laterale.
try {
  const _bv = document.getElementById('app-version-badge');
  if (_bv) _bv.textContent = '· ' + APP_VERSION;
} catch(e) { /* l'affichage de la version ne doit jamais empecher le demarrage */ }

// ═══════════════ TÉLÉMESURE DES ERREURS (diagnostic distant) ═════════
// Envoie chaque erreur JS / rejet de promesse non intercepté vers Firestore
// (collection 'logs_erreurs_app'), en plus du console.error existant, pour
// objectiver enfin la fréquence/cause des plantages signalés sur le terrain
// (nécessite la règle Firestore correspondante sur 'logs_erreurs_app').
// Best-effort : ne bloque jamais l'UI, ne relance jamais d'erreur, et
// s'arrête tout seul en cas de doublons ou de trop d'erreurs d'affilée
// (pour ne pas transformer un plantage en tempête d'écritures Firestore).
const _ERR_LOG_MAX_PAR_SESSION = 20;
const _ERR_LOG_DEDUP_FENETRE_MS = 5000;
let _errLogCount = 0;
let _errLogDernierMsg = null;
let _errLogDernierTs = 0;

// ── VOLET 39 ── L'ECHEC DE LA TELEMESURE ETAIT TOTALEMENT SILENCIEUX.
// Le catch de _logErreurDistante() est vide — a juste titre : signaler une
// erreur ne doit pas en provoquer une autre. Mais la consequence etait qu'une
// regle Firestore absente ou mal deployee faisait croire a une telemesure
// active alors que RIEN n'etait enregistre. On aurait cherche des pannes dans
// une collection vide en concluant qu'il n'y en avait pas.
// Desormais : un etat est retenu, affiche dans l'ecran « Erreurs
// applicatives », et un avertissement console est emis UNE SEULE FOIS — pas a
// chaque erreur, sinon on remplacerait un silence par du bruit.
let _errLogOk = null;        // null = rien tente encore, true = ca marche, false = refus
let _errLogMotifEchec = '';
let _errLogAverti = false;

function _errLogEtat(){
  if (_errLogOk === true)  return { ok:true,  texte:'Télémesure active' };
  if (_errLogOk === false) return { ok:false, texte:'Télémesure en échec — ' + (_errLogMotifEchec||'cause inconnue') };
  return { ok:null, texte:'Télémesure non sollicitée depuis le démarrage' };
}
window._errLogEtat = _errLogEtat;

async function _logErreurDistante(type, message, stack){
  try {
    if (!db_fs) return; // Firebase pas encore prêt (ex: tout début du chargement)
    if (_errLogCount >= _ERR_LOG_MAX_PAR_SESSION) return;

    const cle = type + '|' + String(message||'').slice(0,200);
    const maintenant = Date.now();
    if (cle === _errLogDernierMsg && (maintenant - _errLogDernierTs) < _ERR_LOG_DEDUP_FENETRE_MS) return;
    _errLogDernierMsg = cle;
    _errLogDernierTs = maintenant;
    _errLogCount++;

    await addDoc(collection(db_fs, 'logs_erreurs_app'), {
      type,
      message: String(message||'').slice(0,500),
      stack: String(stack||'').slice(0,1000),
      page: document.querySelector('.page.active')?.id || '',
      commercialId: session ? session.userId : null,
      commercialNom: session ? session.nom : null,
      userAgent: navigator.userAgent,
      deviceMemoryGo: navigator.deviceMemory || null,
      online: navigator.onLine,
      // ── VOLET 39 ── sans ce champ, l'ecran « Erreurs applicatives » montre
      // des pannes sans pouvoir dire si elles sont deja corrigees.
      appVersion: APP_VERSION,
      createdAt: serverTimestamp()
    });
    _errLogOk = true;
  } catch(e) {
    // ── VOLET 39 ── toujours sans relancer d'erreur ni bloquer l'utilisateur,
    // mais plus en aveugle : on retient la cause et on avertit UNE fois.
    _errLogOk = false;
    _errLogMotifEchec = (e && (e.code || e.message)) ? String(e.code || e.message).slice(0,120) : 'inconnue';
    if (!_errLogAverti) {
      _errLogAverti = true;
      console.warn("[télémesure] Les erreurs ne sont PAS enregistrées sur le serveur : "
        + _errLogMotifEchec + ". Vérifiez la règle Firestore 'logs_erreurs_app'. "
        + "Cet avertissement n'est émis qu'une fois par session.");
    }
  }
}

// ✅ Filet de sécurité global : toute erreur JS qui échapperait encore à un
// try/catch local est désormais signalée à l'utilisateur (au lieu de rester
// silencieuse), journalisée en console pour diagnostic, et remontée à
// distance (voir _logErreurDistante ci-dessus) pour objectiver les plantages.
window.addEventListener('error', function(e){
  console.error('[Erreur globale]', e.message, e.error);
  _logErreurDistante('error', e.message, e.error && e.error.stack);
  if (typeof notify === 'function') {
    notify('Erreur : '+(e.message||'action impossible')+' — réessayez ou changez de page puis revenez.', 'err');
  }
});
window.addEventListener('unhandledrejection', function(e){
  console.error('[Promesse rejetée]', e.reason);
  _logErreurDistante('unhandledrejection', e.reason && e.reason.message, e.reason && e.reason.stack);
  if (typeof notify === 'function') {
    notify('Erreur : '+((e.reason&&e.reason.message)||'action impossible')+' — réessayez ou changez de page puis revenez.', 'err');
  }
});

// ═══════════════ ENREGISTREMENT SERVICE WORKER (PWA) ═════════
// + Détection de nouvelle version déployée sur GitHub/hébergeur, avec
// bannière visuelle proposant à l'utilisateur de mettre à jour l'app.
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js')
      .then((reg) => {
        // Cas 1 : une version est déjà en attente au moment où l'app se charge
        // (ex: onglet resté ouvert pendant un déploiement).
        if (reg.waiting) _afficherBanniereMAJ(reg.waiting);

        // Cas 2 : une nouvelle version vient d'être détectée (sw.js a changé
        // sur le serveur) et est en cours d'installation.
        reg.addEventListener('updatefound', () => {
          const nouveauWorker = reg.installing;
          if (!nouveauWorker) return;
          nouveauWorker.addEventListener('statechange', () => {
            // 'installed' + un controller déjà actif = ce n'est pas la toute
            // première installation, c'est une mise à jour d'une version déjà
            // utilisée -> on prévient l'utilisateur.
            if (nouveauWorker.state === 'installed' && navigator.serviceWorker.controller) {
              _afficherBanniereMAJ(nouveauWorker);
            }
          });
        });

        // Revérifie s'il existe une nouvelle version quand l'app revient au
        // premier plan (changement d'onglet, réouverture du téléphone, etc.)
        // — utile car le navigateur ne revérifie pas toujours sw.js assez tôt.
        document.addEventListener('visibilitychange', () => {
          if (document.visibilityState === 'visible') reg.update().catch(()=>{});
        });

        // Revérifie aussi périodiquement (toutes les 20 min) tant que l'onglet
        // est ouvert et visible — utile pour les utilisateurs qui gardent
        // l'app ouverte toute la journée sans jamais changer d'onglet, cas où
        // ils ne recevraient sinon la notification qu'après ~24h.
        const INTERVALLE_VERIF_MAJ = 20 * 60 * 1000; // 20 minutes
        setInterval(() => {
          if (document.visibilityState === 'visible') reg.update().catch(()=>{});
        }, INTERVALLE_VERIF_MAJ);
      })
      .catch(err => console.error('Échec enregistrement Service Worker :', err));

    // Quand le nouveau Service Worker prend le contrôle (juste après que
    // l'utilisateur a cliqué sur "Mettre à jour"), on recharge la page pour
    // charger les nouveaux fichiers.
    let _majEnCours = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (_majEnCours) return;
      // ── VOLET 32 ── 'controllerchange' ne signifie PAS « cet utilisateur a
      // demande la mise a jour ». Le sw.js appelle clients.claim() a
      // l'activation : des qu'UN onglet accepte, le nouveau worker prend le
      // controle de TOUS les onglets ouverts, qui recevaient donc cet
      // evenement et rechargeaient — y compris celui ou quelqu'un saisissait.
      // Le meme evenement survient aussi a la toute premiere installation.
      //
      // On ne recharge donc que si c'est CET onglet qui a demande. Les autres
      // affichent une invitation, et decident eux-memes.
      if (!_majDemandeeIci) {
        _afficherBanniereRechargement();
        return;
      }
      // Dernier controle juste avant de recharger : une modale a pu s'ouvrir
      // entre le clic et l'activation du nouveau worker.
      const raison = _majSaisieEnCours();
      if (raison) {
        notify(`⏸️ Nouvelle version prête, mais ${raison}. Rechargez quand vous aurez terminé.`, 'err');
        _majDemandeeIci = false;
        _afficherBanniereRechargement();
        return;
      }
      _majEnCours = true;
      // ── VOLET 12 ── on marque ce rechargement comme etant une MISE A JOUR,
      // juste avant de recharger. Au redemarrage, ce marqueur autorise la
      // restauration silencieuse de la session (voir
      // _tenterRestaurationSession) : l'agent retrouve son ecran sans
      // retaper son mot de passe.
      // sessionStorage : limite a CET onglet et efface a sa fermeture — il ne
      // peut donc pas servir a contourner l'authentification lors d'une
      // ouverture normale de l'application.
      _majPoserMarqueur();
      window.location.reload();
    });
  });
}

// ╔══════════════════════════════════════════════════════════════╗
// ║  VOLET 32 — ON NE RECHARGE PAS SUR UNE SAISIE EN COURS        ║
// ╚══════════════════════════════════════════════════════════════╝
// Renvoie la RAISON pour laquelle le rechargement doit etre refuse, ou null
// si l'ecran est au repos. On renvoie une phrase et non un booleen : un refus
// sans explication est vecu comme une panne.
//
// Deux signaux, volontairement simples et verifiables :
//   · une modale ouverte (.mo.open) — c'est le cas le plus frequent et le
//     plus couteux : livraison, adhesion, paiement, attribution de carnets ;
//   · un champ rempli sur la page affichee, hors champs de recherche et de
//     filtre — ceux-la ne representent aucune saisie a perdre.
//
// Volontairement PAS de detection « intelligente » supplementaire : un
// garde-fou qu'on ne peut pas expliquer en une phrase est un garde-fou qu'on
// finit par contourner.
const _MAJ_CHAMPS_IGNORES = /(search|recherche|filter|filtre|date-debut|date-fin|-q$)/i;

function _majSaisieEnCours(){
  try {
    const modale = document.querySelector('.mo.open');
    if (modale) {
      const titre = modale.querySelector('.mo-title, h3, h2');
      const nom = (titre && titre.textContent || '').trim().slice(0, 60);
      return nom ? `la fenêtre « ${nom} » est ouverte` : 'une fenêtre de saisie est ouverte';
    }
    const page = document.querySelector('.page.active') || document;
    const champs = page.querySelectorAll('input[type="text"], input[type="number"], input[type="tel"], textarea');
    for (const ch of champs) {
      if (!ch.id || _MAJ_CHAMPS_IGNORES.test(ch.id)) continue;
      if (ch.disabled || ch.readOnly) continue;
      if (ch.offsetParent === null) continue;          // masque : ne compte pas
      if (String(ch.value || '').trim() !== '') return 'un formulaire est rempli sur cet écran';
    }
    return null;
  } catch (e) {
    // En cas de doute on NE BLOQUE PAS : une erreur ici ne doit pas empecher
    // indefiniment toute mise a jour.
    console.warn('[maj] detection de saisie impossible :', e);
    return null;
  }
}

// Vrai si c'est CET onglet qui a demande la mise a jour. Sans ce drapeau, le
// 'controllerchange' declenche par clients.claim() faisait recharger TOUS les
// onglets ouverts des qu'un seul acceptait la mise a jour — y compris celui
// ou quelqu'un etait en pleine saisie. C'est l'autre moitie du defaut signale.
let _majDemandeeIci = false;

// Affiche une bannière discrète en bas de l'écran proposant la mise à jour.
// N'affiche qu'une seule fois même si l'événement se déclenche plusieurs fois.
function _afficherBanniereMAJ(workerEnAttente){
  if (document.getElementById('maj-banniere')) return;

  const bandeau = document.createElement('div');
  bandeau.id = 'maj-banniere';
  bandeau.innerHTML = `
    <span class="maj-banniere-texte">🚀 Une nouvelle version de l'application est disponible.</span>
    <button type="button" class="maj-banniere-btn" id="maj-banniere-btn">Mettre à jour</button>
    <button type="button" class="maj-banniere-fermer" id="maj-banniere-fermer" aria-label="Fermer">✕</button>
  `;
  document.body.appendChild(bandeau);

  document.getElementById('maj-banniere-btn').addEventListener('click', () => {
    // ── VOLET 32 ── refus explicite plutot que perte de saisie.
    const raison = _majSaisieEnCours();
    if (raison) {
      notify(`⏸️ Mise à jour reportée : ${raison}. Terminez ou fermez, puis recliquez — `
        + `le bandeau reste affiché.`, 'err');
      return;
    }
    _majDemandeeIci = true;
    workerEnAttente.postMessage({ type: 'SKIP_WAITING' });
    const btn = document.getElementById('maj-banniere-btn');
    if (btn) { btn.disabled = true; btn.textContent = 'Mise à jour…'; }
  });
  document.getElementById('maj-banniere-fermer').addEventListener('click', () => {
    bandeau.remove();
  });
}

// ── VOLET 32 ── Affiche apres coup, quand la nouvelle version est DEJA
// active mais que cet onglet n'a pas voulu (ou pas pu) recharger. Il tourne
// alors encore sur l'ancien code : le dire est necessaire, forcer ne l'est
// pas. Le rechargement passe par le meme garde-fou.
function _afficherBanniereRechargement(){
  const ancienne = document.getElementById('maj-banniere');
  if (ancienne && ancienne.dataset.mode === 'recharger') return;   // deja affiche
  if (ancienne) ancienne.remove();

  // ⚠️ On REUTILISE l'identifiant « maj-banniere » : l'habillage de ce bandeau
  // vit dans styles.min.css, qui cible cet id. Une classe inventee ici
  // n'aurait aucun style et le bandeau s'afficherait nu en haut de page.
  const bandeau = document.createElement('div');
  bandeau.id = 'maj-banniere';
  bandeau.dataset.mode = 'recharger';
  bandeau.innerHTML = `
    <span class="maj-banniere-texte">✅ Nouvelle version installée — rechargez quand vous aurez terminé votre saisie.</span>
    <button type="button" class="maj-banniere-btn" id="maj-recharger-btn">Recharger</button>
    <button type="button" class="maj-banniere-fermer" id="maj-recharger-fermer" aria-label="Fermer">✕</button>
  `;
  document.body.appendChild(bandeau);

  document.getElementById('maj-recharger-btn').addEventListener('click', () => {
    const raison = _majSaisieEnCours();
    if (raison) {
      notify(`⏸️ Rechargement reporté : ${raison}. Terminez ou fermez, puis recliquez.`, 'err');
      return;
    }
    const btn = document.getElementById('maj-recharger-btn');
    if (btn) { btn.disabled = true; btn.textContent = 'Rechargement…'; }
    _majPoserMarqueur();
    window.location.reload();
  });
  document.getElementById('maj-recharger-fermer').addEventListener('click', () => {
    bandeau.remove();
  });
}
